interface QuotationListProps {
  quotations: Quotation[];
  formatPrice: (amount: number) => string;
  onViewQuotation: (quote: Quotation) => void;
}

export const QuotationList: React.FC<QuotationListProps> = ({ quotations, formatPrice, onViewQuotation }) => {
  if (quotations.length === 0) {
    return (
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex-1 flex flex-col">
        <div className="text-center py-12 text-slate-400 flex flex-col items-center justify-center w-full h-full">
          <FileText className="w-12 h-12 mb-2 opacity-20" />
          No quotations found.
        </div>
      </div>
    );
  }

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex-1 flex flex-col">
      <div className="overflow-x-auto">
        <table className="w-full text-left">
          <thead className="bg-slate-50 border-b border-slate-100">
            <tr>
              <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase">Date / Ref</th>
              <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase">Customer</th>
              <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase">Valid Until</th>
              <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase text-right">Total</th>
              <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase text-center">Status</th>
              <th className="px-6 py-4 text-xs font-semibold text-slate-500 uppercase text-right">Action</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {quotations.map((quote) => {
               const isExpired = new Date(quote.validUntil) < new Date() && quote.status === 'active';

               return (
                  <tr 
                    key={quote.id} 
                    className="hover:bg-slate-50 transition-colors cursor-pointer group"
                    onClick={() => onViewQuotation(quote)}
                  >
                    <td className="px-6 py-4">
                      <div className="font-bold text-slate-800">{new Date(quote.date).toLocaleDateString()}</div>
                      <div className="text-xs text-slate-500 font-mono mt-0.5">{quote.referenceNo}</div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="font-medium text-slate-700">{quote.customerName || 'Walk-in'}</div>
                      <div className="text-xs text-slate-500">{quote.items.length} items</div>
                    </td>
                    <td className="px-6 py-4">
                        <div className={`flex items-center text-sm ${isExpired ? 'text-red-600 font-bold' : 'text-slate-600'}`}>
                           <CalendarClock className="w-3 h-3 mr-1" />
                           {new Date(quote.validUntil).toLocaleDateString()}
                        </div>
                    </td>
                    <td className="px-6 py-4 text-right font-bold text-slate-800">
                      {formatPrice(quote.total)}
                    </td>
                    <td className="px-6 py-4 text-center">
                      {quote.status === 'converted' ? (
                        <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold bg-green-100 text-green-700 border border-green-200">
                          Converted
                        </span>
                      ) : isExpired || quote.status === 'expired' ? (
                        <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold bg-red-100 text-red-700 border border-red-200">
                          Expired
                        </span>
                      ) : (
                        <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-bold bg-blue-100 text-blue-700 border border-blue-200">
                          Active
                        </span>
                      )}
                    </td>
                    <td className="px-6 py-4 text-right">
                      <button 
                        onClick={(e) => { e.stopPropagation(); onViewQuotation(quote); }}
                        className="p-2 bg-slate-100 text-slate-600 rounded hover:bg-slate-200 transition-colors"
                      >
                        <Eye className="w-4 h-4" />
                      </button>
                    </td>
                  </tr>
               );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
};

import React from 'react';
import { Quotation, SystemSettings } from '../../types';
import { X, Printer, ShoppingCart, Trash2 } from 'lucide-react';
import { PrintableQuotation } from '../shared/PrintableQuotation';
import { useCartStore } from '../../store/useCartStore';
import { useSalesStore } from '../../store/useSalesStore';

interface QuotationDetailModalProps {
  quotation: Quotation | null;
  isOpen: boolean;
  onClose: () => void;
  settings?: SystemSettings;
}

export const QuotationDetailModal: React.FC<QuotationDetailModalProps> = ({ quotation, isOpen, onClose, settings }) => {
  const addToCart = useCartStore((state) => state.addToCart);
  const clearCart = useCartStore((state) => state.clearCart);
  const updateQuotation = useSalesStore((state) => state.updateQuotation);
  const deleteQuotation = useSalesStore((state) => state.deleteQuotation);

  if (!isOpen || !quotation) return null;

  const handlePrint = () => {
    window.print();
  };

  const handleConvertToSale = () => {
    if (window.confirm("This will clear your current cart and load items from this quotation. Continue?")) {
       clearCart();

       if (quotation.items && quotation.items.length > 0) {
         quotation.items.forEach(item => {
            addToCart(item, item.quantity, item.selectedVariantId);
         });

         updateQuotation({ ...quotation, status: 'converted' });

         onClose();

         setTimeout(() => {
            alert("Items loaded to POS Cart. Please proceed to payment.");
         }, 100);
       }
    }
  };

  const handleDelete = () => {
     if (window.confirm("Delete this quotation permanently?")) {
        deleteQuotation(quotation.id);
        onClose();
     }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-black/60 backdrop-blur-sm transition-opacity" 
        onClick={onClose}
      />

      {/* Modal Container */}
      <div className="relative bg-white w-full max-w-4xl max-h-[90vh] rounded-xl shadow-2xl flex flex-col overflow-hidden animate-fade-in print:shadow-none print:max-w-none print:max-h-none print:rounded-none print:h-auto print:w-full print:fixed print:inset-0">

        {/* Header */}
        <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50 print:hidden shrink-0">
           <div>
              <h3 className="text-xl font-bold text-slate-800">Quotation Details</h3>
              <p className="text-xs text-slate-500 font-mono">{quotation.referenceNo}</p>
           </div>
           <button 
             onClick={onClose} 
             className="p-2 bg-slate-200 rounded-full text-slate-600 hover:bg-slate-300 transition-colors"
           >
             <X className="w-5 h-5" />
           </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto bg-slate-50 p-6 print:p-0 print:bg-white print:overflow-visible">
           <div className="shadow-sm md:shadow-md print:shadow-none mx-auto max-w-[210mm] bg-white min-h-[500px]">
              <PrintableQuotation quotation={quotation} settings={settings} />
           </div>
        </div>

        {/* Footer */}
        <div className="p-4 border-t border-slate-200 bg-white flex flex-col sm:flex-row justify-between gap-3 print:hidden shrink-0 z-20 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)]">
           <button 
              onClick={handleDelete}
              className="px-4 py-2 border border-red-200 text-red-600 rounded-lg hover:bg-red-50 font-bold flex items-center justify-center text-sm transition-colors"
           >
              <Trash2 className="w-4 h-4 mr-2" /> Delete
           </button>
           <div className="flex flex-col sm:flex-row gap-3">
              <button 
                 onClick={handlePrint}
                 className="px-5 py-2 bg-white border border-slate-300 text-slate-700 rounded-lg hover:bg-slate-50 font-bold flex items-center justify-center shadow-sm transition-colors"
              >
                 <Printer className="w-4 h-4 mr-2" /> Print / PDF
              </button>
              {quotation.status === 'active' && (
                 <button 
                    onClick={handleConvertToSale}
                    className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 font-bold shadow-md flex items-center justify-center transition-colors"
                 >
                    <ShoppingCart className="w-4 h-4 mr-2" /> Load to Cart
                 </button>
              )}
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Quotation, Product, Customer, CartItem } from '../types';
import { Search, Plus, FileText } from 'lucide-react';
import { useGlobal } from '../context/GlobalContext';
import { QuotationList } from './sales/QuotationList';
import { QuotationDetailModal } from './sales/QuotationDetailModal';
import { BackOfficeSaleModal } from './sales/BackOfficeSaleModal';
import { useSalesStore } from '../store/useSalesStore';

export const QuotationsManagement: React.FC = () => {
  const { 
    settings, 
    formatPrice, 
    products, 
    customers, 
    currentUser 
  } = useGlobal();

  const { quotations, addQuotation } = useSalesStore();

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedQuotation, setSelectedQuotation] = useState<Quotation | null>(null);
  const [isNewQuotationOpen, setIsNewQuotationOpen] = useState(false);

  const filteredQuotations = quotations.filter(q => 
    q.referenceNo.toLowerCase().includes(searchTerm.toLowerCase()) ||
    (q.customerName && q.customerName.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  const handleCreateQuotation = async (
    items: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number,
    paymentMethod?: any,
    amountReceived?: number,
    change?: number,
    pointsRedeemed?: number,
    source?: string
  ) => {
    // Generate Ref No
    const refNo = `QT-${new Date().getFullYear()}${Math.floor(Math.random() * 10000).toString().padStart(4, '0')}`;
    const validDate = new Date();
    validDate.setDate(validDate.getDate() + 7); // Default 7 days validity

    const customer = customers.find(c => c.id === customerId);

    const newQuotation: Quotation = {
      id: `q-${Date.now()}`,
      referenceNo: refNo,
      date: new Date().toISOString(),
      validUntil: validDate.toISOString(),
      items: items,
      subtotal: subtotal || total,
      discountAmount: discountAmount || 0,
      taxAmount: 0, // Simplified tax logic for demo
      total: total,
      status: 'active',
      customerId: customerId,
      customerName: customer ? customer.name : 'Walk-in',
      customerPhone: customer?.phone,
      customerAddress: customer?.address,
      userId: currentUser?.id,
      userName: currentUser?.name
    };

    addQuotation(newQuotation);
    return newQuotation;
  };

  return (
    <div className="space-y-6 h-full flex flex-col">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Quotations</h2>
          <p className="text-slate-500">Create and manage price estimates for customers.</p>
        </div>
        <button 
          onClick={() => setIsNewQuotationOpen(true)}
          className="flex items-center px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors font-medium shadow-sm whitespace-nowrap"
        >
          <Plus className="w-5 h-5 mr-2" />
          Create Quotation
        </button>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex flex-col md:flex-row gap-4 items-end">
        <div className="flex-1 w-full">
           <label className="block text-xs font-medium text-slate-500 mb-1">Search Quotations</label>
           <div className="relative">
              <Search className="absolute left-3 top-2.5 w-4 h-4 text-slate-400" />
              <input
                type="text"
                placeholder="Ref No. or Customer Name"
                value={searchTerm}
                onChange={e => setSearchTerm(e.target.value)}
                className="w-full pl-9 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500"
              />
           </div>
        </div>
      </div>

      <QuotationList 
        quotations={filteredQuotations}
        formatPrice={formatPrice}
        onViewQuotation={setSelectedQuotation}
      />

      <QuotationDetailModal 
        quotation={selectedQuotation}
        isOpen={!!selectedQuotation}
        onClose={() => setSelectedQuotation(null)}
        settings={settings}
      />

      {/* Reusing BackOfficeSaleModal for UI, but hooking into handleCreateQuotation */}
      {isNewQuotationOpen && (
        <BackOfficeSaleModal 
          isOpen={isNewQuotationOpen}
          onClose={() => setIsNewQuotationOpen(false)}
          products={products}
          customers={customers}
          onProcessSale={handleCreateQuotation} // This injects our quotation logic instead of sale logic
        />
      )}
    </div>
  );
};

