import React, { useState, useEffect } from 'react';
import { Product, Customer, CartItem, Quotation } from '../../types';
import { X, Plus, Save, AlertCircle, Search, Calendar, FileText, Trash2 } from 'lucide-react';
import { useGlobal } from '../../context/GlobalContext';

interface QuotationFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  products: Product[];
  customers: Customer[];
  initialData?: Quotation | null;
  onSubmit: (quotationData: any) => void;
}

export const QuotationFormModal: React.FC<QuotationFormModalProps> = ({
  isOpen,
  onClose,
  products,
  customers,
  initialData,
  onSubmit
}) => {
  const { formatPrice } = useGlobal();
  const [customerId, setCustomerId] = useState<string>('');
  const [selectedItems, setSelectedItems] = useState<CartItem[]>([]);
  const [validUntil, setValidUntil] = useState('');
  const [note, setNote] = useState('');
  const [error, setError] = useState<string | null>(null);

  // Item adding state
  const [searchProduct, setSearchProduct] = useState('');
  const [qtyInput, setQtyInput] = useState(1);

  // Initialize form
  useEffect(() => {
    if (isOpen) {
      if (initialData) {
        setCustomerId(initialData.customerId || '');
        // Deep copy items to avoid mutating state directly if referenced elsewhere
        setSelectedItems(initialData.items.map(item => ({...item})));
        setValidUntil(new Date(initialData.validUntil).toISOString().split('T')[0]);
        setNote(initialData.note || '');
      } else {
        setCustomerId('');
        setSelectedItems([]);
        // Default 7 days validity
        const nextWeek = new Date();
        nextWeek.setDate(nextWeek.getDate() + 7);
        setValidUntil(nextWeek.toISOString().split('T')[0]);
        setNote('');
      }
      setError(null);
      setSearchProduct('');
      setQtyInput(1);
    }
  }, [isOpen, initialData]);

  const handleAddItem = (product: Product) => {
    const existingIdx = selectedItems.findIndex(i => i.id === product.id);

    if (existingIdx >= 0) {
      const newItems = [...selectedItems];
      newItems[existingIdx].quantity += qtyInput;
      setSelectedItems(newItems);
    } else {
      const newItem: CartItem = {
        ...product,
        quantity: qtyInput,
        sellPrice: product.price,
        sellUnit: product.unit,
        sellConversionFactor: 1
      };
      setSelectedItems([...selectedItems, newItem]);
    }
    setQtyInput(1);
    setSearchProduct('');
  };

  const handleUpdateItem = (index: number, field: 'quantity' | 'sellPrice', value: number) => {
    const newItems = [...selectedItems];
    newItems[index] = { ...newItems[index], [field]: value };
    setSelectedItems(newItems);
  };

  const handleRemoveItem = (index: number) => {
    const newItems = [...selectedItems];
    newItems.splice(index, 1);
    setSelectedItems(newItems);
  };

  const calculateTotal = () => {
    return selectedItems.reduce((acc, item) => acc + (item.sellPrice * item.quantity), 0);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (selectedItems.length === 0) {
      setError("Please add at least one product.");
      return;
    }
    if (!validUntil) {
      setError("Please select a validity date.");
      return;
    }

    const total = calculateTotal();

    onSubmit({
      items: selectedItems,
      customerId,
      validUntil,
      note,
      subtotal: total,
      total: total, // Simplified: Tax/Discount logic can be expanded here
      discountAmount: 0,
      taxAmount: 0
    });
  };

  if (!isOpen) return null;

  const filteredProducts = products.filter(p => {
    const searchLower = searchProduct.toLowerCase();
    return (
      p.name.toLowerCase().includes(searchLower) || 
      p.sku?.toLowerCase().includes(searchLower) ||
      p.barcode?.toLowerCase().includes(searchLower)
    );
  }).slice(0, 5);

  return (
    <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-[70] p-4 backdrop-blur-sm animate-fade-in">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-4xl max-h-[90vh] flex flex-col overflow-hidden">

        {/* Header */}
        <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-slate-50">
          <div>
            <h3 className="text-xl font-bold text-slate-800">{initialData ? 'Edit Quotation' : 'Create Quotation'}</h3>
            <p className="text-xs text-slate-500">{initialData ? `Ref: ${initialData.referenceNo}` : 'New price estimate'}</p>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600"><X className="w-6 h-6" /></button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-6">

          {error && (
            <div className="bg-red-50 border border-red-200 text-red-700 p-4 rounded-lg flex items-start">
              <AlertCircle className="w-5 h-5 mr-2 flex-shrink-0 mt-0.5" />
              <div>
                <p className="font-bold">Validation Error</p>
                <p className="text-sm">{error}</p>
              </div>
            </div>
          )}

          {/* Form Header */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label className="block text-sm font-bold text-slate-700 mb-1">Customer</label>
              <select 
                value={customerId} 
                onChange={e => setCustomerId(e.target.value)}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 bg-white"
              >
                <option value="">Select Customer (Optional)</option>
                {customers.map(c => (
                  <option key={c.id} value={c.id}>{c.name} ({c.code})</option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-sm font-bold text-slate-700 mb-1">Valid Until</label>
              <div className="relative">
                 <Calendar className="absolute left-3 top-2.5 w-4 h-4 text-slate-400" />
                 <input 
                   type="date"
                   value={validUntil}
                   onChange={e => setValidUntil(e.target.value)}
                   className="w-full pl-9 pr-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                 />
              </div>
            </div>
            <div>
               <label className="block text-sm font-bold text-slate-700 mb-1">Status</label>
               <div className="px-3 py-2 border border-slate-200 bg-slate-100 rounded-lg text-slate-500 text-sm font-medium">
                  {initialData ? initialData.status.toUpperCase() : 'DRAFT'}
               </div>
            </div>
          </div>

          {/* Product Selection */}
          <div className="bg-slate-50 p-4 rounded-xl border border-slate-200">
            <label className="block text-sm font-bold text-slate-700 mb-2">Add Items</label>
            <div className="flex gap-2 mb-2">
              <div className="relative flex-1">
                <Search className="absolute left-3 top-2.5 w-4 h-4 text-slate-400" />
                <input 
                  type="text" 
                  placeholder="Search Products..." 
                  className="w-full pl-9 pr-4 py-2 border border-slate-300 rounded-lg"
                  value={searchProduct}
                  onChange={e => setSearchProduct(e.target.value)}
                />
                {searchProduct && (
                  <div className="absolute top-full left-0 right-0 bg-white border border-slate-200 shadow-lg rounded-lg mt-1 z-20 max-h-48 overflow-y-auto">
                    {filteredProducts.length > 0 ? filteredProducts.map(p => (
                      <div 
                        key={p.id} 
                        className="p-2 hover:bg-slate-50 cursor-pointer flex justify-between items-center border-b border-slate-50 last:border-0"
                        onClick={() => handleAddItem(p)}
                      >
                        <div>
                          <p className="text-sm font-bold text-slate-800">{p.name}</p>
                          <p className="text-xs text-slate-500">{p.sku} • Stock: {p.stock}</p>
                        </div>
                        <span className="text-sm font-bold text-blue-600">{formatPrice(p.price)}</span>
                      </div>
                    )) : (
                      <div className="p-3 text-sm text-slate-400 text-center">No products found</div>
                    )}
                  </div>
                )}
              </div>
              <input 
                type="number" 
                min="1" 
                value={qtyInput}
                onChange={e => setQtyInput(parseInt(e.target.value) || 1)}
                className="w-20 px-3 py-2 border border-slate-300 rounded-lg text-center font-bold"
              />
            </div>
          </div>

          {/* Items Table */}
          <div className="border rounded-lg overflow-hidden">
            <table className="w-full text-left text-sm">
              <thead className="bg-slate-100 text-slate-700 font-bold border-b">
                <tr>
                  <th className="p-3">Product</th>
                  <th className="p-3 w-32 text-right">Price (Edit)</th>
                  <th className="p-3 w-24 text-center">Qty</th>
                  <th className="p-3 w-32 text-right">Total</th>
                  <th className="p-3 w-10"></th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {selectedItems.length === 0 ? (
                  <tr>
                    <td colSpan={5} className="p-8 text-center text-slate-400">No items added to quotation.</td>
                  </tr>
                ) : (
                  selectedItems.map((item, idx) => (
                    <tr key={idx} className="hover:bg-slate-50 transition-colors">
                      <td className="p-3">
                        <div className="font-bold text-slate-800">{item.name}</div>
                        <div className="text-xs text-slate-500">{item.sku}</div>
                      </td>
                      <td className="p-3 text-right">
                         <input 
                           type="number" 
                           min="0"
                           value={item.sellPrice}
                           onChange={e => handleUpdateItem(idx, 'sellPrice', parseFloat(e.target.value))}
                           className="w-24 px-2 py-1 border border-slate-300 rounded text-right text-sm"
                         />
                      </td>
                      <td className="p-3 text-center">
                         <input 
                           type="number" 
                           min="1"
                           value={item.quantity}
                           onChange={e => handleUpdateItem(idx, 'quantity', parseFloat(e.target.value))}
                           className="w-16 px-2 py-1 border border-slate-300 rounded text-center text-sm"
                        />
                      </td>
                      <td className="p-3 text-right font-bold text-slate-800">{formatPrice(item.sellPrice * item.quantity)}</td>
                      <td className="p-3 text-center">
                        <button onClick={() => handleRemoveItem(idx)} className="text-red-400 hover:text-red-600 p-1 rounded hover:bg-red-50">
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
              <tfoot className="bg-slate-50 font-bold border-t">
                <tr>
                  <td colSpan={3} className="p-3 text-right text-slate-700">Grand Total:</td>
                  <td className="p-3 text-right text-lg text-blue-700">{formatPrice(calculateTotal())}</td>
                  <td></td>
                </tr>
              </tfoot>
            </table>
          </div>

          <div>
             <label className="block text-sm font-medium text-slate-700 mb-1">Notes / Terms</label>
             <div className="relative">
                <FileText className="absolute left-3 top-3 w-4 h-4 text-slate-400" />
                <textarea 
                   value={note}
                   onChange={e => setNote(e.target.value)}
                   className="w-full pl-9 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 h-24 resize-none text-sm"
                   placeholder="e.g. Valid for 7 days. 50% deposit required."
                />
             </div>
          </div>

        </div>

        {/* Footer */}
        <div className="p-4 border-t border-slate-100 bg-white flex justify-end gap-3">
          <button 
            type="button"
            onClick={onClose}
            className="px-5 py-2.5 text-slate-600 font-medium hover:bg-slate-100 rounded-lg border border-slate-200"
          >
            Cancel
          </button>
          <button 
            onClick={handleSubmit}
            className="px-6 py-2.5 bg-blue-600 text-white font-bold rounded-lg hover:bg-blue-700 shadow-sm flex items-center"
          >
            <Save className="w-4 h-4 mr-2" />
            {initialData ? 'Update Quotation' : 'Save Quotation'}
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Quotation, Product, Customer } from '../types';
import { Search, Plus } from 'lucide-react';
import { useGlobal } from '../context/GlobalContext';
import { QuotationList } from './sales/QuotationList';
import { QuotationDetailModal } from './sales/QuotationDetailModal';
import { QuotationFormModal } from './sales/QuotationFormModal';
import { useSalesStore } from '../store/useSalesStore';

export const QuotationsManagement: React.FC = () => {
  const { 
    settings, 
    formatPrice, 
    products, 
    customers, 
    currentUser 
  } = useGlobal();

  const { quotations, addQuotation, updateQuotation } = useSalesStore();

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedQuotation, setSelectedQuotation] = useState<Quotation | null>(null);

  // Form State
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingQuotation, setEditingQuotation] = useState<Quotation | null>(null);

  const filteredQuotations = quotations.filter(q => 
    q.referenceNo.toLowerCase().includes(searchTerm.toLowerCase()) ||
    (q.customerName && q.customerName.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  const handleOpenCreate = () => {
    setEditingQuotation(null);
    setIsFormOpen(true);
  };

  const handleOpenEdit = (quotation: Quotation) => {
    // Close detail view if open
    setSelectedQuotation(null);
    setEditingQuotation(quotation);
    setIsFormOpen(true);
  };

  const handleSaveQuotation = (data: any) => {
    const customer = customers.find(c => c.id === data.customerId);

    if (editingQuotation) {
       // Update existing
       const updatedQuote: Quotation = {
          ...editingQuotation,
          items: data.items,
          subtotal: data.subtotal,
          total: data.total,
          validUntil: data.validUntil,
          note: data.note,
          customerId: data.customerId,
          customerName: customer ? customer.name : 'Walk-in',
          customerAddress: customer?.address,
          customerPhone: customer?.phone
       };
       updateQuotation(updatedQuote);
    } else {
       // Create new
       const refNo = `QT-${new Date().getFullYear()}${Math.floor(Math.random() * 10000).toString().padStart(4, '0')}`;
       const newQuote: Quotation = {
          id: `q-${Date.now()}`,
          referenceNo: refNo,
          date: new Date().toISOString(),
          status: 'active',
          userId: currentUser?.id,
          userName: currentUser?.name,
          items: data.items,
          subtotal: data.subtotal,
          total: data.total,
          discountAmount: 0,
          taxAmount: 0,
          validUntil: data.validUntil,
          note: data.note,
          customerId: data.customerId,
          customerName: customer ? customer.name : 'Walk-in',
          customerAddress: customer?.address,
          customerPhone: customer?.phone
       };
       addQuotation(newQuote);
    }

    setIsFormOpen(false);
  };

  return (
    <div className="space-y-6 h-full flex flex-col">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Quotations</h2>
          <p className="text-slate-500">Create and manage price estimates for customers.</p>
        </div>
        <button 
          onClick={handleOpenCreate}
          className="flex items-center px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors font-medium shadow-sm whitespace-nowrap"
        >
          <Plus className="w-5 h-5 mr-2" />
          Create Quotation
        </button>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex flex-col md:flex-row gap-4 items-end">
        <div className="flex-1 w-full">
           <label className="block text-xs font-medium text-slate-500 mb-1">Search Quotations</label>
           <div className="relative">
              <Search className="absolute left-3 top-2.5 w-4 h-4 text-slate-400" />
              <input
                type="text"
                placeholder="Ref No. or Customer Name"
                value={searchTerm}
                onChange={e => setSearchTerm(e.target.value)}
                className="w-full pl-9 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500"
              />
           </div>
        </div>
      </div>

      <QuotationList 
        quotations={filteredQuotations}
        formatPrice={formatPrice}
        onViewQuotation={setSelectedQuotation}
      />

      <QuotationDetailModal 
        quotation={selectedQuotation}
        isOpen={!!selectedQuotation}
        onClose={() => setSelectedQuotation(null)}
        settings={settings}
        onEdit={() => selectedQuotation && handleOpenEdit(selectedQuotation)}
      />

      <QuotationFormModal 
        isOpen={isFormOpen}
        onClose={() => setIsFormOpen(false)}
        products={products}
        customers={customers}
        initialData={editingQuotation}
        onSubmit={handleSaveQuotation}
      />
    </div>
  );
};

import React from 'react';
import { Quotation, SystemSettings } from '../../types';
import { X, Printer, ShoppingCart, Trash2, Edit } from 'lucide-react';
import { PrintableQuotation } from '../shared/PrintableQuotation';
import { useCartStore } from '../../store/useCartStore';
import { useSalesStore } from '../../store/useSalesStore';

interface QuotationDetailModalProps {
  quotation: Quotation | null;
  isOpen: boolean;
  onClose: () => void;
  settings?: SystemSettings;
  onEdit?: () => void; // Added onEdit prop
}

export const QuotationDetailModal: React.FC<QuotationDetailModalProps> = ({ 
  quotation, isOpen, onClose, settings, onEdit 
}) => {
  const addToCart = useCartStore((state) => state.addToCart);
  const clearCart = useCartStore((state) => state.clearCart);
  const updateQuotation = useSalesStore((state) => state.updateQuotation);
  const deleteQuotation = useSalesStore((state) => state.deleteQuotation);

  if (!isOpen || !quotation) return null;

  const handlePrint = () => {
    window.print();
  };

  const handleConvertToSale = () => {
    if (window.confirm("This will clear your current cart and load items from this quotation. Continue?")) {
       clearCart();

       if (quotation.items && quotation.items.length > 0) {
         quotation.items.forEach(item => {
            addToCart(item, item.quantity, item.selectedVariantId);
         });

         updateQuotation({ ...quotation, status: 'converted' });

         onClose();

         setTimeout(() => {
            alert("Items loaded to POS Cart. Please proceed to payment.");
         }, 100);
       }
    }
  };

  const handleDelete = () => {
     if (window.confirm("Delete this quotation permanently?")) {
        deleteQuotation(quotation.id);
        onClose();
     }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-black/60 backdrop-blur-sm transition-opacity" 
        onClick={onClose}
      />

      {/* Modal Container */}
      <div className="relative bg-white w-full max-w-4xl max-h-[90vh] rounded-xl shadow-2xl flex flex-col overflow-hidden animate-fade-in print:shadow-none print:max-w-none print:max-h-none print:rounded-none print:h-auto print:w-full print:fixed print:inset-0">

        {/* Header */}
        <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50 print:hidden shrink-0">
           <div>
              <h3 className="text-xl font-bold text-slate-800">Quotation Details</h3>
              <p className="text-xs text-slate-500 font-mono">{quotation.referenceNo}</p>
           </div>
           <div className="flex items-center gap-2">
              {quotation.status === 'active' && onEdit && (
                 <button 
                    onClick={onEdit}
                    className="flex items-center px-3 py-1.5 bg-blue-50 text-blue-700 rounded-lg hover:bg-blue-100 font-medium text-sm transition-colors"
                 >
                    <Edit className="w-4 h-4 mr-1.5" /> Edit
                 </button>
              )}
              <button 
                onClick={onClose} 
                className="p-2 bg-slate-200 rounded-full text-slate-600 hover:bg-slate-300 transition-colors"
              >
                <X className="w-5 h-5" />
              </button>
           </div>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto bg-slate-50 p-6 print:p-0 print:bg-white print:overflow-visible">
           <div className="shadow-sm md:shadow-md print:shadow-none mx-auto max-w-[210mm] bg-white min-h-[500px]">
              <PrintableQuotation quotation={quotation} settings={settings} />
           </div>
        </div>

        {/* Footer */}
        <div className="p-4 border-t border-slate-200 bg-white flex flex-col sm:flex-row justify-between gap-3 print:hidden shrink-0 z-20 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)]">
           <button 
              onClick={handleDelete}
              className="px-4 py-2 border border-red-200 text-red-600 rounded-lg hover:bg-red-50 font-bold flex items-center justify-center text-sm transition-colors"
           >
              <Trash2 className="w-4 h-4 mr-2" /> Delete
           </button>
           <div className="flex flex-col sm:flex-row gap-3">
              <button 
                 onClick={handlePrint}
                 className="px-5 py-2 bg-white border border-slate-300 text-slate-700 rounded-lg hover:bg-slate-50 font-bold flex items-center justify-center shadow-sm transition-colors"
              >
                 <Printer className="w-4 h-4 mr-2" /> Print / PDF
              </button>
              {quotation.status === 'active' && (
                 <button 
                    onClick={handleConvertToSale}
                    className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 font-bold shadow-md flex items-center justify-center transition-colors"
                 >
                    <ShoppingCart className="w-4 h-4 mr-2" /> Load to Cart
                 </button>
              )}
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Product, Customer, CartItem, Quotation, SystemSettings } from '../../types';
import { X, Plus, Save, AlertCircle, Search, Calendar, FileText, Trash2, User, Calculator } from 'lucide-react';
import { useGlobal } from '../../context/GlobalContext';

interface QuotationFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  products: Product[];
  customers: Customer[];
  settings: SystemSettings;
  initialData?: Quotation | null;
  onSubmit: (quotationData: any) => void;
}

export const QuotationFormModal: React.FC<QuotationFormModalProps> = ({
  isOpen,
  onClose,
  products,
  customers,
  settings,
  initialData,
  onSubmit
}) => {
  const { formatPrice } = useGlobal();

  // Header State
  const [customerId, setCustomerId] = useState<string>('');
  const [validUntil, setValidUntil] = useState('');
  const [note, setNote] = useState('');

  // Items State
  const [selectedItems, setSelectedItems] = useState<CartItem[]>([]);

  // Financial State
  const [discountAmount, setDiscountAmount] = useState<number>(0);

  // UI State
  const [error, setError] = useState<string | null>(null);
  const [searchProduct, setSearchProduct] = useState('');
  const [qtyInput, setQtyInput] = useState(1);

  // Initialize form
  useEffect(() => {
    if (isOpen) {
      if (initialData) {
        setCustomerId(initialData.customerId || '');
        setSelectedItems(initialData.items.map(item => ({...item}))); // Deep copy
        setValidUntil(new Date(initialData.validUntil).toISOString().split('T')[0]);
        setNote(initialData.note || '');
        setDiscountAmount(initialData.discountAmount || 0);
      } else {
        setCustomerId('');
        setSelectedItems([]);
        setDiscountAmount(0);
        // Default 7 days validity
        const nextWeek = new Date();
        nextWeek.setDate(nextWeek.getDate() + 7);
        setValidUntil(nextWeek.toISOString().split('T')[0]);
        setNote('');
      }
      setError(null);
      setSearchProduct('');
      setQtyInput(1);
    }
  }, [isOpen, initialData]);

  // Calculations
  const subtotal = useMemo(() => {
    return selectedItems.reduce((acc, item) => acc + (item.sellPrice * item.quantity), 0);
  }, [selectedItems]);

  const taxAmount = useMemo(() => {
    if (!settings.tax.enabled) return 0;

    // Logic matches POS:
    // If tax is Excluded: (Subtotal - Discount) * Rate
    // If tax is Included: Tax is part of the price, so we calculate backward or just show it purely informational?
    // Usually for Quotations, if Excluded, we add it on top.

    const taxable = Math.max(0, subtotal - discountAmount);
    const rate = settings.tax.rate / 100;

    if (settings.tax.calculationMode === 'excluded') {
       return taxable * rate;
    } else {
       // Included: Tax = Price - (Price / (1 + Rate))
       return taxable - (taxable / (1 + rate));
    }
  }, [subtotal, discountAmount, settings.tax]);

  const total = useMemo(() => {
    if (settings.tax.enabled && settings.tax.calculationMode === 'excluded') {
       return Math.max(0, subtotal - discountAmount) + taxAmount;
    }
    return Math.max(0, subtotal - discountAmount);
  }, [subtotal, discountAmount, taxAmount, settings.tax]);

  // Handlers
  const handleAddItem = (product: Product) => {
    const existingIdx = selectedItems.findIndex(i => i.id === product.id);

    if (existingIdx >= 0) {
      const newItems = [...selectedItems];
      newItems[existingIdx].quantity += qtyInput;
      setSelectedItems(newItems);
    } else {
      const newItem: CartItem = {
        ...product,
        quantity: qtyInput,
        sellPrice: product.price,
        sellUnit: product.unit,
        sellConversionFactor: 1
      };
      setSelectedItems([...selectedItems, newItem]);
    }
    setQtyInput(1);
    setSearchProduct('');
  };

  const handleUpdateItem = (index: number, field: 'quantity' | 'sellPrice', value: number) => {
    const newItems = [...selectedItems];
    newItems[index] = { ...newItems[index], [field]: value };
    setSelectedItems(newItems);
  };

  const handleRemoveItem = (index: number) => {
    const newItems = [...selectedItems];
    newItems.splice(index, 1);
    setSelectedItems(newItems);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (selectedItems.length === 0) {
      setError("Please add at least one product.");
      return;
    }
    if (!validUntil) {
      setError("Please select a validity date.");
      return;
    }

    onSubmit({
      items: selectedItems,
      customerId,
      validUntil,
      note,
      subtotal,
      discountAmount,
      taxAmount,
      total
    });
  };

  if (!isOpen) return null;

  const filteredProducts = products.filter(p => {
    const searchLower = searchProduct.toLowerCase();
    return (
      p.name.toLowerCase().includes(searchLower) || 
      p.sku?.toLowerCase().includes(searchLower) ||
      p.barcode?.toLowerCase().includes(searchLower)
    );
  }).slice(0, 5);

  return (
    <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-[70] p-4 backdrop-blur-sm animate-fade-in">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-5xl max-h-[90vh] flex flex-col overflow-hidden">

        {/* Header */}
        <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-slate-50">
          <div className="flex items-center gap-3">
             <div className="p-2 bg-blue-100 text-blue-600 rounded-lg">
                <FileText className="w-6 h-6" />
             </div>
             <div>
                <h3 className="text-xl font-bold text-slate-800">{initialData ? 'Edit Quotation' : 'New Quotation'}</h3>
                <p className="text-xs text-slate-500">{initialData ? `Ref: ${initialData.referenceNo}` : 'Drafting new estimate'}</p>
             </div>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 p-2 hover:bg-slate-100 rounded-full transition-colors">
             <X className="w-6 h-6" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-6 bg-slate-50/50">

          {error && (
            <div className="bg-red-50 border border-red-200 text-red-700 p-4 rounded-lg flex items-start shadow-sm">
              <AlertCircle className="w-5 h-5 mr-2 flex-shrink-0 mt-0.5" />
              <div>
                <p className="font-bold">Validation Error</p>
                <p className="text-sm">{error}</p>
              </div>
            </div>
          )}

          {/* Form Header Fields */}
          <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm grid grid-cols-1 md:grid-cols-3 gap-6">
            <div>
              <label className="block text-sm font-bold text-slate-700 mb-1 flex items-center">
                 <User className="w-4 h-4 mr-1.5 text-slate-400" /> Customer
              </label>
              <select 
                value={customerId} 
                onChange={e => setCustomerId(e.target.value)}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 bg-white transition-shadow"
              >
                <option value="">Select Customer (Optional)</option>
                {customers.map(c => (
                  <option key={c.id} value={c.id}>{c.name} ({c.code})</option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-sm font-bold text-slate-700 mb-1 flex items-center">
                 <Calendar className="w-4 h-4 mr-1.5 text-slate-400" /> Valid Until
              </label>
              <input 
                type="date"
                value={validUntil}
                onChange={e => setValidUntil(e.target.value)}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500"
              />
            </div>
            <div>
               <label className="block text-sm font-bold text-slate-700 mb-1">Status</label>
               <div className="px-4 py-2 border border-slate-200 bg-slate-50 rounded-lg text-slate-500 text-sm font-bold uppercase tracking-wide">
                  {initialData ? initialData.status : 'DRAFT'}
               </div>
            </div>
          </div>

          {/* Product Selection */}
          <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm space-y-4">
            <h4 className="font-bold text-slate-800 text-sm flex items-center">
               <Search className="w-4 h-4 mr-2 text-slate-500" /> Add Products
            </h4>
            <div className="flex gap-2">
              <div className="relative flex-1">
                <input 
                  type="text" 
                  placeholder="Scan barcode or search product name..." 
                  className="w-full pl-4 pr-4 py-2.5 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                  value={searchProduct}
                  onChange={e => setSearchProduct(e.target.value)}
                />
                {searchProduct && (
                  <div className="absolute top-full left-0 right-0 bg-white border border-slate-200 shadow-xl rounded-lg mt-1 z-20 max-h-60 overflow-y-auto">
                    {filteredProducts.length > 0 ? filteredProducts.map(p => (
                      <div 
                        key={p.id} 
                        className="p-3 hover:bg-blue-50 cursor-pointer flex justify-between items-center border-b border-slate-50 last:border-0 transition-colors"
                        onClick={() => handleAddItem(p)}
                      >
                        <div>
                          <p className="text-sm font-bold text-slate-800">{p.name}</p>
                          <p className="text-xs text-slate-500 font-mono mt-0.5">{p.sku} • Stock: {p.stock}</p>
                        </div>
                        <span className="text-sm font-bold text-blue-600 bg-blue-50 px-2 py-1 rounded">{formatPrice(p.price)}</span>
                      </div>
                    )) : (
                      <div className="p-4 text-sm text-slate-400 text-center italic">No products found</div>
                    )}
                  </div>
                )}
              </div>
              <input 
                type="number" 
                min="1" 
                value={qtyInput}
                onChange={e => setQtyInput(parseInt(e.target.value) || 1)}
                className="w-24 px-3 py-2 border border-slate-300 rounded-lg text-center font-bold"
                placeholder="Qty"
              />
            </div>
          </div>

          {/* Items Table */}
          <div className="bg-white border border-slate-200 rounded-xl overflow-hidden shadow-sm">
            <table className="w-full text-left text-sm">
              <thead className="bg-slate-50 text-slate-700 font-bold border-b border-slate-200">
                <tr>
                  <th className="p-4 w-12 text-center">#</th>
                  <th className="p-4">Product Description</th>
                  <th className="p-4 w-32 text-right">Unit Price</th>
                  <th className="p-4 w-24 text-center">Qty</th>
                  <th className="p-4 w-32 text-right">Total</th>
                  <th className="p-4 w-12"></th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {selectedItems.length === 0 ? (
                  <tr>
                    <td colSpan={6} className="p-12 text-center text-slate-400 italic">
                       No items added to quotation yet.
                    </td>
                  </tr>
                ) : (
                  selectedItems.map((item, idx) => (
                    <tr key={idx} className="hover:bg-slate-50 transition-colors group">
                      <td className="p-4 text-center text-slate-400">{idx + 1}</td>
                      <td className="p-4">
                        <div className="font-bold text-slate-800">{item.name}</div>
                        <div className="text-xs text-slate-500 font-mono mt-0.5">{item.sku}</div>
                      </td>
                      <td className="p-4 text-right">
                         <input 
                           type="number" 
                           min="0"
                           value={item.sellPrice}
                           onChange={e => handleUpdateItem(idx, 'sellPrice', parseFloat(e.target.value))}
                           className="w-24 px-2 py-1 border border-slate-200 rounded text-right text-sm focus:ring-1 focus:ring-blue-500 focus:border-blue-500"
                         />
                      </td>
                      <td className="p-4 text-center">
                         <input 
                           type="number" 
                           min="1"
                           value={item.quantity}
                           onChange={e => handleUpdateItem(idx, 'quantity', parseFloat(e.target.value))}
                           className="w-20 px-2 py-1 border border-slate-200 rounded text-center text-sm focus:ring-1 focus:ring-blue-500 focus:border-blue-500 font-medium"
                        />
                      </td>
                      <td className="p-4 text-right font-bold text-slate-800">{formatPrice(item.sellPrice * item.quantity)}</td>
                      <td className="p-4 text-center">
                        <button onClick={() => handleRemoveItem(idx)} className="text-slate-300 hover:text-red-500 p-1.5 rounded-full hover:bg-red-50 transition-colors">
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>

          <div className="flex flex-col md:flex-row gap-6">
             {/* Notes */}
             <div className="flex-1">
                <label className="block text-sm font-bold text-slate-700 mb-2">Terms & Notes</label>
                <textarea 
                   value={note}
                   onChange={e => setNote(e.target.value)}
                   className="w-full p-4 border border-slate-300 rounded-xl focus:ring-2 focus:ring-blue-500 h-32 resize-none text-sm bg-white"
                   placeholder="e.g. Price valid for 7 days. 50% deposit required."
                />
             </div>

             {/* Totals Calculation */}
             <div className="w-full md:w-80 bg-white p-5 rounded-xl border border-slate-200 shadow-sm space-y-3 h-fit">
                <div className="flex justify-between text-sm text-slate-600">
                   <span>Subtotal</span>
                   <span className="font-bold">{formatPrice(subtotal)}</span>
                </div>

                <div className="flex justify-between items-center text-sm text-slate-600">
                   <span className="flex items-center">Discount <Calculator className="w-3 h-3 ml-1 text-slate-400" /></span>
                   <input 
                      type="number"
                      min="0"
                      value={discountAmount}
                      onChange={e => setDiscountAmount(parseFloat(e.target.value) || 0)}
                      className="w-24 px-2 py-1 border border-slate-200 rounded text-right text-sm focus:ring-1 focus:ring-green-500 text-green-600 font-bold"
                   />
                </div>

                {settings.tax.enabled && (
                   <div className="flex justify-between text-sm text-slate-500">
                      <span>Tax ({settings.tax.rate}%)</span>
                      <span>{formatPrice(taxAmount)}</span>
                   </div>
                )}

                <div className="border-t border-slate-100 my-2 pt-3 flex justify-between items-end">
                   <span className="font-bold text-lg text-slate-800">Total</span>
                   <span className="font-bold text-2xl text-blue-700">{formatPrice(total)}</span>
                </div>
             </div>
          </div>

        </div>

        {/* Footer */}
        <div className="p-4 border-t border-slate-100 bg-white flex justify-end gap-3 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)] z-10">
          <button 
            type="button"
            onClick={onClose}
            className="px-5 py-2.5 text-slate-600 font-medium hover:bg-slate-100 rounded-lg border border-slate-200 transition-colors"
          >
            Cancel
          </button>
          <button 
            onClick={handleSubmit}
            className="px-8 py-2.5 bg-blue-600 text-white font-bold rounded-lg hover:bg-blue-700 shadow-md hover:shadow-lg transition-all flex items-center"
          >
            <Save className="w-4 h-4 mr-2" />
            {initialData ? 'Update Quotation' : 'Save Quotation'}
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Quotation } from '../types';
import { Search, Plus } from 'lucide-react';
import { useGlobal } from '../context/GlobalContext';
import { QuotationList } from './sales/QuotationList';
import { QuotationDetailModal } from './sales/QuotationDetailModal';
import { QuotationFormModal } from './sales/QuotationFormModal';
import { useSalesStore } from '../store/useSalesStore';

export const QuotationsManagement: React.FC = () => {
  const { 
    settings, 
    formatPrice, 
    products, 
    customers, 
    currentUser 
  } = useGlobal();

  const { quotations, addQuotation, updateQuotation } = useSalesStore();

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedQuotation, setSelectedQuotation] = useState<Quotation | null>(null);

  // Form State
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingQuotation, setEditingQuotation] = useState<Quotation | null>(null);

  const filteredQuotations = quotations.filter(q => 
    q.referenceNo.toLowerCase().includes(searchTerm.toLowerCase()) ||
    (q.customerName && q.customerName.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  const handleOpenCreate = () => {
    setEditingQuotation(null);
    setIsFormOpen(true);
  };

  const handleOpenEdit = (quotation: Quotation) => {
    // Close detail view if open
    setSelectedQuotation(null);
    setEditingQuotation(quotation);
    setIsFormOpen(true);
  };

  const handleSaveQuotation = (data: any) => {
    const customer = customers.find(c => c.id === data.customerId);

    if (editingQuotation) {
       // Update existing
       const updatedQuote: Quotation = {
          ...editingQuotation,
          items: data.items,
          subtotal: data.subtotal,
          total: data.total,
          discountAmount: data.discountAmount || 0,
          taxAmount: data.taxAmount || 0,
          validUntil: data.validUntil,
          note: data.note,
          customerId: data.customerId,
          customerName: customer ? customer.name : 'Walk-in',
          customerAddress: customer?.address,
          customerPhone: customer?.phone
       };
       updateQuotation(updatedQuote);
    } else {
       // Create new
       const refNo = `QT-${new Date().getFullYear()}${Math.floor(Math.random() * 10000).toString().padStart(4, '0')}`;
       const newQuote: Quotation = {
          id: `q-${Date.now()}`,
          referenceNo: refNo,
          date: new Date().toISOString(),
          status: 'active',
          userId: currentUser?.id,
          userName: currentUser?.name,
          items: data.items,
          subtotal: data.subtotal,
          total: data.total,
          discountAmount: data.discountAmount || 0,
          taxAmount: data.taxAmount || 0,
          validUntil: data.validUntil,
          note: data.note,
          customerId: data.customerId,
          customerName: customer ? customer.name : 'Walk-in',
          customerAddress: customer?.address,
          customerPhone: customer?.phone
       };
       addQuotation(newQuote);
    }

    setIsFormOpen(false);
  };

  return (
    <div className="space-y-6 h-full flex flex-col">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Quotations</h2>
          <p className="text-slate-500">Create and manage price estimates for customers.</p>
        </div>
        <button 
          onClick={handleOpenCreate}
          className="flex items-center px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors font-medium shadow-sm whitespace-nowrap"
        >
          <Plus className="w-5 h-5 mr-2" />
          Create Quotation
        </button>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex flex-col md:flex-row gap-4 items-end">
        <div className="flex-1 w-full">
           <label className="block text-xs font-medium text-slate-500 mb-1">Search Quotations</label>
           <div className="relative">
              <Search className="absolute left-3 top-2.5 w-4 h-4 text-slate-400" />
              <input
                type="text"
                placeholder="Ref No. or Customer Name"
                value={searchTerm}
                onChange={e => setSearchTerm(e.target.value)}
                className="w-full pl-9 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500"
              />
           </div>
        </div>
      </div>

      <QuotationList 
        quotations={filteredQuotations}
        formatPrice={formatPrice}
        onViewQuotation={setSelectedQuotation}
      />

      <QuotationDetailModal 
        quotation={selectedQuotation}
        isOpen={!!selectedQuotation}
        onClose={() => setSelectedQuotation(null)}
        settings={settings}
        onEdit={() => selectedQuotation && handleOpenEdit(selectedQuotation)}
      />

      <QuotationFormModal 
        isOpen={isFormOpen}
        onClose={() => setIsFormOpen(false)}
        products={products}
        customers={customers}
        settings={settings}
        initialData={editingQuotation}
        onSubmit={handleSaveQuotation}
      />
    </div>
  );
};

import React from 'react';
import { Quotation, SystemSettings } from '../../types';
import { X, Printer, ShoppingCart, Trash2, Edit } from 'lucide-react';
import { PrintableQuotation } from '../shared/PrintableQuotation';
import { useCartStore } from '../../store/useCartStore';
import { useSalesStore } from '../../store/useSalesStore';

interface QuotationDetailModalProps {
  quotation: Quotation | null;
  isOpen: boolean;
  onClose: () => void;
  settings?: SystemSettings;
  onEdit?: () => void;
}

export const QuotationDetailModal: React.FC<QuotationDetailModalProps> = ({ 
  quotation, isOpen, onClose, settings, onEdit 
}) => {
  const addToCart = useCartStore((state) => state.addToCart);
  const clearCart = useCartStore((state) => state.clearCart);
  const updateQuotation = useSalesStore((state) => state.updateQuotation);
  const deleteQuotation = useSalesStore((state) => state.deleteQuotation);

  if (!isOpen || !quotation) return null;

  const handlePrint = () => {
    window.print();
  };

  const handleConvertToSale = () => {
    if (window.confirm("This will clear your current cart and load items from this quotation. Continue?")) {
       clearCart();

       if (quotation.items && quotation.items.length > 0) {
         quotation.items.forEach(item => {
            addToCart(item, item.quantity, item.selectedVariantId);
         });

         updateQuotation({ ...quotation, status: 'converted' });

         onClose();

         // Trigger POS tab switch if not already there? 
         // In a real app we might navigate, but here user usually goes to POS manually or we rely on notification
         setTimeout(() => {
            alert("Items loaded to POS Cart. Please proceed to Point of Sale.");
         }, 100);
       }
    }
  };

  const handleDelete = () => {
     if (window.confirm("Delete this quotation permanently?")) {
        deleteQuotation(quotation.id);
        onClose();
     }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-black/60 backdrop-blur-sm transition-opacity" 
        onClick={onClose}
      />

      {/* Modal Container */}
      <div className="relative bg-white w-full max-w-4xl max-h-[90vh] rounded-xl shadow-2xl flex flex-col overflow-hidden animate-fade-in print:shadow-none print:max-w-none print:max-h-none print:rounded-none print:h-auto print:w-full print:fixed print:inset-0">

        {/* Header */}
        <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50 print:hidden shrink-0">
           <div>
              <h3 className="text-xl font-bold text-slate-800">Quotation Details</h3>
              <p className="text-xs text-slate-500 font-mono">{quotation.referenceNo}</p>
           </div>
           <div className="flex items-center gap-2">
              {quotation.status === 'active' && onEdit && (
                 <button 
                    onClick={onEdit}
                    className="flex items-center px-3 py-1.5 bg-blue-50 text-blue-700 rounded-lg hover:bg-blue-100 font-medium text-sm transition-colors border border-blue-100"
                 >
                    <Edit className="w-4 h-4 mr-1.5" /> Edit
                 </button>
              )}
              <button 
                onClick={onClose} 
                className="p-2 bg-slate-200 rounded-full text-slate-600 hover:bg-slate-300 transition-colors"
              >
                <X className="w-5 h-5" />
              </button>
           </div>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto bg-slate-50 p-6 print:p-0 print:bg-white print:overflow-visible">
           <div className="shadow-sm md:shadow-md print:shadow-none mx-auto max-w-[210mm] bg-white min-h-[500px]">
              <PrintableQuotation quotation={quotation} settings={settings} />
           </div>
        </div>

        {/* Footer */}
        <div className="p-4 border-t border-slate-200 bg-white flex flex-col sm:flex-row justify-between gap-3 print:hidden shrink-0 z-20 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)]">
           <button 
              onClick={handleDelete}
              className="px-4 py-2 border border-red-200 text-red-600 rounded-lg hover:bg-red-50 font-bold flex items-center justify-center text-sm transition-colors"
           >
              <Trash2 className="w-4 h-4 mr-2" /> Delete
           </button>
           <div className="flex flex-col sm:flex-row gap-3">
              <button 
                 onClick={handlePrint}
                 className="px-5 py-2 bg-white border border-slate-300 text-slate-700 rounded-lg hover:bg-slate-50 font-bold flex items-center justify-center shadow-sm transition-colors"
              >
                 <Printer className="w-4 h-4 mr-2" /> Print / PDF
              </button>
              {quotation.status === 'active' && (
                 <button 
                    onClick={handleConvertToSale}
                    className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 font-bold shadow-md flex items-center justify-center transition-colors"
                 >
                    <ShoppingCart className="w-4 h-4 mr-2" /> Load to Cart
                 </button>
              )}
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { Product, Customer, CartItem, Quotation, SystemSettings } from '../../types';
import { X, Plus, Save, AlertCircle, Search, Calendar, FileText, Trash2, User, Calculator } from 'lucide-react';
import { useGlobal } from '../../context/GlobalContext';

interface QuotationFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  products: Product[];
  customers: Customer[];
  settings: SystemSettings;
  initialData?: Quotation | null;
  onSubmit: (quotationData: any) => void;
}

export const QuotationFormModal: React.FC<QuotationFormModalProps> = ({
  isOpen,
  onClose,
  products,
  customers,
  settings,
  initialData,
  onSubmit
}) => {
  const { formatPrice } = useGlobal();

  // Header State
  const [customerId, setCustomerId] = useState<string>('');
  const [validUntil, setValidUntil] = useState('');
  const [note, setNote] = useState('');

  // Items State
  const [selectedItems, setSelectedItems] = useState<CartItem[]>([]);

  // Financial State
  const [discountInput, setDiscountInput] = useState<number>(0);

  // UI State
  const [error, setError] = useState<string | null>(null);
  const [searchProduct, setSearchProduct] = useState('');
  const [qtyInput, setQtyInput] = useState(1);

  // Initialize form
  useEffect(() => {
    if (isOpen) {
      if (initialData) {
        setCustomerId(initialData.customerId || '');
        setSelectedItems(initialData.items.map(item => ({...item}))); // Deep copy
        setValidUntil(new Date(initialData.validUntil).toISOString().split('T')[0]);
        setNote(initialData.note || '');
        setDiscountInput(initialData.discountAmount || 0);
      } else {
        setCustomerId('');
        setSelectedItems([]);
        setDiscountInput(0);
        // Default 7 days validity
        const nextWeek = new Date();
        nextWeek.setDate(nextWeek.getDate() + 7);
        setValidUntil(nextWeek.toISOString().split('T')[0]);
        setNote('');
      }
      setError(null);
      setSearchProduct('');
      setQtyInput(1);
    }
  }, [isOpen, initialData]);

  // Calculations
  const subtotal = useMemo(() => {
    return selectedItems.reduce((acc, item) => acc + (item.sellPrice * item.quantity), 0);
  }, [selectedItems]);

  const taxAmount = useMemo(() => {
    if (!settings.tax.enabled) return 0;

    // Taxable amount is after discount
    const taxable = Math.max(0, subtotal - discountInput);
    const rate = settings.tax.rate / 100;

    if (settings.tax.calculationMode === 'excluded') {
       return taxable * rate;
    } else {
       // Included: Tax = Price - (Price / (1 + Rate))
       return taxable - (taxable / (1 + rate));
    }
  }, [subtotal, discountInput, settings.tax]);

  const total = useMemo(() => {
    const afterDiscount = Math.max(0, subtotal - discountInput);

    if (settings.tax.enabled && settings.tax.calculationMode === 'excluded') {
       return afterDiscount + taxAmount;
    }
    return afterDiscount;
  }, [subtotal, discountInput, taxAmount, settings.tax]);

  // Handlers
  const handleAddItem = (product: Product) => {
    const existingIdx = selectedItems.findIndex(i => i.id === product.id);

    if (existingIdx >= 0) {
      const newItems = [...selectedItems];
      newItems[existingIdx].quantity += qtyInput;
      setSelectedItems(newItems);
    } else {
      const newItem: CartItem = {
        ...product,
        quantity: qtyInput,
        sellPrice: product.price,
        sellUnit: product.unit,
        sellConversionFactor: 1
      };
      setSelectedItems([...selectedItems, newItem]);
    }
    setQtyInput(1);
    setSearchProduct('');
  };

  const handleUpdateItem = (index: number, field: 'quantity' | 'sellPrice', value: number) => {
    const newItems = [...selectedItems];
    newItems[index] = { ...newItems[index], [field]: value };
    setSelectedItems(newItems);
  };

  const handleRemoveItem = (index: number) => {
    const newItems = [...selectedItems];
    newItems.splice(index, 1);
    setSelectedItems(newItems);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (selectedItems.length === 0) {
      setError("Please add at least one product.");
      return;
    }
    if (!validUntil) {
      setError("Please select a validity date.");
      return;
    }

    onSubmit({
      items: selectedItems,
      customerId,
      validUntil,
      note,
      subtotal,
      discountAmount: discountInput,
      taxAmount,
      total
    });
  };

  if (!isOpen) return null;

  const filteredProducts = products.filter(p => {
    const searchLower = searchProduct.toLowerCase();
    return (
      p.name.toLowerCase().includes(searchLower) || 
      p.sku?.toLowerCase().includes(searchLower) ||
      p.barcode?.toLowerCase().includes(searchLower)
    );
  }).slice(0, 5);

  return (
    <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-[70] p-4 backdrop-blur-sm animate-fade-in">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-5xl max-h-[90vh] flex flex-col overflow-hidden">

        {/* Header */}
        <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-slate-50">
          <div className="flex items-center gap-3">
             <div className="p-2 bg-blue-100 text-blue-600 rounded-lg">
                <FileText className="w-6 h-6" />
             </div>
             <div>
                <h3 className="text-xl font-bold text-slate-800">{initialData ? 'Edit Quotation' : 'New Quotation'}</h3>
                <p className="text-xs text-slate-500">{initialData ? `Ref: ${initialData.referenceNo}` : 'Drafting new estimate'}</p>
             </div>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 p-2 hover:bg-slate-100 rounded-full transition-colors">
             <X className="w-6 h-6" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-6 bg-slate-50/50">

          {error && (
            <div className="bg-red-50 border border-red-200 text-red-700 p-4 rounded-lg flex items-start shadow-sm">
              <AlertCircle className="w-5 h-5 mr-2 flex-shrink-0 mt-0.5" />
              <div>
                <p className="font-bold">Validation Error</p>
                <p className="text-sm">{error}</p>
              </div>
            </div>
          )}

          {/* Form Header Fields */}
          <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm grid grid-cols-1 md:grid-cols-3 gap-6">
            <div>
              <label className="block text-sm font-bold text-slate-700 mb-1 flex items-center">
                 <User className="w-4 h-4 mr-1.5 text-slate-400" /> Customer
              </label>
              <select 
                value={customerId} 
                onChange={e => setCustomerId(e.target.value)}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 bg-white transition-shadow"
              >
                <option value="">Select Customer (Optional)</option>
                {customers.map(c => (
                  <option key={c.id} value={c.id}>{c.name} ({c.code})</option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-sm font-bold text-slate-700 mb-1 flex items-center">
                 <Calendar className="w-4 h-4 mr-1.5 text-slate-400" /> Valid Until
              </label>
              <input 
                type="date"
                value={validUntil}
                onChange={e => setValidUntil(e.target.value)}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500"
              />
            </div>
            <div>
               <label className="block text-sm font-bold text-slate-700 mb-1">Status</label>
               <div className="px-4 py-2 border border-slate-200 bg-slate-50 rounded-lg text-slate-500 text-sm font-bold uppercase tracking-wide">
                  {initialData ? initialData.status : 'DRAFT'}
               </div>
            </div>
          </div>

          {/* Product Selection */}
          <div className="bg-white p-5 rounded-xl border border-slate-200 shadow-sm space-y-4">
            <h4 className="font-bold text-slate-800 text-sm flex items-center">
               <Search className="w-4 h-4 mr-2 text-slate-500" /> Add Products
            </h4>
            <div className="flex gap-2">
              <div className="relative flex-1">
                <input 
                  type="text" 
                  placeholder="Scan barcode or search product name..." 
                  className="w-full pl-4 pr-4 py-2.5 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                  value={searchProduct}
                  onChange={e => setSearchProduct(e.target.value)}
                />
                {searchProduct && (
                  <div className="absolute top-full left-0 right-0 bg-white border border-slate-200 shadow-xl rounded-lg mt-1 z-20 max-h-60 overflow-y-auto">
                    {filteredProducts.length > 0 ? filteredProducts.map(p => (
                      <div 
                        key={p.id} 
                        className="p-3 hover:bg-blue-50 cursor-pointer flex justify-between items-center border-b border-slate-50 last:border-0 transition-colors"
                        onClick={() => handleAddItem(p)}
                      >
                        <div>
                          <p className="text-sm font-bold text-slate-800">{p.name}</p>
                          <p className="text-xs text-slate-500 font-mono mt-0.5">{p.sku} • Stock: {p.stock}</p>
                        </div>
                        <span className="text-sm font-bold text-blue-600 bg-blue-50 px-2 py-1 rounded">{formatPrice(p.price)}</span>
                      </div>
                    )) : (
                      <div className="p-4 text-sm text-slate-400 text-center italic">No products found</div>
                    )}
                  </div>
                )}
              </div>
              <input 
                type="number" 
                min="1" 
                value={qtyInput}
                onChange={e => setQtyInput(parseInt(e.target.value) || 1)}
                className="w-24 px-3 py-2 border border-slate-300 rounded-lg text-center font-bold"
                placeholder="Qty"
              />
            </div>
          </div>

          {/* Items Table */}
          <div className="bg-white border border-slate-200 rounded-xl overflow-hidden shadow-sm">
            <table className="w-full text-left text-sm">
              <thead className="bg-slate-50 text-slate-700 font-bold border-b border-slate-200">
                <tr>
                  <th className="p-4 w-12 text-center">#</th>
                  <th className="p-4">Product Description</th>
                  <th className="p-4 w-32 text-right">Unit Price</th>
                  <th className="p-4 w-24 text-center">Qty</th>
                  <th className="p-4 w-32 text-right">Total</th>
                  <th className="p-4 w-12"></th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {selectedItems.length === 0 ? (
                  <tr>
                    <td colSpan={6} className="p-12 text-center text-slate-400 italic">
                       No items added to quotation yet.
                    </td>
                  </tr>
                ) : (
                  selectedItems.map((item, idx) => (
                    <tr key={idx} className="hover:bg-slate-50 transition-colors group">
                      <td className="p-4 text-center text-slate-400">{idx + 1}</td>
                      <td className="p-4">
                        <div className="font-bold text-slate-800">{item.name}</div>
                        <div className="text-xs text-slate-500 font-mono mt-0.5">{item.sku}</div>
                      </td>
                      <td className="p-4 text-right">
                         <input 
                           type="number" 
                           min="0"
                           value={item.sellPrice}
                           onChange={e => handleUpdateItem(idx, 'sellPrice', parseFloat(e.target.value))}
                           className="w-24 px-2 py-1 border border-slate-200 rounded text-right text-sm focus:ring-1 focus:ring-blue-500 focus:border-blue-500"
                         />
                      </td>
                      <td className="p-4 text-center">
                         <input 
                           type="number" 
                           min="1"
                           value={item.quantity}
                           onChange={e => handleUpdateItem(idx, 'quantity', parseFloat(e.target.value))}
                           className="w-20 px-2 py-1 border border-slate-200 rounded text-center text-sm focus:ring-1 focus:ring-blue-500 focus:border-blue-500 font-medium"
                        />
                      </td>
                      <td className="p-4 text-right font-bold text-slate-800">{formatPrice(item.sellPrice * item.quantity)}</td>
                      <td className="p-4 text-center">
                        <button onClick={() => handleRemoveItem(idx)} className="text-slate-300 hover:text-red-500 p-1.5 rounded-full hover:bg-red-50 transition-colors">
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>

          <div className="flex flex-col md:flex-row gap-6">
             {/* Notes */}
             <div className="flex-1">
                <label className="block text-sm font-bold text-slate-700 mb-2">Terms & Notes</label>
                <textarea 
                   value={note}
                   onChange={e => setNote(e.target.value)}
                   className="w-full p-4 border border-slate-300 rounded-xl focus:ring-2 focus:ring-blue-500 h-32 resize-none text-sm bg-white"
                   placeholder="e.g. Price valid for 7 days. 50% deposit required."
                />
             </div>

             {/* Totals Calculation */}
             <div className="w-full md:w-80 bg-white p-5 rounded-xl border border-slate-200 shadow-sm space-y-3 h-fit">
                <div className="flex justify-between text-sm text-slate-600">
                   <span>Subtotal</span>
                   <span className="font-bold">{formatPrice(subtotal)}</span>
                </div>

                <div className="flex justify-between items-center text-sm text-slate-600">
                   <span className="flex items-center">Discount <Calculator className="w-3 h-3 ml-1 text-slate-400" /></span>
                   <input 
                      type="number"
                      min="0"
                      value={discountInput}
                      onChange={e => setDiscountInput(parseFloat(e.target.value) || 0)}
                      className="w-24 px-2 py-1 border border-slate-200 rounded text-right text-sm focus:ring-1 focus:ring-green-500 text-green-600 font-bold"
                   />
                </div>

                {settings.tax.enabled && (
                   <div className="flex justify-between text-sm text-slate-500">
                      <span>Tax ({settings.tax.rate}%)</span>
                      <span>{formatPrice(taxAmount)}</span>
                   </div>
                )}

                <div className="border-t border-slate-100 my-2 pt-3 flex justify-between items-end">
                   <span className="font-bold text-lg text-slate-800">Total</span>
                   <span className="font-bold text-2xl text-blue-700">{formatPrice(total)}</span>
                </div>
             </div>
          </div>

        </div>

        {/* Footer */}
        <div className="p-4 border-t border-slate-100 bg-white flex justify-end gap-3 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)] z-10">
          <button 
            type="button"
            onClick={onClose}
            className="px-5 py-2.5 text-slate-600 font-medium hover:bg-slate-100 rounded-lg border border-slate-200 transition-colors"
          >
            Cancel
          </button>
          <button 
            onClick={handleSubmit}
            className="px-8 py-2.5 bg-blue-600 text-white font-bold rounded-lg hover:bg-blue-700 shadow-md hover:shadow-lg transition-all flex items-center"
          >
            <Save className="w-4 h-4 mr-2" />
            {initialData ? 'Update Quotation' : 'Save Quotation'}
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Quotation } from '../types';
import { Search, Plus } from 'lucide-react';
import { useGlobal } from '../context/GlobalContext';
import { QuotationList } from './sales/QuotationList';
import { QuotationDetailModal } from './sales/QuotationDetailModal';
import { QuotationFormModal } from './sales/QuotationFormModal';
import { useSalesStore } from '../store/useSalesStore';

export const QuotationsManagement: React.FC = () => {
  const { 
    settings, 
    formatPrice, 
    products, 
    customers, 
    currentUser 
  } = useGlobal();

  const { quotations, addQuotation, updateQuotation } = useSalesStore();

  const [searchTerm, setSearchTerm] = useState('');
  const [selectedQuotation, setSelectedQuotation] = useState<Quotation | null>(null);

  // Form State
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingQuotation, setEditingQuotation] = useState<Quotation | null>(null);

  const filteredQuotations = quotations.filter(q => 
    q.referenceNo.toLowerCase().includes(searchTerm.toLowerCase()) ||
    (q.customerName && q.customerName.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  const handleOpenCreate = () => {
    setEditingQuotation(null);
    setIsFormOpen(true);
  };

  const handleOpenEdit = (quotation: Quotation) => {
    // Close detail view if open
    setSelectedQuotation(null);
    setEditingQuotation(quotation);
    setIsFormOpen(true);
  };

  const handleSaveQuotation = (data: any) => {
    const customer = customers.find(c => c.id === data.customerId);

    if (editingQuotation) {
       // Update existing
       const updatedQuote: Quotation = {
          ...editingQuotation,
          items: data.items,
          subtotal: data.subtotal,
          total: data.total,
          discountAmount: data.discountAmount || 0,
          taxAmount: data.taxAmount || 0,
          validUntil: data.validUntil,
          note: data.note,
          customerId: data.customerId,
          customerName: customer ? customer.name : 'Walk-in',
          customerAddress: customer?.address,
          customerPhone: customer?.phone
       };
       updateQuotation(updatedQuote);
    } else {
       // Create new
       const refNo = `QT-${new Date().getFullYear()}${Math.floor(Math.random() * 10000).toString().padStart(4, '0')}`;
       const newQuote: Quotation = {
          id: `q-${Date.now()}`,
          referenceNo: refNo,
          date: new Date().toISOString(),
          status: 'active',
          userId: currentUser?.id,
          userName: currentUser?.name,
          items: data.items,
          subtotal: data.subtotal,
          total: data.total,
          discountAmount: data.discountAmount || 0,
          taxAmount: data.taxAmount || 0,
          validUntil: data.validUntil,
          note: data.note,
          customerId: data.customerId,
          customerName: customer ? customer.name : 'Walk-in',
          customerAddress: customer?.address,
          customerPhone: customer?.phone
       };
       addQuotation(newQuote);
    }

    setIsFormOpen(false);
  };

  return (
    <div className="space-y-6 h-full flex flex-col">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Quotations</h2>
          <p className="text-slate-500">Create and manage price estimates for customers.</p>
        </div>
        <button 
          onClick={handleOpenCreate}
          className="flex items-center px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors font-medium shadow-sm whitespace-nowrap"
        >
          <Plus className="w-5 h-5 mr-2" />
          Create Quotation
        </button>
      </div>

      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex flex-col md:flex-row gap-4 items-end">
        <div className="flex-1 w-full">
           <label className="block text-xs font-medium text-slate-500 mb-1">Search Quotations</label>
           <div className="relative">
              <Search className="absolute left-3 top-2.5 w-4 h-4 text-slate-400" />
              <input
                type="text"
                placeholder="Ref No. or Customer Name"
                value={searchTerm}
                onChange={e => setSearchTerm(e.target.value)}
                className="w-full pl-9 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500"
              />
           </div>
        </div>
      </div>

      <QuotationList 
        quotations={filteredQuotations}
        formatPrice={formatPrice}
        onViewQuotation={setSelectedQuotation}
      />

      <QuotationDetailModal 
        quotation={selectedQuotation}
        isOpen={!!selectedQuotation}
        onClose={() => setSelectedQuotation(null)}
        settings={settings}
        onEdit={() => selectedQuotation && handleOpenEdit(selectedQuotation)}
      />

      <QuotationFormModal 
        isOpen={isFormOpen}
        onClose={() => setIsFormOpen(false)}
        products={products}
        customers={customers}
        settings={settings}
        initialData={editingQuotation}
        onSubmit={handleSaveQuotation}
      />
    </div>
  );
};

import React from 'react';
import { Quotation, SystemSettings } from '../../types';
import { X, Printer, ShoppingCart, Trash2, Edit } from 'lucide-react';
import { PrintableQuotation } from '../shared/PrintableQuotation';
import { useCartStore } from '../../store/useCartStore';
import { useSalesStore } from '../../store/useSalesStore';

interface QuotationDetailModalProps {
  quotation: Quotation | null;
  isOpen: boolean;
  onClose: () => void;
  settings?: SystemSettings;
  onEdit?: () => void;
}

export const QuotationDetailModal: React.FC<QuotationDetailModalProps> = ({ 
  quotation, isOpen, onClose, settings, onEdit 
}) => {
  const addToCart = useCartStore((state) => state.addToCart);
  const clearCart = useCartStore((state) => state.clearCart);
  const updateQuotation = useSalesStore((state) => state.updateQuotation);
  const deleteQuotation = useSalesStore((state) => state.deleteQuotation);

  if (!isOpen || !quotation) return null;

  const handlePrint = () => {
    window.print();
  };

  const handleConvertToSale = () => {
    if (window.confirm("This will clear your current cart and load items from this quotation. Continue?")) {
       clearCart();

       if (quotation.items && quotation.items.length > 0) {
         quotation.items.forEach(item => {
            addToCart(item, item.quantity, item.selectedVariantId);
         });

         updateQuotation({ ...quotation, status: 'converted' });

         onClose();

         // Trigger POS tab switch if not already there? 
         // In a real app we might navigate, but here user usually goes to POS manually or we rely on notification
         setTimeout(() => {
            alert("Items loaded to POS Cart. Please proceed to Point of Sale.");
         }, 100);
       }
    }
  };

  const handleDelete = () => {
     if (window.confirm("Delete this quotation permanently?")) {
        deleteQuotation(quotation.id);
        onClose();
     }
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
      {/* Backdrop */}
      <div 
        className="absolute inset-0 bg-black/60 backdrop-blur-sm transition-opacity" 
        onClick={onClose}
      />

      {/* Modal Container */}
      <div className="relative bg-white w-full max-w-4xl max-h-[90vh] rounded-xl shadow-2xl flex flex-col overflow-hidden animate-fade-in print:shadow-none print:max-w-none print:max-h-none print:rounded-none print:h-auto print:w-full print:fixed print:inset-0">

        {/* Header */}
        <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50 print:hidden shrink-0">
           <div>
              <h3 className="text-xl font-bold text-slate-800">Quotation Details</h3>
              <p className="text-xs text-slate-500 font-mono">{quotation.referenceNo}</p>
           </div>
           <div className="flex items-center gap-2">
              {quotation.status === 'active' && onEdit && (
                 <button 
                    onClick={onEdit}
                    className="flex items-center px-3 py-1.5 bg-blue-50 text-blue-700 rounded-lg hover:bg-blue-100 font-medium text-sm transition-colors border border-blue-100"
                 >
                    <Edit className="w-4 h-4 mr-1.5" /> Edit
                 </button>
              )}
              <button 
                onClick={onClose} 
                className="p-2 bg-slate-200 rounded-full text-slate-600 hover:bg-slate-300 transition-colors"
              >
                <X className="w-5 h-5" />
              </button>
           </div>
        </div>

        {/* Content */}
