        {filteredProducts.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-64 text-slate-400">
            <Box className="w-12 h-12 mb-2 opacity-30" />
            <p>No products found.</p>
          </div>
        ) : viewMode === 'grid' ? (
          // GRID VIEW
          <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4">
            {filteredProducts.map((product) => (
              <div key={product.id} onClick={() => !product.variants?.length && addToCart(product, undefined)} className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden hover:shadow-lg hover:border-orange-200 transition-all cursor-pointer flex flex-col group h-full">
                <div className="h-32 bg-slate-50 relative flex items-center justify-center overflow-hidden">
                  {product.imageUrl ? (
                    <img src={product.imageUrl} alt={product.name} className="w-full h-full object-cover" />
                  ) : (
                    <Box className="w-10 h-10 text-slate-300" />
                  )}
                  <span className={`absolute top-2 right-2 px-2 py-0.5 rounded text-[10px] font-bold text-white shadow-sm ${product.stock > (product.minStock || 0) ? 'bg-green-500' : 'bg-red-500'}`}>
                    {product.stock} {product.unit}
                  </span>
                  {product.minOrderQuantity && product.minOrderQuantity > 1 && (
                     <span className="absolute bottom-2 left-2 px-2 py-0.5 rounded text-[10px] font-bold text-slate-600 bg-white/90 shadow-sm border border-slate-200">
                        MOQ: {product.minOrderQuantity}
                     </span>
