                    <div className="flex justify-between items-center mb-2">
                      <span className="font-bold text-slate-900">{formatPrice(product.price)}</span>
                    </div>
                    {product.variants?.length ? (
                      <div className="grid grid-cols-2 gap-1">
                         {product.variants.map(v => (
                           <button key={v.id} onClick={(e) => { e.stopPropagation(); addToCart(product, undefined, v.id); }} className="px-2 py-1.5 bg-slate-100 hover:bg-orange-100 text-xs font-bold rounded text-slate-700 hover:text-orange-700 border border-slate-200 truncate">
