        ) : (
          // LIST VIEW
          <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
             <table className="w-full text-left border-collapse">
                <thead className="bg-slate-50 border-b border-slate-100 text-xs font-bold text-slate-500 uppercase sticky top-0 z-10">
                   <tr>
                      <th className="p-4 w-16">Image</th>
                      <th className="p-4">Product Info</th>
                      <th className="p-4 text-right">Price</th>
                      <th className="p-4 text-center">Stock</th>
                      <th className="p-4 text-right w-40">Action</th>
                   </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 text-sm">
                   {filteredProducts.map(product => {
                      const hasVariants = product.variants && product.variants.length > 0;
                      return (
                         <tr 
                            key={product.id} 
                            className="hover:bg-slate-50 transition-colors cursor-pointer group"
                            onClick={() => !hasVariants && addToCart(product, undefined)}
                         >
                            <td className="p-3">
                               <div className="w-10 h-10 rounded-lg bg-slate-100 border border-slate-200 flex items-center justify-center overflow-hidden shrink-0">
                                  {product.imageUrl ? <img src={product.imageUrl} className="w-full h-full object-cover"/> : <Box className="w-5 h-5 text-slate-300"/>}
                               </div>
                            </td>
                            <td className="p-3">
                               <div className="font-bold text-slate-800">{product.name}</div>
                               <div className="flex items-center gap-2 mt-0.5">
                                  <span className="text-xs text-slate-500 font-mono bg-slate-100 px-1.5 rounded">{product.sku}</span>
                                  {product.minOrderQuantity && product.minOrderQuantity > 1 && (
                                     <span className="text-[10px] text-orange-600 border border-orange-200 px-1.5 rounded">MOQ: {product.minOrderQuantity}</span>
                                  )}
                               </div>
                            </td>
                            <td className="p-3 text-right font-bold text-slate-800">
                               {formatPrice(product.price)}
                            </td>
                            <td className="p-3 text-center">
                               <span className={`text-xs font-bold px-2 py-1 rounded ${product.stock > (product.minStock||0) ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'}`}>
                                  {product.stock} {product.unit}
                               </span>
                            </td>
                            <td className="p-3 text-right">
                               {hasVariants ? (
                                  <div className="flex flex-wrap justify-end gap-1.5">
                                     {product.variants!.map(v => (
                                        <button 
                                           key={v.id}
                                           onClick={(e) => { e.stopPropagation(); addToCart(product, undefined, v.id); }}
                                           className="px-2 py-1 text-xs bg-white border border-slate-300 rounded hover:bg-orange-50 hover:text-orange-700 hover:border-orange-200 font-medium transition-colors shadow-sm"
                                        >
                                           {v.name}
                                        </button>
                                     ))}
                                  </div>
                               ) : (
                                  <button className="px-4 py-1.5 bg-slate-900 text-white rounded-lg text-xs font-bold hover:bg-orange-600 transition-colors shadow-sm flex items-center ml-auto">
                                     <Plus className="w-3.5 h-3.5 mr-1" /> Add
                                  </button>
                               )}
