import React, { useState, useMemo } from 'react';
import { Product, Category } from '../../types';
import { Search, Box, ScanBarcode, LayoutGrid, List, Plus } from 'lucide-react';
import { useGlobal } from '../../context/GlobalContext';
import { useCartStore } from '../../store/useCartStore';

interface ProductGridProps {
  products: Product[];
  onScanClick: () => void;
  searchTerm: string;
  setSearchTerm: (term: string) => void;
  onScan: (code: string) => void; // Passed down for handleBarcodeScan form submission
}

export const ProductGrid: React.FC<ProductGridProps> = ({ 
  products, 
  onScanClick,
  searchTerm,
  setSearchTerm,
  onScan
}) => {
  const { formatPrice, t } = useGlobal();
  const addToCart = useCartStore((state) => state.addToCart);
  const [selectedCategory, setSelectedCategory] = useState<string>('all');
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const searchLower = searchTerm.toLowerCase();
      const matchesMain = 
        p.name.toLowerCase().includes(searchLower) ||
        p.sku?.toLowerCase().includes(searchLower) ||
        p.barcode?.includes(searchLower);

      const matchesVariant = p.variants && p.variants.some(v => 
        v.code.toLowerCase().includes(searchLower) || 
        v.barcode.includes(searchLower)
      );

      const matchesCategory = selectedCategory === 'all' || p.category === selectedCategory;
      return (matchesMain || matchesVariant) && matchesCategory;
    });
  }, [products, searchTerm, selectedCategory]);

  const handleFormSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchTerm) return;
    onScan(searchTerm);
  };

  return (
    <div className="flex flex-col h-full">
      {/* Search & Filter */}
      <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-200 mb-4 space-y-3">
        <div className="flex flex-col md:flex-row gap-3">
          <form onSubmit={handleFormSubmit} className="relative flex-1 flex gap-2">
            <div className="relative flex-1">
               <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-slate-400 w-5 h-5" />
               <input
                 id="pos-search-input"
                 type="text"
                 placeholder={t('pos.scanPlaceholder')}
                 className="w-full pl-10 pr-4 py-3 border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-orange-500 text-slate-700 bg-slate-50 font-medium"
                 value={searchTerm}
                 onChange={(e) => setSearchTerm(e.target.value)}
                 autoFocus
               />
            </div>
            <button type="button" onClick={onScanClick} className="bg-slate-800 text-white px-4 rounded-xl hover:bg-slate-900 shadow-md">
               <ScanBarcode className="w-6 h-6" />
            </button>
          </form>

          {/* View Toggle */}
          <div className="flex bg-slate-100 p-1 rounded-xl border border-slate-200 shrink-0 h-[50px] items-center self-end md:self-auto">
             <button 
                onClick={() => setViewMode('list')} 
                className={`p-2.5 rounded-lg transition-all ${viewMode === 'list' ? 'bg-white shadow-sm text-slate-800' : 'text-slate-400 hover:text-slate-600'}`}
                title="List View"
             >
                <List className="w-5 h-5" />
             </button>
             <button 
                onClick={() => setViewMode('grid')} 
                className={`p-2.5 rounded-lg transition-all ${viewMode === 'grid' ? 'bg-white shadow-sm text-slate-800' : 'text-slate-400 hover:text-slate-600'}`}
                title="Grid View"
             >
                <LayoutGrid className="w-5 h-5" />
             </button>
          </div>
        </div>

        <div className="flex gap-2 overflow-x-auto pb-1 scrollbar-hide">
          <button onClick={() => setSelectedCategory('all')} className={`px-4 py-2 rounded-full text-xs font-bold whitespace-nowrap border ${selectedCategory === 'all' ? 'bg-slate-800 text-white border-slate-800' : 'bg-white text-slate-600 border-slate-200'}`}>{t('pos.allItems')}</button>
          {Object.values(Category).map(cat => (
            <button key={cat} onClick={() => setSelectedCategory(cat)} className={`px-4 py-2 rounded-full text-xs font-bold whitespace-nowrap border ${selectedCategory === cat ? 'bg-orange-500 text-white border-orange-500' : 'bg-white text-slate-600 border-slate-200'}`}>{cat}</button>
          ))}
        </div>
      </div>

      {/* Products Display */}
      <div className="flex-1 overflow-y-auto pb-20 md:pb-0">
        {filteredProducts.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-64 text-slate-400">
            <Box className="w-12 h-12 mb-2 opacity-30" />
            <p>No products found.</p>
          </div>
        ) : viewMode === 'grid' ? (
          // GRID VIEW
          <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-4">
            {filteredProducts.map((product) => (
              <div key={product.id} onClick={() => !product.variants?.length && addToCart(product, undefined)} className="bg-white rounded-xl shadow-sm border border-slate-100 overflow-hidden hover:shadow-lg hover:border-orange-200 transition-all cursor-pointer flex flex-col group h-full">
                <div className="h-32 bg-slate-50 relative flex items-center justify-center overflow-hidden">
                  {product.imageUrl ? (
                    <img src={product.imageUrl} alt={product.name} className="w-full h-full object-cover" />
                  ) : (
                    <Box className="w-10 h-10 text-slate-300" />
                  )}
                  <span className={`absolute top-2 right-2 px-2 py-0.5 rounded text-[10px] font-bold text-white shadow-sm ${product.stock > (product.minStock || 0) ? 'bg-green-500' : 'bg-red-500'}`}>
                    {product.stock} {product.unit}
                  </span>
                  {product.minOrderQuantity && product.minOrderQuantity > 1 && (
                     <span className="absolute bottom-2 left-2 px-2 py-0.5 rounded text-[10px] font-bold text-slate-600 bg-white/90 shadow-sm border border-slate-200">
                        MOQ: {product.minOrderQuantity}
                     </span>
                  )}
                </div>
                <div className="p-3 flex-1 flex flex-col">
                  <h3 className="font-bold text-slate-800 text-sm line-clamp-2 mb-1">{product.name}</h3>
                  <div className="mt-auto pt-2">
                    <div className="flex justify-between items-center mb-2">
                      <span className="font-bold text-slate-900">{formatPrice(product.price)}</span>
                    </div>
                    {product.variants?.length ? (
                      <div className="grid grid-cols-2 gap-1">
                         {product.variants.map(v => (
                           <button key={v.id} onClick={(e) => { e.stopPropagation(); addToCart(product, undefined, v.id); }} className="px-2 py-1.5 bg-slate-100 hover:bg-orange-100 text-xs font-bold rounded text-slate-700 hover:text-orange-700 border border-slate-200 truncate">
                              {v.name}
