                               {hasVariants ? (
                                  <div className="flex flex-wrap justify-end gap-1.5">
                                     {product.variants!.map(v => (
                                        <button 
                                           key={v.id}
                                           onClick={(e) => { e.stopPropagation(); addToCart(product, undefined, v.id); }}
                                           className="px-2 py-1 text-xs bg-white border border-slate-300 rounded hover:bg-orange-50 hover:text-orange-700 hover:border-orange-200 font-medium transition-colors shadow-sm"
