  // Modals State
  const [isScheduleModalOpen, setIsScheduleModalOpen] = useState(false);
  const [editingScheduleId, setEditingScheduleId] = useState<string | null>(null);
  const [viewingReport, setViewingReport] = useState<ZReportData | null>(null);

  // Derived State
  const activeShift = shifts.find(s => s.userId === currentUser?.id && s.status === 'Open');
  const todaySchedule = useMemo(() => {
    if (!currentUser) return undefined;
    const todayStr = new Date().toISOString().split('T')[0];
    return shiftSchedules.find(s => s.userId === currentUser.id && s.date === todayStr);
  }, [shiftSchedules, currentUser]);

  const historyShifts = useMemo(() => {
    let filtered = shifts;
    if (currentUser?.role !== 'Admin' && currentUser?.role !== 'Manager') {
      filtered = filtered.filter(s => s.userId === currentUser?.id);
    }
    return filtered.sort((a, b) => new Date(b.startTime).getTime() - new Date(a.startTime).getTime());
  }, [shifts, currentUser]);

  const canPlanShifts = currentUser?.role === 'Admin' || currentUser?.role === 'Manager';
  const selectedBranchId = currentUser?.branchId || settings.currentBranchId || branches[0]?.id || '';

  // Auto-clone logic for calendar (simplified version of original hook)
  useEffect(() => {
    if (activeTab !== 'planning') return;
    const currentYear = calendarDate.getFullYear();
    const currentMonth = calendarDate.getMonth();

    // Check if empty
    const hasCurrent = shiftSchedules.some(s => {
       const d = new Date(s.date);
       return d.getMonth() === currentMonth && d.getFullYear() === currentYear;
    });

    if (!hasCurrent) {
       // Check prev month
       const prevDate = new Date(currentYear, currentMonth - 1, 1);
       const prevSchedules = shiftSchedules.filter(s => {
          const d = new Date(s.date);
          return d.getMonth() === prevDate.getMonth() && d.getFullYear() === prevDate.getFullYear();
       });

       if (prevSchedules.length > 0) {
          console.log("Auto-populating roster...");
          prevSchedules.forEach((oldSch, idx) => {
             const oldDate = new Date(oldSch.date);
             const targetDate = new Date(currentYear, currentMonth, oldDate.getDate());
             // Basic copy
             if (targetDate.getMonth() === currentMonth) {
                addShiftSchedule({
                   ...oldSch,
                   id: `auto-${Date.now()}-${idx}`,
                   date: targetDate.toISOString().split('T')[0],
                   isSwap: false
                });
             }
          });
       }
    }
  }, [activeTab, calendarDate, shiftSchedules, addShiftSchedule]);

  // Handlers
  const handleOpenAddSchedule = () => {
    setEditingScheduleId(null);
    setIsScheduleModalOpen(true);
  };

  const handleOpenEditSchedule = (schedule: ShiftSchedule) => {
    setEditingScheduleId(schedule.id);
    setIsScheduleModalOpen(true);
  };

  const handleSaveSchedule = (formData: any, isRecurring: boolean, recurringDays: number[]) => {
    if (editingScheduleId) {
       // Update Single
       const original = shiftSchedules.find(s => s.id === editingScheduleId);
       const isSwap = original && original.userId !== formData.userId;
       const originalUserId = (isSwap && !original?.originalUserId) ? original?.userId : original?.originalUserId;

       updateShiftSchedule({
          id: editingScheduleId,
          date: original ? original.date : planningDate,
          userId: formData.userId,
          branchId: formData.branchId,
          startTime: formData.startTime,
          endTime: formData.endTime,
          note: formData.note,
          isSwap: isSwap || original?.isSwap,
          originalUserId: originalUserId
       });
    } else {
       // Add New
       if (isRecurring) {
          const year = calendarDate.getFullYear();
          const month = calendarDate.getMonth();
          const daysInMonth = new Date(year, month + 1, 0).getDate();
          let count = 0;

          for (let i = 1; i <= daysInMonth; i++) {
             const d = new Date(year, month, i);
             if (recurringDays.includes(d.getDay())) {
                addShiftSchedule({
                   id: `sch-${Date.now()}-${count++}`,
                   date: d.toISOString().split('T')[0],
                   userId: formData.userId,
                   branchId: formData.branchId,
                   startTime: formData.startTime,
                   endTime: formData.endTime,
                   note: formData.note
                });
             }
          }
       } else {
          addShiftSchedule({
             id: `sch-${Date.now()}`,
             date: planningDate,
             userId: formData.userId,
             branchId: formData.branchId,
             startTime: formData.startTime,
             endTime: formData.endTime,
             note: formData.note
          });
       }
    }
    setIsScheduleModalOpen(false);
  };

  const handleRevertSwap = (id: string) => {
     const s = shiftSchedules.find(x => x.id === id);
     if (s && s.originalUserId) {
        if(confirm("Revert to original user?")) {
           updateShiftSchedule({ ...s, userId: s.originalUserId, originalUserId: undefined, isSwap: false });
           setIsScheduleModalOpen(false);
        }
     }
  };

  const generateZReport = (shift: Shift) => {
    // Re-implement report logic using global sales/data
    const start = new Date(shift.startTime);
    const end = shift.endTime ? new Date(shift.endTime) : new Date();

    const shiftSales = sales.filter(s => {
      const sDate = new Date(s.date);
      return sDate >= start && sDate <= end && s.status !== 'voided';
    });

    const salesByMethod: Record<string, number> = {};
    let totalSales = 0;
    let cashReceived = 0;
    let cashChange = 0;

    shiftSales.forEach(s => {
      const method = s.paymentMethod;
      salesByMethod[method] = (salesByMethod[method] || 0) + s.total;
      totalSales += s.total;
      if (method === 'cash') {
         cashReceived += (s.amountReceived || s.total);
         cashChange += (s.change || 0);
      }
    });

    const txns = shift.cashTransactions || [];
    const cashIn = txns.filter(t => t.type === 'in').reduce((sum, t) => sum + t.amount, 0);
    const cashOut = txns.filter(t => t.type === 'out').reduce((sum, t) => sum + t.amount, 0);
    const netCashSales = cashReceived - cashChange;
    const expectedCash = shift.startCash + netCashSales + cashIn - cashOut;
    const actualEndCash = shift.endCash || 0; 

    setViewingReport({
      shiftId: shift.id,
      user: users.find(u => u.id === shift.userId)?.name || 'Unknown',
      branch: branches.find(b => b.id === shift.branchId)?.name || 'Unknown',
      posMachine: shift.posId ? (posMachines.find(p => p.id === shift.posId)?.machineNumber || shift.posId) : 'N/A',
      start: start.toLocaleString(),
      end: shift.status === 'Open' ? 'Running...' : end.toLocaleString(),
      startCash: shift.startCash,
      endCash: actualEndCash,
      totalSales,
      salesByMethod,
      cashReceived,
      cashChange,
      expectedCash,
      discrepancy: actualEndCash - expectedCash,
      transactionCount: shiftSales.length,
      cashIn,
      cashOut,
      notes: shift.notes
    });
  };

  return (
    <div className="space-y-6 h-full flex flex-col pb-20 md:pb-0">
      <div className="flex flex-col md:flex-row justify-between items-center gap-4 print:hidden">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">Shift Management</h2>
          <p className="text-slate-500">Track working hours and manage staff schedules.</p>
        </div>

        {/* Style A: Pill Toggle */}
        <div className="flex bg-slate-100 p-1 rounded-xl w-fit">
           <button
             onClick={() => setActiveTab('attendance')}
             className={`flex items-center px-6 py-2.5 rounded-lg text-sm font-bold transition-all ${
               activeTab === 'attendance' 
                 ? 'bg-white text-slate-900 shadow-sm' 
                 : 'text-slate-500 hover:text-slate-700'
             }`}
           >
             <Clock className="w-4 h-4 mr-2" />
             Time Clock
           </button>
           {canPlanShifts && (
             <button
               onClick={() => setActiveTab('planning')}
               className={`flex items-center px-6 py-2.5 rounded-lg text-sm font-bold transition-all ${
                 activeTab === 'planning' 
                   ? 'bg-white text-slate-900 shadow-sm' 
                   : 'text-slate-500 hover:text-slate-700'
               }`}
             >
               <CalendarDays className="w-4 h-4 mr-2" />
               Roster
             </button>
           )}
        </div>
      </div>

      {activeTab === 'attendance' && (
        <ShiftAttendance 
          shifts={shifts}
          branches={branches}
          posMachines={posMachines}
          users={users}
          currentUser={currentUser}
          settings={settings}
          activeShift={activeShift}
          todaySchedule={todaySchedule}
          historyShifts={historyShifts}
          onStartShift={onStartShift}
          onEndShift={onEndShift}
          onAddCashTransaction={addCashTransaction}
          onGenerateReport={generateZReport}
        />
      )}

      {activeTab === 'planning' && (
        <ShiftRoster 
          shiftSchedules={shiftSchedules}
          shifts={shifts}
          users={users}
          branches={branches}
          canPlanShifts={canPlanShifts}
          onAddSchedule={handleOpenAddSchedule}
          onEditSchedule={handleOpenEditSchedule}
          onDeleteSchedule={deleteShiftSchedule}
          planningDate={planningDate}
          setPlanningDate={setPlanningDate}
          calendarDate={calendarDate}
          setCalendarDate={setCalendarDate}
        />
      )}

      <ScheduleModal 
        isOpen={isScheduleModalOpen}
        onClose={() => setIsScheduleModalOpen(false)}
        branches={branches}
        users={users}
        editingScheduleId={editingScheduleId}
        shiftSchedules={shiftSchedules}
        planningDate={planningDate}
        selectedBranchId={selectedBranchId}
        calendarDate={calendarDate}
        onSave={handleSaveSchedule}
        onRevertSwap={handleRevertSwap}
      />

      <ZReportModal 
        report={viewingReport}
        onClose={() => setViewingReport(null)}
      />
    </div>
  );
};

import React, { useState } from 'react';
import { Customer, CustomerLevel, Sale } from '../types';
import { useGlobal } from '../context/GlobalContext';
import { Plus, Search } from 'lucide-react';

// Sub-components
import { CustomerList } from './customer/CustomerList';
import { CustomerFormModal } from './customer/CustomerFormModal';
import { LevelManagement } from './customer/LevelManagement';
import { LevelFormModal } from './customer/LevelFormModal';
import { CustomerDetailProfile } from './customer/CustomerDetailProfile';

interface CustomerManagementProps {
  customers: Customer[];
  sales?: Sale[];
  onAddCustomer: (customer: Customer) => void;
  onUpdateCustomer: (customer: Customer) => void;
  onDeleteCustomer: (id: string) => void;
}

export const CustomerManagement: React.FC<CustomerManagementProps> = ({
  customers = [],
  sales = [],
  onAddCustomer,
  onUpdateCustomer,
  onDeleteCustomer
}) => {
  const { 
    customerLevels, 
    addCustomerLevel, 
    updateCustomerLevel, 
    deleteCustomerLevel, 
    formatPrice 
  } = useGlobal();

  const safeLevels = customerLevels || []; 

  const [activeTab, setActiveTab] = useState<'customers' | 'levels'>('customers');
  const [viewingCustomer, setViewingCustomer] = useState<Customer | null>(null);

  // Modal States
  const [isCustomerModalOpen, setIsCustomerModalOpen] = useState(false);
  const [editingCustomer, setEditingCustomer] = useState<Customer | undefined>(undefined);

  const [isLevelModalOpen, setIsLevelModalOpen] = useState(false);
  const [editingLevel, setEditingLevel] = useState<CustomerLevel | undefined>(undefined);

  // --- Handlers for Customer ---
  const handleOpenCustomerModal = (customer?: Customer) => {
    setEditingCustomer(customer);
    setIsCustomerModalOpen(true);
  };

  const handleCustomerSubmit = (customer: Customer) => {
    if (customer.id) {
      onUpdateCustomer(customer);
    } else {
      onAddCustomer({ ...customer, id: `c-${Date.now()}` });
    }
  };

  const handleDeleteCustomer = (id: string) => {
    if(confirm('Are you sure you want to delete this customer?')) {
      onDeleteCustomer(id);
      if (viewingCustomer?.id === id) setViewingCustomer(null);
    }
  };

  // --- Handlers for Levels ---
  const handleOpenLevelModal = (level?: CustomerLevel) => {
    setEditingLevel(level);
    setIsLevelModalOpen(true);
  };

  const handleLevelSubmit = (level: CustomerLevel) => {
    if (level.id) {
      updateCustomerLevel(level);
    } else {
      addCustomerLevel({ ...level, id: `lvl-${Date.now()}` });
    }
  };

  const handleDeleteLevel = (id: string) => {
    if(confirm('Delete this membership level?')) {
      deleteCustomerLevel(id);
    }
  };

  if (viewingCustomer) {
    return (
      <CustomerDetailProfile 
        customer={viewingCustomer}
        sales={sales}
        formatPrice={formatPrice}
        onBack={() => setViewingCustomer(null)}
        onEdit={() => handleOpenCustomerModal(viewingCustomer)}
      />
    );
  }

  return (
    <div className="space-y-6 h-full flex flex-col pb-20 md:pb-0">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">Customer Management</h2>
          <p className="text-slate-500">Manage customer profiles and membership tiers.</p>
        </div>

        {/* Style A: Primary Button */}
        {activeTab === 'customers' && (
           <button 
             onClick={() => handleOpenCustomerModal()}
             className="flex items-center px-6 py-3 bg-slate-900 text-white rounded-xl hover:bg-slate-800 transition-all font-bold shadow-sm whitespace-nowrap"
           >
             <Plus className="w-5 h-5 mr-2" />
             Add Customer
           </button>
        )}
      </div>

      {/* Style A: Pill Tabs */}
      <div className="flex bg-slate-100 p-1 rounded-xl w-fit">
         <button 
          onClick={() => setActiveTab('customers')}
          className={`px-6 py-2.5 rounded-lg text-sm font-bold transition-all whitespace-nowrap ${
             activeTab === 'customers' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'
          }`}
        >
          Customers
        </button>
        <button 
          onClick={() => setActiveTab('levels')}
          className={`px-6 py-2.5 rounded-lg text-sm font-bold transition-all whitespace-nowrap ${
             activeTab === 'levels' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'
          }`}
        >
          Membership Levels
        </button>
      </div>

      {activeTab === 'customers' && (
        <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden flex-1 flex flex-col">
           <CustomerList 
             customers={customers}
             levels={safeLevels}
             onAdd={() => handleOpenCustomerModal()}
             onEdit={handleOpenCustomerModal}
             onDelete={handleDeleteCustomer}
             onView={setViewingCustomer}
           />
        </div>
      )}

      {activeTab === 'levels' && (
        <LevelManagement 
          levels={safeLevels}
          onAdd={() => handleOpenLevelModal()}
          onEdit={handleOpenLevelModal}
          onDelete={handleDeleteLevel}
        />
      )}

      {/* Modals */}
      <CustomerFormModal 
        isOpen={isCustomerModalOpen}
        onClose={() => setIsCustomerModalOpen(false)}
        onSubmit={handleCustomerSubmit}
        initialData={editingCustomer}
        levels={safeLevels}
      />

      <LevelFormModal 
        isOpen={isLevelModalOpen}
        onClose={() => setIsLevelModalOpen(false)}
        onSubmit={handleLevelSubmit}
        initialData={editingLevel}
      />
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { Sale, Product, BusinessInsight } from '../types';
import { CalendarRange, Sparkles } from 'lucide-react';
import { INITIAL_CATEGORIES_TREE } from '../services/data';
import { useGlobal } from '../context/GlobalContext';
import { generateBusinessInsights } from '../services/geminiService';

// Sub-components
import { DashboardStats } from './dashboard/DashboardStats';
import { AiInsightPanel } from './dashboard/AiInsightPanel';
import { LowStockAlert } from './dashboard/LowStockAlert';
import { SalesTrendChart } from './dashboard/SalesTrendChart';
import { CategoryPieChart } from './dashboard/CategoryPieChart';
import { RecentActivity } from './dashboard/RecentActivity';
import { TopProductsTable } from './dashboard/TopProductsTable';

interface DashboardProps {
  sales: Sale[];
  products: Product[];
}

const COLORS = ['#0088FE', '#00C49F', '#FFBB28', '#FF8042', '#8884d8', '#82ca9d', '#ffc658'];

type TimeRange = '7d' | '30d' | '90d' | 'all';

export const Dashboard: React.FC<DashboardProps> = ({ sales, products }) => {
  const { t, formatPrice, auditLogs, settings } = useGlobal();
  const [timeRange, setTimeRange] = useState<TimeRange>('30d');

  // AI State
  const [insight, setInsight] = useState<BusinessInsight | null>(null);
  const [loadingInsight, setLoadingInsight] = useState(false);

  // 1. Filter Sales based on Time Range
  const dashboardMetrics = useMemo(() => {
    const today = new Date();
    let startDate = new Date();

    if (timeRange === '7d') startDate.setDate(today.getDate() - 7);
    else if (timeRange === '30d') startDate.setDate(today.getDate() - 30);
    else if (timeRange === '90d') startDate.setDate(today.getDate() - 90);
    else startDate = new Date(0); // Beginning of time

    // Filter sales strictly by date range and non-voided status
    const filteredSales = sales.filter(s => {
       const saleDate = new Date(s.date);
       return saleDate >= startDate && saleDate <= today && s.status !== 'voided';
    });

    const totalRevenue = filteredSales.reduce((acc, s) => acc + s.total, 0);
    const totalOrders = filteredSales.length;

    // Average Order Value
    const aov = totalOrders > 0 ? totalRevenue / totalOrders : 0;

    return { filteredSales, totalRevenue, totalOrders, aov, startDate };
  }, [sales, timeRange]);

  // 2. Dynamic Trend Data
  const trendData = useMemo(() => {
    const dailyMap = new Map<string, number>();
    const today = new Date();

    let daysToGenerate = 30;
    if (timeRange === '7d') daysToGenerate = 7;
    else if (timeRange === '90d') daysToGenerate = 90;
    else if (timeRange === 'all') daysToGenerate = 60; 

    for(let i = daysToGenerate - 1; i >= 0; i--) {
        const d = new Date(today);
        d.setDate(d.getDate() - i);
        const key = d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
        dailyMap.set(key, 0);
    }

    dashboardMetrics.filteredSales.forEach(sale => {
      const dateStr = new Date(sale.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
      if (dailyMap.has(dateStr)) {
        dailyMap.set(dateStr, (dailyMap.get(dateStr) || 0) + sale.total);
      }
    });

    const data = Array.from(dailyMap).map(([name, sales]) => ({ name, sales, projected: 0 }));

    // Inject Projection if available
    if (insight && insight.predictedRevenueNextWeek > 0) {
       const dailyAvg = insight.predictedRevenueNextWeek / 7;
       // Add 3 days of projection to end of chart
       for (let i = 1; i <= 3; i++) {
          const d = new Date();
          d.setDate(d.getDate() + i);
          const key = d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
          data.push({ name: key + ' (Est)', sales: 0, projected: dailyAvg });
       }
    }

    return data;
  }, [dashboardMetrics.filteredSales, timeRange, insight]);

  // 3. Category Breakdown
  const categoryData = useMemo(() => {
    const catMap = new Map<string, number>();

    dashboardMetrics.filteredSales.forEach(sale => {
      sale.items.forEach(item => {
        let catName = item.category;
        const catObj = INITIAL_CATEGORIES_TREE.find(c => c.id === item.category);
        if (catObj) catName = catObj.name;

        const lineTotal = item.sellPrice * item.quantity;
        catMap.set(catName, (catMap.get(catName) || 0) + lineTotal);
      });
    });

    const result = Array.from(catMap)
      .map(([name, value]) => ({ name, value }))
      .sort((a, b) => b.value - a.value);

    if (result.length > 5) {
       const top5 = result.slice(0, 5);
       const others = result.slice(5).reduce((sum, item) => sum + item.value, 0);
       return [...top5, { name: 'Others', value: others }];
    }
    return result;
  }, [dashboardMetrics.filteredSales]);

  // 4. Top Selling Products
  const topProducts = useMemo(() => {
    const prodMap = new Map<string, { name: string; revenue: number; qty: number; unit: string }>();

    dashboardMetrics.filteredSales.forEach(sale => {
      sale.items.forEach(item => {
        const existing = prodMap.get(item.id) || { name: item.name, revenue: 0, qty: 0, unit: item.unit };
        existing.revenue += (item.sellPrice * item.quantity);
        existing.qty += (item.quantity / (item.sellConversionFactor || 1));
        prodMap.set(item.id, existing);
      });
    });

    return Array.from(prodMap.values())
      .sort((a, b) => b.revenue - a.revenue)
      .slice(0, 5);
  }, [dashboardMetrics.filteredSales]);

  // Low Stock Logic
  const lowStockProducts = products.filter(p => p.stock < (p.minStock || 20)).sort((a, b) => a.stock - b.stock);

  // Outstanding Debt
  const totalOutstanding = useMemo(() => {
     return sales
        .filter(s => s.status !== 'voided' && (s.paymentStatus === 'unpaid' || s.paymentStatus === 'partial'))
        .reduce((acc, s) => acc + (s.remainingAmount || s.total), 0);
  }, [sales]);

  // Recent Logs (Latest 5)
  const recentLogs = useMemo(() => {
     return [...auditLogs].sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()).slice(0, 5);
  }, [auditLogs]);

  // Calculate Target Progress (Monthly)
  const currentMonthRevenue = useMemo(() => {
     const now = new Date();
     return sales.filter(s => {
        const d = new Date(s.date);
        return d.getMonth() === now.getMonth() && d.getFullYear() === now.getFullYear() && s.status !== 'voided';
     }).reduce((acc, s) => acc + s.total, 0);
  }, [sales]);

  const targetProgress = settings.monthlyTarget ? (currentMonthRevenue / settings.monthlyTarget) * 100 : 0;

  // AI Handler
  const handleGenerateInsight = async () => {
    setLoadingInsight(true);
    const recentSales = sales.filter(s => {
       const d = new Date(s.date);
       const thirtyDaysAgo = new Date();
       thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
       return d >= thirtyDaysAgo && s.status !== 'voided';
    });
    const result = await generateBusinessInsights(recentSales, products);
    setInsight(result);
    setLoadingInsight(false);
  };

  return (
    <div className="space-y-6 animate-fade-in pb-12">
      {/* Header & Filter */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">{t('dashboard.title')}</h2>
          <p className="text-slate-500 text-sm flex items-center mt-1">
            <CalendarRange className="w-4 h-4 mr-1" />
            Performance Overview
          </p>
        </div>

        <div className="flex items-center gap-3">
           <button 
             onClick={handleGenerateInsight}
             disabled={loadingInsight}
             className="flex items-center px-4 py-2 bg-gradient-to-r from-violet-600 to-indigo-600 text-white rounded-xl shadow-md hover:shadow-lg transition-all text-sm font-bold disabled:opacity-70"
           >
             <Sparkles className={`w-4 h-4 mr-2 ${loadingInsight ? 'animate-spin' : ''}`} />
             {loadingInsight ? 'Analyzing...' : 'AI Analyst'}
           </button>

           {/* Style A: Pill Segmented Control */}
           <div className="bg-slate-100 p-1 rounded-xl flex">
              {(['7d', '30d', '90d', 'all'] as const).map((range) => (
                 <button
                   key={range}
                   onClick={() => setTimeRange(range)}
                   className={`px-4 py-2 rounded-lg text-sm font-bold transition-all whitespace-nowrap ${
                      timeRange === range 
                      ? 'bg-white text-slate-900 shadow-sm' 
                      : 'text-slate-500 hover:text-slate-700'
                   }`}
                 >
                    {range === '7d' ? '7 Days' : range === '30d' ? '30 Days' : range === '90d' ? '3 Months' : 'All Time'}
                 </button>
              ))}
           </div>
        </div>
      </div>

      {/* KPI Cards */}
      <DashboardStats 
        metrics={dashboardMetrics}
        totalOutstanding={totalOutstanding}
        lowStockCount={lowStockProducts.length}
        productCount={products.length}
        targetProgress={targetProgress}
        showTarget={timeRange === '30d'}
        formatPrice={formatPrice}
        t={t}
      />

      {/* AI Insight Panel */}
      {insight && <AiInsightPanel insight={insight} formatPrice={formatPrice} />}

      {/* Low Stock Alert */}
