import React, { useState, useMemo } from 'react';
import { Sale, Product } from '../types';
import { 
  Download, 
  Calendar, 
  TrendingUp, 
  Package, 
  AlertTriangle,
  Users,
  Clock,
} from 'lucide-react';
import { useGlobal } from '../context/GlobalContext';

// Sub-components
import { SalesAnalytics } from './reports/SalesAnalytics';
import { StaffPerformance } from './reports/StaffPerformance';
import { HourlyTraffic } from './reports/HourlyTraffic';
import { InventoryValuation } from './reports/InventoryValuation';

interface ReportsManagementProps {
  sales: Sale[];
  products: Product[];
}

type ReportType = 'sales' | 'inventory' | 'low-stock' | 'staff' | 'hourly';

export const ReportsManagement: React.FC<ReportsManagementProps> = ({ sales, products }) => {
  const { formatPrice } = useGlobal();
  const [activeTab, setActiveTab] = useState<ReportType>('sales');

  // Date Filters
  const [startDate, setStartDate] = useState(new Date(new Date().setDate(new Date().getDate() - 30)).toISOString().split('T')[0]);
  const [endDate, setEndDate] = useState(new Date().toISOString().split('T')[0]);

  // --- Filtered Sales Helper ---
  const filteredSales = useMemo(() => {
    const start = new Date(startDate);
    const end = new Date(endDate);
    end.setHours(23, 59, 59, 999);

    return sales.filter(s => {
      const d = new Date(s.date);
      return d >= start && d <= end && s.status !== 'voided';
    });
  }, [sales, startDate, endDate]);

  // --- Sales Report Logic ---
  const salesReportData = useMemo(() => {
    const dailyData = new Map<string, { date: string; revenue: number; profit: number; count: number }>();
    let totalRevenue = 0;
    let totalProfit = 0;
    let totalCost = 0;

    filteredSales.forEach(sale => {
      const dateKey = new Date(sale.date).toLocaleDateString('en-US');

      let saleCost = 0;
      sale.items.forEach(item => {
         const product = products.find(p => p.id === item.id);
         let unitCost = product?.costPrice || 0;

         if (item.selectedVariantId && product?.variants) {
            const variant = product.variants.find(v => v.id === item.selectedVariantId);
            if (variant && variant.costPrice) {
               unitCost = variant.costPrice;
            } else if (variant && variant.conversionFactor) {
               unitCost = (product?.costPrice || 0) / variant.conversionFactor;
            }
         }
         saleCost += unitCost * item.quantity;
      });

      const saleProfit = sale.total - saleCost;
      totalRevenue += sale.total;
      totalCost += saleCost;
      totalProfit += saleProfit;

      const existing = dailyData.get(dateKey) || { date: dateKey, revenue: 0, profit: 0, count: 0 };
      existing.revenue += sale.total;
      existing.profit += saleProfit;
      existing.count += 1;
      dailyData.set(dateKey, existing);
    });

    const chartData = Array.from(dailyData.values()).sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    return { totalRevenue, totalCost, totalProfit, chartData };
  }, [filteredSales, products]);

  // --- Inventory Report Logic ---
  const inventoryReportData = useMemo(() => {
    let totalStockValue = 0; 
    let totalRetailValue = 0; 
    let totalItems = 0;

    const reportItems = products.map(p => {
      const stockVal = p.stock * (p.costPrice || 0);
      const retailVal = p.stock * p.price;

      totalStockValue += stockVal;
      totalRetailValue += retailVal;
      totalItems += p.stock;

      return {
        ...p,
        stockValue: stockVal,
        retailValue: retailVal,
        margin: p.costPrice ? ((p.price - p.costPrice) / p.price) * 100 : 100
      };
    });

    return { reportItems, totalStockValue, totalRetailValue, totalItems };
  }, [products]);

  // --- Staff Performance Logic ---
  const staffReportData = useMemo(() => {
    const staffMap = new Map<string, { id: string; name: string; revenue: number; count: number }>();

    filteredSales.forEach(s => {
        const uid = s.userId || 'unknown';
        const uName = s.userName || 'Unknown Staff';

        const existing = staffMap.get(uid) || { id: uid, name: uName, revenue: 0, count: 0 };
        existing.revenue += s.total;
        existing.count += 1;
        staffMap.set(uid, existing);
    });

    return Array.from(staffMap.values()).sort((a, b) => b.revenue - a.revenue);
  }, [filteredSales]);

  // --- Hourly Heatmap Logic ---
  const hourlyReportData = useMemo(() => {
    const hours = Array(24).fill(0).map((_, i) => ({ 
        hour: i, 
        label: `${String(i).padStart(2, '0')}:00`, 
        revenue: 0, 
        count: 0 
    }));

    filteredSales.forEach(s => {
        const h = new Date(s.date).getHours();
        if (hours[h]) {
            hours[h].revenue += s.total;
            hours[h].count += 1;
        }
    });

    return hours;
  }, [filteredSales]);

  // --- CSV Export Logic ---
  const handleExport = () => {
    let csvContent = "data:text/csv;charset=utf-8,";

    if (activeTab === 'sales') {
      csvContent += "Date,Invoice ID,Customer,Items,Total,Profit,Payment Method\n";
      filteredSales.forEach(s => {
        let cost = 0;
        s.items.forEach(i => {
           const p = products.find(prod => prod.id === i.id);
           cost += (p?.costPrice || 0) * i.quantity;
        });
        const profit = s.total - cost;
        csvContent += `${new Date(s.date).toLocaleDateString()},${s.id},"${s.customerName || 'Walk-in'}",${s.items.length},${s.total},${profit},${s.paymentMethod}\n`;
      });
    } else if (activeTab === 'inventory' || activeTab === 'low-stock') {
      csvContent += "Name,SKU,Category,Stock,Unit,Cost Price,Sell Price,Total Cost Value,Total Retail Value\n";
      const targetList = activeTab === 'low-stock' 
        ? inventoryReportData.reportItems.filter(p => p.stock <= (p.minStock || 0))
        : inventoryReportData.reportItems;

      targetList.forEach(p => {
        csvContent += `"${p.name}",${p.sku},${p.category},${p.stock},${p.unit},${p.costPrice || 0},${p.price},${p.stockValue},${p.retailValue}\n`;
      });
    } else if (activeTab === 'staff') {
      csvContent += "Staff Name,Transactions,Revenue,Avg Ticket\n";
      staffReportData.forEach(s => {
        csvContent += `"${s.name}",${s.count},${s.revenue},${s.count > 0 ? s.revenue/s.count : 0}\n`;
      });
    }

    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", `${activeTab}_report_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6 h-full flex flex-col pb-20 md:pb-0">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">Reports & Analytics</h2>
          <p className="text-slate-500">Business intelligence and financial insights.</p>
        </div>
        <button 
          onClick={handleExport}
          className="flex items-center justify-center px-6 py-2.5 bg-slate-900 text-white rounded-xl hover:bg-slate-800 transition-colors font-bold text-sm shadow-sm"
        >
          <Download className="w-4 h-4 mr-2" />
          Export CSV
        </button>
      </div>

      {/* Tabs - Style A: Pill Toggle */}
      <div className="overflow-x-auto pb-2 -mx-4 px-4 md:mx-0 md:px-0 md:pb-0 scrollbar-hide">
        <div className="flex space-x-1 bg-slate-100 p-1 rounded-xl w-fit min-w-max">
          <button
            onClick={() => setActiveTab('sales')}
            className={`flex items-center px-5 py-2.5 rounded-lg text-sm font-bold transition-all ${activeTab === 'sales' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
          >
            <TrendingUp className="w-4 h-4 mr-2" /> Sales
          </button>
          <button
            onClick={() => setActiveTab('staff')}
            className={`flex items-center px-5 py-2.5 rounded-lg text-sm font-bold transition-all ${activeTab === 'staff' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
          >
            <Users className="w-4 h-4 mr-2" /> Staff
          </button>
          <button
            onClick={() => setActiveTab('hourly')}
            className={`flex items-center px-5 py-2.5 rounded-lg text-sm font-bold transition-all ${activeTab === 'hourly' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
          >
            <Clock className="w-4 h-4 mr-2" /> Hourly
          </button>
          <button
            onClick={() => setActiveTab('inventory')}
            className={`flex items-center px-5 py-2.5 rounded-lg text-sm font-bold transition-all ${activeTab === 'inventory' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
          >
            <Package className="w-4 h-4 mr-2" /> Valuation
          </button>
          <button
            onClick={() => setActiveTab('low-stock')}
            className={`flex items-center px-5 py-2.5 rounded-lg text-sm font-bold transition-all ${activeTab === 'low-stock' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
          >
            <AlertTriangle className="w-4 h-4 mr-2" /> Low Stock
          </button>
        </div>
      </div>

      {/* Date Filters (Hidden for Inventory/Low Stock) */}
      {(activeTab === 'sales' || activeTab === 'staff' || activeTab === 'hourly') && (
        <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 flex items-center gap-4 flex-wrap animate-fade-in">
           <div className="flex items-center gap-3">
              <div className="flex items-center bg-slate-100 px-3 py-2 rounded-xl">
                 <Calendar className="w-5 h-5 text-slate-400 mr-2" />
                 <input 
                   type="date" 
                   value={startDate} 
                   onChange={e => setStartDate(e.target.value)} 
                   className="bg-transparent border-none text-sm font-medium text-slate-700 focus:ring-0 p-0"
                 />
              </div>
              <span className="text-slate-400 font-bold">-</span>
              <div className="flex items-center bg-slate-100 px-3 py-2 rounded-xl">
                 <input 
                   type="date" 
                   value={endDate} 
                   onChange={e => setEndDate(e.target.value)} 
                   className="bg-transparent border-none text-sm font-medium text-slate-700 focus:ring-0 p-0"
                 />
              </div>
           </div>
        </div>
      )}

      {activeTab === 'sales' && (
        <SalesAnalytics data={salesReportData} formatPrice={formatPrice} />
      )}

      {activeTab === 'staff' && (
        <StaffPerformance data={staffReportData} formatPrice={formatPrice} />
      )}

      {activeTab === 'hourly' && (
         <HourlyTraffic data={hourlyReportData} formatPrice={formatPrice} />
      )}

      {(activeTab === 'inventory' || activeTab === 'low-stock') && (
         <InventoryValuation data={inventoryReportData} mode={activeTab} formatPrice={formatPrice} />
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { SystemSettings, Branch, PosMachine } from '../types';
import { 
  Save, 
  Globe, 
  Building, 
  Printer, 
  Percent, 
  Monitor, 
  Database, 
  LayoutList, 
  CheckCircle, 
  Tv, 
  AlertTriangle,
  Loader2,
  Network
} from 'lucide-react';

// Import Sub-Components
import { CompanySettings } from './settings/CompanySettings';
import { ReceiptSettings } from './settings/ReceiptSettings';
import { FinancialSettings } from './settings/FinancialSettings';
import { DeviceSettings } from './settings/DeviceSettings';
import { DatabaseSettings } from './settings/DatabaseSettings';
import { LocalizationSettings } from './settings/LocalizationSettings';
import { CustomerDisplaySettings } from './settings/CustomerDisplaySettings';

interface SettingsProps {
  settings: SystemSettings;
  onUpdateSettings: (settings: SystemSettings) => void;
  branches?: Branch[];
  posMachines?: PosMachine[];
}

type SettingsTab = 'company' | 'receipt' | 'financials' | 'device' | 'database' | 'localization' | 'interface' | 'customer_display';

const TABS: { id: SettingsTab; label: string; icon: any }[] = [
  { id: 'company', label: 'Company Information', icon: Building },
  { id: 'receipt', label: 'Receipt & Print Settings', icon: Printer },
  { id: 'financials', label: 'Financials & Tax', icon: Percent },
  { id: 'customer_display', label: 'Customer Display Configuration', icon: Tv },
  { id: 'device', label: 'Device & Network (Master/Slave)', icon: Network },
  { id: 'database', label: 'Database & Backup', icon: Database },
  { id: 'localization', label: 'Localization & Language', icon: Globe },
  { id: 'interface', label: 'Interface & Display', icon: LayoutList },
];

export const Settings: React.FC<SettingsProps> = ({ settings, onUpdateSettings, branches = [], posMachines = [] }) => {
  const [formData, setFormData] = useState<SystemSettings>(settings);
  const [activeTab, setActiveTab] = useState<SettingsTab>('company');
  const [successMsg, setSuccessMsg] = useState('');

  // POS Availability Check State (Lifted state for validation)
  const [posCheckStatus, setPosCheckStatus] = useState<'idle' | 'checking' | 'available' | 'taken'>('idle');

  // Sync state when props change
  useEffect(() => {
    setFormData(settings);
  }, [settings]);

  // Handle Tab Change with Auto-Reset Logic
  const handleTabChange = (newTab: SettingsTab) => {
    if (activeTab === 'device' && (posCheckStatus === 'taken' || posCheckStatus === 'checking')) {
        setFormData(prev => ({
            ...prev,
            currentBranchId: settings.currentBranchId,
            currentPosId: settings.currentPosId,
            deviceRole: settings.deviceRole,
            masterApiUrl: settings.masterApiUrl,
            autoSyncInterval: settings.autoSyncInterval
        }));
        setPosCheckStatus('idle');
    }
    setActiveTab(newTab);
  };

  const handleSave = (e: React.FormEvent) => {
    e.preventDefault();

    // Strict Block: Prevent saving ONLY if on Device tab AND (ID is duplicate OR Checking)
    if (activeTab === 'device') {
       if (posCheckStatus === 'taken') {
          alert("Error: Cannot save settings. The selected POS Terminal ID is already in use.");
          return;
       }
       if (posCheckStatus === 'checking') {
          return; // Silently block
       }
    }

    onUpdateSettings(formData);
    setSuccessMsg('Settings saved successfully!');
    setTimeout(() => setSuccessMsg(''), 3000);
  };

  const isSaveDisabled = activeTab === 'device' && (posCheckStatus === 'taken' || posCheckStatus === 'checking');

  return (
    <div className="flex flex-col h-full">
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">System Settings</h2>
          <p className="text-slate-500">Manage configuration, preferences, and connections.</p>
        </div>
        {successMsg && (
          <div className="bg-green-100 border border-green-200 text-green-700 px-4 py-2 rounded-xl flex items-center shadow-sm animate-fade-in font-bold text-sm">
            <CheckCircle className="w-5 h-5 mr-2" />
            {successMsg}
          </div>
        )}
      </div>

      <div className="flex flex-col md:flex-row bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden flex-1 min-h-0">
        {/* Sidebar Tabs - Style A: Clean list */}
        <div className="w-full md:w-72 bg-slate-50 border-b md:border-b-0 md:border-r border-slate-100 flex flex-row md:flex-col overflow-x-auto md:overflow-y-auto shrink-0 p-2 md:p-3 gap-1">
          {TABS.map((tab) => {
            const Icon = tab.icon;
            const isActive = activeTab === tab.id;

            let label = tab.label;
            if (tab.id === 'database') {
                label = 'Database & Backup';
            }

            return (
              <button
                key={tab.id}
                onClick={() => handleTabChange(tab.id)}
                className={`flex items-center px-4 py-3 text-sm font-bold transition-all rounded-xl whitespace-nowrap md:whitespace-normal text-left
                  ${isActive 
                    ? 'bg-white text-slate-900 shadow-sm' 
                    : 'text-slate-500 hover:bg-slate-100 hover:text-slate-700'
                  } ${
                    tab.id === 'device' && activeTab === 'device' && posCheckStatus === 'taken' ? 'text-red-500 hover:text-red-600' : ''
                  }`}
              >
                <Icon className={`w-5 h-5 mr-3 shrink-0 ${isActive ? 'text-slate-900' : (tab.id === 'device' && activeTab === 'device' && posCheckStatus === 'taken' ? 'text-red-500' : 'text-slate-400')}`} />
                {label}
                {tab.id === 'device' && activeTab === 'device' && posCheckStatus === 'taken' && (
                   <AlertTriangle className="w-4 h-4 ml-auto text-red-500" />
                )}
                {tab.id === 'device' && activeTab === 'device' && posCheckStatus === 'checking' && (
                   <Loader2 className="w-4 h-4 ml-auto text-slate-400 animate-spin" />
                )}
              </button>
            );
          })}
        </div>

        {/* Content Area */}
        <div className="flex-1 overflow-y-auto p-6 md:p-8 bg-white relative">
          <form onSubmit={handleSave} className="max-w-4xl mx-auto pb-20">

            {activeTab === 'company' && <CompanySettings formData={formData} setFormData={setFormData} />}

            {activeTab === 'receipt' && <ReceiptSettings formData={formData} setFormData={setFormData} branches={branches} posMachines={posMachines} />}

            {activeTab === 'financials' && <FinancialSettings formData={formData} setFormData={setFormData} />}

            {activeTab === 'device' && (
              <DeviceSettings 
                formData={formData} 
                setFormData={setFormData} 
                branches={branches} 
                posMachines={posMachines}
                posCheckStatus={posCheckStatus}
                setPosCheckStatus={setPosCheckStatus}
              />
            )}

            {activeTab === 'database' && <DatabaseSettings formData={formData} setFormData={setFormData} />}

            {activeTab === 'localization' && <LocalizationSettings formData={formData} setFormData={setFormData} />}

            {activeTab === 'customer_display' && <CustomerDisplaySettings formData={formData} setFormData={setFormData} />}

            {activeTab === 'interface' && (
               <div className="space-y-6 animate-fade-in">
                  <h3 className="text-lg font-bold text-slate-800 border-b border-slate-100 pb-3 mb-6">Interface & Display</h3>
                  <div>
                     <label className="block text-sm font-medium text-slate-700 mb-2">Default Items Per Page</label>
                     <select value={formData.defaultItemsPerPage} onChange={e => setFormData({ ...formData, defaultItemsPerPage: parseInt(e.target.value) })} className="w-full md:w-64 px-4 py-2 border border-slate-300 rounded-lg">
                        <option value={10}>10 items</option>
                        <option value={20}>20 items</option>
                        <option value={50}>50 items</option>
                     </select>
                  </div>
               </div>
            )}

            {/* Floating Save Button - Style A: Black */}
            <div className="fixed bottom-6 right-6 md:absolute md:bottom-0 md:right-0 md:p-8 md:bg-transparent pointer-events-none">
                <button
                  type="submit"
                  disabled={isSaveDisabled}
                  className={`pointer-events-auto px-8 py-3.5 font-bold rounded-full md:rounded-xl shadow-xl flex items-center transform transition-all ${
                    isSaveDisabled 
                      ? 'bg-slate-300 text-slate-500 cursor-not-allowed' 
                      : 'bg-slate-900 text-white hover:bg-slate-800 hover:scale-105 active:scale-95'
                  }`}
                >
                  {isSaveDisabled && <AlertTriangle className="w-5 h-5 mr-2" />}
                  {!isSaveDisabled && <Save className="w-5 h-5 mr-2" />}
                  {isSaveDisabled 
                     ? (posCheckStatus === 'checking' ? 'Checking ID...' : 'Cannot Save (Invalid ID)') 
                     : 'Save Settings'}
                </button>
            </div>

          </form>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { User } from '../types';
import { Plus } from 'lucide-react';
import { useGlobal } from '../context/GlobalContext';
import { UserList } from './user/UserList';
import { UserFormModal } from './user/UserFormModal';

interface UserManagementProps {
  users: User[];
  onAddUser: (user: User) => void;
  onUpdateUser: (user: User) => void;
  onDeleteUser: (id: string) => void;
}

export const UserManagement: React.FC<UserManagementProps> = ({
  users,
  onAddUser,
  onUpdateUser,
  onDeleteUser
}) => {
  const { branches, currentUser } = useGlobal();
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<User | undefined>(undefined);

  const handleOpenModal = (user?: User) => {
    // Permission check: Managers cannot edit Admins
    if (user && user.role === 'Admin' && currentUser?.role !== 'Admin') {
      alert("Only Administrators can edit other Administrator accounts.");
      return;
    }
    setEditingUser(user);
    setIsModalOpen(true);
  };

  const handleDeleteUser = (user: User) => {
    if (user.role === 'Admin' && currentUser?.role !== 'Admin') {
      alert("Only Administrators can delete Administrator accounts.");
      return;
    }
    if (confirm(`Are you sure you want to delete ${user.name}?`)) {
      onDeleteUser(user.id);
    }
  };

  const handleSubmit = (formData: any, isEdit: boolean) => {
    // Prepare Data
    const userData: any = {
      username: formData.username,
      name: formData.name,
      email: formData.email,
      role: formData.role,
      avatarUrl: formData.avatarUrl,
      department: formData.department,
      branchId: formData.branchId
    };

    if (formData.password) {
      userData.password = formData.password;
    }

    if (isEdit && editingUser) {
        // If edit and no password provided, preserve old password logic is handled by global hook logic or backend
        // But for client state update simulation:
        const existing = users.find(u => u.id === editingUser.id);
        if (existing && !userData.password) {
            userData.password = existing.password;
        }
        onUpdateUser({ ...userData, id: editingUser.id });
    } else {
        onAddUser({ ...userData, id: `u-${Date.now()}` });
    }
    setIsModalOpen(false);
  };

  return (
    <div className="space-y-6 h-full flex flex-col">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">User Management</h2>
          <p className="text-slate-500">Manage system users, roles, and access permissions.</p>
        </div>
        <button 
          onClick={() => handleOpenModal()}
          className="flex items-center px-6 py-3 bg-slate-900 text-white rounded-xl hover:bg-slate-800 transition-colors font-bold shadow-sm whitespace-nowrap"
        >
          <Plus className="w-5 h-5 mr-2" />
          Add User
        </button>
      </div>

      <UserList 
        users={users} 
        branches={branches} 
        currentUser={currentUser} 
        onEdit={handleOpenModal} 
        onDelete={handleDeleteUser} 
      />

      <UserFormModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSubmit={handleSubmit}
        initialData={editingUser}
        branches={branches}
        currentUser={currentUser}
      />
    </div>
  );
};

import React, { useState } from 'react';
import { 
  Warehouse, Product, StockTransfer, StockCount, StockReservation, StockReceipt, StockAdjustment, 
  DocumentStatus 
} from '../types';
import { Plus } from 'lucide-react';
import { StockNavigation } from './stock/StockNavigation';
import { StockList } from './stock/StockList';
import { StockDocumentModal } from './stock/StockDocumentModal';

interface StockManagementProps {
  warehouses: Warehouse[];
  products: Product[];
  transfers: StockTransfer[];
  counts: StockCount[];
  reservations: StockReservation[];
  receipts: StockReceipt[];
  adjustments: StockAdjustment[];
  defaultItemsPerPage: number;
  onUpdateTransfer: (t: StockTransfer) => void;
  onDeleteTransfer: (id: string) => void;
  onUpdateCount: (c: StockCount) => void;
  onDeleteCount: (id: string) => void;
  onUpdateReservation: (r: StockReservation) => void;
  onDeleteReservation: (id: string) => void;
  onUpdateReceipt: (r: StockReceipt) => void;
  onDeleteReceipt: (id: string) => void;
  onUpdateAdjustment: (a: StockAdjustment) => void;
  onDeleteAdjustment: (id: string) => void;
  onStatusChange: (type: 'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment', id: string, status: DocumentStatus) => void;
}

export const StockManagement: React.FC<StockManagementProps> = ({
  warehouses, products, transfers, counts, reservations, receipts, adjustments,
  onUpdateTransfer, onDeleteTransfer,
  onUpdateCount, onDeleteCount,
  onUpdateReservation, onDeleteReservation,
  onUpdateReceipt, onDeleteReceipt,
  onUpdateAdjustment, onDeleteAdjustment,
  onStatusChange
}) => {
  const [activeTab, setActiveTab] = useState<'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment'>('transfer');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [formData, setFormData] = useState<any>({}); 

  // Init form based on tab
  const initForm = () => {
    const common = {
      referenceNo: '',
      date: new Date().toISOString().split('T')[0],
      status: 'Draft',
      items: []
    };

    switch(activeTab) {
      case 'transfer': return { ...common, sourceWarehouseId: '', targetWarehouseId: '' };
      case 'count': return { ...common, warehouseId: '', counterName: '', reason: '' };
      case 'reservation': return { ...common, warehouseId: '', customerName: '', expiryDate: '' };
      case 'receipt': return { ...common, warehouseId: '', vendorName: '', vendorInvoiceNo: '', totalCost: 0 };
      case 'adjustment': return { ...common, warehouseId: '', reason: '' };
    }
  };

  const handleOpenModal = (item?: any) => {
    if (item) {
      setEditingId(item.id);
      setFormData({ ...item });
    } else {
      setEditingId(null);
      setFormData(initForm());
    }
    setIsModalOpen(true);
  };

  const handleSave = (data: any) => {
    const id = editingId || (activeTab === 'transfer' ? `TR-${Date.now()}` : 
                             activeTab === 'count' ? `SC-${Date.now()}` :
                             activeTab === 'reservation' ? `RS-${Date.now()}` :
                             activeTab === 'receipt' ? `RC-${Date.now()}` :
                             `AD-${Date.now()}`);

    // Always save as Draft initially or preserve existing status if editing
    const currentStatus = data.status === 'Completed' || data.status === 'Approved' ? data.status : 'Draft';
    const payload = { ...data, id, status: currentStatus };

    // Auto-generate Ref No if missing
    if (!payload.referenceNo) {
        payload.referenceNo = `${activeTab.toUpperCase().slice(0,2)}-${new Date().getFullYear()}${new Date().getMonth()+1}-${Math.floor(Math.random()*1000)}`;
    }

    switch (activeTab) {
      case 'transfer': onUpdateTransfer(payload); break;
      case 'count': onUpdateCount(payload); break;
      case 'reservation': onUpdateReservation(payload); break;
      case 'receipt': onUpdateReceipt(payload); break;
      case 'adjustment': onUpdateAdjustment(payload); break;
    }
    setIsModalOpen(false);
  };

  const handleComplete = (item: any) => {
    if (window.confirm('Confirm completion? This will update stock levels permanently.')) {
      onStatusChange(activeTab, item.id, 'Completed');
      if (isModalOpen) setIsModalOpen(false);
    }
  };

  const handleDelete = (id: string) => {
    if (!confirm('Delete this document?')) return;
    switch(activeTab) {
      case 'transfer': onDeleteTransfer(id); break;
      case 'count': onDeleteCount(id); break;
      case 'reservation': onDeleteReservation(id); break;
      case 'receipt': onDeleteReceipt(id); break;
      case 'adjustment': onDeleteAdjustment(id); break;
    }
  };

  const getList = () => {
    switch(activeTab) {
      case 'transfer': return transfers;
      case 'count': return counts;
      case 'reservation': return reservations;
      case 'receipt': return receipts;
      case 'adjustment': return adjustments;
      default: return [];
    }
  };

  return (
    <div className="space-y-4 md:space-y-6 h-full flex flex-col pb-20 md:pb-0">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">Stock Management</h2>
          <p className="text-slate-500 text-sm md:text-base">Manage stock movements, counts, and adjustments.</p>
        </div>
        <button 
          onClick={() => handleOpenModal()} 
          className="flex items-center justify-center px-4 py-3 bg-slate-900 text-white rounded-xl hover:bg-slate-800 transition-all font-bold shadow-md active:scale-95"
        >
          <Plus className="w-5 h-5 mr-2" />
          Create Document
        </button>
      </div>

      <StockNavigation activeTab={activeTab} setActiveTab={setActiveTab} />

      <div className="flex-1 overflow-hidden flex flex-col bg-white rounded-2xl shadow-sm border border-slate-100">
        <StockList 
          activeTab={activeTab}
          items={getList()}
          warehouses={warehouses}
          onOpenModal={handleOpenModal}
          onComplete={handleComplete}
          onDelete={handleDelete}
        />
      </div>

      <StockDocumentModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        activeTab={activeTab}
        editingId={editingId}
        initialData={formData}
        warehouses={warehouses}
        products={products}
        onSave={handleSave}
        onComplete={handleComplete}
      />
    </div>
  );
};

