import React, { useState } from 'react';
import { Branch, PosMachine } from '../types';
import { Plus } from 'lucide-react';
import { BranchList } from './branch/BranchList';
import { PosTerminalList } from './branch/PosTerminalList';
import { BranchFormModal } from './branch/BranchFormModal';
import { PosFormModal } from './branch/PosFormModal';

interface BranchManagementProps {
  branches: Branch[];
  posMachines: PosMachine[];
  onAddBranch: (branch: Branch) => void;
  onUpdateBranch: (branch: Branch) => void;
  onDeleteBranch: (id: string) => void;
  onAddPosMachine: (machine: PosMachine) => void;
  onUpdatePosMachine: (machine: PosMachine) => void;
  onDeletePosMachine: (id: string) => void;
}

export const BranchManagement: React.FC<BranchManagementProps> = ({
  branches,
  posMachines,
  onAddBranch,
  onUpdateBranch,
  onDeleteBranch,
  onAddPosMachine,
  onUpdatePosMachine,
  onDeletePosMachine
}) => {
  const [selectedBranchId, setSelectedBranchId] = useState<string | null>(null);

  // Modal States
  const [isBranchModalOpen, setIsBranchModalOpen] = useState(false);
  const [editingBranch, setEditingBranch] = useState<Branch | null>(null);

  const [isPosModalOpen, setIsPosModalOpen] = useState(false);
  const [editingPos, setEditingPos] = useState<PosMachine | null>(null);

  const activeBranch = branches.find(b => b.id === selectedBranchId);
  const branchPosMachines = posMachines.filter(p => p.branchId === selectedBranchId);

  const handleOpenBranchModal = (branch?: Branch) => {
    setEditingBranch(branch || null);
    setIsBranchModalOpen(true);
  };

  const handleBranchSubmit = (formData: Partial<Branch>) => {
    if (editingBranch) {
      onUpdateBranch({ ...formData, id: editingBranch.id } as Branch);
    } else {
      onAddBranch({ ...formData, id: `b-${Date.now()}` } as Branch);
    }
  };

  const handleOpenPosModal = (pos?: PosMachine) => {
    setEditingPos(pos || null);
    setIsPosModalOpen(true);
  };

  const handlePosSubmit = (formData: Partial<PosMachine>) => {
    if (!selectedBranchId) return;
    if (editingPos) {
      onUpdatePosMachine({ ...formData, id: editingPos.id, branchId: selectedBranchId } as PosMachine);
    } else {
      onAddPosMachine({ ...formData, id: `pm-${Date.now()}`, branchId: selectedBranchId } as PosMachine);
    }
  };

  return (
    <div className="flex flex-col h-full space-y-6 pb-20 md:pb-0">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">Branch Management</h2>
          <p className="text-slate-500">Manage store locations and POS terminals.</p>
        </div>
        <button 
          onClick={() => handleOpenBranchModal()}
          className="flex items-center justify-center px-6 py-3 bg-slate-900 text-white rounded-xl hover:bg-slate-800 transition-colors font-bold shadow-sm whitespace-nowrap"
        >
          <Plus className="w-5 h-5 mr-2" />
          Add Branch
        </button>
      </div>

      {/* Main Content: Stacks on mobile, Row on Large screens */}
      <div className="flex flex-col lg:flex-row gap-6 flex-1 min-h-0">
        <div className="w-full lg:w-1/2 flex flex-col h-full">
           <BranchList 
             branches={branches}
             selectedBranchId={selectedBranchId}
             onSelect={setSelectedBranchId}
             onEdit={handleOpenBranchModal}
             onDelete={onDeleteBranch}
           />
        </div>

        <div className="w-full lg:w-1/2 flex flex-col h-full">
           <PosTerminalList 
             activeBranch={activeBranch}
             posMachines={branchPosMachines}
             onAdd={() => handleOpenPosModal()}
             onEdit={handleOpenPosModal}
             onDelete={onDeletePosMachine}
           />
        </div>
      </div>

      <BranchFormModal 
        isOpen={isBranchModalOpen}
        onClose={() => setIsBranchModalOpen(false)}
        onSubmit={handleBranchSubmit}
        initialData={editingBranch}
      />

      <PosFormModal 
        isOpen={isPosModalOpen}
        onClose={() => setIsPosModalOpen(false)}
        onSubmit={handlePosSubmit}
        initialData={editingPos}
      />
    </div>
  );
};

import React, { useState } from 'react';
import { Branch, Warehouse, StorageLocation } from '../types';
import { WarehouseList } from './warehouse/WarehouseList';
import { LocationGrid } from './warehouse/LocationGrid';
import { WarehouseFormModal } from './warehouse/WarehouseFormModal';
import { LocationFormModal } from './warehouse/LocationFormModal';

interface WarehouseManagementProps {
  branches: Branch[];
  warehouses: Warehouse[];
  locations: StorageLocation[];
  onAddWarehouse: (wh: Warehouse) => void;
  onUpdateWarehouse: (wh: Warehouse) => void;
  onDeleteWarehouse: (id: string) => void;
  onAddLocation: (loc: StorageLocation) => void;
  onUpdateLocation: (loc: StorageLocation) => void;
  onDeleteLocation: (id: string) => void;
}

export const WarehouseManagement: React.FC<WarehouseManagementProps> = ({
  branches,
  warehouses,
  locations,
  onAddWarehouse,
  onUpdateWarehouse,
  onDeleteWarehouse,
  onAddLocation,
  onUpdateLocation,
  onDeleteLocation
}) => {
  const [selectedBranchId, setSelectedBranchId] = useState<string>(branches[0]?.id || '');
  const [selectedWarehouseId, setSelectedWarehouseId] = useState<string | null>(null);

  // Modal States
  const [isWhModalOpen, setIsWhModalOpen] = useState(false);
  const [editingWh, setEditingWh] = useState<Warehouse | null>(null);

  const [isLocModalOpen, setIsLocModalOpen] = useState(false);
  const [editingLoc, setEditingLoc] = useState<StorageLocation | null>(null);

  // Filter Logic
  const filteredLocations = locations.filter(l => l.warehouseId === selectedWarehouseId);
  const selectedWarehouse = warehouses.find(w => w.id === selectedWarehouseId);

  // Warehouse Modal Handlers
  const openWhModal = (wh?: Warehouse) => {
    setEditingWh(wh || null);
    setIsWhModalOpen(true);
  };

  const handleWhSubmit = (whForm: Partial<Warehouse>) => {
    if (editingWh) {
      onUpdateWarehouse({ ...whForm, id: editingWh.id, branchId: selectedBranchId } as Warehouse);
    } else {
      onAddWarehouse({ ...whForm, id: `wh-${Date.now()}`, branchId: selectedBranchId } as Warehouse);
    }
    setIsWhModalOpen(false);
  };

  // Location Modal Handlers
  const openLocModal = (loc?: StorageLocation) => {
    setEditingLoc(loc || null);
    setIsLocModalOpen(true);
  };

  const handleLocSubmit = (locForm: Partial<StorageLocation>) => {
    if (!selectedWarehouseId) return;

    const fullCode = `${locForm.zone}-${locForm.rack}-${locForm.shelf}-${locForm.bin}`;
    const locationData = { ...locForm, fullCode, warehouseId: selectedWarehouseId };

    if (editingLoc) {
      onUpdateLocation({ ...locationData, id: editingLoc.id } as StorageLocation);
    } else {
      onAddLocation({ ...locationData, id: `loc-${Date.now()}` } as StorageLocation);
    }
    setIsLocModalOpen(false);
  };

  return (
    <div className="flex flex-col h-full space-y-6 pb-20 md:pb-0">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">Warehouse Management (WMS)</h2>
          <p className="text-slate-500">Manage storage facilities, zones, racks, and bins.</p>
        </div>
      </div>

      {/* Main Content Area: Stacks on Mobile */}
      <div className="flex flex-col lg:flex-row gap-6 flex-1 min-h-0">

        <div className="w-full lg:w-1/3 flex flex-col h-full">
           <WarehouseList 
             branches={branches}
             warehouses={warehouses}
             selectedBranchId={selectedBranchId}
             selectedWarehouseId={selectedWarehouseId}
             onSelectBranch={setSelectedBranchId}
             onSelectWarehouse={setSelectedWarehouseId}
             onAdd={() => openWhModal()}
             onEdit={openWhModal}
             onDelete={onDeleteWarehouse}
           />
        </div>

        <div className="w-full lg:w-2/3 flex flex-col h-full">
           <LocationGrid 
             selectedWarehouse={selectedWarehouse}
             locations={filteredLocations}
             onAdd={() => openLocModal()}
             onEdit={openLocModal}
             onDelete={onDeleteLocation}
           />
        </div>
      </div>

      {/* Modals */}
      <WarehouseFormModal 
        isOpen={isWhModalOpen}
        onClose={() => setIsWhModalOpen(false)}
        onSubmit={handleWhSubmit}
        initialData={editingWh}
      />

      <LocationFormModal 
        isOpen={isLocModalOpen}
        onClose={() => setIsLocModalOpen(false)}
        onSubmit={handleLocSubmit}
        initialData={editingLoc}
      />
    </div>
  );
};

import React, { useState } from 'react';
import { Promotion } from '../types';
import { Plus } from 'lucide-react';
import { PromotionList } from './promotions/PromotionList';
import { PromotionFormModal } from './promotions/PromotionFormModal';

interface PromotionsManagementProps {
  promotions: Promotion[];
  onAddPromotion: (promo: Promotion) => void;
  onUpdatePromotion: (promo: Promotion) => void;
  onDeletePromotion: (id: string) => void;
}

export const PromotionsManagement: React.FC<PromotionsManagementProps> = ({ 
  promotions, 
  onAddPromotion, 
  onUpdatePromotion, 
  onDeletePromotion 
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  const [formData, setFormData] = useState<Partial<Promotion>>({
    title: '',
    imageUrl: '',
    isActive: true,
    startDate: '',
    endDate: ''
  });

  const handleOpenModal = (promo?: Promotion) => {
    if (promo) {
      setEditingId(promo.id);
      setFormData(promo);
    } else {
      setEditingId(null);
      setFormData({
        title: '',
        imageUrl: '',
        isActive: true,
        startDate: '',
        endDate: ''
      });
    }
    setIsModalOpen(true);
  };

  const handleSubmit = (data: Partial<Promotion>) => {
    if (editingId) {
      onUpdatePromotion({ ...data, id: editingId } as Promotion);
    } else {
      onAddPromotion({ ...data, id: `promo-${Date.now()}` } as Promotion);
    }
  };

  const handleToggleActive = (promo: Promotion) => {
    onUpdatePromotion({ ...promo, isActive: !promo.isActive });
  };

  return (
    <div className="space-y-6 h-full flex flex-col pb-20 md:pb-0">
      <div className="flex flex-col md:flex-row justify-between items-center gap-4">
