  deleteTransfer: (id: string) => void;
  counts: StockCount[];
  updateCount: (c: StockCount) => void;
  deleteCount: (id: string) => void;
  reservations: StockReservation[];
  updateReservation: (r: StockReservation) => void;
  deleteReservation: (id: string) => void;
  receipts: StockReceipt[];
  updateReceipt: (r: StockReceipt) => void;
  deleteReceipt: (id: string) => void;
  adjustments: StockAdjustment[];
  updateAdjustment: (a: StockAdjustment) => void;
  deleteAdjustment: (id: string) => void;

  handleStockStatusChange: (type: 'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment', id: string, status: DocumentStatus) => void;
  handleSyncOperation: (type: 'Auto' | 'Manual' | 'Push' | 'Pull') => void;
  restoreSystemData: (data: any) => void;

  // Utilities
  t: (key: string) => string;
  formatPrice: (amount: number) => string;
}

const GlobalContext = createContext<GlobalContextType | undefined>(undefined);

export const GlobalProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const systemStore = useSystemStore();
  const inventoryStore = useInventoryStore();
  const salesStore = useSalesStore();
  const stockStore = useStockStore();

  // Translation helper
  const t = (key: string): string => {
    const lang = systemStore.settings.language || 'en';
    const keys = key.split('.');
    let value: any = (translations as any)[lang];
    for (const k of keys) {
      value = value?.[k];
    }
    return value || key;
  };

  const formatPrice = (amount: number) => {
    const lang = systemStore.settings.language;
    let locale = 'en-US';
    if (lang === 'th') locale = 'th-TH';
    else if (lang === 'lo') locale = 'lo-LA';

    let currencyCode = 'USD';
    if (systemStore.settings.currencySymbol === '฿') currencyCode = 'THB';
    else if (systemStore.settings.currencySymbol === '₭') currencyCode = 'LAK';
    else if (systemStore.settings.currencySymbol === '$') currencyCode = 'USD';

    return new Intl.NumberFormat(locale, {
      style: 'currency',
      currency: currencyCode,
      currencyDisplay: 'symbol',
      minimumFractionDigits: currencyCode === 'LAK' ? 0 : 2,
      maximumFractionDigits: currencyCode === 'LAK' ? 0 : 2,
    }).format(amount);
  };

  // Complex Actions
  const processSale = async (
    items: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number,
    paymentMethod: 'cash' | 'card' | 'transfer' | 'qr' | 'credit' = 'cash',
    amountReceived?: number,
    change?: number,
    pointsRedeemed?: number,
    source: 'pos' | 'back-office' = 'pos'
  ): Promise<Sale> => {

    // Client-side Inventory Check for Back Office Sales
    if (source === 'back-office') {
      for (const item of items) {
        const product = inventoryStore.products.find(p => p.id === item.id);
        if (!product || product.stock < item.quantity) {
          throw new Error(`Insufficient stock for "${item.name}". Back-office sales cannot result in negative inventory.`);
        }
      }
    }

    // Create Sale Object
    const newSale: Sale = {
      id: `S-${Date.now()}`,
      items: items,
      total: total,
      subtotal: subtotal || total,
      discountAmount: discountAmount || 0,
      date: new Date().toISOString(),
      paymentMethod: paymentMethod,
      paymentStatus: paymentMethod === 'credit' ? 'unpaid' : 'paid',
      remainingAmount: paymentMethod === 'credit' ? total - (amountReceived || 0) : 0,
      amountReceived: amountReceived,
      change: change,
      status: 'completed',
      syncStatus: 'pending',
      customerId: customerId,
      customerName: customerId ? salesStore.customers.find(c => c.id === customerId)?.name : undefined,
      userId: systemStore.currentUser?.id,
      userName: systemStore.currentUser?.name,
      pointsRedeemed: pointsRedeemed
    };

    salesStore.addSale(newSale);

    // Update Inventory (Defaulting to primary warehouse if not specified, 
    // though for real multi-warehouse POS we would track session warehouse)
    const activeWarehouseId = systemStore.settings.currentBranchId ? 
      stockStore.warehouses.find(w => w.branchId === systemStore.settings.currentBranchId)?.id : 'wh1';

    items.forEach(item => {
      inventoryStore.updateProductStock(item.id, -item.quantity, activeWarehouseId || 'wh1');
    });

    if (customerId) {
       const customer = salesStore.customers.find(c => c.id === customerId);
       if (customer) {
          const earnRate = systemStore.settings.loyaltyProgram?.earnRate || 10000;
          const pointsEarned = Math.floor(total / earnRate);
          const newPoints = (customer.loyaltyPoints || 0) - (pointsRedeemed || 0) + pointsEarned;

          salesStore.updateCustomer({
             ...customer,
             loyaltyPoints: newPoints
          });
       }
    }

    return newSale;
  };

  const handleVoidSale = (id: string) => {
    const sale = salesStore.sales.find(s => s.id === id);
    if (sale && sale.status !== 'voided') {
      salesStore.updateSale({ ...sale, status: 'voided' });

      const activeWarehouseId = systemStore.settings.currentBranchId ? 
        stockStore.warehouses.find(w => w.branchId === systemStore.settings.currentBranchId)?.id : 'wh1';

      sale.items.forEach(item => {
        inventoryStore.updateProductStock(item.id, item.quantity, activeWarehouseId || 'wh1');
      });

      if (systemStore.currentUser) {
         systemStore.logAction({
            id: `aud-${Date.now()}`,
            action: 'SALE_VOID',
            userId: systemStore.currentUser.id,
            userName: systemStore.currentUser.name,
            details: `Voided Sale #${id}`,
            timestamp: new Date().toISOString(),
            severity: 'high',
            resourceId: id
         });
      }
    }
  };

  const settleSaleDebt = async (id: string, amount: number, method: string) => {
     const sale = salesStore.sales.find(s => s.id === id);
     if (sale) {
        const newPaid = (sale.amountReceived || 0) + amount;
        const newRemaining = Math.max(0, (sale.remainingAmount || sale.total) - amount);

        salesStore.updateSale({
           ...sale,
           amountReceived: newPaid,
           remainingAmount: newRemaining,
           paymentStatus: newRemaining <= 0.01 ? 'paid' : 'partial'
        });

        if (method === 'cash') {
           const shift = salesStore.shifts.find(s => s.userId === systemStore.currentUser?.id && s.status === 'Open');
           if (shift) {
              salesStore.addCashTransaction({
                 id: `ctx-${Date.now()}`,
                 shiftId: shift.id,
                 userId: shift.userId,
                 type: 'in',
                 amount: amount,
                 reason: `Debt Settle #${sale.id.slice(-6)}`,
                 timestamp: new Date().toISOString()
              });
           }
        }
     }
  };

  const processReturn = async (originalSale: Sale, itemsToReturn: { itemIndex: number, quantity: number }[], refundMethod: string) => {
     const returnItems: CartItem[] = [];
     let refundTotal = 0;
     const activeWarehouseId = systemStore.settings.currentBranchId ? 
        stockStore.warehouses.find(w => w.branchId === systemStore.settings.currentBranchId)?.id : 'wh1';

     itemsToReturn.forEach(({ itemIndex, quantity }) => {
        const originalItem = originalSale.items[itemIndex];
        if (originalItem) {
           returnItems.push({
              ...originalItem,
              quantity: quantity
           });
           refundTotal += originalItem.sellPrice * quantity;
           inventoryStore.updateProductStock(originalItem.id, quantity, activeWarehouseId || 'wh1');
        }
     });

     const returnSale: Sale = {
        id: `R-${Date.now()}`,
        type: 'return',
        originalSaleId: originalSale.id,
        items: returnItems,
        total: -refundTotal,
        date: new Date().toISOString(),
        paymentMethod: refundMethod as any,
        paymentStatus: 'paid', 
        status: 'completed',
        syncStatus: 'pending',
        customerId: originalSale.customerId,
        customerName: originalSale.customerName,
        userId: systemStore.currentUser?.id,
        userName: systemStore.currentUser?.name,
     };

     salesStore.addSale(returnSale);
  };

  const handleStockStatusChange = (type: 'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment', id: string, status: DocumentStatus) => {
    const docList = stockStore[type === 'transfer' ? 'transfers' : type === 'count' ? 'counts' : type === 'reservation' ? 'reservations' : type === 'receipt' ? 'receipts' : 'adjustments'];
    const doc = docList.find((d: any) => d.id === id);
    if (!doc) return;

    stockStore.updateDocument(type === 'transfer' ? 'transfers' : type === 'count' ? 'counts' : type === 'reservation' ? 'reservations' : type === 'receipt' ? 'receipts' : 'adjustments', { ...doc, status });

    if (status === 'Completed' || status === 'Approved') {
       if (type === 'transfer') {
          const t = doc as StockTransfer;
          t.items.forEach(item => {
             // Deduct from Source
             inventoryStore.updateProductStock(item.productId, -item.quantity, t.sourceWarehouseId);
             // Add to Target
             inventoryStore.updateProductStock(item.productId, item.quantity, t.targetWarehouseId);
          });
       }
       else if (type === 'receipt') {
          const r = doc as StockReceipt;
          r.items.forEach(item => {
             inventoryStore.updateProductStock(item.productId, item.quantity, r.warehouseId);
          });
       }
       else if (type === 'adjustment') {
          const a = doc as StockAdjustment;
          a.items.forEach(item => {
             inventoryStore.updateProductStock(item.productId, item.quantity, a.warehouseId);
          });
       }
       else if (type === 'count') {
          const c = doc as StockCount;
          c.items.forEach(item => {
             if (item.diff !== undefined) {
                inventoryStore.updateProductStock(item.productId, item.diff, c.warehouseId);
             }
          });
       }
    }
  };

  const startShift = (branchId: string, startCash: number, notes?: string, posId?: string) => {
    if (!systemStore.currentUser) return;
    salesStore.startShift({
      id: `sh-${Date.now()}`,
      userId: systemStore.currentUser.id,
      branchId,
      posId,
      startTime: new Date().toISOString(),
      startCash,
      notes,
      status: 'Open',
      cashTransactions: []
    });
  };

  const endShift = (shiftId: string, endCash: number, notes?: string) => {
    salesStore.endShift(shiftId, {
      endTime: new Date().toISOString(),
      endCash,
      notes,
      status: 'Closed'
    });
  };

  const addCashTransaction = (type: 'in' | 'out', amount: number, reason: string) => {
     const shift = salesStore.shifts.find(s => s.userId === systemStore.currentUser?.id && s.status === 'Open');
     if (shift) {
        salesStore.addCashTransaction({
           id: `ctx-${Date.now()}`,
           shiftId: shift.id,
           userId: shift.userId,
           type,
           amount,
           reason,
           timestamp: new Date().toISOString()
        });
     }
  };

  const handleSyncOperation = (type: 'Auto' | 'Manual' | 'Push' | 'Pull') => {
     const start = Date.now();
     setTimeout(() => {
        const duration = Date.now() - start;
        systemStore.addSyncLog({
           id: `log-${Date.now()}`,
           timestamp: new Date().toISOString(),
           type,
           status: 'Success',
           details: `Synced successfully (${salesStore.sales.length} records checked)`,
           durationMs: duration
        });
        salesStore.sales.forEach(s => {
           if (s.syncStatus === 'pending') {
              salesStore.updateSale({ ...s, syncStatus: 'synced' });
           }
        });
     }, 1000);
  };

  const restoreSystemData = (data: any) => {
     systemStore.restoreSystemData(data);
     inventoryStore.restoreInventoryData(data);
     salesStore.restoreSalesData(data);
     stockStore.restoreStockData(data);
  };

  return (
    <GlobalContext.Provider value={{
      // System
      currentUser: systemStore.currentUser,
      setCurrentUser: systemStore.setCurrentUser,
      users: systemStore.users,
      addUser: systemStore.addUser,
      updateUser: systemStore.updateUser,
      deleteUser: systemStore.deleteUser,
      settings: systemStore.settings,
      updateSettings: systemStore.updateSettings,
      notifications: systemStore.notifications,
      markNotificationRead: systemStore.markNotificationRead,
      clearAllNotifications: systemStore.clearAllNotifications,
      auditLogs: systemStore.auditLogs,
      syncLogs: systemStore.syncLogs,

      // Inventory
      products: inventoryStore.products,
      addProduct: inventoryStore.addProduct,
      updateProduct: inventoryStore.updateProduct,
      deleteProduct: inventoryStore.deleteProduct,
      units: inventoryStore.units,
      addUnit: inventoryStore.addUnit,
      updateUnit: inventoryStore.updateUnit,
      deleteUnit: inventoryStore.deleteUnit,
      categories: inventoryStore.categories,
      addCategory: inventoryStore.addCategory,
      updateCategory: inventoryStore.updateCategory,
      deleteCategory: inventoryStore.deleteCategory,

      // Sales
      sales: salesStore.sales,
      processSale,
      handleVoidSale,
      settleSaleDebt,
      processReturn,
      customers: salesStore.customers,
      addCustomer: salesStore.addCustomer,
      updateCustomer: salesStore.updateCustomer,
      deleteCustomer: salesStore.deleteCustomer,
      customerLevels: salesStore.customerLevels,
      addCustomerLevel: salesStore.addCustomerLevel,
      updateCustomerLevel: salesStore.updateCustomerLevel,
      deleteCustomerLevel: salesStore.deleteCustomerLevel,
      promotions: salesStore.promotions,
      addPromotion: salesStore.addPromotion,
      updatePromotion: salesStore.updatePromotion,
      deletePromotion: salesStore.deletePromotion,

      // Shifts
      shifts: salesStore.shifts,
      startShift,
      endShift,
      addCashTransaction,
      shiftSchedules: salesStore.shiftSchedules,
      addShiftSchedule: salesStore.addShiftSchedule,
      updateShiftSchedule: salesStore.updateShiftSchedule,
      deleteShiftSchedule: salesStore.deleteShiftSchedule,

      // Locations & Stock
      branches: systemStore.branches,
      addBranch: systemStore.addBranch,
      updateBranch: systemStore.updateBranch,
      deleteBranch: systemStore.deleteBranch,
      posMachines: systemStore.posMachines,
      addPos: systemStore.addPos,
      updatePos: systemStore.updatePos,
      deletePos: systemStore.deletePos,
      warehouses: stockStore.warehouses,
      addWarehouse: stockStore.addWarehouse,
      updateWarehouse: stockStore.updateWarehouse,
      deleteWarehouse: stockStore.deleteWarehouse,
      locations: stockStore.locations,
      addLocation: stockStore.addLocation,
      updateLocation: stockStore.updateLocation,
      deleteLocation: stockStore.deleteLocation,

      transfers: stockStore.transfers,
      updateTransfer: (t) => stockStore.updateDocument('transfers', t),
      deleteTransfer: (id) => stockStore.deleteDocument('transfers', id),
      counts: stockStore.counts,
      updateCount: (c) => stockStore.updateDocument('counts', c),
      deleteCount: (id) => stockStore.deleteDocument('counts', id),
      reservations: stockStore.reservations,
      updateReservation: (r) => stockStore.updateDocument('reservations', r),
      deleteReservation: (id) => stockStore.deleteDocument('reservations', id),
      receipts: stockStore.receipts,
      updateReceipt: (r) => stockStore.updateDocument('receipts', r),
      deleteReceipt: (id) => stockStore.deleteDocument('receipts', id),
      adjustments: stockStore.adjustments,
      updateAdjustment: (a) => stockStore.updateDocument('adjustments', a),
      deleteAdjustment: (id) => stockStore.deleteDocument('adjustments', id),

      handleStockStatusChange,
      handleSyncOperation,
      restoreSystemData,

      t,
      formatPrice
    }}>
      {children}
    </GlobalContext.Provider>
  );
};

export const useGlobal = () => {
  const context = useContext(GlobalContext);
  if (!context) {
    throw new Error('useGlobal must be used within a GlobalProvider');
  }
  return context;
};

import React, { useState } from 'react';
import { Product, StockItem } from '../../../types';
import { Plus, Trash2, Search, Package } from 'lucide-react';

interface StockItemsTableProps {
  items: any[];
  setItems: (items: any[]) => void;
  products: Product[];
  isReadOnly: boolean;
  activeTab: string;
  sourceWarehouseId?: string; // Passed to check available stock
}

export const StockItemsTable: React.FC<StockItemsTableProps> = ({ 
  items, setItems, products, isReadOnly, activeTab, sourceWarehouseId 
}) => {
  const [searchTerm, setSearchTerm] = useState('');

  const handleAddItem = (p: Product) => {
    const newItem: StockItem = {
      productId: p.id,
      productName: p.name,
      unit: p.unit,
      quantity: 1
    };
    setItems([...(items || []), newItem]);
    setSearchTerm('');
  };

  const handleUpdateItem = (index: number, field: string, value: any) => {
    const newItems = [...items];
    newItems[index] = { ...newItems[index], [field]: value };
    setItems(newItems);
  };

  const handleRemoveItem = (index: number) => {
    const newItems = [...items];
    newItems.splice(index, 1);
    setItems(newItems);
  };

  // Helper to get stock in source warehouse
  const getSourceStock = (productId: string) => {
    if (!sourceWarehouseId) return null;
    const p = products.find(prod => prod.id === productId);
    const whStock = p?.warehouseInventory?.find(inv => inv.warehouseId === sourceWarehouseId);
    return whStock ? whStock.quantity : 0;
  };

  const filteredSuggestions = products.filter(p => {
    const s = searchTerm.toLowerCase();
    return p.name.toLowerCase().includes(s) || p.sku.toLowerCase().includes(s) || p.barcode.includes(s);
  }).slice(0, 5);

  return (
    <div className="border-t border-slate-100 pt-4">
       <div className="flex justify-between items-center mb-4">
          <h4 className="font-bold text-slate-700">Movement Items</h4>
       </div>

       {/* Searchable Add Bar */}
       {!isReadOnly && (
         <div className="relative mb-6">
            <div className="relative">
               <Search className="absolute left-3 top-2.5 w-5 h-5 text-slate-400" />
               <input 
                  type="text"
                  placeholder="Search item to add (Name, SKU, Barcode)..."
                  className="w-full pl-10 pr-4 py-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-blue-500 bg-white"
                  value={searchTerm}
                  onChange={e => setSearchTerm(e.target.value)}
               />
            </div>
            {searchTerm && (
               <div className="absolute top-full left-0 right-0 bg-white border border-slate-200 rounded-xl mt-1 shadow-xl z-20 overflow-hidden">
                  {filteredSuggestions.length > 0 ? filteredSuggestions.map(p => (
                     <div 
                        key={p.id}
                        onClick={() => handleAddItem(p)}
                        className="p-3 hover:bg-slate-50 cursor-pointer border-b border-slate-50 last:border-0 flex justify-between items-center"
                     >
                        <div>
                           <p className="font-bold text-slate-800 text-sm">{p.name}</p>
                           <p className="text-[10px] text-slate-500 font-mono">{p.sku}</p>
                        </div>
                        <div className="text-right">
                           <span className="text-[10px] bg-slate-100 px-2 py-0.5 rounded font-bold text-slate-600 uppercase">
                              {p.unit}
                           </span>
                        </div>
                     </div>
                  )) : (
                     <div className="p-4 text-center text-slate-400 text-sm">No products found</div>
                  )}
               </div>
            )}
         </div>
       )}

       <div className="space-y-3">
          {items?.map((item: any, idx: number) => {
             const available = getSourceStock(item.productId);
             const isOver = activeTab === 'transfer' && available !== null && item.quantity > available;

             return (
                <div key={idx} className={`flex flex-col md:flex-row gap-3 items-start md:items-center p-3 rounded-xl border transition-all ${isOver ? 'bg-red-50 border-red-200' : 'bg-white border-slate-200'}`}>
                   <div className="flex-1 min-w-0">
                      <p className="font-bold text-slate-800 truncate">{item.productName}</p>
                      <div className="flex items-center gap-2 mt-0.5">
                         <span className="text-[10px] text-slate-400 font-mono">ID: {item.productId.slice(-6)}</span>
                         {activeTab === 'transfer' && sourceWarehouseId && (
                            <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded ${isOver ? 'bg-red-200 text-red-800' : 'bg-blue-50 text-blue-700'}`}>
                               Available in Source: {available}
                            </span>
                         )}
                      </div>
                   </div>

                   <div className="flex gap-3 w-full md:w-auto items-center shrink-0">
                      {activeTab === 'count' ? (
                         <div className="flex-1 md:w-32">
                            <label className="block text-[10px] font-bold text-slate-400 uppercase mb-0.5">Actual Count</label>
                            <input 
                               disabled={isReadOnly}
                               type="number" 
                               value={item.countedQuantity !== undefined ? item.countedQuantity : ''} 
                               onChange={e => handleUpdateItem(idx, 'countedQuantity', parseFloat(e.target.value))} 
                               className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm disabled:bg-slate-100 font-bold"
                               placeholder="Count"
                            />
                         </div>
                      ) : (
                         <div className="flex-1 md:w-32">
                            <label className="block text-[10px] font-bold text-slate-400 uppercase mb-0.5">Move Qty</label>
                            <input 
                               disabled={isReadOnly}
                               type="number" 
                               min="0.001"
                               value={item.quantity || ''} 
                               onChange={e => handleUpdateItem(idx, 'quantity', parseFloat(e.target.value))} 
                               className={`w-full px-3 py-2 border rounded-lg text-sm disabled:bg-slate-100 font-bold ${isOver ? 'border-red-500 focus:ring-red-200' : 'border-slate-300 focus:ring-blue-200'}`}
                               placeholder="Qty"
                            />
                         </div>
                      )}

                      <div className="flex flex-col items-center justify-center h-full pt-4">
                         <span className="text-[10px] font-bold text-slate-400 uppercase">{item.unit}</span>
                      </div>

                      {!isReadOnly && (
                          <div className="pt-4">
                             <button type="button" onClick={() => handleRemoveItem(idx)} className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"><Trash2 className="w-5 h-5"/></button>
                          </div>
                      )}
                   </div>
                </div>
             );
          })}
          {(!items || items.length === 0) && (
             <div className="flex flex-col items-center justify-center py-12 text-slate-400 border-2 border-dashed border-slate-100 rounded-2xl bg-slate-50/50">
                <Package className="w-12 h-12 mb-2 opacity-20" />
                <p className="text-sm italic">Search and select items to move.</p>
             </div>
          )}
       </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Warehouse, Product } from '../../types';
import { Edit2, Plus, X, AlertCircle, CheckCircle, PlayCircle } from 'lucide-react';
import { StockHeaderFields } from './document-form/StockHeaderFields';
import { StockItemsTable } from './document-form/StockItemsTable';

interface StockDocumentModalProps {
  isOpen: boolean;
  onClose: () => void;
  activeTab: 'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment';
  editingId: string | null;
  initialData: any;
  warehouses: Warehouse[];
  products: Product[];
  onSave: (data: any) => void;
  onComplete: (data: any) => void;
}

export const StockDocumentModal: React.FC<StockDocumentModalProps> = ({
  isOpen, onClose, activeTab, editingId, initialData, warehouses, products, onSave, onComplete
}) => {
  const [formData, setFormData] = useState<any>(initialData);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    setFormData(initialData);
    setError(null);
  }, [initialData, isOpen]);

  if (!isOpen) return null;

  const isReadOnly = formData.status !== 'Draft';

  const validateForm = () => {
    if (!formData.date) return 'Date is required';
    if (activeTab === 'transfer') {
        if (!formData.sourceWarehouseId) return 'Source Warehouse is required';
        if (!formData.targetWarehouseId) return 'Target Warehouse is required';
        if (formData.sourceWarehouseId === formData.targetWarehouseId) return 'Source and Target warehouses cannot be the same';
    }
    if (['adjustment', 'count', 'receipt', 'reservation'].includes(activeTab)) {
        if (!formData.warehouseId) return 'Warehouse is required';
    }
    if (activeTab === 'receipt' && !formData.vendorName) return 'Vendor Name is required';
    if (activeTab === 'reservation') {
        if (!formData.customerName) return 'Customer Name is required';
        if (!formData.expiryDate) return 'Expiry Date is required';
    }
    if (activeTab === 'count' && !formData.counterName) return 'Counter Name is required';
    if (activeTab === 'adjustment' && !formData.reason) return 'Reason is required';
    return null;
  };

  const handleSaveClick = () => {
    const err = validateForm();
    if (err) {
      setError(err);
      return;
    }
    onSave(formData);
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-[60] p-4">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-4xl max-h-[95vh] flex flex-col overflow-hidden animate-fade-in">
        <div className="p-4 md:p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 shrink-0">
          <h3 className="text-lg md:text-xl font-bold text-slate-800 uppercase flex items-center">
            {editingId ? <Edit2 className="w-5 h-5 mr-2 text-blue-500" /> : <Plus className="w-5 h-5 mr-2 text-green-500" />}
            {editingId ? 'Edit' : 'New'} {activeTab}
          </h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 transition-colors p-1 rounded-full hover:bg-slate-100">
            <X className="w-6 h-6" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto">
          <div className="p-4 md:p-6 space-y-4">

            {error && (
              <div className="p-3 bg-red-50 border border-red-100 rounded-lg text-red-600 text-sm flex items-center">
                <AlertCircle className="w-4 h-4 mr-2 flex-shrink-0 mt-0.5" />
                {error}
              </div>
            )}

            <StockHeaderFields 
              activeTab={activeTab}
              formData={formData}
              setFormData={setFormData}
              warehouses={warehouses}
              isReadOnly={isReadOnly}
            />

            <StockItemsTable 
              items={formData.items}
              setItems={(items) => setFormData({...formData, items})}
              products={products}
              isReadOnly={isReadOnly}
              activeTab={activeTab}
              sourceWarehouseId={formData.sourceWarehouseId || formData.warehouseId}
            />
          </div>
        </div>

        <div className="p-4 border-t border-slate-100 flex justify-end space-x-3 bg-slate-50 shrink-0">
          <button
            type="button"
            onClick={onClose}
            className="px-5 py-2.5 text-slate-600 font-medium hover:bg-slate-200 rounded-lg transition-colors"
          >
            {isReadOnly ? 'Close' : 'Cancel'}
          </button>

          {formData.status === 'Draft' && (
             <button
                type="button"
                onClick={handleSaveClick}
                className="px-6 py-2.5 bg-slate-900 text-white font-bold rounded-lg hover:bg-slate-800 transition-colors shadow-sm"
             >
                Save Draft
             </button>
          )}

          {formData.status === 'Approved' && (
             <button
                type="button"
                onClick={() => onComplete(formData)}
                className="flex items-center px-6 py-2.5 bg-green-600 text-white font-bold rounded-lg hover:bg-green-700 transition-colors shadow-sm"
             >
                <PlayCircle className="w-4 h-4 mr-2" />
                Complete
             </button>
          )}

          {(formData.status === 'Completed' || formData.status === 'Cancelled') && (
             <span className={`flex items-center font-bold px-4 py-2 ${formData.status === 'Completed' ? 'text-green-600 bg-green-50 rounded-lg' : 'text-red-600 bg-red-50 rounded-lg'}`}>
                {formData.status === 'Completed' ? <CheckCircle className="w-5 h-5 mr-2" /> : <AlertCircle className="w-5 h-5 mr-2" />} 
                {formData.status}
             </span>
          )}
        </div>
      </div>
    </div>
  );
};

