import { Elysia, t } from 'elysia';
import { cors } from '@elysiajs/cors';
import { PrismaClient } from '@prisma/client';

const db = new PrismaClient();
const app = new Elysia()
  .use(cors())

  // --- Products ---
  .group('/api/products', (app) => app
    .get('/', async () => {
      return await db.product.findMany({
        include: { variants: true, inventory: true }
      });
    })
    .post('/', async ({ body }) => {
      return await db.product.create({
        data: body as any,
        include: { variants: true }
      });
    }, {
      body: t.Object({
        name: t.String(),
        category: t.String(),
        price: t.Number(),
        unit: t.String(),
        sku: t.String(),
        barcode: t.Optional(t.String()),
        stock: t.Number(),
        minStock: t.Optional(t.Number())
      })
    })
    .put('/:id', async ({ params: { id }, body }) => {
      return await db.product.update({
        where: { id },
        data: body as any
      });
    })
  )

  // --- Sales ---
  .group('/api/sales', (app) => app
    .get('/', async () => {
      return await db.sale.findMany({
        include: { items: true, customer: true },
        orderBy: { date: 'desc' },
        take: 100
      });
    })
    .post('/', async ({ body }: any) => {
      return await db.$transaction(async (tx) => {
        const sale = await tx.sale.create({
          data: {
            total: body.total,
            subtotal: body.subtotal,
            paymentMethod: body.paymentMethod,
            paymentStatus: body.paymentStatus,
            customerId: body.customerId,
            userId: body.userId,
            userName: body.userName,
            items: {
              create: body.items.map((item: any) => ({
                productId: item.id,
                variantId: item.selectedVariantId,
                name: item.name,
                quantity: item.quantity,
                sellPrice: item.sellPrice,
                sellUnit: item.sellUnit
              }))
            }
          },
          include: { items: true }
        });

        // Simple stock decrement logic
        for (const item of body.items) {
          await tx.product.update({
            where: { id: item.id },
            data: { stock: { decrement: item.quantity } }
          });
        }
        return sale;
      });
    })
  )

  // --- Customers ---
  .get('/api/customers', async () => {
    return await db.customer.findMany({ include: { level: true } });
  })

  .listen(3001);

