const GlobalContext = createContext<GlobalContextType | undefined>(undefined);

export const GlobalProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const systemStore = useSystemStore();
  const inventoryStore = useInventoryStore();
  const salesStore = useSalesStore();
  const stockStore = useStockStore();

  // Helper for Translation
  const t = (key: string): string => {
    const lang = systemStore.settings.language || 'en';
    const keys = key.split('.');
    let value: any = (translations as any)[lang];
    for (const k of keys) { value = value?.[k]; }
    return value || key;
  };

  // Helper for Pricing
  const formatPrice = (amount: number) => {
    const symbol = systemStore.settings.currencySymbol;
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: symbol === '₭' ? 'LAK' : symbol === '฿' ? 'THB' : 'USD',
      minimumFractionDigits: symbol === '₭' ? 0 : 2,
    }).format(amount).replace('LAK', '₭').replace('THB', '฿');
  };

  // Local Data Refresh (Pure state, no API)
  const refreshData = async () => {
    console.debug("[Local Mode] Data refresh requested");
  };

  // Process Sale Locally
  const processSale = async (
    items: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number, 
    paymentMethod: any = 'cash', 
    amountReceived?: number, 
    change?: number, 
    pointsRedeemed?: number
  ): Promise<Sale> => {
    const saleId = `S-${Date.now()}`;
    const customer = salesStore.customers.find(c => c.id === customerId);

    const newSale: Sale = {
      id: saleId,
      items,
      total,
      subtotal: subtotal || total,
      discountAmount: discountAmount || 0,
      date: new Date().toISOString(),
      paymentMethod,
      paymentStatus: paymentMethod === 'credit' ? 'unpaid' : 'paid',
      amountReceived,
      change,
      remainingAmount: paymentMethod === 'credit' ? total : 0,
      status: 'completed',
      syncStatus: 'synced',
      customerId,
      customerName: customer?.name,
      userId: systemStore.currentUser?.id,
      userName: systemStore.currentUser?.name
    };

    // 1. Add to sales history
    salesStore.addSale(newSale);

    // 2. Update Inventory (Deduct stock)
    items.forEach(item => {
       inventoryStore.updateProductStock(item.id, -item.quantity, 'wh1');
    });

    // 3. Update Customer Points
    if (customerId && systemStore.settings.loyaltyProgram.enabled) {
       const earned = Math.floor(total / systemStore.settings.loyaltyProgram.earnRate);
       const updatedCustomer = { ...customer!, loyaltyPoints: (customer?.loyaltyPoints || 0) + earned - (pointsRedeemed || 0) };
       salesStore.updateCustomer(updatedCustomer as Customer);
    }

    return newSale;
  };

  // Process Debt Settle
  const settleSaleDebt = async (saleId: string, amount: number, method: string) => {
    const sale = salesStore.sales.find(s => s.id === saleId);
    if (!sale) return;

    const newAmountReceived = (sale.amountReceived || 0) + amount;
    const newRemaining = Math.max(0, (sale.remainingAmount || sale.total) - amount);

    salesStore.updateSale({
      ...sale,
      amountReceived: newAmountReceived,
      remainingAmount: newRemaining,
      paymentStatus: newRemaining <= 0.01 ? 'paid' : 'partial'
    });

    // Log the transaction
    systemStore.logAction({
       id: `aud-${Date.now()}`,
       action: 'CASH_IN',
       userId: systemStore.currentUser?.id || 'sys',
       userName: systemStore.currentUser?.name || 'System',
       details: `Settled debt for Sale ${saleId}: ${amount}`,
       timestamp: new Date().toISOString(),
       severity: 'low',
       resourceId: saleId
    });
  };

  // Process Return/Refund
  const processReturn = async (originalSale: Sale, returnItems: { itemIndex: number, quantity: number }[]) => {
    const returnSaleId = `RET-${Date.now()}`;
    const items: CartItem[] = [];
    let returnTotal = 0;

    returnItems.forEach(ret => {
       const originalItem = originalSale.items[ret.itemIndex];
       const returnQty = ret.quantity;
       const lineTotal = originalItem.sellPrice * returnQty;

       returnTotal += lineTotal;
       items.push({ ...originalItem, quantity: returnQty });

       // Restore stock
       inventoryStore.updateProductStock(originalItem.id, returnQty, 'wh1');
    });

    const returnSale: Sale = {
      id: returnSaleId,
      items,
      total: -returnTotal,
      date: new Date().toISOString(),
      paymentMethod: originalSale.paymentMethod,
      paymentStatus: 'paid',
      status: 'completed',
      type: 'return',
      originalSaleId: originalSale.id,
      customerId: originalSale.customerId,
      customerName: originalSale.customerName,
      userId: systemStore.currentUser?.id,
      userName: systemStore.currentUser?.name
    };

    salesStore.addSale(returnSale);

    systemStore.logAction({
       id: `aud-${Date.now()}`,
       action: 'SALE_RETURN',
       userId: systemStore.currentUser?.id || 'sys',
       userName: systemStore.currentUser?.name || 'System',
       details: `Processed return for Sale ${originalSale.id}`,
       timestamp: new Date().toISOString(),
       severity: 'medium',
       resourceId: originalSale.id
    });
  };

  const handleVoidSale = (id: string) => {
    const sale = salesStore.sales.find(s => s.id === id);
    if (!sale || sale.status === 'voided') return;

    // 1. Mark as voided
    salesStore.updateSale({ ...sale, status: 'voided' });

    // 2. Return items to stock
    sale.items.forEach(item => {
       inventoryStore.updateProductStock(item.id, item.quantity, 'wh1');
    });

    // 3. Log
    systemStore.logAction({
       id: `aud-${Date.now()}`,
       action: 'SALE_VOID',
       userId: systemStore.currentUser?.id || 'sys',
       userName: systemStore.currentUser?.name || 'System',
       details: `Voided Sale ${id}`,
       timestamp: new Date().toISOString(),
       severity: 'high',
       resourceId: id
    });
  };

  return (
    <GlobalContext.Provider value={{
      currentUser: systemStore.currentUser,
      setCurrentUser: systemStore.setCurrentUser,
      users: systemStore.users,
      settings: systemStore.settings,
      products: inventoryStore.products,
      sales: salesStore.sales,
      customers: salesStore.customers,
      customerLevels: salesStore.customerLevels,
      units: inventoryStore.units,
      categories: inventoryStore.categories,
      branches: systemStore.branches,
      posMachines: systemStore.posMachines,
      warehouses: stockStore.warehouses,
      locations: stockStore.locations,
      shifts: salesStore.shifts,
      shiftSchedules: salesStore.shiftSchedules,
      promotions: salesStore.promotions,
      notifications: systemStore.notifications,
      syncLogs: systemStore.syncLogs,
      auditLogs: systemStore.auditLogs || [],

      processSale,
      processReturn,
      settleSaleDebt,
      handleVoidSale,
      addProduct: inventoryStore.addProduct,
      updateProduct: inventoryStore.updateProduct,
      deleteProduct: inventoryStore.deleteProduct,
      addCustomer: salesStore.addCustomer,
      updateCustomer: salesStore.updateCustomer,
      deleteCustomer: (id) => {}, 
      updateSettings: systemStore.updateSettings,
      markNotificationRead: systemStore.markNotificationRead,
      clearAllNotifications: systemStore.clearAllNotifications,
      refreshData,
      t,
      formatPrice
    }}>
      {children}
    </GlobalContext.Provider>
  );
};

export const useGlobal = () => {
  const context = useContext(GlobalContext);
  if (!context) throw new Error('useGlobal must be used within a GlobalProvider');
  return context;
};

import { create } from 'zustand';
import { Sale, Customer, CustomerLevel, Shift, ShiftSchedule, Promotion, CashTransaction, Quotation } from '../types';
import { INITIAL_CUSTOMERS, INITIAL_CUSTOMER_LEVELS, INITIAL_PROMOTIONS, INITIAL_SHIFT_SCHEDULES } from '../services/data';

interface SalesState {
  sales: Sale[];
  quotations: Quotation[];
  customers: Customer[];
  customerLevels: CustomerLevel[];
  shifts: Shift[];
  shiftSchedules: ShiftSchedule[];
  promotions: Promotion[];

  addSale: (sale: Sale) => void;
  updateSale: (sale: Sale) => void;

  addQuotation: (q: Quotation) => void;
  updateQuotation: (q: Quotation) => void;
  deleteQuotation: (id: string) => void;

  addCustomer: (customer: Customer) => void;
  updateCustomer: (customer: Customer) => void;

  addCustomerLevel: (level: CustomerLevel) => void;
  updateCustomerLevel: (level: CustomerLevel) => void;
  deleteCustomerLevel: (id: string) => void;

  addPromotion: (promo: Promotion) => void;
  updatePromotion: (promo: Promotion) => void;
  deletePromotion: (id: string) => void;

  addShift: (shift: Shift) => void;
  updateShift: (shift: Shift) => void;

  addShiftSchedule: (schedule: ShiftSchedule) => void;
  updateShiftSchedule: (schedule: ShiftSchedule) => void;
  deleteShiftSchedule: (id: string) => void;

  // Fix: Handle cash transactions within a shift
  addCashTransaction: (shiftId: string, transaction: CashTransaction) => void;

  restoreSalesData: (data: any) => void;
}

export const useSalesStore = create<SalesState>((set) => ({
  sales: [], // Hydrated by INITIAL_SALES in data.ts via restore if needed, or left empty for fresh start
  quotations: [],
  customers: INITIAL_CUSTOMERS,
  customerLevels: INITIAL_CUSTOMER_LEVELS,
  shifts: [],
  shiftSchedules: INITIAL_SHIFT_SCHEDULES,
  promotions: INITIAL_PROMOTIONS,

  addSale: (sale) => set((state) => ({ sales: [sale, ...state.sales] })),
  updateSale: (sale) => set((state) => ({ sales: state.sales.map(s => s.id === sale.id ? sale : s) })),

  addQuotation: (q) => set((state) => ({ quotations: [q, ...state.quotations] })),
  updateQuotation: (q) => set((state) => ({ quotations: state.quotations.map(x => x.id === q.id ? q : x) })),
  deleteQuotation: (id) => set((state) => ({ quotations: state.quotations.filter(x => x.id !== id) })),

  addCustomer: (customer) => set((state) => ({ customers: [...state.customers, customer] })),
  updateCustomer: (customer) => set((state) => ({ customers: state.customers.map(c => c.id === customer.id ? customer : c) })),

  addCustomerLevel: (level) => set((state) => ({ customerLevels: [...state.customerLevels, level] })),
  updateCustomerLevel: (level) => set((state) => ({ customerLevels: state.customerLevels.map(l => l.id === level.id ? level : l) })),
  deleteCustomerLevel: (id) => set((state) => ({ customerLevels: state.customerLevels.filter(l => l.id !== id) })),

  addPromotion: (promo) => set((state) => ({ promotions: [...state.promotions, promo] })),
  updatePromotion: (promo) => set((state) => ({ promotions: state.promotions.map(p => p.id === promo.id ? promo : p) })),
  deletePromotion: (id) => set((state) => ({ promotions: state.promotions.filter(p => p.id !== id) })),

  addShift: (shift) => set((state) => ({ shifts: [shift, ...state.shifts] })),
  updateShift: (shift) => set((state) => ({ shifts: state.shifts.map(s => s.id === shift.id ? shift : s) })),

  addShiftSchedule: (schedule) => set((state) => ({ shiftSchedules: [...state.shiftSchedules, schedule] })),
  updateShiftSchedule: (schedule) => set((state) => ({ shiftSchedules: state.shiftSchedules.map(s => s.id === schedule.id ? schedule : s) })),
  deleteShiftSchedule: (id) => set((state) => ({ shiftSchedules: state.shiftSchedules.filter(s => s.id !== id) })),

  // Fix: implementation for adding cash transaction to a shift's internal list
  addCashTransaction: (shiftId, transaction) => set((state) => ({
    shifts: state.shifts.map(s => 
      s.id === shiftId 
        ? { ...s, cashTransactions: [...(s.cashTransactions || []), transaction] } 
        : s
    )
  })),

  restoreSalesData: (data) => set((state) => ({
    ...state,
    sales: data.sales || state.sales,
    customers: data.customers || state.customers,
    customerLevels: data.customerLevels || state.customerLevels,
    quotations: data.quotations || state.quotations,
    shifts: data.shifts || state.shifts,
    shiftSchedules: data.shiftSchedules || state.shiftSchedules,
    promotions: data.promotions || state.promotions,
  }))
}));

import React, { createContext, useContext, useEffect, useState } from 'react';
import { 
  User, Product, Sale, UnitDefinition, CategoryItem, Branch, PosMachine, 
  Warehouse, StorageLocation, StockTransfer, StockCount, StockReservation, 
  StockReceipt, StockAdjustment, SyncLog, Customer, CustomerLevel, Shift, 
