  onDelete: (id: string) => void;
}

export const UnitTree: React.FC<UnitTreeProps> = ({ units, onAdd, onEdit, onDelete }) => {
  // We assume units with parentId === null OR isBase === true as roots
  const rootUnits = units.filter(u => !u.parentId);

  return (
    <div className="flex-1 flex flex-col">
      <div className="px-8 py-6 border-b border-slate-50 bg-slate-50/30 flex items-center justify-between">
        <div className="flex items-center gap-2">
           <Layers className="w-5 h-5 text-slate-400" />
           <span className="text-sm font-black text-slate-500 uppercase tracking-widest">Hierarchy View</span>
        </div>
        <div className="flex gap-10 pr-32 text-[10px] font-black text-slate-400 uppercase tracking-widest hidden md:flex">
           <span className="w-24 text-center">Symbol</span>
           <span className="w-32 text-center">Factor</span>
           <span className="w-24 text-center">Actions</span>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto custom-scrollbar p-4 space-y-2">
        {rootUnits.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-full text-slate-300 py-20">
             <Layers className="w-16 h-16 mb-4 opacity-20" />
             <p className="font-bold uppercase tracking-widest">No units in this category</p>
          </div>
        ) : (
          rootUnits.map(unit => (
            <UnitTreeNode 
              key={unit.id}
              unit={unit}
              allUnits={units}
              level={0}
              onAdd={onAdd}
              onEdit={onEdit}
              onDelete={onDelete}
            />
          ))
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { UnitDefinition } from '../../types';
import { ChevronRight, ChevronDown, Hash, Edit2, Trash2, Plus, ArrowRightLeft } from 'lucide-react';
import { cn } from '../../lib/utils';
import { Badge } from '../ui/Badge';

interface UnitTreeNodeProps {
  unit: UnitDefinition;
  allUnits: UnitDefinition[];
  level: number;
  onAdd: (unit?: UnitDefinition, parentId?: string | null) => void;
  onEdit: (unit: UnitDefinition) => void;
  onDelete: (id: string) => void;
}

export const UnitTreeNode: React.FC<UnitTreeNodeProps> = ({ 
  unit, allUnits, level, onAdd, onEdit, onDelete 
}) => {
  const [isExpanded, setIsExpanded] = useState(true);
  const children = allUnits.filter(u => u.parentId === unit.id);
  const hasChildren = children.length > 0;

  return (
    <div className="animate-slide-in-right">
      <div 
        className={cn(
          "group flex items-center p-3 rounded-2xl transition-all duration-200 hover:bg-slate-50 border border-transparent hover:border-slate-100",
          level === 0 && "bg-white shadow-sm border-slate-50 mb-1"
        )}
        style={{ marginLeft: `${level * 32}px` }}
      >
        <div className="flex items-center flex-1 min-w-0">
          <button 
            onClick={() => setIsExpanded(!isExpanded)}
            className={cn(
              "mr-2 p-1.5 rounded-lg text-slate-300 hover:text-slate-600 hover:bg-white transition-all",
              !hasChildren && "invisible"
            )}
          >
            {isExpanded ? <ChevronDown className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}
          </button>

          <div className={cn(
            "mr-4 p-2.5 rounded-xl shrink-0 transition-transform group-hover:scale-110",
            unit.isBase ? "bg-slate-900 text-white shadow-lg" : "bg-slate-100 text-slate-500"
          )}>
            <Hash className="w-5 h-5" />
          </div>

          <div className="flex flex-col truncate">
            <div className="flex items-center gap-2">
               <span className={cn("font-black tracking-tight", level === 0 ? "text-slate-900 text-lg" : "text-slate-700")}>
                 {unit.name}
               </span>
               {unit.isBase && <Badge variant="primary">Base Unit</Badge>}
            </div>
            <span className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">ID: {unit.id.slice(-6)}</span>
          </div>
        </div>

        {/* Data Columns */}
        <div className="flex items-center gap-10 mr-4">
           <div className="w-24 text-center">
              <span className="font-mono text-sm font-black bg-slate-100 px-2 py-1 rounded-lg text-slate-600 border border-slate-200">
                {unit.symbol}
              </span>
           </div>

           <div className="w-32 text-center">
              {unit.isBase ? (
                <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest">Primary</span>
              ) : (
                <div className="flex items-center justify-center text-xs font-bold text-slate-600 bg-orange-50 px-2 py-1 rounded-lg border border-orange-100">
                   {unit.baseFactor}
                   <ArrowRightLeft className="w-3 h-3 mx-1 text-orange-300" />
                </div>
              )}
           </div>

           {/* Actions */}
           <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
              <button 
                onClick={() => onAdd(undefined, unit.id)}
                className="p-2 text-slate-400 hover:text-construction-orange hover:bg-orange-50 rounded-xl transition-all"
                title="Add Child Unit"
              >
                <Plus className="w-4 h-4" />
              </button>
              <button 
                onClick={() => onEdit(unit)}
                className="p-2 text-slate-400 hover:text-slate-900 hover:bg-slate-100 rounded-xl transition-all"
              >
                <Edit2 className="w-4 h-4" />
              </button>
              <button 
                onClick={() => onDelete(unit.id)}
                disabled={unit.isBase}
                className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all disabled:opacity-30"
              >
                <Trash2 className="w-4 h-4" />
              </button>
           </div>
        </div>
      </div>

      {isExpanded && hasChildren && (
        <div className="relative">
           {/* Visual connector line */}
           <div className="absolute left-[24px] top-0 bottom-4 w-0.5 bg-slate-100 rounded-full" style={{ marginLeft: `${level * 32}px` }} />

           {children.map(child => (
            <UnitTreeNode 
              key={child.id} 
              unit={child} 
              allUnits={allUnits}
              level={level + 1} 
              onAdd={onAdd}
              onEdit={onEdit}
              onDelete={onDelete}
            />
          ))}
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { UnitDefinition, UnitCategory } from '../../types';
