          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <Input 
              label="Unit Name"
              required
              value={formData.name}
              onChange={e => setFormData({...formData, name: e.target.value})}
              placeholder="e.g. Dozen"
            />
            <Input 
              label="Symbol"
              required
              value={formData.symbol}
              onChange={e => setFormData({...formData, symbol: e.target.value})}
              placeholder="e.g. doz"
