                      />
                      <div className={cn(
                         "w-12 h-6 rounded-full transition-all",
                         formData.isBase ? "bg-construction-orange" : "bg-slate-200"
                      )}></div>
                      <div className={cn(
                         "absolute left-1 top-1 bg-white w-4 h-4 rounded-full transition-transform",
