import React, { useState } from 'react';
import { RoleDefinition } from '../../types';
import { ShieldCheck, Plus, Edit2, Trash2, Info, CheckSquare, Square } from 'lucide-react';
import { RoleFormModal } from './RoleFormModal';

interface RoleManagementProps {
  roles: RoleDefinition[];
  onAdd: (role: RoleDefinition) => void;
  onUpdate: (role: RoleDefinition) => void;
  onDelete: (id: string) => void;
}

export const RoleManagement: React.FC<RoleManagementProps> = ({ roles, onAdd, onUpdate, onDelete }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingRole, setEditingRole] = useState<RoleDefinition | null>(null);

  const handleOpenAdd = () => {
    setEditingRole(null);
    setIsModalOpen(true);
  };

  const handleOpenEdit = (role: RoleDefinition) => {
    setEditingRole(role);
    setIsModalOpen(true);
  };

  const handleSubmit = (data: RoleDefinition) => {
    if (editingRole) {
      onUpdate(data);
    } else {
      onAdd(data);
    }
    setIsModalOpen(false);
  };

  return (
    <div className="flex flex-col gap-6 animate-fade-in flex-1">
      <div className="flex justify-between items-center">
        <div className="flex items-center gap-2">
           <Info className="w-4 h-4 text-slate-400" />
           <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Defined roles determine UI access and module permissions</p>
        </div>
        <button 
          onClick={handleOpenAdd}
          className="flex items-center px-6 py-3 bg-slate-900 text-white rounded-xl hover:bg-slate-800 transition-all font-black text-sm shadow-xl active:scale-95"
        >
          <Plus className="w-5 h-5 mr-2" />
          Define Role
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {roles.map(role => (
          <div key={role.id} className="bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm hover:shadow-xl transition-all group flex flex-col">
            <div className="flex justify-between items-start mb-4">
              <div className="p-3 bg-slate-100 text-slate-900 rounded-2xl group-hover:bg-construction-orange group-hover:text-white transition-colors">
                <ShieldCheck className="w-6 h-6" />
              </div>
              <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                <button onClick={() => handleOpenEdit(role)} className="p-2 text-slate-400 hover:text-slate-900 hover:bg-slate-50 rounded-lg"><Edit2 className="w-4 h-4" /></button>
                <button 
                  onClick={() => { if(confirm(`Delete the "${role.name}" role?`)) onDelete(role.id); }}
                  disabled={role.name === 'Admin'}
                  className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg disabled:opacity-0"
                >
                  <Trash2 className="w-4 h-4" />
                </button>
              </div>
            </div>

            <h3 className="text-xl font-black text-slate-900 uppercase tracking-widest mb-2">{role.name}</h3>
            <p className="text-xs text-slate-400 font-medium leading-relaxed mb-6 flex-1">{role.description || 'No description provided.'}</p>

            <div className="pt-4 border-t border-slate-50">
               <p className="text-[9px] font-black text-slate-300 uppercase tracking-[0.2em] mb-3">Permissions ({role.permissions.length})</p>
               <div className="flex flex-wrap gap-1.5">
                  {role.permissions.slice(0, 5).map(p => (
                    <span key={p} className="px-2 py-0.5 bg-slate-50 text-slate-500 text-[9px] font-black rounded-full uppercase border border-slate-100">
                      {p}
                    </span>
                  ))}
                  {role.permissions.length > 5 && (
                    <span className="px-2 py-0.5 bg-orange-50 text-orange-600 text-[9px] font-black rounded-full uppercase border border-orange-100">
                       +{role.permissions.length - 5} More
                    </span>
                  )}
               </div>
            </div>
          </div>
        ))}
      </div>

      <RoleFormModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSubmit={handleSubmit}
        initialData={editingRole}
      />
    </div>
  );
};

