export const RoleFormModal: React.FC<RoleFormModalProps> = ({ isOpen, onClose, onSubmit, initialData }) => {
  const [formData, setFormData] = useState<Partial<RoleDefinition>>({
    name: '',
    description: '',
    permissions: []
  });

  useEffect(() => {
    if (initialData) {
      setFormData(initialData);
    } else {
      setFormData({ name: '', description: '', permissions: [] });
    }
  }, [initialData, isOpen]);

  const togglePermission = (id: string) => {
    setFormData(prev => {
      const perms = prev.permissions || [];
      if (perms.includes(id)) {
        return { ...prev, permissions: perms.filter(p => p !== id) };
      }
      return { ...prev, permissions: [...perms, id] };
    });
  };

  const handleSelectAll = () => {
    const allIds = PERMISSION_GROUPS.flatMap(g => g.items.map(i => i.id));
    setFormData(prev => ({ ...prev, permissions: allIds }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name) return;
    onSubmit({
      ...formData,
      id: initialData?.id || `role-${Date.now()}`,
      permissions: formData.permissions || []
    } as RoleDefinition);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-[100] p-4 animate-fade-in">
      <div className="bg-white rounded-[3.5rem] shadow-2xl w-full max-w-5xl max-h-[90vh] overflow-hidden flex flex-col border border-white/20">
        <div className="p-10 border-b border-slate-100 flex justify-between items-center bg-slate-50/50 shrink-0">
          <div className="flex items-center gap-4">
             <div className="p-3 bg-slate-900 text-white rounded-2xl">
                <ShieldCheck className="w-6 h-6" />
             </div>
             <div>
                <h3 className="text-3xl font-black text-slate-900 tracking-tight">Role Definition</h3>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">Configure Access Matrix</p>
             </div>
          </div>
          <button onClick={onClose} className="p-2 bg-white rounded-full text-slate-400 hover:text-slate-600 shadow-sm border border-slate-100">
            <X className="w-6 h-6" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar bg-white">
          <form id="role-form" onSubmit={handleSubmit} className="p-10">
             <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
                {/* Basic Info */}
                <div className="lg:col-span-1 space-y-8">
                   <div>
                      <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Role Name</label>
                      <input
                        required
                        type="text"
                        value={formData.name}
                        onChange={e => setFormData({...formData, name: e.target.value})}
                        className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl focus:ring-4 focus:ring-orange-100 focus:border-construction-orange focus:bg-white transition-all outline-none font-bold text-slate-900"
                        placeholder="e.g. Sales Lead"
                      />
                   </div>
                   <div>
                      <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-2 ml-1">Role Purpose</label>
                      <textarea
                        value={formData.description}
                        onChange={e => setFormData({...formData, description: e.target.value})}
                        className="w-full px-5 py-4 bg-slate-50 border-2 border-slate-50 rounded-2xl focus:ring-4 focus:ring-orange-100 focus:border-construction-orange focus:bg-white transition-all outline-none font-bold text-slate-800 resize-none h-32"
                        placeholder="Describe what this role manages..."
                      />
                   </div>
                   <div className="p-6 bg-blue-50 border border-blue-100 rounded-[2rem]">
                      <h4 className="flex items-center text-xs font-black text-blue-900 uppercase tracking-widest mb-3">
                         <Info className="w-4 h-4 mr-2" /> Security Notice
                      </h4>
                      <p className="text-[11px] text-blue-700 font-medium leading-relaxed">
                         Roles define which sidebar menus and system actions are visible to the user. System critical functions should be restricted to verified administrators.
                      </p>
                   </div>
                </div>

                {/* Permissions Grid */}
                <div className="lg:col-span-2">
                   <div className="flex justify-between items-center mb-6">
                      <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Module Permissions</label>
                      <button 
                        type="button" 
                        onClick={handleSelectAll}
                        className="text-[10px] font-black text-construction-orange uppercase tracking-widest hover:underline"
                      >
                         Select All Access
                      </button>
                   </div>

                   <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                      {PERMISSION_GROUPS.map((group, gIdx) => (
                        <div key={gIdx} className="bg-slate-50/50 p-6 rounded-3xl border border-slate-100">
                           <div className="flex items-center gap-2 mb-4 border-b border-slate-100 pb-3">
                              <group.icon className="w-4 h-4 text-slate-400" />
                              <span className="text-xs font-black text-slate-700 uppercase tracking-widest">{group.label}</span>
                           </div>
                           <div className="space-y-2">
                              {group.items.map(item => {
                                const isChecked = formData.permissions?.includes(item.id);
                                return (
                                  <button
                                    key={item.id}
                                    type="button"
                                    onClick={() => togglePermission(item.id)}
                                    className={`flex items-center w-full p-3 rounded-xl transition-all ${isChecked ? 'bg-white shadow-sm ring-1 ring-slate-100' : 'hover:bg-slate-100'}`}
                                  >
                                     <div className={`w-5 h-5 rounded-md border-2 flex items-center justify-center transition-all mr-3 ${isChecked ? 'bg-construction-orange border-construction-orange text-white' : 'bg-white border-slate-200'}`}>
                                        {isChecked && <Check className="w-3.5 h-3.5 font-black" />}
                                     </div>
                                     <span className={`text-xs font-bold ${isChecked ? 'text-slate-900' : 'text-slate-500'}`}>{item.label}</span>
                                  </button>
                                );
                              })}
                           </div>
                        </div>
                      ))}
                   </div>
                </div>
             </div>
          </form>
        </div>

        <div className="p-10 border-t border-slate-100 bg-white flex justify-end gap-4 shrink-0">
          <button
            type="button"
            onClick={onClose}
            className="px-8 py-3 text-xs font-black text-slate-400 uppercase tracking-widest hover:text-slate-600 transition-colors"
          >
            Cancel
          </button>
          <button
            type="submit"
            form="role-form"
            className="px-10 py-4 bg-slate-900 text-white font-black text-sm uppercase tracking-widest rounded-2xl hover:bg-slate-800 transition-all shadow-xl shadow-slate-200 active:scale-95"
          >
            {initialData ? 'Update Role' : 'Confirm Role'}
          </button>
        </div>
      </div>
    </div>
  );
};

