                      <div className="w-2 h-2 bg-emerald-500 rounded-full mr-2 shadow-[0_0_8px_rgba(16,185,129,0.5)]"></div>
                      <span className="text-[10px] font-black text-slate-700 uppercase tracking-widest">Active</span>
                   </div>
                </td>
                <td className="px-8 py-5 text-right pr-10">
                  <div className="flex justify-end space-x-2 opacity-0 group-hover:opacity-100 transition-opacity">
                     <button 
                        onClick={() => onEdit(user)} 
                        className={`p-2 rounded-xl transition-all ${user.role === 'Admin' && currentUser?.role !== 'Admin' ? 'text-slate-200 cursor-not-allowed' : 'text-slate-400 hover:text-slate-900 hover:bg-slate-100'}`}
                      >
                        <Edit2 className="w-4 h-4" />
                      </button>
                      <button 
                        onClick={() => onDelete(user)} 
                        className={`p-2 rounded-xl transition-all ${user.role === 'Admin' && currentUser?.role !== 'Admin' ? 'text-slate-200 cursor-not-allowed' : 'text-slate-400 hover:text-red-600 hover:bg-red-50'}`}
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
};

import React, { useRef, useState, useEffect } from 'react';
import { 
  Menu, 
  Search, 
  Keyboard, 
  Bell, 
  UserCircle, 
  ChevronDown, 
  Settings, 
  LogOut 
} from 'lucide-react';
import { User, AppNotification } from '../../types';

interface TopBarProps {
  setMobileMenuOpen: (open: boolean) => void;
  mobileMenuOpen: boolean;
  onTabChange: (tab: string) => void;
  setShowKeyboardHelp: (show: boolean) => void;
  notifications: AppNotification[];
  clearAllNotifications: () => void;
  markNotificationRead: (id: string) => void;
  currentUser: User | null;
  onLogout: () => void;
}

export const TopBar: React.FC<TopBarProps> = ({
  setMobileMenuOpen,
  mobileMenuOpen,
  onTabChange,
  setShowKeyboardHelp,
  notifications,
  clearAllNotifications,
  markNotificationRead,
  currentUser,
  onLogout
}) => {
  const [showNotifications, setShowNotifications] = useState(false);
  const [showUserMenu, setShowUserMenu] = useState(false);
  const searchInputRef = useRef<HTMLInputElement>(null);
  const notifRef = useRef<HTMLDivElement>(null);
  const userMenuRef = useRef<HTMLDivElement>(null);

  const unreadCount = notifications.filter(n => !n.read).length;

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (notifRef.current && !notifRef.current.contains(event.target as Node)) {
        setShowNotifications(false);
      }
      if (userMenuRef.current && !userMenuRef.current.contains(event.target as Node)) {
        setShowUserMenu(false);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key === 'k') {
        e.preventDefault();
        searchInputRef.current?.focus();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, []);

  return (
    <header className="h-20 bg-white/80 backdrop-blur-md border-b border-slate-200/50 flex items-center justify-between px-6 z-30 sticky top-0">
      <button onClick={() => setMobileMenuOpen(!mobileMenuOpen)} className="p-3 md:hidden text-slate-600 hover:bg-slate-100 rounded-2xl transition-colors">
        <Menu className="w-6 h-6" />
      </button>

      {/* Search Bar - Style A Minimalist */}
      <div className="hidden md:flex items-center bg-slate-100/50 border border-slate-200/50 rounded-2xl px-5 py-2.5 w-64 lg:w-[420px] group focus-within:border-construction-orange focus-within:ring-4 focus-within:ring-orange-100 focus-within:bg-white transition-all duration-300">
         <Search className="w-4 h-4 text-slate-400 mr-3 group-focus-within:text-construction-orange" />
         <input 
           ref={searchInputRef}
           type="text" 
           placeholder="Search records (Ctrl+K)..." 
           className="bg-transparent text-sm font-bold focus:outline-none w-full text-slate-800 placeholder:text-slate-400"
         />
         <kbd className="hidden lg:inline-flex items-center text-[10px] font-black text-slate-400 bg-white border border-slate-200 rounded-lg px-2 py-1 ml-2 font-mono shadow-sm">
           ⌘K
         </kbd>
      </div>

      {/* Right Actions */}
      <div className="flex items-center space-x-2 md:space-x-4">
         <button 
            onClick={() => setShowKeyboardHelp(true)}
            className="p-3 text-slate-400 hover:text-slate-900 hover:bg-slate-100 rounded-2xl hidden md:block transition-all"
            title="Keyboard Shortcuts"
         >
            <Keyboard className="w-5 h-5" />
         </button>

         {/* Notifications */}
         <div className="relative" ref={notifRef}>
            <button 
              onClick={() => setShowNotifications(!showNotifications)}
              className="p-3 text-slate-400 hover:text-slate-900 hover:bg-slate-100 rounded-2xl relative transition-all"
            >
               <Bell className="w-6 h-6" />
               {unreadCount > 0 && (
                  <span className="absolute top-2.5 right-2.5 w-3 h-3 bg-red-500 border-2 border-white rounded-full shadow-sm"></span>
               )}
            </button>

            {showNotifications && (
               <div className="absolute right-0 mt-4 w-96 bg-white rounded-[2rem] shadow-2xl border border-slate-100 overflow-hidden z-50 animate-fade-in origin-top-right ring-1 ring-black/5">
                  <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
                     <h3 className="font-black text-slate-800 uppercase tracking-widest text-xs">System Alerts</h3>
                     {notifications.length > 0 && (
                        <button onClick={clearAllNotifications} className="text-[10px] font-black text-orange-600 uppercase tracking-widest hover:text-orange-700">Clear all</button>
                     )}
                  </div>
                  <div className="max-h-[400px] overflow-y-auto custom-scrollbar">
                     {notifications.length === 0 ? (
                        <div className="p-12 text-center text-slate-400">
                           <Bell className="w-10 h-10 mx-auto mb-3 opacity-10" />
                           <p className="text-sm font-bold uppercase tracking-widest opacity-50">All Clear</p>
                        </div>
                     ) : (
                        <div className="divide-y divide-slate-50">
                           {notifications.map(n => (
                              <div 
                                key={n.id} 
                                className={`p-5 hover:bg-slate-50 transition-colors cursor-pointer ${!n.read ? 'bg-orange-50/20' : ''}`}
                                onClick={() => {
                                   markNotificationRead(n.id);
                                   if(n.link) onTabChange(n.link.replace('/', ''));
                                }}
                              >
                                 <div className="flex justify-between items-start mb-1.5">
                                    <h4 className={`text-sm font-black tracking-tight ${!n.read ? 'text-slate-900' : 'text-slate-500'}`}>{n.title}</h4>
                                    <span className="text-[10px] font-black text-slate-300 whitespace-nowrap ml-3 uppercase">{new Date(n.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</span>
                                 </div>
                                 <p className="text-xs text-slate-500 font-medium leading-relaxed line-clamp-2">{n.message}</p>
                              </div>
                           ))}
                        </div>
                     )}
                  </div>
               </div>
            )}
         </div>

         {/* User Profile */}
         <div className="relative" ref={userMenuRef}>
            <button 
              onClick={() => setShowUserMenu(!showUserMenu)}
              className="flex items-center space-x-3 hover:bg-slate-100 p-2 pr-4 rounded-2xl border border-transparent transition-all group"
            >
               <div className="w-10 h-10 rounded-2xl bg-slate-900 overflow-hidden flex items-center justify-center border-2 border-white shadow-lg group-hover:scale-105 transition-transform">
                  {currentUser?.avatarUrl ? (
                     <img src={currentUser.avatarUrl} alt={currentUser.name} className="w-full h-full object-cover" />
                  ) : (
                     <UserCircle className="w-7 h-7 text-white" />
                  )}
               </div>
               <div className="hidden md:block text-left">
                  <p className="text-sm font-black text-slate-900 leading-none">{currentUser?.name}</p>
                  <p className="text-[10px] text-slate-400 uppercase font-black mt-1.5 tracking-widest">{currentUser?.role}</p>
               </div>
               <ChevronDown className="w-4 h-4 text-slate-400 hidden md:block group-hover:text-slate-900 transition-colors" />
            </button>

            {showUserMenu && (
               <div className="absolute right-0 mt-4 w-64 bg-white rounded-[2rem] shadow-2xl border border-slate-100 overflow-hidden z-50 animate-fade-in origin-top-right ring-1 ring-black/5">
                  <div className="p-6 border-b border-slate-100 bg-slate-50/50">
                     <p className="font-black text-slate-900 leading-tight">{currentUser?.name}</p>
                     <p className="text-[10px] text-slate-400 font-black uppercase mt-1 tracking-[0.2em]">{currentUser?.role}</p>
                  </div>
                  <div className="p-2">
                     <button 
                       onClick={() => { onTabChange('profile'); setShowUserMenu(false); }}
                       className="flex items-center w-full px-4 py-3.5 text-xs font-black uppercase tracking-widest text-slate-700 hover:bg-slate-100 rounded-xl transition-all mb-1"
                     >
                        <UserCircle className="w-4 h-4 mr-3 text-slate-400" /> My Account
                     </button>

                     {currentUser?.role === 'Admin' && (
                       <button 
                         onClick={() => { onTabChange('settings'); setShowUserMenu(false); }}
                         className="flex items-center w-full px-4 py-3.5 text-xs font-black uppercase tracking-widest text-slate-700 hover:bg-slate-100 rounded-xl transition-all"
                       >
                          <Settings className="w-4 h-4 mr-3 text-slate-400" /> Config
                       </button>
                     )}

                     <div className="border-t border-slate-50 my-2 mx-3"></div>

                     <button 
                       onClick={onLogout}
                       className="flex items-center w-full px-4 py-3.5 text-xs font-black uppercase tracking-widest text-red-600 hover:bg-red-50 rounded-xl transition-all"
                     >
                        <LogOut className="w-4 h-4 mr-3" /> Sign Out
                     </button>
                  </div>
               </div>
            )}
         </div>
      </div>
    </header>
  );
};

import React, { useState } from 'react';
import { User, UserRoleDefinition, Department } from '../types';
import { Plus, Users, ShieldCheck, Briefcase, Lock } from 'lucide-react';
import { useGlobal } from '../context/GlobalContext';
import { UserList } from './user/UserList';
import { UserFormModal } from './user/UserFormModal';
import { RoleTab } from './user/RoleTab';
import { DepartmentTab } from './user/DepartmentTab';

export const UserManagement: React.FC = () => {
  const { 
    users, addUser, updateUser, deleteUser,
    roles, addRole, updateRole, deleteRole,
    departments, addDepartment, updateDepartment, deleteDepartment,
    branches, currentUser, permissions
  } = useGlobal();

  const [activeTab, setActiveTab] = useState<'users' | 'roles' | 'departments'>('users');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingUser, setEditingUser] = useState<User | undefined>(undefined);

  const handleOpenModal = (user?: User) => {
    if (user && user.role === 'Admin' && currentUser?.role !== 'Admin') {
      alert("Only Administrators can edit other Administrator accounts.");
      return;
    }
    setEditingUser(user);
    setIsModalOpen(true);
  };

  const handleDeleteUser = (user: User) => {
    if (user.role === 'Admin' && currentUser?.role !== 'Admin') {
      alert("Only Administrators can delete Administrator accounts.");
      return;
    }
    if (confirm(`Are you sure you want to delete ${user.name}?`)) {
      deleteUser(user.id);
    }
  };

  const handleSubmitUser = (formData: any, isEdit: boolean) => {
    const userData: any = {
      username: formData.username,
      name: formData.name,
      email: formData.email,
      role: formData.role,
      avatarUrl: formData.avatarUrl,
      departmentId: formData.departmentId,
      branchId: formData.branchId
    };

    if (formData.password) {
      userData.password = formData.password;
    }

    if (isEdit && editingUser) {
        const existing = users.find(u => u.id === editingUser.id);
        if (existing && !userData.password) {
            userData.password = existing.password;
        }
        updateUser({ ...userData, id: editingUser.id });
    } else {
        addUser({ ...userData, id: `u-${Date.now()}` });
    }
    setIsModalOpen(false);
  };

  return (
    <div className="space-y-8 h-full flex flex-col pb-20 md:pb-0 animate-fade-in max-w-[1600px] mx-auto w-full px-1">
      {/* Page Header - Style A */}
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-6">
        <div>
          <div className="flex items-center gap-3 mb-2">
             <div className="p-2 bg-slate-900 text-white rounded-xl">
                <Lock className="w-5 h-5" />
             </div>
             <h2 className="text-4xl font-black text-slate-900 tracking-tight">Access Control</h2>
          </div>
          <p className="text-slate-400 font-bold text-xs uppercase tracking-[0.2em] flex items-center ml-11">
            <Users className="w-4 h-4 mr-2 text-construction-orange" />
            Personnel, Roles & Infrastructure
          </p>
        </div>

        <div className="flex bg-slate-100 p-1.5 rounded-2xl w-fit shadow-inner">
           {[
             { id: 'users', label: 'Users', icon: Users },
             { id: 'roles', label: 'Roles', icon: ShieldCheck },
             { id: 'departments', label: 'Departments', icon: Briefcase },
           ].map((tab) => (
             <button
               key={tab.id}
               onClick={() => setActiveTab(tab.id as any)}
               className={`flex items-center px-8 py-2.5 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${
                 activeTab === tab.id 
                   ? 'bg-white text-slate-900 shadow-md scale-105' 
                   : 'text-slate-400 hover:text-slate-600'
               }`}
             >
               <tab.icon className="w-4 h-4 mr-2" />
               <span className="hidden sm:inline">{tab.label}</span>
             </button>
           ))}
        </div>
      </div>

      <div className="flex-1 min-h-0 flex flex-col">
        {activeTab === 'users' && (
          <div className="flex flex-col gap-6 flex-1 animate-fade-in">
             <div className="flex justify-end">
                <button 
                  onClick={() => handleOpenModal()}
                  className="flex items-center px-8 py-4 bg-slate-900 text-white rounded-[2rem] hover:bg-slate-800 transition-all font-black text-sm shadow-xl active:scale-95"
                >
                  <Plus className="w-5 h-5 mr-2" />
                  Add New User
                </button>
             </div>
             <UserList 
                users={users} 
                branches={branches} 
                currentUser={currentUser} 
                onEdit={handleOpenModal} 
                onDelete={handleDeleteUser} 
             />
          </div>
        )}

        {activeTab === 'roles' && (
          <RoleTab 
            roles={roles}
            permissions={permissions}
            onAdd={addRole}
            onUpdate={updateRole}
            onDelete={deleteRole} 
          />
        )}

        {activeTab === 'departments' && (
          <DepartmentTab 
            departments={departments}
            onAdd={addDepartment}
            onUpdate={updateDepartment}
            onDelete={deleteDepartment} 
          />
        )}
      </div>

      <UserFormModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        onSubmit={handleSubmitUser}
        initialData={editingUser}
        branches={branches}
        departments={departments}
        roles={roles}
        currentUser={currentUser}
      />
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { User, Branch, UserRoleDefinition, Department } from '../../types';
import { X, UserCircle, Edit2, Lock, Mail, Briefcase, Building2, CheckCircle, ShieldCheck, Hash } from 'lucide-react';
import { Input } from '../ui/Input';
import { Button } from '../ui/Button';

interface UserFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (formData: any, isEdit: boolean) => void;
  initialData?: User;
  branches: Branch[];
  departments: Department[];
  roles: UserRoleDefinition[];
  currentUser: User | null;
}

const MAX_FILE_SIZE_MB = 5;
const MAX_FILE_SIZE_BYTES = MAX_FILE_SIZE_MB * 1024 * 1024;

export const UserFormModal: React.FC<UserFormModalProps> = ({ 
  isOpen, onClose, onSubmit, initialData, branches, departments, roles, currentUser 
}) => {
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<User>>({
    username: '',
    password: '',
    name: '',
    email: '',
    role: 'Cashier',
    avatarUrl: '',
    departmentId: '',
    branchId: ''
  });

  useEffect(() => {
    if (initialData) {
      setFormData({ 
        username: initialData.username,
        name: initialData.name,
        email: initialData.email || '',
        role: initialData.role,
        avatarUrl: initialData.avatarUrl || '',
        password: '',
        departmentId: initialData.departmentId || '',
        branchId: initialData.branchId || ''
      });
    } else {
      setFormData({
        username: '',
        password: '',
        name: '',
        email: '',
        role: roles[0]?.name || 'Cashier',
        avatarUrl: '',
        departmentId: departments[0]?.id || '',
        branchId: branches[0]?.id || ''
      });
    }
  }, [initialData, isOpen, roles, departments, branches]);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.size > MAX_FILE_SIZE_BYTES) {
      alert(`File size exceeds the limit of ${MAX_FILE_SIZE_MB}MB.`);
      return;
    }

    const reader = new FileReader();
    reader.onloadend = () => {
      setFormData(prev => ({ ...prev, avatarUrl: reader.result as string }));
    };
    reader.readAsDataURL(file);
  };

  const handleRemoveImage = () => {
    setFormData(prev => ({ ...prev, avatarUrl: '' }));
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.username || !formData.name || !formData.role) return;
    if (!initialData && !formData.password) {
        alert("Password is required for new users.");
        return;
    }
    if (currentUser?.role !== 'Admin' && formData.role === 'Admin') {
       alert("You do not have permission to create Administrator accounts.");
       return;
    }
    onSubmit(formData, !!initialData);
  };

  if (!isOpen) return null;

  const selectedRoleDef = roles.find(r => r.name === formData.role);

  return (
    <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-50 p-4 animate-fade-in">
      <div className="bg-white rounded-[3rem] shadow-2xl w-full max-w-4xl max-h-[90vh] overflow-hidden flex flex-col border border-white/20">
        <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50/50 shrink-0">
          <div>
            <h3 className="text-3xl font-black text-slate-900 tracking-tight">
              {initialData ? 'Edit Identity' : 'Register Identity'}
            </h3>
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">Staff Access & Profile Configuration</p>
          </div>
          <button onClick={onClose} className="p-2 bg-white rounded-full text-slate-400 hover:text-slate-600 shadow-sm border border-slate-100 transition-colors">
            <X className="w-6 h-6" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto custom-scrollbar">
          <form onSubmit={handleSubmit} className="p-10">
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
              {/* Left Column: Form Fields */}
              <div className="space-y-6">
                <div className="flex items-center space-x-6 pb-6 border-b border-slate-50">
                  <div 
                    onClick={() => fileInputRef.current?.click()}
                    className="relative w-24 h-24 rounded-[2rem] bg-slate-900 overflow-hidden flex items-center justify-center cursor-pointer border-4 border-white shadow-xl group transition-transform hover:scale-105"
                  >
                    {formData.avatarUrl ? (
                      <>
                        <img src={formData.avatarUrl} alt="Preview" className="w-full h-full object-cover" />
                        <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                           <Edit2 className="w-5 h-5 text-white" />
                        </div>
                      </>
                    ) : (
                      <UserCircle className="w-10 h-10 text-white/40" />
                    )}
                  </div>

                  <div className="flex-1">
                     <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-2">Profile Image</p>
                     <div className="flex space-x-2">
                        <button
                          type="button"
                          onClick={() => fileInputRef.current?.click()}
                          className="px-4 py-2 bg-white border-2 border-slate-100 rounded-xl text-[10px] font-black uppercase tracking-widest text-slate-700 hover:border-slate-200 transition-all"
                        >
                          Change
                        </button>
                        {formData.avatarUrl && (
                          <button
                            type="button"
                            onClick={handleRemoveImage}
                            className="px-4 py-2 bg-white border-2 border-red-50 rounded-xl text-[10px] font-black uppercase tracking-widest text-red-600 hover:border-red-100 transition-all"
                          >
                            Remove
                          </button>
                        )}
                     </div>
                  </div>
                  <input 
                    type="file" 
                    ref={fileInputRef} 
                    className="hidden" 
                    accept="image/*"
                    onChange={handleImageUpload}
                  />
                </div>

                <Input 
                   label="Full Name"
                   required
                   value={formData.name}
                   onChange={e => setFormData({...formData, name: e.target.value})}
                   placeholder="e.g. John Wick"
                />

                <div className="grid grid-cols-2 gap-6">
                  <Input 
                    label="Username"
                    required
                    icon={<Hash className="w-4 h-4" />}
                    value={formData.username}
                    onChange={e => setFormData({...formData, username: e.target.value})}
                    placeholder="jwick"
                  />
                  <Input 
                    label={initialData ? "Update Password" : "Secure Password"}
                    required={!initialData}
                    type="password"
                    icon={<Lock className="w-4 h-4" />}
                    value={formData.password}
                    onChange={e => setFormData({...formData, password: e.target.value})}
                    placeholder="••••••••"
                  />
                </div>

                <Input 
                   label="Email Address"
                   type="email"
                   icon={<Mail className="w-4 h-4" />}
                   value={formData.email}
                   onChange={e => setFormData({...formData, email: e.target.value})}
                   placeholder="wick@continental.com"
                />

                <div className="grid grid-cols-2 gap-6">
                  <div className="space-y-1.5">
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Business Unit / Dept</label>
                    <div className="relative group">
                       <Briefcase className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-300 group-focus-within:text-construction-orange transition-colors" />
                       <select
                         value={formData.departmentId || ''}
                         onChange={e => setFormData({...formData, departmentId: e.target.value})}
                         className="w-full pl-12 pr-4 py-3.5 bg-slate-50 border-2 border-slate-50 rounded-2xl focus:ring-4 focus:ring-orange-100 focus:border-construction-orange transition-all outline-none font-bold text-slate-800 appearance-none"
                       >
                         <option value="">Unassigned</option>
                         {departments.map(d => (
                           <option key={d.id} value={d.id}>{d.name}</option>
                         ))}
                       </select>
                    </div>
                  </div>
                  <div className="space-y-1.5">
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Primary Station / Branch</label>
                    <div className="relative group">
