            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { UserRoleDefinition, Permission } from '../../types';
import { ShieldCheck, Plus, Edit2, Trash2, Info, Lock } from 'lucide-react';
import { RoleFormModal } from './RoleFormModal';

interface RoleTabProps {
  roles: UserRoleDefinition[];
  permissions: Permission[];
  onAdd: (role: UserRoleDefinition) => void;
  onUpdate: (role: UserRoleDefinition) => void;
  onDelete: (id: string) => void;
}

export const RoleTab: React.FC<RoleTabProps> = ({ roles, permissions, onAdd, onUpdate, onDelete }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingRole, setEditingRole] = useState<UserRoleDefinition | undefined>(undefined);

  const handleOpenModal = (role?: UserRoleDefinition) => {
    setEditingRole(role);
    setIsModalOpen(true);
  };

  const handleSave = (data: Partial<UserRoleDefinition>) => {
    if (editingRole) {
      onUpdate({ ...editingRole, ...data } as UserRoleDefinition);
    } else {
      onAdd({ ...data, id: `role-${Date.now()}` } as UserRoleDefinition);
    }
  };

  return (
    <div className="flex flex-col h-full space-y-6 animate-fade-in">
       <div className="flex justify-end">
          <button 
            onClick={() => handleOpenModal()}
            className="flex items-center px-8 py-4 bg-slate-900 text-white rounded-[2rem] hover:bg-slate-800 transition-all font-black text-sm shadow-xl active:scale-95"
          >
             <Plus className="w-5 h-5 mr-2" /> Add New Role
          </button>
       </div>

       <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 overflow-y-auto pr-2 custom-scrollbar pb-10">
          {roles.map(role => (
             <div key={role.id} className="bg-white p-8 rounded-[3rem] border-2 border-slate-100 hover:border-construction-orange transition-all group flex flex-col h-full relative overflow-hidden shadow-sm hover:shadow-2xl hover:-translate-y-1">
                <div className="flex justify-between items-start mb-8">
                   <div className={`p-4 rounded-[1.5rem] shadow-xl ${role.isSystem ? 'bg-slate-900 text-white shadow-slate-200' : 'bg-orange-50 text-orange-600 shadow-orange-100'}`}>
                      <ShieldCheck className="w-8 h-8" />
                   </div>
                   <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-all translate-x-2 group-hover:translate-x-0">
                      <button onClick={() => handleOpenModal(role)} className="p-3 text-slate-400 hover:text-slate-900 hover:bg-slate-50 rounded-2xl transition-all">
                         <Edit2 className="w-5 h-5" />
                      </button>
                      {!role.isSystem && (
                        <button onClick={() => confirm('Permanently delete this access role?') && onDelete(role.id)} className="p-3 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-2xl transition-all">
                           <Trash2 className="w-5 h-5" />
                        </button>
                      )}
                   </div>
                </div>

                <div className="mb-8">
                   <div className="flex items-center gap-3 mb-2">
                      <h4 className="text-2xl font-black text-slate-900 uppercase tracking-tighter leading-none">{role.name}</h4>
                      {role.isSystem && <span className="text-[9px] font-black bg-slate-900 text-white px-2 py-1 rounded-lg uppercase tracking-widest">Core</span>}
                   </div>
                   <p className="text-sm font-medium text-slate-400 leading-relaxed">{role.description || 'Defines functional access boundaries for personnel.'}</p>
                </div>

                <div className="space-y-4 mt-auto border-t border-slate-50 pt-6">
                   <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-2 flex items-center">
                      <Lock className="w-3.5 h-3.5 mr-2 text-construction-orange" /> {role.permissions.length} Enabled Modules
                   </p>
                   <div className="flex flex-wrap gap-2">
                      {role.permissions.slice(0, 5).map(pId => {
                        const p = permissions.find(x => x.id === pId);
                        return (
                          <span key={pId} className="text-[10px] font-black bg-slate-50 text-slate-600 border border-slate-100 px-3 py-1.5 rounded-xl uppercase tracking-wide">
                             {p?.label || pId}
                          </span>
                        );
                      })}
                      {role.permissions.length > 5 && (
                         <span className="text-[10px] font-black bg-slate-900 text-white px-3 py-1.5 rounded-xl border border-slate-900">
                            +{role.permissions.length - 5} MORE
                         </span>
                      )}
                   </div>
                </div>
             </div>
          ))}
       </div>

       <RoleFormModal 
          isOpen={isModalOpen}
          onClose={() => setIsModalOpen(false)}
          onSubmit={handleSave}
          initialData={editingRole}
          allPermissions={permissions}
       />
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { UserRoleDefinition, Permission } from '../../types';
import { X, Check, ShieldCheck, CheckCircle2, Lock } from 'lucide-react';
import { Button } from '../ui/Button';
import { Input } from '../ui/Input';

interface RoleFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (data: Partial<UserRoleDefinition>) => void;
  initialData?: UserRoleDefinition;
  allPermissions: Permission[];
}

export const RoleFormModal: React.FC<RoleFormModalProps> = ({ 
  isOpen, onClose, onSubmit, initialData, allPermissions 
}) => {
  const [form, setForm] = useState<Partial<UserRoleDefinition>>({
    name: '', description: '', permissions: []
  });

  useEffect(() => {
    if (initialData) setForm(initialData);
    else setForm({ name: '', description: '', permissions: [] });
  }, [initialData, isOpen]);

  const togglePermission = (id: string) => {
     setForm(prev => {
        const current = prev.permissions || [];
        const next = current.includes(id) ? current.filter(x => x !== id) : [...current, id];
        return { ...prev, permissions: next };
     });
  };

  const handleSelectAll = () => {
     setForm(prev => ({ ...prev, permissions: allPermissions.map(p => p.id) }));
  };

  const handleClearAll = () => {
     setForm(prev => ({ ...prev, permissions: [] }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!form.name) return;
    onSubmit(form);
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center z-[100] p-4 animate-fade-in">
      <div className="bg-white rounded-[3.5rem] shadow-2xl w-full max-w-5xl max-h-[90vh] flex flex-col overflow-hidden border border-white/20">
        <div className="p-8 border-b border-slate-100 flex justify-between items-center bg-slate-50/50 shrink-0">
          <div className="flex items-center gap-4">
             <div className="p-3 bg-slate-900 text-white rounded-2xl shadow-xl">
                <ShieldCheck className="w-8 h-8" />
             </div>
             <div>
                <h3 className="text-3xl font-black text-slate-900 tracking-tight">
                  {initialData ? 'Edit Permissions' : 'Define Access Role'}
                </h3>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mt-1">Configure functional access boundaries</p>
             </div>
          </div>
          <button onClick={onClose} className="p-2 bg-white rounded-full text-slate-400 hover:text-slate-600 shadow-sm border border-slate-100">
            <X className="w-6 h-6" />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-10 space-y-10 flex-1 overflow-y-auto custom-scrollbar">
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-12">
             <div className="space-y-6">
                <Input 
                  label="Role Title"
                  required
                  value={form.name}
                  onChange={e => setForm({...form, name: e.target.value})}
                  placeholder="e.g. Master Logistics"
                  className="text-xl font-black uppercase tracking-tighter"
                />

                <div className="space-y-2">
                   <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Functional Mandate</label>
                   <textarea
                     value={form.description || ''}
                     onChange={e => setForm({...form, description: e.target.value})}
                     className="w-full bg-slate-50 border-2 border-slate-50 rounded-[2rem] p-6 transition-all outline-none font-bold text-slate-800 focus:ring-4 focus:ring-orange-100 focus:border-construction-orange focus:bg-white resize-none h-40 placeholder:text-slate-300"
                     placeholder="Detailed responsibilities for this role profile..."
                   />
                </div>
             </div>

             <div className="lg:col-span-2 space-y-6">
                <div className="flex items-center justify-between px-2">
                   <label className="block text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] flex items-center">
                      <Lock className="w-4 h-4 mr-2 text-construction-orange" /> Capability Matrix
                   </label>
                   <div className="flex gap-4">
                      <button type="button" onClick={handleSelectAll} className="text-[10px] font-black text-blue-600 uppercase tracking-widest hover:underline">Grant All</button>
                      <button type="button" onClick={handleClearAll} className="text-[10px] font-black text-red-600 uppercase tracking-widest hover:underline">Revoke All</button>
                   </div>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                   {allPermissions.map(p => {
                     const isSelected = form.permissions?.includes(p.id);
                     return (
                       <button
                         key={p.id}
                         type="button"
                         onClick={() => togglePermission(p.id)}
                         className={`group flex items-start p-6 rounded-[2rem] border-2 transition-all text-left relative overflow-hidden ${isSelected ? 'bg-slate-900 border-slate-900 text-white shadow-xl translate-x-1' : 'bg-slate-50 border-transparent hover:border-slate-200'}`}
                       >
                          <div className={`mt-0.5 w-6 h-6 rounded-xl border-2 shrink-0 mr-4 flex items-center justify-center transition-all ${isSelected ? 'bg-construction-orange border-construction-orange' : 'bg-white border-slate-200 group-hover:border-slate-300'}`}>
                             {isSelected && <Check className="w-4 h-4 text-white font-black" />}
                          </div>
                          <div>
                             <p className={`text-sm font-black uppercase tracking-tight ${isSelected ? 'text-white' : 'text-slate-800'}`}>{p.label}</p>
                             <p className={`text-[10px] font-medium leading-relaxed mt-1 ${isSelected ? 'text-slate-400' : 'text-slate-400'}`}>{p.description}</p>
                          </div>
                       </button>
                     )
                   })}
                </div>
             </div>
          </div>

          <div className="flex items-center justify-end space-x-6 pt-10 border-t border-slate-100">
            <button
              type="button"
              onClick={onClose}
              className="px-8 py-3 text-sm font-black text-slate-400 uppercase tracking-widest hover:text-slate-600 transition-colors"
            >
              Discard Changes
            </button>
            <Button
              type="submit"
              variant="primary"
              size="lg"
              className="min-w-[320px] rounded-[2rem] py-5 shadow-2xl"
            >
              <CheckCircle2 className="w-6 h-6 mr-3" />
              Authorize Access Role
            </Button>
          </div>
        </form>
      </div>
    </div>
  );
};

