import { CustomerModal } from './pos/CustomerModal';
import { DiscountModal } from './pos/DiscountModal';
import { RecallModal } from './pos/RecallModal';
import { VariantSelectorModal } from './pos/VariantSelectorModal';

interface PosTerminalProps {
  products: Product[];
  onProcessSale: (
    items: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number,
    paymentMethod?: 'cash' | 'card' | 'transfer' | 'qr' | 'credit',
    amountReceived?: number,
    change?: number,
    pointsRedeemed?: number,
    source?: 'pos' | 'back-office'
  ) => Promise<Sale>;
  settings?: SystemSettings;
}

export const PosTerminal: React.FC<PosTerminalProps> = ({ products, onProcessSale, settings }) => {
  const { customers, customerLevels, t, branches, warehouses, currentUser, formatPrice } = useGlobal();
  const { 
    cart, addToCart, clearCart,
    heldOrders, holdCurrentOrder, recallOrder, discardHeldOrder
  } = useCartStore();

  const [searchTerm, setSearchTerm] = useState('');
  const [isAiModalOpen, setIsAiModalOpen] = useState(false);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isScannerOpen, setIsScannerOpen] = useState(false); 

  const [isDiscountModalOpen, setIsDiscountModalOpen] = useState(false);
  const [isCustomerModalOpen, setIsCustomerModalOpen] = useState(false);
  const [isRecallModalOpen, setIsRecallModalOpen] = useState(false);
  const [isCheckoutOpen, setIsCheckoutOpen] = useState(false);
  const [isReceiptOpen, setIsReceiptOpen] = useState(false);
  const [isVariantModalOpen, setIsVariantModalOpen] = useState(false);
  const [selectedProductForVariant, setSelectedProductForVariant] = useState<Product | null>(null);

  const [manualDiscount, setManualDiscount] = useState<{ type: 'percent' | 'fixed', value: number } | null>(null);
  const [redeemPoints, setRedeemPoints] = useState<number>(0);
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);
  const [lastSale, setLastSale] = useState<Sale | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  const activeBranchId = settings?.currentBranchId || currentUser?.branchId || (branches.length > 0 ? branches[0].id : '');

  const branchProducts = useMemo(() => {
    if (!activeBranchId) return products;
    const branchWarehouseIds = warehouses.filter(w => w.branchId === activeBranchId).map(w => w.id);
    return products.map(p => {
      const branchStock = p.warehouseInventory?.reduce((acc, inv) => {
        if (branchWarehouseIds.includes(inv.warehouseId)) return acc + inv.quantity;
        return acc;
      }, 0) || 0;
      const branchPriceConfig = p.branchPrices?.find(bp => bp.branchId === activeBranchId);
      const effectivePrice = branchPriceConfig ? branchPriceConfig.price : p.price;
      return { ...p, stock: branchStock, price: effectivePrice };
    });
  }, [products, activeBranchId, warehouses]);

  const rawSubtotal = cart.reduce((sum, item) => sum + (item.sellPrice * item.quantity), 0);
  const customerLevel = useMemo(() => selectedCustomer?.levelId ? customerLevels.find(l => l.id === selectedCustomer.levelId) : null, [selectedCustomer, customerLevels]);
  const customerDiscountAmount = (customerLevel?.discountPercentage || 0) > 0 ? rawSubtotal * (customerLevel!.discountPercentage / 100) : 0;
  let manualDiscountAmount = 0;
  if (manualDiscount) {
    manualDiscountAmount = manualDiscount.type === 'percent' ? rawSubtotal * (manualDiscount.value / 100) : manualDiscount.value;
  }
  const redeemRate = settings?.loyaltyProgram?.redeemRate || 100;
  const loyaltyDiscountAmount = redeemPoints > 0 ? redeemPoints / redeemRate : 0;
  let discountAmount = Math.min(customerDiscountAmount + manualDiscountAmount + loyaltyDiscountAmount, rawSubtotal);
  let discountedSubtotal = rawSubtotal - discountAmount;

  let taxAmount = 0;
  let finalTotal = discountedSubtotal;
  if (settings?.tax?.enabled) {
    const rate = settings.tax.rate / 100;
    if (settings.tax.calculationMode === 'excluded') {
       taxAmount = discountedSubtotal * rate;
       finalTotal = discountedSubtotal + taxAmount;
    } else {
       taxAmount = discountedSubtotal - (discountedSubtotal / (1 + rate));
       finalTotal = discountedSubtotal;
    }
  }

  const handleProductSelect = (product: Product) => {
    if (product.variants && product.variants.length > 0) {
      setSelectedProductForVariant(product);
      setIsVariantModalOpen(true);
    } else {
      addToCart(product, 1);
      setSearchTerm('');
    }
  };

  const handleProcessPayment = async (method: any, received: number, change: number) => {
    setIsProcessing(true);
    try {
      const sale = await onProcessSale(cart, finalTotal, selectedCustomer?.id, discountAmount, rawSubtotal, method, received, change, redeemPoints, 'pos');
      setLastSale(sale);
      setIsCheckoutOpen(false);
      clearCart();
      setManualDiscount(null); 
      setRedeemPoints(0);
      setSelectedCustomer(null);
      setIsReceiptOpen(true);
      setIsCartOpen(false);
    } catch (error) {
      alert("Transaction failed.");
    } finally {
      setIsProcessing(false);
    }
  };

  const cartItemCount = cart.reduce((acc, item) => acc + item.quantity, 0);

  return (
    <div className="flex flex-col lg:flex-row h-full overflow-hidden bg-white -m-4 md:-m-6 relative">
      <div className="flex-1 flex flex-col min-w-0 h-full overflow-hidden border-r border-slate-100">
        <div className="px-4 md:px-6 py-4 bg-white flex items-center justify-between shrink-0 border-b border-slate-50">
          <div className="flex items-center gap-3">
            <h2 className="text-lg md:text-xl font-black text-slate-900 uppercase tracking-tighter hidden sm:block">Terminal 01</h2>
            <div className="flex gap-2">
               <button onClick={() => setIsRecallModalOpen(true)} className={`p-2 rounded-xl transition-all ${heldOrders.length > 0 ? 'bg-orange-50 text-orange-600 border border-orange-100' : 'bg-slate-50 text-slate-400'}`}>
                 <ClipboardList className="w-5 h-5" />
               </button>
               <button onClick={() => setIsAiModalOpen(true)} className="p-2 bg-violet-50 text-violet-600 border border-violet-100 rounded-xl hover:bg-violet-100 transition-all">
                  <Sparkles className="w-5 h-5" />
               </button>
            </div>
          </div>
          <div className="flex items-center space-x-2">
             <button onClick={() => setIsCustomerModalOpen(true)} className={`flex items-center px-4 py-2 rounded-xl text-xs font-black uppercase tracking-widest border transition-all ${selectedCustomer ? 'bg-slate-900 text-white border-slate-900' : 'bg-white text-slate-600 border-slate-200'}`}>
              <User className="w-3.5 h-3.5 mr-2" />
              <span className="max-w-[100px] truncate">{selectedCustomer ? selectedCustomer.name : 'Customer'}</span>
            </button>
            <button onClick={() => setIsCartOpen(true)} className="lg:hidden p-2 bg-slate-900 text-white rounded-xl relative">
               <ShoppingCart className="w-5 h-5" />
               {cartItemCount > 0 && <span className="absolute -top-1 -right-1 bg-construction-orange text-[10px] w-4 h-4 rounded-full flex items-center justify-center font-black">{cartItemCount}</span>}
            </button>
          </div>
        </div>

        <div className="flex-1 overflow-hidden relative">
           <ProductGrid 
             products={branchProducts} 
             searchTerm={searchTerm}
             setSearchTerm={setSearchTerm}
             onScanClick={() => setIsScannerOpen(true)}
             onScan={(code) => {
               const match = branchProducts.find(p => p.barcode === code || p.sku === code);
               if (match) handleProductSelect(match); else alert('No match');
             }}
             onProductSelect={handleProductSelect}
           />
        </div>
      </div>

      <div className={`
         fixed inset-0 z-[45] transform transition-transform duration-300 lg:relative lg:translate-x-0 lg:w-[420px] xl:w-[480px]
         ${isCartOpen ? 'translate-x-0' : 'translate-x-full lg:translate-x-0'}
      `}>
         <div className="absolute inset-0 bg-slate-900/60 lg:hidden" onClick={() => setIsCartOpen(false)}></div>
         <div className="relative h-full w-full bg-white shadow-2xl flex flex-col">
            <CartSidebar 
                isOpen={isCartOpen}
                onClose={() => setIsCartOpen(false)}
                selectedCustomer={selectedCustomer}
                onRemoveCustomer={() => setSelectedCustomer(null)}
                onHoldOrder={() => { holdCurrentOrder(selectedCustomer); setIsCartOpen(false); }}
                onCheckout={() => setIsCheckoutOpen(true)}
                onDiscountClick={() => setIsDiscountModalOpen(true)}
                subtotal={rawSubtotal}
                discount={discountAmount}
                tax={taxAmount}
                total={finalTotal}
                settings={settings}
            />
         </div>
      </div>

      <CheckoutModal isOpen={isCheckoutOpen} onClose={() => setIsCheckoutOpen(false)} total={finalTotal} onProcessPayment={handleProcessPayment} selectedCustomer={selectedCustomer} isProcessing={isProcessing} />
      <ReceiptModal isOpen={isReceiptOpen} onClose={() => setIsReceiptOpen(false)} sale={lastSale} settings={settings} />
      <CustomerModal isOpen={isCustomerModalOpen} onClose={() => setIsCustomerModalOpen(false)} customers={customers} onSelectCustomer={(c) => { setSelectedCustomer(c); setIsCustomerModalOpen(false); }} />
      <DiscountModal isOpen={isDiscountModalOpen} onClose={() => setIsDiscountModalOpen(false)} onApplyDiscount={setManualDiscount} currencySymbol={settings?.currencySymbol} />
      <RecallModal isOpen={isRecallModalOpen} onClose={() => setIsRecallModalOpen(false)} heldOrders={heldOrders} onRecall={(id) => { recallOrder(id); setIsRecallModalOpen(false); setIsCartOpen(true); }} onDiscard={discardHeldOrder} />
      <AiAssistant isOpen={isAiModalOpen} onClose={() => setIsAiModalOpen(false)} inventory={branchProducts} onAddItemsToCart={(items) => { items.forEach(i => i.matchedProductId && addToCart(branchProducts.find(p => p.id === i.matchedProductId)!, Math.ceil(i.estimatedQuantity))); setIsAiModalOpen(false); setIsCartOpen(true); }} />
      <BarcodeScanner isOpen={isScannerOpen} onClose={() => setIsScannerOpen(false)} onScan={(code) => { const m = branchProducts.find(p => p.barcode === code); if (m) handleProductSelect(m); }} />
      {selectedProductForVariant && <VariantSelectorModal isOpen={isVariantModalOpen} onClose={() => setIsVariantModalOpen(false)} product={selectedProductForVariant} onConfirm={(p, q, v) => { addToCart(p, q, v); setIsVariantModalOpen(false); setIsCartOpen(true); }} formatPrice={formatPrice} />}
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Product, Category } from '../../types';
import { Search, Box, ScanBarcode, LayoutGrid, List, Plus, Tag } from 'lucide-react';
import { useGlobal } from '../../context/GlobalContext';

interface ProductGridProps {
  products: Product[];
  onScanClick: () => void;
  searchTerm: string;
  setSearchTerm: (term: string) => void;
  onScan: (code: string) => void; 
  onProductSelect: (product: Product) => void;
}

export const ProductGrid: React.FC<ProductGridProps> = ({ 
  products, onScanClick, searchTerm, setSearchTerm, onScan, onProductSelect
}) => {
  const { formatPrice, t } = useGlobal();
  const [selectedCategory, setSelectedCategory] = useState<string>('all');
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const searchLower = searchTerm.toLowerCase();
      const matchesMain = p.name.toLowerCase().includes(searchLower) || p.sku?.toLowerCase().includes(searchLower) || p.barcode?.includes(searchLower);
      const matchesCategory = selectedCategory === 'all' || p.category === selectedCategory;
      return matchesMain && matchesCategory;
    });
  }, [products, searchTerm, selectedCategory]);

  return (
    <div className="flex flex-col h-full bg-white animate-fade-in">
      <div className="p-4 md:p-6 space-y-4">
        <div className="flex flex-col sm:flex-row gap-3">
          <div className="relative flex-1 flex gap-2">
            <div className="relative flex-1 group">
               <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-construction-orange transition-colors" />
               <input
                 type="text"
                 placeholder="Find materials..."
                 className="w-full pl-11 pr-4 py-3 bg-slate-50 border-2 border-slate-50 rounded-2xl focus:border-construction-orange focus:bg-white outline-none font-bold text-slate-800 transition-all placeholder:text-slate-300"
                 value={searchTerm}
                 onChange={(e) => setSearchTerm(e.target.value)}
               />
            </div>
            <button onClick={onScanClick} className="p-3 bg-slate-50 border-2 border-slate-50 text-slate-400 rounded-2xl hover:border-slate-200 transition-all">
               <ScanBarcode className="w-6 h-6" />
            </button>
          </div>

          <div className="flex bg-slate-100 p-1 rounded-2xl w-fit">
             <button onClick={() => setViewMode('grid')} className={`p-2 rounded-xl transition-all ${viewMode === 'grid' ? 'bg-white shadow-md text-slate-900' : 'text-slate-400'}`}><LayoutGrid className="w-5 h-5"/></button>
             <button onClick={() => setViewMode('list')} className={`p-2 rounded-xl transition-all ${viewMode === 'list' ? 'bg-white shadow-md text-slate-900' : 'text-slate-400'}`}><List className="w-5 h-5"/></button>
          </div>
        </div>

        <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide -mx-4 px-4 sm:mx-0 sm:px-0">
          <button 
            onClick={() => setSelectedCategory('all')} 
            className={`px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest whitespace-nowrap transition-all border-2 ${selectedCategory === 'all' ? 'bg-slate-900 border-slate-900 text-white shadow-lg' : 'bg-white border-slate-50 text-slate-400'}`}
          >
            All Stock
          </button>
          {Object.values(Category).map(cat => (
            <button 
              key={cat} 
              onClick={() => setSelectedCategory(cat)} 
              className={`px-6 py-2 rounded-xl text-xs font-black uppercase tracking-widest whitespace-nowrap transition-all border-2 ${selectedCategory === cat ? 'bg-slate-900 border-slate-900 text-white shadow-lg' : 'bg-white border-slate-50 text-slate-400'}`}
            >
              {cat}
            </button>
          ))}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto px-4 md:px-6 pb-20 custom-scrollbar">
        {viewMode === 'grid' ? (
          <div className="grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-5 gap-4">
            {filteredProducts.map((product) => (
              <div key={product.id} onClick={() => onProductSelect(product)} className="bg-white rounded-3xl border-2 border-slate-50 p-4 hover:border-construction-orange hover:shadow-xl hover:shadow-slate-200 transition-all cursor-pointer group flex flex-col">
                <div className="aspect-square bg-slate-50 rounded-2xl mb-3 overflow-hidden flex items-center justify-center relative">
                   {product.imageUrl ? <img src={product.imageUrl} className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500"/> : <Box className="w-8 h-8 text-slate-200"/>}
                   <div className={`absolute top-2 right-2 px-2 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest ${product.stock <= (product.minStock||10) ? 'bg-red-500 text-white' : 'bg-white/90 text-slate-900'}`}>{product.stock} {product.unit}</div>
                </div>
                <h4 className="font-black text-slate-900 text-xs uppercase tracking-tight line-clamp-2 mb-2 leading-tight">{product.name}</h4>
                <div className="mt-auto pt-2 flex items-center justify-between">
                   <div className="font-black text-slate-900 text-sm">{formatPrice(product.price)}</div>
                   <div className="w-8 h-8 bg-slate-900 text-white rounded-xl flex items-center justify-center group-hover:bg-construction-orange transition-colors"><Plus className="w-4 h-4"/></div>
                </div>
              </div>
            ))}
          </div>
        ) : (
           <div className="space-y-2">
              {filteredProducts.map(p => (
                 <div key={p.id} onClick={() => onProductSelect(p)} className="flex items-center gap-4 p-3 bg-white border-2 border-slate-50 rounded-2xl hover:border-construction-orange transition-all cursor-pointer">
                    <div className="w-12 h-12 rounded-xl bg-slate-50 overflow-hidden flex items-center justify-center shrink-0">
                       {p.imageUrl ? <img src={p.imageUrl} className="w-full h-full object-cover"/> : <Box className="w-4 h-4 text-slate-200"/>}
                    </div>
                    <div className="flex-1 min-w-0">
                       <h4 className="font-black text-slate-900 text-sm uppercase tracking-tighter truncate">{p.name}</h4>
                       <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Stock: {p.stock} {p.unit}</p>
                    </div>
                    <div className="text-right">
                       <p className="font-black text-slate-900">{formatPrice(p.price)}</p>
                       <span className="text-[9px] bg-slate-100 text-slate-500 px-1.5 py-0.5 rounded font-black uppercase">Add Item</span>
                    </div>
                 </div>
              ))}
           </div>
        )}
      </div>
    </div>
  );
};

import React from 'react';
import { Customer, SystemSettings } from '../../types';
import { ShoppingCart, PauseCircle, X, Minus, Plus, Trash2, User, ChevronRight, Tag } from 'lucide-react';
import { useGlobal } from '../../context/GlobalContext';
import { useCartStore } from '../../store/useCartStore';

interface CartSidebarProps {
  isOpen: boolean;
  onClose: () => void;
  selectedCustomer: Customer | null;
  onRemoveCustomer: () => void;
  onHoldOrder: () => void;
  onCheckout: () => void;
  onDiscountClick: () => void;
  subtotal: number;
  discount: number;
  tax: number;
  total: number;
  settings?: SystemSettings;
}

export const CartSidebar: React.FC<CartSidebarProps> = ({
  isOpen, onClose, selectedCustomer, onRemoveCustomer,
  onHoldOrder, onCheckout, onDiscountClick,
  subtotal, discount, tax, total, settings
}) => {
  const { formatPrice } = useGlobal();
  const { cart, removeFromCart, updateQuantity } = useCartStore();

  return (
    <div className="flex flex-col h-full bg-white relative">
      <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50/50 shrink-0">
        <div>
           <h3 className="font-black text-slate-900 text-2xl tracking-tighter uppercase italic">Order Ticket</h3>
           <div className="flex items-center text-[10px] text-slate-400 mt-1 font-black space-x-2 uppercase tracking-[0.2em]">
              <span>{cart.reduce((a,c)=>a+c.quantity,0)} Materials</span>
              <span className="w-1 h-1 bg-slate-200 rounded-full"></span>
              <span>LIVE RECKONING</span>
           </div>
        </div>
        <div className="flex space-x-2">
           <button onClick={onHoldOrder} disabled={cart.length === 0} className="p-3 bg-white text-slate-400 rounded-2xl hover:text-orange-500 border border-slate-100 shadow-sm transition-all disabled:opacity-20"><PauseCircle className="w-6 h-6" /></button>
           <button onClick={onClose} className="lg:hidden p-3 bg-slate-900 text-white rounded-2xl shadow-xl transition-all active:scale-95"><X className="w-6 h-6" /></button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto px-6 space-y-4 custom-scrollbar py-6">
        {cart.length === 0 ? (
          <div className="h-full flex flex-col items-center justify-center text-slate-200 py-20">
            <ShoppingCart className="w-20 h-20 mb-4 opacity-10" />
            <p className="font-black uppercase tracking-widest text-slate-300">Ticket Empty</p>
          </div>
        ) : (
          cart.map((item, index) => (
            <div key={`${item.id}-${index}`} className="flex gap-4 animate-slide-in-right group border-b border-slate-50 pb-4 last:border-0">
              <div className="flex flex-col items-center justify-center bg-slate-900 rounded-2xl w-10 shrink-0 shadow-lg py-2">
                 <button onClick={() => updateQuantity(index, 1)} className="p-2 text-white hover:text-construction-orange"><Plus className="w-4 h-4" /></button>
                 <span className="text-sm font-black text-white">{item.quantity}</span>
                 <button onClick={() => updateQuantity(index, -1)} disabled={item.quantity <= (item.minOrderQuantity || 1)} className="p-2 text-white/40 hover:text-red-400 disabled:opacity-0"><Minus className="w-4 h-4" /></button>
              </div>
              <div className="flex-1 min-w-0">
                 <div className="flex justify-between items-start">
                    <h4 className="font-black text-slate-900 text-xs uppercase tracking-tight leading-tight pr-4">{item.name}</h4>
                    <span className="font-black text-slate-900 text-sm whitespace-nowrap">{formatPrice(item.sellPrice * item.quantity)}</span>
                 </div>
                 <div className="flex justify-between items-center mt-2">
                    <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest">{item.sellUnit} @ {formatPrice(item.sellPrice)}</p>
                    <button onClick={() => removeFromCart(index)} className="text-slate-300 hover:text-red-500 transition-colors"><Trash2 className="w-3.5 h-3.5"/></button>
                 </div>
              </div>
            </div>
          ))
