      <div className="bg-white border-t-2 border-slate-100 p-6 space-y-6 shadow-[0_-10px_30px_rgba(0,0,0,0.03)] shrink-0">
        <button onClick={onDiscountClick} className="w-full p-4 border-2 border-dashed border-slate-100 rounded-2xl text-[10px] font-black text-slate-400 uppercase tracking-widest hover:border-slate-300 transition-all flex justify-between items-center">
           <span className="flex items-center"><Tag className="w-3.5 h-3.5 mr-2" /> Applied Deductions</span>
           {discount > 0 && <span className="bg-emerald-500 text-white px-2 py-0.5 rounded-lg">-{formatPrice(discount)}</span>}
        </button>

        <div className="space-y-2">
           <div className="flex justify-between text-[10px] font-black text-slate-400 uppercase tracking-widest">
              <span>Gross Balance</span>
              <span>{formatPrice(subtotal)}</span>
           </div>
           <div className="flex justify-between items-end">
              <span className="text-sm font-black text-slate-900 uppercase italic">Grand Total</span>
              <span className="text-5xl font-black text-slate-900 tracking-tighter">{formatPrice(total)}</span>
           </div>
        </div>

        <button 
           onClick={onCheckout} 
           disabled={cart.length === 0}
           className="w-full py-5 bg-slate-900 text-white rounded-[2rem] font-black text-xl hover:bg-slate-800 shadow-2xl shadow-slate-300 transition-all flex items-center justify-center disabled:opacity-30 disabled:grayscale active:scale-95 uppercase tracking-tighter italic"
        >
           <span>Checkout</span>
           <ChevronRight className="w-6 h-6 ml-2" />
        </button>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Customer } from '../../types';
import { X, Banknote, QrCode, CreditCard, FileText, ChevronLeft, CheckCircle } from 'lucide-react';
import { useGlobal } from '../../context/GlobalContext';
import { PaymentMethodList } from './checkout/PaymentMethodList';
import { PaymentNumpad } from './checkout/PaymentNumpad';

interface CheckoutModalProps {
  isOpen: boolean;
  onClose: () => void;
  total: number;
  onProcessPayment: (method: 'cash' | 'card' | 'transfer' | 'qr' | 'credit', receivedAmount: number, change: number) => Promise<void>;
  selectedCustomer: Customer | null;
  isProcessing: boolean;
}

export const CheckoutModal: React.FC<CheckoutModalProps> = ({
  isOpen, onClose, total, onProcessPayment, selectedCustomer, isProcessing
}) => {
  const { formatPrice } = useGlobal();
  const [paymentMethod, setPaymentMethod] = useState<'cash' | 'card' | 'transfer' | 'qr' | 'credit'>('cash');
  const [receivedAmountStr, setReceivedAmountStr] = useState('');
  const [checkoutStep, setCheckoutStep] = useState<'method' | 'detail'>('method');

  const receivedAmount = parseFloat(receivedAmountStr) || 0;
  const change = Math.max(0, receivedAmount - total);

  const handleProcess = () => {
    let finalReceived = paymentMethod === 'cash' || paymentMethod === 'credit' ? receivedAmount : total;
    let finalChange = paymentMethod === 'cash' ? change : 0;
    if (paymentMethod !== 'cash' && paymentMethod !== 'credit') finalReceived = total;
    onProcessPayment(paymentMethod, finalReceived, finalChange);
  };

  useEffect(() => {
    if (!isOpen) return;
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Enter' || e.key === 'F12') {
         e.preventDefault();
         if (isProcessing) return;
         if (paymentMethod === 'cash' && receivedAmount < total) return;
         handleProcess();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, paymentMethod, receivedAmount, total, isProcessing]);

  if (!isOpen) return null;

  const selectPaymentMethod = (method: 'cash' | 'card' | 'transfer' | 'qr' | 'credit') => {
    if (method === 'credit' && !selectedCustomer) { alert("Customer required for credit"); return; }
    setPaymentMethod(method);
    setReceivedAmountStr('');
    setCheckoutStep('detail');
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-slate-900/60 backdrop-blur-md p-0 sm:p-4 animate-fade-in">
      <div className="bg-white w-full h-full sm:h-auto sm:max-h-[90vh] sm:max-w-5xl sm:rounded-[3rem] shadow-2xl flex flex-col sm:flex-row overflow-hidden border border-white/20">

        <PaymentMethodList 
            paymentMethod={paymentMethod}
            onSelect={selectPaymentMethod}
            onClose={onClose}
            total={total}
            selectedCustomer={selectedCustomer}
            className={checkoutStep === 'detail' ? 'hidden sm:flex' : 'flex'}
        />

        <div className={`flex-1 bg-white flex flex-col ${checkoutStep === 'method' ? 'hidden sm:flex' : 'flex'} h-full sm:h-auto`}>
           <div className="p-6 border-b border-slate-50 flex items-center justify-between">
              <button onClick={() => setCheckoutStep('method')} className="sm:hidden flex items-center text-slate-400 font-black text-[10px] uppercase tracking-widest hover:text-slate-900">
                 <ChevronLeft className="w-4 h-4 mr-1" /> Choose Method
              </button>
              <h3 className="hidden sm:block text-[10px] font-black text-slate-400 uppercase tracking-widest">Transaction Details</h3>
              <button onClick={onClose} className="p-2 hover:bg-slate-50 rounded-full text-slate-300">
                 <X className="w-6 h-6" />
              </button>
           </div>

           <div className="flex-1 p-6 sm:p-10 overflow-y-auto custom-scrollbar">
              <div className="text-center mb-8">
                 <div className="inline-flex p-4 rounded-[2rem] bg-slate-900 text-white shadow-xl mb-4">
                    {paymentMethod === 'cash' ? <Banknote className="w-8 h-8"/> : paymentMethod === 'qr' ? <QrCode className="w-8 h-8"/> : paymentMethod === 'credit' ? <FileText className="w-8 h-8"/> : <CreditCard className="w-8 h-8"/>}
                 </div>
                 <h2 className="text-2xl font-black text-slate-900 tracking-tight uppercase">
                    {paymentMethod === 'cash' ? 'Cash Settlement' : paymentMethod === 'qr' ? 'AI QR Scanned' : paymentMethod === 'credit' ? 'Account Credit' : 'Digital Terminal'}
                 </h2>
              </div>

              {paymentMethod === 'cash' || paymentMethod === 'credit' ? (
                 <PaymentNumpad 
                    receivedAmountStr={receivedAmountStr}
                    setReceivedAmountStr={setReceivedAmountStr}
                    total={total}
                    change={paymentMethod === 'cash' ? change : 0}
                    handleQuickCash={(amt) => setReceivedAmountStr(amt.toString())}
                 />
              ) : paymentMethod === 'qr' ? (
                 <div className="flex flex-col items-center justify-center py-10">
                    <div className="bg-white p-6 rounded-[2.5rem] border-4 border-slate-50 shadow-2xl mb-8 relative">
                       <img src={`https://api.qrserver.com/v1/create-qr-code/?size=250x250&data=BuildMaster_${total}`} className="w-64 h-64 grayscale contrast-125" alt="QR" />
                       <div className="absolute inset-0 border-2 border-construction-orange/20 rounded-[2.5rem] animate-pulse"></div>
                    </div>
                    <p className="text-lg font-black text-slate-900 uppercase tracking-tighter">Charge: {formatPrice(total)}</p>
                 </div>
              ) : (
                 <div className="flex flex-col items-center justify-center py-20 text-center">
                    <div className="w-24 h-24 bg-slate-50 rounded-full flex items-center justify-center mb-6 animate-pulse">
                       <CreditCard className="w-10 h-10 text-slate-300" />
                    </div>
                    <h4 className="text-xl font-black text-slate-900 tracking-tight uppercase">Awaiting Link...</h4>
                    <p className="text-slate-400 font-bold text-xs uppercase tracking-widest mt-2">Connect payment terminal</p>
                 </div>
              )}
           </div>

           <div className="p-6 sm:p-10 border-t border-slate-50 bg-white">
              <button 
                 onClick={handleProcess}
                 disabled={isProcessing || (paymentMethod === 'cash' && receivedAmount < total)}
                 className="w-full py-6 bg-slate-900 text-white rounded-[2rem] font-black text-2xl uppercase tracking-tighter italic shadow-2xl shadow-slate-300 hover:bg-slate-800 transition-all active:scale-[0.98] disabled:opacity-20 disabled:grayscale"
              >
                 {isProcessing ? 'SYNCHRONIZING...' : (
                    <div className="flex items-center justify-center">
                       <CheckCircle className="w-8 h-8 mr-3" /> 
                       AUTHORIZE {formatPrice(total)}
                    </div>
                 )}
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

