'use client';

import React, { useState } from 'react';
import { useGlobal } from '../context/GlobalContext';
import { Lock, User as UserIcon, AlertCircle } from 'lucide-react';
import { verifyPasswordSync } from '../lib/auth';
import { Button } from './ui/Button';

export const LoginPage: React.FC = () => {
  const { setCurrentUser, users } = useGlobal();

  const [loginUsername, setLoginUsername] = useState('admin');
  const [loginPassword, setLoginPassword] = useState('123');
  const [loginError, setLoginError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleLoginSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoginError('');
    setLoading(true);

    try {
      const clientMatch = users.find(u => u.username.toLowerCase() === loginUsername.trim().toLowerCase());

      if (clientMatch && clientMatch.password) {
        const isValid = verifyPasswordSync(loginPassword.trim(), clientMatch.password);
        if (isValid) {
          await new Promise(resolve => setTimeout(resolve, 800));
          const { password, ...safeUser } = clientMatch;
          setCurrentUser(safeUser as any);
          return;
        }
      }
      throw new Error('Verification failed');
    } catch (err: any) {
      setLoginError(err.message || 'Access denied');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 flex items-center justify-center bg-slate-50 z-50 p-4 overflow-y-auto">
        <div className="bg-white rounded-[4rem] shadow-[0_50px_100px_-20px_rgba(0,0,0,0.15)] overflow-hidden w-full max-w-5xl min-h-[600px] flex flex-col md:flex-row animate-fade-in border border-white">

           <div className="md:w-1/2 bg-brand-red p-12 text-white flex flex-col justify-center items-center text-center relative overflow-hidden">
              <div className="absolute inset-0 bg-black/10 mix-blend-overlay opacity-30"></div>
              {/* Brand Logo Container */}
              <div className="bg-white p-10 rounded-[3.5rem] mb-10 shadow-2xl relative z-10 border-8 border-white/20">
                <div className="text-brand-red font-black text-7xl tracking-tighter">M</div>
              </div>
              <h1 className="text-6xl font-black mb-4 relative z-10 tracking-tighter">MAHAXAY</h1>
              <p className="text-white/70 text-sm relative z-10 max-w-xs font-black uppercase tracking-[0.4em] italic">Industrial Supply POS</p>
           </div>

           <div className="md:w-1/2 p-10 md:p-20 flex flex-col justify-center bg-white">
              <div className="mb-12">
                <h2 className="text-4xl font-black text-brand-grey tracking-tight">System Login</h2>
                <p className="text-slate-400 font-bold text-[10px] uppercase tracking-widest mt-3 flex items-center">
                   <span className="w-2 h-2 bg-brand-red rounded-full mr-2"></span> Authorized Personnel Only
                </p>
              </div>

              <form onSubmit={handleLoginSubmit} className="space-y-8">
                 <div>
                   <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 ml-2">Terminal ID</label>
                   <div className="relative group">
                     <UserIcon className="absolute left-5 top-5 w-5 h-5 text-slate-300 group-focus-within:text-brand-red transition-colors" />
                     <input 
                       type="text"
                       required
                       value={loginUsername}
                       onChange={e => setLoginUsername(e.target.value)}
                       className="w-full pl-14 pr-6 py-5 bg-slate-50 border-2 border-slate-50 rounded-[1.5rem] focus:ring-8 focus:ring-red-50 focus:border-brand-red transition-all outline-none font-bold text-slate-800 text-lg"
                       placeholder="Username"
                     />
                   </div>
                 </div>

                 <div>
                   <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 ml-2">Secure Key</label>
                   <div className="relative group">
                     <Lock className="absolute left-5 top-5 w-5 h-5 text-slate-300 group-focus-within:text-brand-red transition-colors" />
                     <input 
                       type="password"
                       required
                       value={loginPassword}
                       onChange={e => setLoginPassword(e.target.value)}
                       className="w-full pl-14 pr-6 py-5 bg-slate-50 border-2 border-slate-50 rounded-[1.5rem] focus:ring-8 focus:ring-red-50 focus:border-brand-red transition-all outline-none font-bold text-slate-800 text-lg"
                       placeholder="••••••••"
                     />
                   </div>
                 </div>

                 {loginError && (
                   <div className="bg-rose-50 text-rose-600 text-xs font-black p-5 rounded-[1.5rem] border border-rose-100 flex items-center animate-shake">
                     <AlertCircle className="w-5 h-5 mr-3 shrink-0" />
                     {loginError}
                   </div>
                 )}

                 <Button 
                   type="submit"
                   variant="primary"
                   size="xl"
                   isLoading={loading}
                   className="w-full mt-6 rounded-[2rem] py-6 shadow-2xl shadow-red-900/20"
                 >
                   Open Terminal
                 </Button>
              </form>

              <p className="mt-12 text-center text-[10px] font-bold text-slate-300 uppercase tracking-widest">
                 Cloud Sync Instance: VN-01
              </p>
           </div>
        </div>
    </div>
  );
};

