import React, { useState, useMemo } from 'react';
import { Product, Category } from '../../types';
import { Search, Box, ScanBarcode, LayoutGrid, List, Plus } from 'lucide-react';
import { useGlobal } from '../../context/GlobalContext';

interface ProductGridProps {
  products: Product[];
  onScanClick: () => void;
  searchTerm: string;
  setSearchTerm: (term: string) => void;
  onScan: (code: string) => void; 
  onProductSelect: (product: Product) => void;
}

export const ProductGrid: React.FC<ProductGridProps> = ({ 
  products, onScanClick, searchTerm, setSearchTerm, onScan, onProductSelect
}) => {
  const { formatPrice } = useGlobal();
  const [selectedCategory, setSelectedCategory] = useState<string>('all');
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const searchLower = searchTerm.toLowerCase();
      const matchesMain = p.name.toLowerCase().includes(searchLower) || p.sku?.toLowerCase().includes(searchLower) || p.barcode?.includes(searchLower);
      const matchesCategory = selectedCategory === 'all' || p.category === selectedCategory;
      return matchesMain && matchesCategory;
    });
  }, [products, searchTerm, selectedCategory]);

  return (
    <div className="flex flex-col h-full bg-slate-50/50 animate-fade-in">
      {/* Header Section */}
      <div className="px-4 py-3 bg-white border-b border-slate-200 shadow-sm z-10 space-y-3">
        {/* Search Bar */}
        <div className="flex gap-2">
          <div className="relative flex-1 group">
             <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-brand-red transition-colors w-4 h-4" />
             <input
               type="text"
               placeholder="Search Name, SKU, Barcode..."
               className="w-full pl-9 pr-4 py-2.5 bg-slate-100 border border-transparent rounded-xl focus:bg-white focus:border-brand-red focus:ring-4 focus:ring-red-50/50 outline-none font-medium text-slate-700 transition-all placeholder:text-slate-400 text-sm"
               value={searchTerm}
               onChange={(e) => setSearchTerm(e.target.value)}
             />
          </div>
          <button onClick={onScanClick} className="px-3 bg-white border border-slate-200 text-slate-600 rounded-xl hover:text-brand-red hover:border-brand-red transition-all shrink-0 shadow-sm">
             <ScanBarcode className="w-5 h-5" />
          </button>
          <div className="hidden sm:flex bg-slate-100 p-1 rounded-xl shrink-0 border border-slate-200">
             <button onClick={() => setViewMode('grid')} className={`p-1.5 rounded-lg transition-all ${viewMode === 'grid' ? 'bg-white shadow text-brand-red' : 'text-slate-400 hover:text-slate-600'}`}><LayoutGrid className="w-4 h-4"/></button>
             <button onClick={() => setViewMode('list')} className={`p-1.5 rounded-lg transition-all ${viewMode === 'list' ? 'bg-white shadow text-brand-red' : 'text-slate-400 hover:text-slate-600'}`}><List className="w-4 h-4"/></button>
          </div>
        </div>

        {/* Category Pills */}
        <div className="flex gap-2 overflow-x-auto pb-1 scrollbar-hide -mx-4 px-4 sm:mx-0 sm:px-0">
          <button 
            onClick={() => setSelectedCategory('all')} 
            className={`px-4 py-1.5 rounded-full text-xs font-bold whitespace-nowrap transition-all border ${selectedCategory === 'all' ? 'bg-brand-red text-white border-brand-red shadow-md shadow-red-200' : 'bg-white border-slate-200 text-slate-500 hover:border-slate-300 hover:text-slate-700'}`}
          >
            All Items
          </button>
          {Object.values(Category).map(cat => (
            <button 
              key={cat} 
              onClick={() => setSelectedCategory(cat)} 
              className={`px-4 py-1.5 rounded-full text-xs font-bold whitespace-nowrap transition-all border ${selectedCategory === cat ? 'bg-brand-red text-white border-brand-red shadow-md shadow-red-200' : 'bg-white border-slate-200 text-slate-500 hover:border-slate-300 hover:text-slate-700'}`}
            >
              {cat}
            </button>
          ))}
        </div>
      </div>

      {/* Grid Content */}
      <div className="flex-1 overflow-y-auto px-4 py-4 custom-scrollbar">
        {viewMode === 'grid' ? (
          <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-5 gap-3">
            {filteredProducts.map((product) => (
              <div 
                key={product.id} 
                onClick={() => onProductSelect(product)} 
                className="bg-white rounded-2xl border border-slate-100 p-3 hover:border-brand-red hover:shadow-lg hover:shadow-red-900/5 transition-all cursor-pointer group flex flex-col active:scale-[0.98] relative overflow-hidden"
              >
                {/* Image Area */}
                <div className="aspect-[4/3] bg-slate-50 rounded-xl mb-3 overflow-hidden flex items-center justify-center relative border border-slate-50">
                   {product.imageUrl ? <img src={product.imageUrl} className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"/> : <Box className="w-8 h-8 text-slate-300"/>}

                   {/* Stock Badge */}
                   <div className={`absolute top-2 right-2 px-1.5 py-0.5 rounded-md text-[9px] font-black uppercase tracking-wider shadow-sm backdrop-blur-md ${product.stock <= (product.minStock||10) ? 'bg-red-500/90 text-white' : 'bg-white/90 text-slate-700 border border-slate-100'}`}>
                      {product.stock} {product.unit}
                   </div>
                </div>

                {/* Info Area */}
                <div className="flex-1 flex flex-col">
                    <h4 className="font-bold text-brand-grey text-xs md:text-sm leading-tight line-clamp-2 mb-1 min-h-[2.5em]">
                        {product.name}
                    </h4>
                    <p className="text-[10px] text-slate-400 font-mono mb-2">{product.sku}</p>

                    <div className="mt-auto pt-2 flex items-end justify-between border-t border-slate-50">
                       <div className="flex flex-col">
                          <span className="text-[10px] text-slate-400 font-medium">Price</span>
                          <span className="font-black text-brand-red text-sm md:text-base">{formatPrice(product.price)}</span>
                       </div>
                       <div className="w-8 h-8 bg-slate-50 text-slate-400 rounded-full flex items-center justify-center group-hover:bg-brand-red group-hover:text-white transition-colors">
                          <Plus className="w-4 h-4"/>
                       </div>
                    </div>
                </div>
              </div>
            ))}
          </div>
        ) : (
           <div className="space-y-2 pb-20">
              {filteredProducts.map(p => (
                 <div key={p.id} onClick={() => onProductSelect(p)} className="flex items-center gap-3 p-3 bg-white border border-slate-100 rounded-xl hover:border-brand-red hover:shadow-sm transition-all cursor-pointer active:scale-[0.99]">
                    <div className="w-12 h-12 rounded-lg bg-slate-50 overflow-hidden flex items-center justify-center shrink-0 border border-slate-100">
                       {p.imageUrl ? <img src={p.imageUrl} className="w-full h-full object-cover"/> : <Box className="w-5 h-5 text-slate-300"/>}
                    </div>
                    <div className="flex-1 min-w-0">
                       <h4 className="font-bold text-brand-grey text-sm truncate">{p.name}</h4>
                       <div className="flex items-center text-[10px] text-slate-500 font-medium mt-0.5">
                          <span className="bg-slate-100 px-1.5 py-0.5 rounded text-slate-600 mr-2">{p.sku}</span>
                          <span className={p.stock < (p.minStock || 10) ? "text-red-500" : ""}>{p.stock} {p.unit} in stock</span>
                       </div>
                    </div>
                    <div className="text-right">
                       <p className="font-black text-brand-red text-sm">{formatPrice(p.price)}</p>
                    </div>
                 </div>
              ))}
           </div>
        )}

        {filteredProducts.length === 0 && (
           <div className="flex flex-col items-center justify-center h-64 text-slate-400">
              <Box className="w-12 h-12 mb-3 opacity-20" />
              <p className="font-medium text-sm">No items found</p>
           </div>
        )}
      </div>
    </div>
  );
};

