                 <span className="text-xs font-black text-slate-800 tabular-nums">{item.quantity}</span>
                 <button onClick={() => updateQuantity(index, -1)} disabled={item.quantity <= (item.minOrderQuantity || 1)} className="w-6 h-6 flex items-center justify-center bg-white border border-slate-200 rounded-full text-slate-600 hover:text-red-500 hover:border-red-200 shadow-sm active:scale-90 transition-all disabled:opacity-30">
