           <span className="flex items-center group-hover:text-brand-red"><Tag className="w-3.5 h-3.5 mr-2" /> Add Discount</span>
           {discount > 0 && <span className="bg-red-50 text-brand-red px-2 py-0.5 rounded text-[10px] font-black">-{formatPrice(discount)}</span>}
        </button>

        {/* Totals */}
        <div className="space-y-1.5 mb-4">
           <div className="flex justify-between text-[11px] font-bold text-slate-400 uppercase tracking-wider">
              <span>Subtotal</span>
              <span>{formatPrice(subtotal)}</span>
           </div>
           {tax > 0 && (
              <div className="flex justify-between text-[11px] font-bold text-slate-400 uppercase tracking-wider">
                 <span>Tax</span>
