           <div className="flex justify-between items-end pt-3 border-t border-slate-100 mt-2">
              <div className="flex flex-col">
                 <span className="text-[10px] font-black text-brand-grey uppercase tracking-widest">Total Due</span>
                 <span className="text-[10px] text-slate-400">{cart.reduce((a,c)=>a+c.quantity,0)} Items</span>
