                  <div>
                     <label className="block text-sm font-medium text-slate-700 mb-1">Host</label>
                     <div className="relative">
                        <Server className="absolute left-3 top-2.5 w-4 h-4 text-slate-400" />
                        <input type="text" value={formData.localDatabase.host} onChange={e => setFormData({ ...formData, localDatabase: { ...formData.localDatabase!, host: e.target.value } })} className="w-full pl-9 pr-4 py-2 border border-slate-300 rounded-lg" placeholder="localhost" />
                     </div>
                  </div>
                  <div>
                     <label className="block text-sm font-medium text-slate-700 mb-1">Port</label>
                     <input type="text" value={formData.localDatabase.port} onChange={e => setFormData({ ...formData, localDatabase: { ...formData.localDatabase!, port: e.target.value } })} className="w-full px-4 py-2 border border-slate-300 rounded-lg" placeholder="5432" />
                  </div>
                  <div>
                     <label className="block text-sm font-medium text-slate-700 mb-1">Database Name</label>
                     <input type="text" value={formData.localDatabase.databaseName} onChange={e => setFormData({ ...formData, localDatabase: { ...formData.localDatabase!, databaseName: e.target.value } })} className="w-full px-4 py-2 border border-slate-300 rounded-lg" placeholder="buildmaster_pos" />
                  </div>
                  <div>
                     <label className="block text-sm font-medium text-slate-700 mb-1">Username</label>
                     <input type="text" value={formData.localDatabase.username} onChange={e => setFormData({ ...formData, localDatabase: { ...formData.localDatabase!, username: e.target.value } })} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                  </div>
                  <div>
                     <label className="block text-sm font-medium text-slate-700 mb-1">Password</label>
                     <input type="password" value={formData.localDatabase.password} onChange={e => setFormData({ ...formData, localDatabase: { ...formData.localDatabase!, password: e.target.value } })} className="w-full px-4 py-2 border border-slate-300 rounded-lg" />
                  </div>
               </div>

               <div className="flex justify-end pt-4 mt-4 border-t border-slate-200">
                  <button 
                     type="button"
                     onClick={handleTestDb}
                     disabled={dbStatus === 'testing'}
                     className={`px-4 py-2 rounded-lg font-bold text-sm flex items-center transition-all ${dbStatus === 'success' ? 'bg-green-100 text-green-700' : dbStatus === 'error' ? 'bg-red-100 text-red-700' : 'bg-white border border-slate-300 text-slate-700 hover:bg-slate-50'}`}
                  >
                     {dbStatus === 'testing' ? <RefreshCw className="w-4 h-4 animate-spin mr-2" /> : dbStatus === 'success' ? <CheckCircle className="w-4 h-4 mr-2"/> : dbStatus === 'error' ? <XCircle className="w-4 h-4 mr-2"/> : <Database className="w-4 h-4 mr-2" />}
                     {dbStatus === 'testing' ? 'Connecting...' : dbStatus === 'success' ? 'Connected' : dbStatus === 'error' ? 'Failed' : 'Test Connection'}
                  </button>
               </div>
            </div>
         )}
      </div>
    </div>
  );
};

import React, { useRef } from 'react';
import { SystemSettings } from '../../types';
import { HardDrive, Download, Upload, AlertCircle } from 'lucide-react';
import { useGlobal } from '../../context/GlobalContext';

interface DatabaseSettingsProps {
  formData: SystemSettings;
  setFormData: React.Dispatch<React.SetStateAction<SystemSettings>>;
}

export const DatabaseSettings: React.FC<DatabaseSettingsProps> = ({ formData, setFormData }) => {
  const { 
    products, sales, customers, users, units, categories, 
    branches, posMachines, warehouses, locations, transfers, 
    counts, reservations, receipts, adjustments, shifts, 
    shiftSchedules, promotions, restoreSystemData 
  } = useGlobal();

  const importFileRef = useRef<HTMLInputElement>(null);

  const handleExportData = () => {
    const exportData = {
      meta: {
        exportedAt: new Date().toISOString(),
        version: '1.0'
      },
      settings: formData,
      products,
      sales,
      customers,
      users,
      units,
      categories,
      branches,
      posMachines,
      warehouses,
      locations,
      transfers,
      counts,
      reservations,
      receipts,
      adjustments,
      shifts,
      shiftSchedules,
      promotions
    };

    const jsonString = JSON.stringify(exportData, null, 2);
    const blob = new Blob([jsonString], { type: 'application/json' });
    const url = URL.createObjectURL(blob);

    const a = document.createElement('a');
    a.href = url;
    a.download = `buildmaster_backup_${new Date().toISOString().split('T')[0]}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const handleImportData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const jsonData = JSON.parse(event.target?.result as string);
        if (confirm("This will overwrite your current system data. Are you sure?")) {
           restoreSystemData(jsonData);
           alert("System data restored successfully!");
        }
      } catch (err) {
        alert("Failed to parse backup file. Invalid JSON.");
      }
      // Reset input
      if (importFileRef.current) importFileRef.current.value = '';
    };
    reader.readAsText(file);
  };

  return (
    <div className="space-y-6 animate-fade-in">
      <h3 className="text-lg font-bold text-slate-800 border-b border-slate-100 pb-3 mb-6">
         Backup & Restoration
      </h3>

      <div className="bg-slate-50 p-6 rounded-xl border border-slate-200 mb-8">
         <h4 className="font-bold text-slate-800 mb-4 flex items-center">
            <HardDrive className="w-5 h-5 mr-2 text-slate-500" />
            Data Management
         </h4>
         <p className="text-sm text-slate-500 mb-6 max-w-2xl">
            Manage your system data securely. Regular backups are recommended to prevent data loss. 
            Restoring data will replace all current inventory, sales, and settings.
         </p>

         <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="p-5 bg-white rounded-xl border border-slate-200 shadow-sm hover:border-slate-300 transition-colors">
               <h5 className="font-bold text-slate-800 mb-2 flex items-center">
                  <Download className="w-4 h-4 mr-2 text-blue-600" /> Backup Data
               </h5>
               <p className="text-xs text-slate-500 mb-4 h-10">
                  Download a full JSON snapshot of your current system state.
               </p>
               <button 
                  type="button"
                  onClick={handleExportData}
                  className="flex items-center justify-center w-full px-4 py-2.5 bg-slate-800 text-white rounded-lg hover:bg-slate-900 transition-colors text-sm font-bold shadow-sm"
               >
                  Export JSON Backup
               </button>
            </div>

            <div className="p-5 bg-white rounded-xl border border-slate-200 shadow-sm hover:border-slate-300 transition-colors">
               <h5 className="font-bold text-slate-800 mb-2 flex items-center">
                  <Upload className="w-4 h-4 mr-2 text-orange-600" /> Restore Data
               </h5>
               <p className="text-xs text-slate-500 mb-4 h-10">
                  Import a backup file to restore system state. <span className="text-red-500 font-bold">Overwrites current data.</span>
               </p>
               <button 
                  type="button"
                  onClick={() => importFileRef.current?.click()}
                  className="flex items-center justify-center w-full px-4 py-2.5 bg-white border-2 border-slate-100 text-slate-700 rounded-lg hover:bg-slate-50 hover:border-slate-200 transition-colors text-sm font-bold"
               >
                  Select File to Restore
               </button>
               <input 
                  type="file" 
                  ref={importFileRef}
                  className="hidden"
                  accept=".json"
                  onChange={handleImportData}
               />
            </div>
         </div>
      </div>

      <div className="p-4 bg-blue-50 text-blue-800 rounded-xl border border-blue-100 flex items-start">
         <AlertCircle className="w-5 h-5 mr-3 mt-0.5 flex-shrink-0" />
         <div>
            <h4 className="font-bold text-sm">Database Connection Settings</h4>
            <p className="text-xs mt-1 text-blue-700">
               To configure the connection to a local SQL database (PostgreSQL, MySQL, SQLite), 
               please go to the <strong>Device & Network</strong> tab.
            </p>
         </div>
      </div>
    </div>
  );
};

