import React, { useState, useEffect } from 'react';
import { Branch, Warehouse, StorageLocation } from '../types';
import { WarehouseList } from './warehouse/WarehouseList';
import { LocationGrid } from './warehouse/LocationGrid';
import { WarehouseFormModal } from './warehouse/WarehouseFormModal';
import { LocationFormModal } from './warehouse/LocationFormModal';
import { Plus } from 'lucide-react';

interface WarehouseManagementProps {
  branches: Branch[];
  warehouses: Warehouse[];
  locations: StorageLocation[];
  onAddWarehouse: (wh: Warehouse) => void;
  onUpdateWarehouse: (wh: Warehouse) => void;
  onDeleteWarehouse: (id: string) => void;
  onAddLocation: (loc: StorageLocation) => void;
  onUpdateLocation: (loc: StorageLocation) => void;
  onDeleteLocation: (id: string) => void;
}

export const WarehouseManagement: React.FC<WarehouseManagementProps> = ({
  branches,
  warehouses,
  locations,
  onAddWarehouse,
  onUpdateWarehouse,
  onDeleteWarehouse,
  onAddLocation,
  onUpdateLocation,
  onDeleteLocation
}) => {
  const [selectedBranchId, setSelectedBranchId] = useState<string>(branches[0]?.id || '');
  const [selectedWarehouseId, setSelectedWarehouseId] = useState<string | null>(null);

  // Modal States
  const [isWhModalOpen, setIsWhModalOpen] = useState(false);
  const [editingWh, setEditingWh] = useState<Warehouse | null>(null);

  const [isLocModalOpen, setIsLocModalOpen] = useState(false);
  const [editingLoc, setEditingLoc] = useState<StorageLocation | null>(null);

  // Auto-select first branch if none selected
  useEffect(() => {
    if (branches.length > 0 && !selectedBranchId) {
      setSelectedBranchId(branches[0].id);
    }
  }, [branches, selectedBranchId]);

  // Auto-select first warehouse when branch changes or initially
  useEffect(() => {
    if (selectedBranchId) {
      const branchWarehouses = warehouses.filter(w => w.branchId === selectedBranchId);
      if (branchWarehouses.length > 0) {
         if (!selectedWarehouseId || !branchWarehouses.find(w => w.id === selectedWarehouseId)) {
            setSelectedWarehouseId(branchWarehouses[0].id);
         }
      } else {
         setSelectedWarehouseId(null);
      }
    }
  }, [selectedBranchId, warehouses, selectedWarehouseId]);

  // Filter Logic
  const filteredLocations = locations.filter(l => l.warehouseId === selectedWarehouseId);
  const selectedWarehouse = warehouses.find(w => w.id === selectedWarehouseId);

  // Warehouse Modal Handlers
  const openWhModal = (wh?: Warehouse) => {
    setEditingWh(wh || null);
    setIsWhModalOpen(true);
  };

  const handleWhSubmit = (whForm: Partial<Warehouse>) => {
    if (editingWh) {
      onUpdateWarehouse({ ...whForm, id: editingWh.id, branchId: selectedBranchId } as Warehouse);
    } else {
      onAddWarehouse({ ...whForm, id: `wh-${Date.now()}`, branchId: selectedBranchId } as Warehouse);
    }
    setIsWhModalOpen(false);
  };

  // Location Modal Handlers
  const openLocModal = (loc?: StorageLocation) => {
    setEditingLoc(loc || null);
    setIsLocModalOpen(true);
  };

  const handleLocSubmit = (locForm: Partial<StorageLocation>) => {
    if (!selectedWarehouseId) return;

    const fullCode = `${locForm.zone}-${locForm.rack}-${locForm.shelf}-${locForm.bin}`;
    const locationData = { ...locForm, fullCode, warehouseId: selectedWarehouseId };

    if (editingLoc) {
      onUpdateLocation({ ...locationData, id: editingLoc.id } as StorageLocation);
    } else {
      onAddLocation({ ...locationData, id: `loc-${Date.now()}` } as StorageLocation);
    }
    setIsLocModalOpen(false);
  };

  return (
    <div className="flex flex-col h-full space-y-6 pb-20 md:pb-0">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">Warehouse Management (WMS)</h2>
          <p className="text-slate-500">Manage storage facilities, zones, racks, and bins.</p>
        </div>
        <button 
          onClick={() => openWhModal()}
          className="flex items-center justify-center px-6 py-3 bg-slate-900 text-white rounded-xl hover:bg-slate-800 transition-colors font-bold shadow-sm whitespace-nowrap"
        >
          <Plus className="w-5 h-5 mr-2" />
          Add Warehouse
        </button>
      </div>

      {/* Main Content Area: Stacks on Mobile */}
      <div className="flex flex-col lg:flex-row gap-6 flex-1 min-h-0">

        <div className="w-full lg:w-1/3 flex flex-col h-full">
           <WarehouseList 
             branches={branches}
             warehouses={warehouses}
             selectedBranchId={selectedBranchId}
             selectedWarehouseId={selectedWarehouseId}
             onSelectBranch={setSelectedBranchId}
             onSelectWarehouse={setSelectedWarehouseId}
             onAdd={() => openWhModal()}
             onEdit={openWhModal}
             onDelete={onDeleteWarehouse}
           />
        </div>

        <div className="w-full lg:w-2/3 flex flex-col h-full">
           <LocationGrid 
             selectedWarehouse={selectedWarehouse}
             locations={filteredLocations}
             onAdd={() => openLocModal()}
             onEdit={openLocModal}
             onDelete={onDeleteLocation}
           />
        </div>
      </div>

      {/* Modals */}
      <WarehouseFormModal 
        isOpen={isWhModalOpen}
        onClose={() => setIsWhModalOpen(false)}
        onSubmit={handleWhSubmit}
        initialData={editingWh}
      />

      <LocationFormModal 
        isOpen={isLocModalOpen}
        onClose={() => setIsLocModalOpen(false)}
        onSubmit={handleLocSubmit}
        initialData={editingLoc}
      />
    </div>
  );
};

import React, { useState } from 'react';
import { Warehouse, Branch } from '../../types';
import { Container, Plus, Edit2, Trash2, Search, MapPin } from 'lucide-react';

interface WarehouseListProps {
  branches: Branch[];
  warehouses: Warehouse[];
  selectedBranchId: string;
  selectedWarehouseId: string | null;
  onSelectBranch: (id: string) => void;
  onSelectWarehouse: (id: string) => void;
  onAdd: () => void;
  onEdit: (wh: Warehouse) => void;
  onDelete: (id: string) => void;
}

export const WarehouseList: React.FC<WarehouseListProps> = ({
  branches, warehouses, selectedBranchId, selectedWarehouseId,
  onSelectBranch, onSelectWarehouse, onAdd, onEdit, onDelete
}) => {
  const [searchTerm, setSearchTerm] = useState('');

  const filteredWarehouses = warehouses.filter(w => 
    w.branchId === selectedBranchId &&
    (w.name.toLowerCase().includes(searchTerm.toLowerCase()) || w.code.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  return (
    <div className="flex flex-col bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden h-full">
      <div className="p-4 border-b border-slate-100 bg-slate-50 space-y-3">
        <div className="flex items-center justify-between">
          <h3 className="font-bold text-slate-700 flex items-center">
            <Container className="w-5 h-5 mr-2" /> Warehouses
          </h3>
          <span className="text-xs font-bold bg-white text-slate-600 px-2 py-1 rounded-full border border-slate-200 shadow-sm">
             {filteredWarehouses.length}
          </span>
        </div>

        {/* Branch Selector */}
        <div className="relative">
           <MapPin className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 pointer-events-none" />
           <select 
             value={selectedBranchId}
             onChange={(e) => onSelectBranch(e.target.value)}
             className="w-full pl-9 pr-3 py-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-slate-400 outline-none bg-white font-medium text-slate-700"
           >
             {branches.map(b => (
               <option key={b.id} value={b.id}>{b.name}</option>
             ))}
           </select>
        </div>

        {/* Search */}
        <div className="relative">
           <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
           <input 
              type="text"
              placeholder="Search warehouses..."
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
              className="w-full pl-9 pr-4 py-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-slate-400 outline-none transition-all"
           />
        </div>
      </div>

      <div className="overflow-y-auto flex-1 p-3 space-y-3">
        {filteredWarehouses.length === 0 ? (
          <div className="text-center py-10 text-slate-400 flex flex-col items-center">
            <Container className="w-12 h-12 mb-3 opacity-20" />
            <p>No warehouses found.</p>
          </div>
        ) : (
          filteredWarehouses.map(wh => (
            <div 
              key={wh.id}
              onClick={() => onSelectWarehouse(wh.id)}
              className={`p-4 rounded-xl border cursor-pointer transition-all group relative ${
                selectedWarehouseId === wh.id 
                  ? 'border-slate-800 bg-slate-900 text-white shadow-lg transform scale-[1.02]' 
                  : 'border-slate-200 hover:border-slate-300 hover:bg-slate-50 bg-white'
              }`}
            >
              <div className="flex justify-between items-start">
                <div>
                  <h4 className={`font-bold text-base ${selectedWarehouseId === wh.id ? 'text-white' : 'text-slate-800'}`}>{wh.name}</h4>
                  <div className="flex items-center gap-2 mt-1.5">
                     <span className={`text-[10px] font-mono px-1.5 py-0.5 rounded border ${selectedWarehouseId === wh.id ? 'bg-slate-700 text-slate-300 border-slate-600' : 'bg-slate-100 text-slate-600 border-slate-200'}`}>
                        {wh.code}
                     </span>
                     <span className={`text-[10px] uppercase font-bold tracking-wide ${selectedWarehouseId === wh.id ? 'text-slate-400' : 'text-slate-500'}`}>
                        {wh.type}
                     </span>
                  </div>
                </div>
              </div>

              <div className={`mt-3 pt-3 border-t flex justify-between items-center ${selectedWarehouseId === wh.id ? 'border-slate-700' : 'border-slate-100'}`}>
                 <div className={`text-xs ${selectedWarehouseId === wh.id ? 'text-slate-400' : 'text-slate-500'}`}>
                    {wh.description || 'No description'}
                 </div>
                 <div className="flex space-x-2">
                    <button 
                      onClick={(e) => { e.stopPropagation(); onEdit(wh); }}
                      className={`p-1.5 rounded transition-colors ${selectedWarehouseId === wh.id ? 'text-slate-400 hover:text-white hover:bg-slate-700' : 'text-slate-400 hover:text-slate-900 hover:bg-slate-100'}`}
                    >
                      <Edit2 className="w-3.5 h-3.5" />
                    </button>
                    <button 
                      onClick={(e) => { e.stopPropagation(); onDelete(wh.id); }}
                      className={`p-1.5 rounded transition-colors ${selectedWarehouseId === wh.id ? 'text-slate-400 hover:text-red-400 hover:bg-slate-700' : 'text-slate-400 hover:text-red-600 hover:bg-slate-100'}`}
                    >
                      <Trash2 className="w-3.5 h-3.5" />
                    </button>
                 </div>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Warehouse, StorageLocation } from '../../types';
import { Grid, Plus, MapPin, Edit2, Trash2, Container, Search, LayoutGrid } from 'lucide-react';

interface LocationGridProps {
  selectedWarehouse: Warehouse | undefined;
  locations: StorageLocation[];
  onAdd: () => void;
  onEdit: (loc: StorageLocation) => void;
  onDelete: (id: string) => void;
}

export const LocationGrid: React.FC<LocationGridProps> = ({
  selectedWarehouse, locations, onAdd, onEdit, onDelete
}) => {
  const [searchTerm, setSearchTerm] = useState('');

  const filteredLocations = locations.filter(l => 
    l.fullCode.toLowerCase().includes(searchTerm.toLowerCase()) ||
    l.zone.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="flex flex-col bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden h-full">
      {selectedWarehouse ? (
        <>
          <div className="p-6 border-b border-slate-100 bg-slate-50">
            <div className="flex justify-between items-start mb-6">
              <div>
                <div className="flex items-center gap-2 mb-1">
                   <h3 className="text-xl font-bold text-slate-800">{selectedWarehouse.name}</h3>
                   <span className="px-2 py-0.5 bg-white border border-slate-200 rounded text-[10px] font-bold text-slate-500 uppercase tracking-wider">{selectedWarehouse.code}</span>
                </div>
                <p className="text-slate-500 text-sm flex items-center">
                   <Container className="w-4 h-4 mr-1.5" /> {selectedWarehouse.type} Storage
                </p>
              </div>
              <div className="bg-white p-2.5 rounded-xl shadow-sm border border-slate-200 text-slate-400">
                <LayoutGrid className="w-6 h-6" />
              </div>
            </div>

            <div className="flex gap-3">
               <div className="relative flex-1">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
                  <input 
                     type="text" 
                     placeholder="Search locations (Zone, Bin code)..." 
                     value={searchTerm}
                     onChange={e => setSearchTerm(e.target.value)}
                     className="w-full pl-9 pr-4 py-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-slate-400 outline-none transition-all"
                  />
               </div>
               <button 
                  onClick={onAdd}
                  className="flex items-center px-4 py-2 bg-white border border-slate-300 text-slate-700 rounded-lg hover:bg-slate-50 hover:text-slate-900 transition-colors text-sm font-bold shadow-sm whitespace-nowrap"
               >
                  <Plus className="w-4 h-4 mr-1.5" />
                  Add Location
               </button>
            </div>
          </div>

          <div className="overflow-y-auto flex-1">
            {filteredLocations.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-full text-slate-400 pb-10">
                <div className="w-16 h-16 bg-slate-50 rounded-full flex items-center justify-center mb-4">
                   <MapPin className="w-8 h-8 opacity-30" />
                </div>
                <p className="font-medium">No storage locations found.</p>
                {locations.length === 0 && <button onClick={onAdd} className="mt-4 text-blue-600 hover:underline text-sm">Create first location</button>}
              </div>
            ) : (
               <table className="w-full text-left border-collapse">
                  <thead className="bg-slate-50 border-b border-slate-100 sticky top-0 z-10 text-xs font-bold text-slate-500 uppercase tracking-wider">
                     <tr>
                        <th className="px-6 py-3 pl-8">Location Code</th>
                        <th className="px-6 py-3">Zone Details</th>
                        <th className="px-6 py-3">Type</th>
                        <th className="px-6 py-3 text-right pr-8">Actions</th>
                     </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100 text-sm">
                     {filteredLocations.map(loc => (
                        <tr key={loc.id} className="hover:bg-slate-50 transition-colors group">
                           <td className="px-6 py-3 pl-8">
                              <span className="font-mono font-bold text-slate-800 bg-slate-100 px-2 py-1 rounded border border-slate-200">
                                 {loc.fullCode}
                              </span>
                           </td>
                           <td className="px-6 py-3 text-slate-600">
                              <div className="flex items-center gap-3">
                                 <span className="font-bold text-slate-800 bg-blue-50 text-blue-700 px-2 py-0.5 rounded text-xs">Zone {loc.zone}</span>
                                 <span className="text-slate-400 text-xs">Rack {loc.rack} • Shelf {loc.shelf}</span>
                              </div>
                           </td>
                           <td className="px-6 py-3">
                              <span className={`text-[10px] uppercase font-bold px-2 py-1 rounded border ${
                                 loc.type === 'Cold Storage' ? 'bg-cyan-50 text-cyan-700 border-cyan-100' : 
                                 loc.type === 'Hazardous' ? 'bg-orange-50 text-orange-700 border-orange-100' :
                                 'bg-slate-50 text-slate-600 border-slate-100'
                              }`}>
                                 {loc.type || 'Shelf'}
                              </span>
                           </td>
                           <td className="px-6 py-3 text-right pr-8">
                              <div className="flex justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                 <button onClick={() => onEdit(loc)} className="p-1.5 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded transition-colors"><Edit2 className="w-4 h-4"/></button>
                                 <button onClick={() => onDelete(loc.id)} className="p-1.5 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded transition-colors"><Trash2 className="w-4 h-4"/></button>
                              </div>
                           </td>
                        </tr>
                     ))}
                  </tbody>
               </table>
            )}
          </div>
        </>
      ) : (
         <div className="flex flex-col items-center justify-center flex-1 text-slate-400 p-8 bg-slate-50/50">
            <Container className="w-16 h-16 mb-4 text-slate-200" />
            <p className="text-lg font-medium text-slate-500">Select a Warehouse</p>
            <p className="text-sm">Choose a warehouse from the left to manage locations.</p>
         </div>
      )}
    </div>
  );
};

