import React from 'react';
import { ChevronLeft, ChevronRight } from 'lucide-react';
import { User, UserRole } from '../../types';
import { MhxIcon } from '../shared/MhxLogo';

interface NavItemConfig {
  id: string;
  icon: any;
  label: string;
  allowedRoles: UserRole[];
}

interface DesktopSidebarProps {
  navItems: NavItemConfig[];
  activeTab: string;
  onTabChange: (tab: string) => void;
  currentUser: User | null;
  t: (key: string) => string;
  mobileMenuOpen: boolean;
  setMobileMenuOpen: (open: boolean) => void;
  isCollapsed: boolean;
  onToggleCollapse: () => void;
}

export const DesktopSidebar: React.FC<DesktopSidebarProps> = ({
  navItems,
  activeTab,
  onTabChange,
  currentUser,
  t,
  mobileMenuOpen,
  setMobileMenuOpen,
  isCollapsed,
  onToggleCollapse
}) => {
  // Filter nav items based on user role
  const visibleNavItems = navItems.filter(item => 
    currentUser && item.allowedRoles.includes(currentUser.role)
  );

  return (
    <aside className={`
      fixed inset-y-0 left-0 z-50 bg-slate-900 text-white transition-all duration-300 ease-in-out shadow-2xl flex flex-col
      md:relative md:translate-x-0
