'use client';

import React, { useState } from 'react';
import { useGlobal } from '../context/GlobalContext';
import { Lock, User as UserIcon, LogIn, Loader2, AlertCircle } from 'lucide-react';
import { verifyPasswordSync } from '../lib/auth';
import { MhxIcon } from './shared/MhxLogo';

export const LoginPage: React.FC = () => {
  const { setCurrentUser, users, t } = useGlobal();

  const [loginUsername, setLoginUsername] = useState('admin');
  const [loginPassword, setLoginPassword] = useState('123');
  const [loginError, setLoginError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleLoginSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoginError('');
    setLoading(true);

    try {
      const cleanUsername = loginUsername.trim().toLowerCase();
      const cleanPassword = loginPassword.trim();

      // 1. Client-Side Check (Fastest, supports session-created users)
      const clientMatch = users.find(u => 
        u.username.toLowerCase() === cleanUsername
      );

      if (clientMatch && clientMatch.password) {
        // Verify against the hash stored in client state
        const isValid = verifyPasswordSync(cleanPassword, clientMatch.password);

        if (isValid) {
          // Set cookie for middleware access
          document.cookie = `user_role=${clientMatch.role}; path=/; max-age=86400`;

          await new Promise(resolve => setTimeout(resolve, 600));
          const { password, ...safeUser } = clientMatch;
          setCurrentUser(safeUser as any);
          setLoading(false);
          return;
        }
      }

      // 2. Server-Side / API Check (Robust auth)
      try {
        const res = await fetch('/api/auth/login', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ username: cleanUsername, password: cleanPassword })
        });

        if (res.ok) {
          const data = await res.json();
          if (data.user) {
            setCurrentUser(data.user);
            setLoading(false);
            return;
          }
        }
      } catch (apiError) {
        console.warn("API Login failed, attempting local fallback only", apiError);
      }

      throw new Error('Invalid username or password');

    } catch (err: any) {
      console.error(err);
      setLoginError(err.message || 'Login failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 flex items-center justify-center bg-slate-900 z-50">
        <div className="bg-white rounded-2xl shadow-2xl overflow-hidden w-full max-w-4xl flex flex-col md:flex-row mx-4 md:mx-0 animate-fade-in">

           {/* Left Brand Side - Red Theme */}
           <div className="md:w-1/2 bg-gradient-to-br from-red-600 to-red-800 p-12 text-white flex flex-col justify-center items-center text-center relative overflow-hidden">
              <div className="absolute inset-0 bg-[url('https://images.unsplash.com/photo-1541888946425-d81bb19240f5?auto=format&fit=crop&q=80&w=1000')] bg-cover bg-center opacity-10 mix-blend-overlay"></div>

              <div className="bg-white/20 p-6 rounded-3xl mb-6 backdrop-blur-sm shadow-lg relative z-10 border border-white/10">
                <MhxIcon className="w-20 h-20 text-white" />
              </div>
              <h1 className="text-4xl font-bold mb-4 relative z-10">{t('app.name')}</h1>
              <p className="text-red-100 text-lg relative z-10 max-w-xs">{t('app.subtitle')}</p>
           </div>

           {/* Right Login Form Side */}
           <div className="md:w-1/2 p-8 md:p-12 flex flex-col justify-center bg-white">
              <div className="mb-8">
                <h2 className="text-2xl font-bold text-slate-800 flex items-center">
                  <LogIn className="w-6 h-6 mr-2 text-red-600" />
                  {t('common.signIn')}
                </h2>
                <p className="text-slate-500 text-sm mt-1">Access your POS dashboard</p>
              </div>

              <form onSubmit={handleLoginSubmit} className="space-y-5">
                 <div>
                   <label className="block text-sm font-medium text-slate-700 mb-1.5">{t('common.username')}</label>
                   <div className="relative group">
                     <UserIcon className="absolute left-3 top-3 w-5 h-5 text-slate-400 group-focus-within:text-red-500 transition-colors" />
                     <input 
                       type="text"
                       required
                       value={loginUsername}
                       onChange={e => setLoginUsername(e.target.value)}
                       className="w-full pl-10 pr-4 py-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-red-500 focus:border-red-500 transition-all outline-none bg-slate-50 focus:bg-white"
                       placeholder="Enter your username"
                     />
                   </div>
                 </div>

                 <div>
                   <label className="block text-sm font-medium text-slate-700 mb-1.5">{t('common.password')}</label>
                   <div className="relative group">
                     <Lock className="absolute left-3 top-3 w-5 h-5 text-slate-400 group-focus-within:text-red-500 transition-colors" />
                     <input 
                       type="password"
                       required
                       value={loginPassword}
                       onChange={e => setLoginPassword(e.target.value)}
                       className="w-full pl-10 pr-4 py-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-red-500 focus:border-red-500 transition-all outline-none bg-slate-50 focus:bg-white"
                       placeholder="Enter your password"
                     />
                   </div>
                 </div>

                 {loginError && (
                   <div className="bg-red-50 text-red-600 text-sm p-3 rounded-xl border border-red-100 flex items-start animate-pulse">
                     <AlertCircle className="w-5 h-5 mr-2 shrink-0 mt-0.5" />
                     {loginError}
                   </div>
                 )}

                 <button 
                   type="submit"
                   disabled={loading}
                   className="w-full bg-slate-900 text-white py-3.5 rounded-xl font-bold hover:bg-red-600 active:bg-red-700 active:scale-[0.98] transition-all shadow-lg disabled:opacity-70 disabled:cursor-not-allowed flex justify-center items-center"
                 >
                   {loading ? (
                     <>
                       <Loader2 className="w-5 h-5 animate-spin mr-2" />
                       {t('common.loading')}
                     </>
                   ) : t('common.login')}
                 </button>
              </form>

              <div className="mt-8 pt-6 border-t border-slate-100 text-center">
                 <p className="text-xs text-slate-400 font-medium uppercase tracking-wider mb-2">
                   {t('common.demo')}
                 </p>
                 <div className="flex justify-center space-x-2 text-xs">
                    <button onClick={() => { setLoginUsername('admin'); setLoginPassword('123'); }} className="bg-slate-100 px-2 py-1 rounded text-slate-600 font-mono hover:bg-slate-200 transition-colors">admin / 123</button>
                    <button onClick={() => { setLoginUsername('cashier'); setLoginPassword('123'); }} className="bg-slate-100 px-2 py-1 rounded text-slate-600 font-mono hover:bg-slate-200 transition-colors">cashier / 123</button>
                 </div>
              </div>
           </div>
        </div>
    </div>
  );
};

import React from 'react';
import { ChevronLeft, ChevronRight } from 'lucide-react';
import { User, UserRole } from '../../types';
import { MhxIcon } from '../shared/MhxLogo';

interface NavItemConfig {
  id: string;
  icon: any;
  label: string;
  allowedRoles: UserRole[];
}

interface DesktopSidebarProps {
  navItems: NavItemConfig[];
  activeTab: string;
  onTabChange: (tab: string) => void;
  currentUser: User | null;
  t: (key: string) => string;
  mobileMenuOpen: boolean;
  setMobileMenuOpen: (open: boolean) => void;
  isCollapsed: boolean;
  onToggleCollapse: () => void;
}

export const DesktopSidebar: React.FC<DesktopSidebarProps> = ({
  navItems,
  activeTab,
  onTabChange,
  currentUser,
  t,
  mobileMenuOpen,
  setMobileMenuOpen,
  isCollapsed,
  onToggleCollapse
}) => {
  // Filter nav items based on user role
  const visibleNavItems = navItems.filter(item => 
    currentUser && item.allowedRoles.includes(currentUser.role)
  );

  return (
    <aside className={`
      fixed inset-y-0 left-0 z-50 bg-slate-900 text-white transition-all duration-300 ease-in-out shadow-2xl flex flex-col
      md:relative md:translate-x-0
      ${mobileMenuOpen ? 'translate-x-0 w-72' : '-translate-x-full md:translate-x-0'}
      ${isCollapsed ? 'md:w-20' : 'md:w-72'}
    `}>
      {/* Header */}
      <div className={`flex items-center h-20 border-b border-slate-800 bg-slate-950/50 shrink-0 relative ${isCollapsed ? 'justify-center' : 'justify-between px-6'}`}>
        <div className="flex items-center space-x-3 overflow-hidden">
          <div className="text-red-500 shrink-0">
            <MhxIcon className="w-9 h-9" />
          </div>
          <h1 className={`text-lg font-bold tracking-tight text-white transition-opacity duration-200 whitespace-nowrap ${isCollapsed ? 'opacity-0 w-0 hidden' : 'opacity-100'}`}>
            {t('app.name')}
          </h1>
        </div>

        {/* Toggle Button - Visible only on Desktop - Floating on border */}
        <button 
          onClick={onToggleCollapse}
          className="hidden md:flex absolute -right-3 top-7 bg-slate-800 text-slate-400 hover:text-white border border-slate-600 rounded-full w-6 h-6 items-center justify-center shadow-lg transition-colors z-50 hover:bg-slate-700"
          title={isCollapsed ? "Expand Sidebar" : "Collapse Sidebar"}
        >
           {isCollapsed ? <ChevronRight className="w-3 h-3" /> : <ChevronLeft className="w-3 h-3" />}
        </button>
      </div>

      {/* Main Nav */}
      <div className="p-3 flex-1 overflow-y-auto max-h-[calc(100vh-80px)] scrollbar-hide">
        <nav className="space-y-1">
          {visibleNavItems.map(item => {
            const Icon = item.icon;
            const isActive = activeTab === item.id;
            return (
              <button
                key={item.id}
                onClick={() => {
                  onTabChange(item.id);
                  setMobileMenuOpen(false);
                }}
                title={isCollapsed ? t(`nav.${item.id}`) : ''}
                className={`flex items-center w-full px-3 py-3 rounded-xl transition-all duration-200 group relative ${
                  isActive 
                    ? 'bg-gradient-to-r from-red-600 to-red-500 text-white shadow-md font-semibold' 
                    : 'text-slate-400 hover:bg-slate-800 hover:text-white'
                } ${isCollapsed ? 'justify-center' : ''}`}
              >
                <Icon className={`w-5 h-5 shrink-0 transition-transform ${isActive ? 'scale-110' : 'group-hover:scale-110'} ${isCollapsed ? '' : 'mr-3'}`} />

                {!isCollapsed && (
                   <span className="flex-1 text-left truncate text-sm">{t(`nav.${item.id}`)}</span>
                )}

                {/* Shortcuts hint */}
                {!isCollapsed && item.id === 'dashboard' && <span className="text-[9px] bg-white/10 px-1.5 py-0.5 rounded text-white/70 hidden xl:inline font-mono">F1</span>}
                {!isCollapsed && item.id === 'pos' && <span className="text-[9px] bg-white/10 px-1.5 py-0.5 rounded text-white/70 hidden xl:inline font-mono">F2</span>}

                {/* Tooltip for collapsed state */}
                {isCollapsed && (
                   <div className="absolute left-full ml-4 px-2 py-1.5 bg-slate-800 text-white text-xs font-medium rounded opacity-0 group-hover:opacity-100 pointer-events-none transition-all duration-200 whitespace-nowrap z-50 border border-slate-700 shadow-xl translate-x-2 group-hover:translate-x-0">
                      {t(`nav.${item.id}`)}
                      {/* Arrow for tooltip */}
                      <div className="absolute top-1/2 -left-1 w-2 h-2 bg-slate-800 border-l border-b border-slate-700 transform rotate-45 -translate-y-1/2"></div>
                   </div>
                )}
              </button>
            );
          })}
        </nav>
      </div>

      {!isCollapsed && (
         <div className="p-4 border-t border-slate-800 text-[10px] text-slate-600 text-center uppercase tracking-widest font-bold">
            MAHAXAY POS v1.0
         </div>
      )}
    </aside>
  );
};

