import React, { useState, useRef } from 'react';
import { Product, UnitDefinition, CategoryItem, Warehouse, Sale } from '../types';
import { Search, Plus, Sparkles, Download, Upload, ScanBarcode, LayoutGrid, List } from 'lucide-react';
import { useGlobal } from '../context/GlobalContext';
import { BarcodeScanner } from './BarcodeScanner';
import { useInventoryStore } from '../store/useInventoryStore';

// Sub-components
import { InventoryList } from './inventory/InventoryList';
import { ProductFormModal } from './inventory/ProductFormModal';
import { ImportModal } from './inventory/ImportModal';
import { InventoryAiModal } from './inventory/InventoryAiModal';
import { LabelPrintModal } from './inventory/LabelPrintModal';

interface InventoryProps {
  products: Product[];
  units: UnitDefinition[];
  categories: CategoryItem[];
  warehouses?: Warehouse[];
  sales: Sale[];
  onUpdateProduct: (product: Product) => void;
  onDeleteProduct: (id: string) => void;
  onAddProduct: (product: Product) => void;
}

export const Inventory: React.FC<InventoryProps> = ({ sales }) => {
  const { settings, t, formatPrice } = useGlobal();

  // Store Access
  const products = useInventoryStore((state) => state.products);
  const units = useInventoryStore((state) => state.units);
  const categories = useInventoryStore((state) => state.categories);
  const attributes = useInventoryStore((state) => state.attributes); // Access attributes
  const addProduct = useInventoryStore((state) => state.addProduct);
  const updateProduct = useInventoryStore((state) => state.updateProduct);
  const deleteProduct = useInventoryStore((state) => state.deleteProduct);

  // State
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState<string>('all');
  const [viewMode, setViewMode] = useState<'list' | 'grid'>('list'); // View Mode State
  const [isScannerOpen, setIsScannerOpen] = useState(false);

  // Modal States
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Product | undefined>(undefined);

  const [isImportOpen, setIsImportOpen] = useState(false);
  const [isAiOpen, setIsAiOpen] = useState(false);

  const [labelProduct, setLabelProduct] = useState<Product | null>(null);

  // --- Filtering ---
  const getCategoryName = (idOrName: string) => {
    const cat = categories.find(c => c.id === idOrName);
    return cat ? cat.name : idOrName; 
  };

  const filteredProducts = products.filter(p => {
    const searchLower = searchTerm.toLowerCase();
    const matchesSearch = 
      p.name.toLowerCase().includes(searchLower) || 
      p.sku?.toLowerCase().includes(searchLower) || 
      p.barcode?.includes(searchLower);

    const pCatName = getCategoryName(p.category);
    const filterCatName = filterCategory === 'all' ? 'all' : getCategoryName(filterCategory);
    const matchesCategory = filterCategory === 'all' || p.category === filterCategory || pCatName === filterCatName;

    return matchesSearch && matchesCategory;
  });

  // --- Handlers ---
  const handleEdit = (product: Product) => {
    setEditingProduct(product);
    setIsFormOpen(true);
  };

  const handleAdd = () => {
    setEditingProduct(undefined);
    setIsFormOpen(true);
  };

  const handleFormSubmit = (product: Product) => {
    if (editingProduct) updateProduct(product);
    else addProduct(product);
  };

  const handleImport = (importedProducts: Partial<Product>[], action: 'Create' | 'Update') => {
    importedProducts.forEach(p => {
       // Simple mapping logic
       const newProduct = {
          ...p,
          id: p.id || `P-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
          category: p.category || categories[0]?.id || 'Uncategorized',
          unit: p.unit || 'pc',
          warehouseInventory: [{ warehouseId: 'wh1', quantity: p.stock || 0 }]
       } as Product;

       if (action === 'Update') updateProduct(newProduct);
       else addProduct(newProduct);
    });
  };

  const handleScan = (code: string) => {
    setSearchTerm(code);
    setIsScannerOpen(false);
  };

  const handleExportCSV = () => {
    const headers = ['ID', 'Name', 'Category', 'Price', 'Stock', 'SKU'];
    const csvContent = [
      headers.join(','),
      ...filteredProducts.map(p => [p.id, `"${p.name}"`, getCategoryName(p.category), p.price, p.stock, p.sku].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `inventory_export.csv`;
    link.click();
  };

  return (
    <div className="space-y-6 h-full flex flex-col relative pb-20 md:pb-0">
      {/* Header Actions */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">{t('inventory.title')}</h2>
          <p className="text-slate-500">{t('inventory.subtitle')}</p>
        </div>
        <div className="flex gap-2 overflow-x-auto pb-1 md:pb-0 scrollbar-hide">
          <button onClick={handleExportCSV} className="flex items-center px-4 py-2 bg-white border border-slate-200 text-slate-700 rounded-xl hover:bg-slate-50 font-bold text-sm shadow-sm whitespace-nowrap transition-colors">
            <Download className="w-4 h-4 md:mr-2" /> <span className="hidden md:inline">Export</span>
          </button>
          <button onClick={() => setIsImportOpen(true)} className="flex items-center px-4 py-2 bg-white border border-slate-200 text-slate-700 rounded-xl hover:bg-slate-50 font-bold text-sm shadow-sm whitespace-nowrap transition-colors">
            <Upload className="w-4 h-4 md:mr-2" /> <span className="hidden md:inline">Import</span>
          </button>
          <button onClick={() => setIsAiOpen(true)} className="flex items-center px-4 py-2 bg-violet-50 text-violet-700 border border-violet-100 rounded-xl hover:bg-violet-100 font-bold text-sm transition-colors whitespace-nowrap">
            <Sparkles className="w-4 h-4 mr-2" /> {t('inventory.aiInsights')}
          </button>
          {/* Style A: Black Primary Button */}
          <button onClick={handleAdd} className="hidden md:flex items-center px-6 py-2 bg-slate-900 text-white rounded-xl hover:bg-slate-800 font-bold text-sm shadow-md whitespace-nowrap transition-colors">
            <Plus className="w-4 h-4 mr-2" /> {t('inventory.addProduct')}
          </button>
        </div>
      </div>

      {/* Search & Filter - Style A */}
      <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 flex flex-col md:flex-row gap-4">
        <div className="relative flex-1 flex gap-2">
          <div className="relative flex-1">
             <Search className="absolute left-4 top-1/2 transform -translate-y-1/2 text-slate-400 w-5 h-5" />
             <input
               type="text"
               placeholder={t('inventory.searchPlaceholder')}
               className="w-full pl-12 pr-4 py-3 bg-slate-100 border-none rounded-xl text-slate-900 placeholder:text-slate-400 focus:outline-none focus:ring-2 focus:ring-slate-200 transition-all font-medium"
               value={searchTerm}
               onChange={(e) => setSearchTerm(e.target.value)}
             />
          </div>
          <button onClick={() => setIsScannerOpen(true)} className="px-4 py-2 bg-slate-100 rounded-xl hover:bg-slate-200 text-slate-600 transition-colors">
             <ScanBarcode className="w-6 h-6" />
          </button>
        </div>
        <div className="flex gap-2">
          <div className="relative">
             <select 
               value={filterCategory} 
               onChange={(e) => setFilterCategory(e.target.value)} 
               className="appearance-none w-full md:w-48 pl-4 pr-10 py-3 bg-slate-100 border-none rounded-xl text-slate-700 font-medium focus:outline-none focus:ring-2 focus:ring-slate-200 cursor-pointer"
             >
               <option value="all">{t('inventory.allCategories')}</option>
               {categories.map(cat => <option key={cat.id} value={cat.id}>{cat.name}</option>)}
             </select>
             <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-4 text-slate-500">
               <svg className="fill-current h-4 w-4" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20"><path d="M9.293 12.95l.707.707L15.657 8l-1.414-1.414L10 10.828 5.757 6.586 4.343 8z"/></svg>
             </div>
          </div>

          <div className="flex bg-slate-100 p-1 rounded-xl">
             <button 
                onClick={() => setViewMode('list')}
                className={`p-2.5 rounded-lg transition-all ${viewMode === 'list' ? 'bg-white shadow-sm text-slate-900' : 'text-slate-400 hover:text-slate-600'}`}
                title="List View"
             >
                <List className="w-5 h-5" />
             </button>
             <button 
                onClick={() => setViewMode('grid')}
                className={`p-2.5 rounded-lg transition-all ${viewMode === 'grid' ? 'bg-white shadow-sm text-slate-900' : 'text-slate-400 hover:text-slate-600'}`}
                title="Grid View"
             >
                <LayoutGrid className="w-5 h-5" />
             </button>
          </div>
        </div>
      </div>

      {/* Inventory List */}
      <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden flex-1 flex flex-col relative">
        <InventoryList 
          products={filteredProducts} 
          categories={categories} 
          formatPrice={formatPrice} 
          viewMode={viewMode}
          onEdit={handleEdit} 
          onDelete={deleteProduct} 
          onPrintLabel={(p) => setLabelProduct(p)} 
        />
      </div>

      {/* Mobile FAB */}
      <button onClick={handleAdd} className="md:hidden fixed bottom-20 right-6 w-14 h-14 bg-slate-900 text-white rounded-full shadow-xl flex items-center justify-center z-40 hover:bg-slate-800 active:scale-95 transition-all">
          <Plus className="w-8 h-8" />
      </button>

      {/* Modals */}
      <BarcodeScanner isOpen={isScannerOpen} onClose={() => setIsScannerOpen(false)} onScan={handleScan} />

      <ProductFormModal 
        isOpen={isFormOpen} 
        onClose={() => setIsFormOpen(false)} 
        onSubmit={handleFormSubmit} 
        initialData={editingProduct} 
        categories={categories} 
        units={units}
        attributes={attributes}
        currencySymbol={settings.currencySymbol}
      />

      <ImportModal 
        isOpen={isImportOpen} 
        onClose={() => setIsImportOpen(false)} 
        onImport={handleImport}
        currencySymbol={settings.currencySymbol}
        formatPrice={formatPrice}
      />

      <InventoryAiModal 
        isOpen={isAiOpen} 
        onClose={() => setIsAiOpen(false)} 
        products={products} 
        sales={sales} 
        formatPrice={formatPrice} 
      />

      {labelProduct && (
        <LabelPrintModal 
          isOpen={!!labelProduct} 
          onClose={() => setLabelProduct(null)} 
          product={labelProduct} 
          formatPrice={formatPrice} 
        />
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Product, ProductVariant, UnitDefinition, CategoryItem, VariantAttribute } from '../../types';
import { Box, Scale, DollarSign, Layers, X, Check } from 'lucide-react';
import { GeneralTab } from './product-form/GeneralTab';
import { PhysicalTab } from './product-form/PhysicalTab';
import { PricingTab } from './product-form/PricingTab';
import { VariantsTab } from './product-form/VariantsTab';

interface ProductFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (product: Product) => void;
  initialData?: Product;
  categories: CategoryItem[];
  units: UnitDefinition[];
  attributes: VariantAttribute[];
  currencySymbol: string;
}

const MAX_FILE_SIZE_MB = 5;

export const ProductFormModal: React.FC<ProductFormModalProps> = ({
  isOpen, onClose, onSubmit, initialData, categories, units, attributes, currencySymbol
}) => {
  const [activeTab, setActiveTab] = useState<'general' | 'physical' | 'pricing' | 'variants'>('general');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<Product>>({
    name: '', sku: '', barcode: '', category: '', price: 0, costPrice: 0,
    stock: 0, minStock: 20, unit: '', physical: { weight: 0, width: 0, height: 0, depth: 0 },
    branchPrices: [], imageUrl: ''
  });

  const [variants, setVariants] = useState<Partial<ProductVariant>[]>([]);

  useEffect(() => {
    if (initialData) {
      setFormData({ ...initialData });
      setVariants(initialData.variants ? initialData.variants.map(v => ({...v})) : []);
    } else {
      setFormData({
        name: '', sku: '', barcode: '', category: categories[0]?.id || '', price: 0, costPrice: 0,
        stock: 0, minStock: 20, unit: units[0]?.symbol || 'pc',
        physical: { weight: 0, width: 0, height: 0, depth: 0 }, branchPrices: [], imageUrl: ''
      });
      setVariants([]);
    }
    setActiveTab('general');
  }, [initialData, isOpen, categories, units]);

  if (!isOpen) return null;

  // Flatten categories for dropdown
  const categoryOptions: { id: string; name: string; level: number }[] = [];
  const buildCatOptions = (parentId: string | null, level: number) => {
    categories.filter(c => c.parentId === parentId).forEach(c => {
      categoryOptions.push({ id: c.id, name: c.name, level });
      buildCatOptions(c.id, level + 1);
    });
  };
  buildCatOptions(null, 0);

  const unitsByCategory = units.reduce((acc, unit) => {
    if (!acc[unit.category]) acc[unit.category] = [];
    acc[unit.category].push(unit);
    return acc;
  }, {} as Record<string, UnitDefinition[]>);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    const isNum = ['price', 'costPrice', 'stock', 'minStock'].includes(name);

    setFormData(prev => ({ ...prev, [name]: isNum ? (parseFloat(value) || 0) : value }));

    if (name === 'price') {
      const newMainPrice = parseFloat(value) || 0;
      setVariants(prev => prev.map(v => {
         const factor = v.conversionFactor || 1;
         return { ...v, price: factor !== 0 ? newMainPrice / factor : 0 };
      }));
    }
  };

  const handlePhysicalChange = (field: string, value: string) => {
    setFormData(prev => ({
      ...prev, physical: { ...prev.physical, [field]: parseFloat(value) || 0 }
    }));
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.size > MAX_FILE_SIZE_MB * 1024 * 1024) {
      alert(`File size exceeds ${MAX_FILE_SIZE_MB}MB.`);
      return;
    }
    const reader = new FileReader();
    reader.onloadend = () => setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
    reader.readAsDataURL(file);
  };

  // Variant Logic
  const handleAddVariant = () => {
    const suffix = (variants.length + 1).toString().padStart(3, '0');
    setVariants(prev => [...prev, {
      id: `v-${Date.now()}`,
      name: '', code: `${formData.sku || 'SKU'}-${suffix}`, barcode: formData.barcode ? `${formData.barcode}${suffix}` : '',
      conversionFactor: 1, price: formData.price, costPrice: formData.costPrice,
      attributes: {}
    }]);
  };

  const handleVariantChange = (index: number, field: keyof ProductVariant | 'attributes', value: any, attributeName?: string) => {
    setVariants(prev => {
      const newVars = [...prev];

      if (field === 'attributes' && attributeName) {
         // Update specific attribute
         const currentAttrs = newVars[index].attributes || {};
         newVars[index] = { 
            ...newVars[index], 
            attributes: { ...currentAttrs, [attributeName]: value } 
         };
      } else {
         // Standard field update
         newVars[index] = { ...newVars[index], [field]: field === 'name' ? value : (['price', 'costPrice', 'conversionFactor'].includes(field as string) ? parseFloat(value) || 0 : value) };

         if (field === 'name') {
            const main = units.find(u => u.symbol === formData.unit);
            const sub = units.find(u => u.symbol === value);
            if (main && sub && main.category === sub.category) {
               const factor = main.baseFactor / sub.baseFactor;
               newVars[index].conversionFactor = factor;
               newVars[index].price = (formData.price || 0) / factor;
            }
         }
      }
      return newVars;
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.name && formData.unit) {
      const productData: Product = {
        ...initialData,
        ...formData as Product,
        id: initialData?.id || `P-${Date.now()}`,
        variants: variants.length > 0 ? variants as ProductVariant[] : undefined,
        warehouseInventory: initialData?.warehouseInventory || [{ warehouseId: 'wh1', quantity: formData.stock || 0 }],
      };
      onSubmit(productData);
      onClose();
    }
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-5xl max-h-[90vh] flex flex-col overflow-hidden">
        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 shrink-0">
          <h3 className="text-xl font-bold text-slate-800">{initialData ? 'Edit' : 'Add'} Product</h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600"><X className="w-6 h-6" /></button>
        </div>

        <div className="flex border-b border-slate-200 bg-white overflow-x-auto no-scrollbar">
           {[
             { id: 'general', label: 'General Info', icon: Box },
             { id: 'physical', label: 'Physical Attributes', icon: Scale },
             { id: 'pricing', label: 'Pricing & Branches', icon: DollarSign },
             { id: 'variants', label: 'Variants', icon: Layers },
           ].map(tab => (
             <button
               key={tab.id}
               onClick={() => setActiveTab(tab.id as any)}
               className={`flex-1 flex items-center justify-center px-6 py-5 text-lg font-semibold transition-all whitespace-nowrap min-w-fit outline-none focus:outline-none select-none ${
                 activeTab === tab.id ? 'border-b-4 border-construction-orange text-construction-orange bg-orange-50' : 'text-slate-500 hover:text-slate-700 hover:bg-slate-50 border-b-4 border-transparent'
               }`}
             >
               <tab.icon className="w-6 h-6 mr-3" />
               {tab.label}
             </button>
           ))}
        </div>

        <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto p-6 bg-slate-50/50">
          {activeTab === 'general' && (
            <GeneralTab 
              formData={formData} 
              setFormData={setFormData} 
              handleInputChange={handleInputChange} 
              categoryOptions={categoryOptions} 
              units={units}
              fileInputRef={fileInputRef}
              handleImageUpload={handleImageUpload}
            />
          )}

          {activeTab === 'physical' && (
             <PhysicalTab formData={formData} handlePhysicalChange={handlePhysicalChange} />
          )}

          {activeTab === 'pricing' && (
            <PricingTab formData={formData} handleInputChange={handleInputChange} currencySymbol={currencySymbol} />
          )}

          {activeTab === 'variants' && (
            <VariantsTab 
              variants={variants} 
              setVariants={setVariants} 
              handleAddVariant={handleAddVariant} 
              handleVariantChange={handleVariantChange} 
              unitsByCategory={unitsByCategory}
              availableAttributes={attributes}
            />
          )}
        </form>

        <div className="p-4 border-t border-slate-100 flex justify-end space-x-3 bg-white shrink-0">
            <button onClick={onClose} className="px-5 py-2 text-slate-600 font-medium hover:bg-slate-100 rounded-lg">Cancel</button>
            <button type="button" onClick={handleSubmit} className="px-5 py-2 bg-construction-orange text-white font-medium rounded-lg hover:bg-orange-600 shadow-sm flex items-center"><Check className="w-4 h-4 mr-2" /> Save</button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { ProductVariant, UnitDefinition, VariantAttribute } from '../../../types';
import { Plus, Trash2, Tag, Barcode, CheckSquare, Square } from 'lucide-react';

interface VariantsTabProps {
  variants: Partial<ProductVariant>[];
  setVariants: React.Dispatch<React.SetStateAction<Partial<ProductVariant>[]>>;
  handleAddVariant: () => void;
  handleVariantChange: (index: number, field: keyof ProductVariant | 'attributes', value: any, attributeName?: string) => void;
  unitsByCategory: Record<string, UnitDefinition[]>;
  availableAttributes: VariantAttribute[];
}

export const VariantsTab: React.FC<VariantsTabProps> = ({
  variants, setVariants, handleAddVariant, handleVariantChange, unitsByCategory, availableAttributes
}) => {
  // Local state to track which attributes are "enabled" for this product form
  const [activeAttributeIds, setActiveAttributeIds] = useState<string[]>([]);

  // Initialize active attributes based on existing variant data
  useEffect(() => {
    if (variants.length > 0) {
      const usedAttrs = new Set<string>();
      variants.forEach(v => {
        if (v.attributes) {
          Object.keys(v.attributes).forEach(attrName => {
             const attrDef = availableAttributes.find(a => a.name === attrName);
             if (attrDef) usedAttrs.add(attrDef.id);
          });
        }
      });
      if (usedAttrs.size > 0) {
         setActiveAttributeIds(Array.from(usedAttrs));
      }
    }
  }, []); // Run once on mount

  const toggleAttribute = (attrId: string) => {
    if (activeAttributeIds.includes(attrId)) {
      setActiveAttributeIds(prev => prev.filter(id => id !== attrId));
    } else {
      setActiveAttributeIds(prev => [...prev, attrId]);
    }
  };

  const activeAttributes = availableAttributes.filter(a => activeAttributeIds.includes(a.id));

  return (
    <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm animate-fade-in">
       {/* Attribute Selector Section */}
       <div className="mb-6 p-4 bg-slate-50 rounded-xl border border-slate-100">
          <h5 className="font-bold text-slate-700 text-sm mb-3">Active Variant Attributes</h5>
          <div className="flex flex-wrap gap-3">
             {availableAttributes.length === 0 ? (
                <p className="text-xs text-slate-400 italic">No global attributes defined. Go to Unit Mgmt to add attributes.</p>
             ) : (
                availableAttributes.map(attr => {
                   const isActive = activeAttributeIds.includes(attr.id);
                   return (
                      <button
                         key={attr.id}
                         type="button"
                         onClick={() => toggleAttribute(attr.id)}
                         className={`flex items-center px-3 py-1.5 rounded-lg text-sm border transition-all ${
                            isActive 
                               ? 'bg-indigo-50 border-indigo-200 text-indigo-700 font-bold' 
                               : 'bg-white border-slate-200 text-slate-600 hover:border-slate-300'
                         }`}
                      >
                         {isActive ? <CheckSquare className="w-4 h-4 mr-2" /> : <Square className="w-4 h-4 mr-2 text-slate-400" />}
                         {attr.name}
                      </button>
                   );
                })
             )}
          </div>
       </div>

       <div className="flex justify-between items-center mb-6">
         <div>
            <h4 className="font-bold text-slate-800 flex items-center">
               <Tag className="w-5 h-5 mr-2 text-slate-500" />
               Product Variants
            </h4>
            <p className="text-xs text-slate-500 mt-1">Define different units or versions with specific pricing.</p>
         </div>
         <button 
            type="button" 
            onClick={handleAddVariant} 
            className="text-sm flex items-center text-white font-bold bg-slate-900 px-4 py-2 rounded-lg hover:bg-slate-800 transition-colors shadow-sm"
         >
            <Plus className="w-4 h-4 mr-1.5" /> Add Variant
         </button>
       </div>

       <div className="space-y-4">
          {variants.map((v, i) => (
             <div key={i} className="bg-slate-50 p-5 rounded-xl border border-slate-200 relative group transition-all hover:shadow-md hover:border-slate-300">
                <button 
                   type="button" 
                   onClick={() => setVariants(prev => prev.filter((_, idx) => idx !== i))} 
                   className="absolute top-3 right-3 p-1.5 text-slate-400 hover:text-red-500 bg-white rounded-lg border border-slate-200 shadow-sm transition-colors z-10"
                   title="Remove Variant"
                >
                   <Trash2 className="w-4 h-4" />
                </button>

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                   {/* Unit Selection */}
                   <div>
                      <label className="block text-xs font-bold text-slate-500 mb-1.5 uppercase">Unit / Type</label>
                      <select 
                         value={v.name} 
                         onChange={e => handleVariantChange(i, 'name', e.target.value)} 
                         className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm bg-white focus:ring-2 focus:ring-slate-400 outline-none"
                      >
                         <option value="">Select Unit</option>
                         {Object.entries(unitsByCategory).map(([c, uList]) => (
                           <optgroup key={c} label={c}>
                             {(uList as UnitDefinition[]).map(u => <option key={u.id} value={u.symbol}>{u.name} ({u.symbol})</option>)}
                           </optgroup>
                         ))}
                      </select>
                   </div>

                   {/* Dynamic Attributes */}
                   {activeAttributes.map(attr => (
                      <div key={attr.id}>
                         <label className="block text-xs font-bold text-slate-500 mb-1.5 uppercase">{attr.name}</label>
                         <select
                            value={v.attributes?.[attr.name] || ''}
                            onChange={e => handleVariantChange(i, 'attributes', e.target.value, attr.name)}
                            className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm bg-white focus:ring-2 focus:ring-indigo-400 outline-none"
                         >
                            <option value="">Any</option>
                            {attr.values.map(val => (
                               <option key={val} value={val}>{val}</option>
                            ))}
                         </select>
                      </div>
                   ))}

                   {/* SKU / Code */}
                   <div>
                      <label className="block text-xs font-bold text-slate-500 mb-1.5 uppercase">SKU Code</label>
                      <div className="relative">
                         <Barcode className="absolute left-3 top-2.5 w-4 h-4 text-slate-400" />
                         <input 
                            type="text" 
                            value={v.code} 
                            onChange={e => handleVariantChange(i, 'code', e.target.value)} 
                            placeholder="SKU-001" 
                            className="w-full pl-9 pr-3 py-2 border border-slate-300 rounded-lg text-sm font-mono focus:ring-2 focus:ring-slate-400 outline-none" 
                         />
                      </div>
                   </div>

                   {/* Cost Price */}
                   <div>
                      <label className="block text-xs font-bold text-slate-500 mb-1.5 uppercase">Cost Price</label>
                      <input 
                         type="number" 
                         min="0" 
                         step="0.01"
                         value={v.costPrice} 
                         onChange={e => handleVariantChange(i, 'costPrice', e.target.value)} 
                         placeholder="0.00" 
                         className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm font-medium focus:ring-2 focus:ring-slate-400 outline-none" 
                      />
                   </div>

                   {/* Selling Price */}
                   <div>
                      <label className="block text-xs font-bold text-slate-500 mb-1.5 uppercase">Selling Price</label>
                      <input 
                         type="number" 
                         min="0" 
                         step="0.01"
                         value={v.price} 
                         onChange={e => handleVariantChange(i, 'price', e.target.value)} 
                         placeholder="0.00" 
                         className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm font-bold text-slate-900 bg-white focus:ring-2 focus:ring-blue-500 outline-none" 
                      />
                   </div>
                </div>

                {/* Conversion Info Hint */}
                {v.conversionFactor && v.conversionFactor !== 1 && (
                   <div className="mt-3 text-[10px] text-slate-500 font-medium bg-slate-100 inline-block px-2 py-1 rounded border border-slate-200">
                      Conversion Ratio: 1 {v.name} = {v.conversionFactor} Base Units
                   </div>
                )}
             </div>
          ))}

          {variants.length === 0 && (
             <div className="text-center py-12 text-slate-400 border-2 border-dashed border-slate-200 rounded-xl bg-slate-50">
                <Tag className="w-12 h-12 mx-auto mb-3 opacity-20" />
                <p className="font-medium text-sm">No variants added yet.</p>
                <p className="text-xs mt-1">Add variants for different units (e.g. Box, Pallet) with custom pricing.</p>
             </div>
          )}
       </div>
    </div>
  );
};

