import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { Product, CartItem, EstimateResultItem, SystemSettings, Customer, Sale, ProductVariant } from '../types';
import { Sparkles, User, ClipboardList, Monitor, Menu, ChevronLeft } from 'lucide-react';
import { AiAssistant } from './AiAssistant';
import { BarcodeScanner } from './BarcodeScanner';
import { useGlobal } from '../context/GlobalContext';
import { useCartStore } from '../store/useCartStore';

// Sub-components
import { ProductGrid } from './pos/ProductGrid';
import { CartSidebar } from './pos/CartSidebar';
import { CheckoutModal } from './pos/CheckoutModal';
import { ReceiptModal } from './pos/ReceiptModal';
import { CustomerModal } from './pos/CustomerModal';
import { DiscountModal } from './pos/DiscountModal';
import { RecallModal } from './pos/RecallModal';
import { VariantSelectorModal } from './pos/VariantSelectorModal';

interface PosTerminalProps {
  products: Product[];
  onProcessSale: (
    items: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number,
    paymentMethod?: 'cash' | 'card' | 'transfer' | 'qr' | 'credit',
    amountReceived?: number,
    change?: number,
    pointsRedeemed?: number,
    source?: 'pos' | 'back-office'
  ) => Promise<Sale>;
  settings?: SystemSettings;
}

export const PosTerminal: React.FC<PosTerminalProps> = ({ products, onProcessSale, settings }) => {
  const { customers, customerLevels, t, branches, warehouses, currentUser, formatPrice } = useGlobal();
  const { 
    cart, addToCart, clearCart,
    heldOrders, holdCurrentOrder, recallOrder, discardHeldOrder
  } = useCartStore();

  const [searchTerm, setSearchTerm] = useState('');
  const [isAiModalOpen, setIsAiModalOpen] = useState(false);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isScannerOpen, setIsScannerOpen] = useState(false); 

  // Modal States
  const [isDiscountModalOpen, setIsDiscountModalOpen] = useState(false);
  const [isCustomerModalOpen, setIsCustomerModalOpen] = useState(false);
  const [isRecallModalOpen, setIsRecallModalOpen] = useState(false);
  const [isCheckoutOpen, setIsCheckoutOpen] = useState(false);
  const [isReceiptOpen, setIsReceiptOpen] = useState(false);
  const [productForSelector, setProductForSelector] = useState<Product | null>(null);

  // Transaction State
  const [manualDiscount, setManualDiscount] = useState<{ type: 'percent' | 'fixed', value: number } | null>(null);
  const [redeemPoints, setRedeemPoints] = useState<number>(0);
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);
  const [lastSale, setLastSale] = useState<Sale | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  // --- Branch Logic (Inventory Filtering) ---
  const activeBranchId = settings?.currentBranchId || currentUser?.branchId || (branches.length > 0 ? branches[0].id : '');

  const branchProducts = useMemo(() => {
    if (!activeBranchId) return products;

    const branchWarehouseIds = warehouses
      .filter(w => w.branchId === activeBranchId)
      .map(w => w.id);

    return products.map(p => {
      const branchStock = p.warehouseInventory?.reduce((acc, inv) => {
        if (branchWarehouseIds.includes(inv.warehouseId)) {
          return acc + inv.quantity;
        }
        return acc;
      }, 0) || 0;

      const branchPriceConfig = p.branchPrices?.find(bp => bp.branchId === activeBranchId);
      const effectivePrice = branchPriceConfig ? branchPriceConfig.price : p.price;

      return {
        ...p,
        stock: branchStock,
        price: effectivePrice
      };
    });
  }, [products, activeBranchId, warehouses]);

  // --- Helper: Get Dynamic Price based on Customer Level ---
  const getDynamicPrice = (product: Product, variantId?: string): number => {
    // 1. Determine Base Price (Variant or Product)
    let basePrice = product.price;
    let tierPrices = product.tierPrices;

    if (variantId && product.variants) {
      const variant = product.variants.find(v => v.id === variantId);
      if (variant) {
        basePrice = variant.price;
        tierPrices = variant.tierPrices || product.tierPrices; // Fallback to product tiers if variant doesn't have specific ones
      }
    }

    if (!selectedCustomer?.levelId) return basePrice;

    // 2. Check Specific Tier Price
    if (tierPrices && tierPrices[selectedCustomer.levelId]) {
      return tierPrices[selectedCustomer.levelId];
    }

    // 3. Check Level Percentage Discount
    const level = customerLevels.find(l => l.id === selectedCustomer.levelId);
    if (level && level.discountPercentage > 0) {
      return basePrice * (1 - level.discountPercentage / 100);
    }

    return basePrice;
  };

  // --- Handlers ---
  const handleProductSelect = (product: Product) => {
    if (product.variants && product.variants.length > 0) {
      setProductForSelector(product);
    } else {
      // Calculate price immediately
      const price = getDynamicPrice(product);
      // We pass the calculated price by modifying the product temporarily or handling it in addToCart
      // Since addToCart in store recalculates based on static product data, we might need to override.
      // However, simplified approach: We inject the 'price' into a cart item before adding.
      // useCartStore's addToCart takes a product object. 
      addToCart({ ...product, price }, 1);
    }
  };

  const handleConfirmSelection = (product: Product, quantity: number, variantId?: string) => {
    const price = getDynamicPrice(product, variantId);
    addToCart({ ...product, price }, quantity, variantId);
    setProductForSelector(null);
  };

  // --- Calculations ---
  const customerLevel = useMemo(() => {
    if (!selectedCustomer?.levelId) return null;
    return customerLevels.find(l => l.id === selectedCustomer.levelId);
  }, [selectedCustomer, customerLevels]);

  const rawSubtotal = cart.reduce((sum, item) => sum + (item.sellPrice * item.quantity), 0);

  // NOTE: If using Tier Pricing, customerDiscountAmount is logically 0 because the price is already adjusted.
  // Unless we want to apply ADDITIONAL discount on top of Tier Price.
  // Usually Tier Price replaces standard discount.
  // Strategy: If specific tier price was used for ALL items, discount % is 0.
  // But cart items store their sellPrice. 
  // Let's assume standard discount applies ONLY if manual discount is added or strict percentage. 
  // For simplicity here: disable global percentage discount calculation if we are already using dynamic pricing in cart items.
  // The 'getDynamicPrice' function already bakes the level discount into the item price.
  // So 'customerDiscountAmount' here effectively becomes 0 or just decorative if we don't want double discount.
  const customerDiscountAmount = 0; 

  let manualDiscountAmount = 0;
  if (manualDiscount) {
    if (manualDiscount.type === 'percent') {
      manualDiscountAmount = rawSubtotal * (manualDiscount.value / 100);
    } else {
      manualDiscountAmount = manualDiscount.value;
    }
  }

  const redeemRate = settings?.loyaltyProgram?.redeemRate || 100;
  const loyaltyDiscountAmount = redeemPoints > 0 ? redeemPoints / redeemRate : 0;

  let discountAmount = Math.min(customerDiscountAmount + manualDiscountAmount + loyaltyDiscountAmount, rawSubtotal);
  let discountedSubtotal = rawSubtotal - discountAmount;

  let taxAmount = 0;
  let finalTotal = discountedSubtotal;
  const taxConfig = settings?.tax;

  if (taxConfig && taxConfig.enabled) {
    const rate = taxConfig.rate / 100;
    if (taxConfig.calculationMode === 'excluded') {
       taxAmount = discountedSubtotal * rate;
       finalTotal = discountedSubtotal + taxAmount;
    } else {
       taxAmount = discountedSubtotal - (discountedSubtotal / (1 + rate));
       finalTotal = discountedSubtotal;
    }
  }

  // --- Broadcast Channel ---
  useEffect(() => {
    if (settings?.customerDisplay?.enabled) {
      const payload = {
        type: isCheckoutOpen ? 'CHECKOUT' : (cart.length === 0 ? 'RESET' : 'UPDATE'),
        cart,
        subtotal: rawSubtotal,
        discount: discountAmount,
        tax: taxAmount,
        total: finalTotal,
        customer: selectedCustomer,
        companyName: settings?.companyName,
        settings: settings?.customerDisplay
      };
      const channel = new BroadcastChannel('customer_display_channel');
      channel.postMessage(payload);
      return () => channel.close();
    }
  }, [cart, rawSubtotal, discountAmount, taxAmount, finalTotal, selectedCustomer, isCheckoutOpen, settings]);

  const handleOpenCustomerDisplay = () => {
    window.open('/customer-display', 'CustomerDisplay', 'width=1024,height=768,menubar=no,toolbar=no,location=no,status=no');
  };

  useEffect(() => {
     setRedeemPoints(0);
  }, [selectedCustomer]);

  // --- Keyboard Shortcuts ---
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement;
      const isInput = target.tagName === 'INPUT' || target.tagName === 'TEXTAREA';

      if (e.key === 'F4') {
        e.preventDefault();
        setIsCustomerModalOpen(true);
      }
      else if (e.key === 'F6') {
        e.preventDefault();
        setIsRecallModalOpen(true);
      }
      else if (e.key === 'F8') {
        e.preventDefault();
        setIsDiscountModalOpen(true);
      }
      else if (e.key === 'F9') {
        e.preventDefault();
        const searchInput = document.getElementById('pos-search-input');
        if (searchInput) {
            searchInput.focus();
            (searchInput as HTMLInputElement).select();
        }
      }
      else if (e.key === 'F12' || (e.key === 'Enter' && e.ctrlKey)) {
        e.preventDefault();
        if (cart.length > 0 && !isCheckoutOpen && !isReceiptOpen) {
           setIsCheckoutOpen(true);
        }
      }
      else if (e.key === 'Escape') {
         if (isCheckoutOpen) setIsCheckoutOpen(false);
         else if (isDiscountModalOpen) setIsDiscountModalOpen(false);
         else if (isCustomerModalOpen) setIsCustomerModalOpen(false);
         else if (isRecallModalOpen) setIsRecallModalOpen(false);
         else if (isReceiptOpen) setIsReceiptOpen(false);
         else if (isAiModalOpen) setIsAiModalOpen(false);
         else if (isScannerOpen) setIsScannerOpen(false);
         else if (isCartOpen) setIsCartOpen(false);
         else if (productForSelector) setProductForSelector(null);
         else if (document.activeElement?.id === 'pos-search-input') {
            setSearchTerm('');
            (document.activeElement as HTMLInputElement).blur();
         }
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [
    cart.length, 
    isCheckoutOpen, 
    isDiscountModalOpen, 
    isCustomerModalOpen, 
    isRecallModalOpen, 
    isReceiptOpen, 
    isAiModalOpen, 
    isScannerOpen,
    isCartOpen,
    productForSelector
  ]);

  const performScan = (code: string) => {
    const mainMatch = branchProducts.find(p => p.barcode === code || p.sku === code);
    if (mainMatch) {
      handleProductSelect(mainMatch);
      setSearchTerm(''); 
      return;
    }
    for (const p of branchProducts) {
      if (p.variants) {
        const variantMatch = p.variants.find(v => v.barcode === code || v.code === code);
        if (variantMatch) {
          const price = getDynamicPrice(p, variantMatch.id);
          addToCart({ ...p, price }, 1, variantMatch.id);
          setSearchTerm('');
          return;
        }
      }
    }
    alert(`Product not found: ${code}`);
  };

  const handleAiItemsAdded = (items: EstimateResultItem[]) => {
    items.forEach(est => {
      if (est.matchedProductId) {
        const product = branchProducts.find(p => p.id === est.matchedProductId);
        if (product) {
           const price = getDynamicPrice(product);
           addToCart({ ...product, price }, Math.ceil(est.estimatedQuantity), undefined);
        }
      }
    });
  };

  const handleHoldOrder = () => {
    if (cart.length === 0) return;
    const note = prompt("Optional note for this hold:");
    holdCurrentOrder(selectedCustomer, note || undefined);
    setSelectedCustomer(null);
    setManualDiscount(null);
    setRedeemPoints(0);
  };

  const handleRecall = (orderId: string) => {
    const restored = recallOrder(orderId);
    if (restored) {
      setSelectedCustomer(restored.customer || null);
      setIsRecallModalOpen(false);
    }
  };

  const handleProcessPayment = async (
    method: 'cash' | 'card' | 'transfer' | 'qr' | 'credit',
    receivedAmount: number,
    change: number
  ) => {
    setIsProcessing(true);
    try {
      const sale = await onProcessSale(
        cart, finalTotal, selectedCustomer?.id, discountAmount, rawSubtotal,
        method, receivedAmount, change, redeemPoints, 'pos'
      );

      setLastSale(sale);
      setIsCheckoutOpen(false);
      clearCart();
      setManualDiscount(null); 
      setRedeemPoints(0);
      setSelectedCustomer(null);
      setIsReceiptOpen(true);
    } catch (error) {
      console.error("Sale failed", error);
      alert("Transaction failed. Please try again.");
    } finally {
      setIsProcessing(false);
    }
  };

  const cartItemCount = cart.reduce((acc, item) => acc + item.quantity, 0);
  const barcodeList = useMemo(() => products.map(p => p.barcode).filter(Boolean), [products]);

  // Inject current pricing for grid display
  const productsWithDisplayPrice = useMemo(() => {
     return branchProducts.map(p => {
        return {
           ...p,
           displayPrice: getDynamicPrice(p) // used for display in grid
        };
     });
  }, [branchProducts, selectedCustomer, customerLevels]);

  return (
    <div className="flex flex-col lg:flex-row h-full overflow-hidden bg-white md:-m-6">
      {/* Main Product Area (Left Side) */}
      <div className="flex-1 flex flex-col min-w-0 h-full overflow-hidden relative border-r border-slate-200">

        {/* Header / Top Bar for POS - Style A */}
        <div className="px-6 py-4 bg-white flex items-center justify-between shrink-0">
          <div className="flex items-center gap-4">
            <h2 className="text-2xl font-extrabold text-slate-900 hidden md:block">{t('pos.newOrder')}</h2>

            <div className="flex space-x-2">
               <button 
                 onClick={() => setIsRecallModalOpen(true)}
                 disabled={heldOrders.length === 0}
                 title="Shortcut: F6"
                 className={`flex items-center px-4 py-2 rounded-full text-sm font-bold border transition-colors ${
                   heldOrders.length > 0 
                     ? 'bg-orange-50 text-orange-700 border-orange-200 hover:bg-orange-100' 
                     : 'bg-slate-50 text-slate-400 border-transparent cursor-not-allowed'
                 }`}
               >
                 <ClipboardList className="w-4 h-4 mr-2" />
                 Recall
                 {heldOrders.length > 0 && <span className="ml-2 bg-orange-200 text-orange-800 px-1.5 rounded-full text-xs font-bold">{heldOrders.length}</span>}
               </button>

               <button onClick={() => setIsAiModalOpen(true)} className="flex items-center px-4 py-2 bg-violet-50 text-violet-700 border border-violet-100 rounded-full hover:bg-violet-100 transition-all text-sm font-bold whitespace-nowrap">
                  <Sparkles className="w-4 h-4 mr-2" /> AI Estimate
               </button>
            </div>
          </div>

          <div className="flex items-center space-x-3">
             {settings?.customerDisplay?.enabled && (
               <button onClick={handleOpenCustomerDisplay} className="hidden xl:flex items-center px-3 py-2 text-slate-500 hover:text-slate-800 hover:bg-slate-100 rounded-lg transition-colors text-sm">
                 <Monitor className="w-4 h-4 mr-2" /> Screen
               </button>
             )}

             <button 
              onClick={() => setIsCustomerModalOpen(true)}
              title="Shortcut: F4"
              className={`flex items-center px-5 py-2.5 rounded-full shadow-sm font-bold text-sm border transition-all ${
                selectedCustomer 
                  ? 'bg-slate-900 text-white border-slate-900 hover:bg-slate-800' 
                  : 'bg-white text-slate-700 border-slate-200 hover:border-slate-400'
              }`}
            >
              <User className="w-4 h-4 mr-2" />
              {selectedCustomer ? (
                 <div className="flex flex-col items-start leading-none">
                    <span>{selectedCustomer.name}</span>
                    {customerLevel && <span className="text-[9px] opacity-80 font-normal uppercase">{customerLevel.name}</span>}
                 </div>
              ) : 'Select Customer'}
            </button>
          </div>
        </div>

        {/* Product Grid Container */}
        <div className="flex-1 overflow-hidden relative">
           <ProductGrid 
             products={productsWithDisplayPrice} 
             searchTerm={searchTerm}
             setSearchTerm={setSearchTerm}
             onScanClick={() => setIsScannerOpen(true)}
             onScan={performScan}
             onProductSelect={handleProductSelect}
           />
        </div>
      </div>

      {/* Cart Sidebar (Right Side) */}
      <div className={`
         fixed inset-0 z-40 bg-white transform transition-transform duration-300 lg:relative lg:translate-x-0 lg:w-[420px] xl:w-[480px] shadow-2xl lg:shadow-none
         ${isCartOpen ? 'translate-x-0' : 'translate-x-full lg:translate-x-0'}
      `}>
         <CartSidebar 
            isOpen={isCartOpen}
            onClose={() => setIsCartOpen(false)}
            selectedCustomer={selectedCustomer}
            onRemoveCustomer={() => setSelectedCustomer(null)}
            onHoldOrder={handleHoldOrder}
            onCheckout={() => setIsCheckoutOpen(true)}
            onDiscountClick={() => setIsDiscountModalOpen(true)}
            subtotal={rawSubtotal}
            discount={discountAmount}
            tax={taxAmount}
            total={finalTotal}
            settings={settings}
         />
      </div>

      {/* Mobile Cart Toggle Button */}
      {cartItemCount > 0 && !isCartOpen && (
        <button 
          onClick={() => setIsCartOpen(true)}
          className="lg:hidden fixed bottom-6 right-6 z-50 bg-slate-900 text-white pl-4 pr-6 py-4 rounded-full shadow-2xl flex items-center justify-between min-w-[200px] animate-bounce-in"
        >
          <div className="flex items-center">
            <span className="bg-orange-500 rounded-full w-8 h-8 flex items-center justify-center font-bold text-xs mr-3">
              {cartItemCount}
            </span>
            <span className="font-bold text-sm">Order Ticket</span>
          </div>
          <span className="font-bold text-lg ml-4">{formatPrice(finalTotal)}</span>
        </button>
      )}

      {/* Modals */}
      <CheckoutModal 
        isOpen={isCheckoutOpen}
        onClose={() => setIsCheckoutOpen(false)}
        total={finalTotal}
        onProcessPayment={handleProcessPayment}
        selectedCustomer={selectedCustomer}
        isProcessing={isProcessing}
      />

      <ReceiptModal 
        isOpen={isReceiptOpen}
        onClose={() => setIsReceiptOpen(false)}
        sale={lastSale}
        settings={settings}
      />

      <CustomerModal 
        isOpen={isCustomerModalOpen}
        onClose={() => setIsCustomerModalOpen(false)}
        customers={customers}
        onSelectCustomer={(c) => { setSelectedCustomer(c); setIsCustomerModalOpen(false); }}
      />

      <DiscountModal 
        isOpen={isDiscountModalOpen}
        onClose={() => setIsDiscountModalOpen(false)}
        onApplyDiscount={setManualDiscount}
        currencySymbol={settings?.currencySymbol}
      />

      <RecallModal 
        isOpen={isRecallModalOpen}
        onClose={() => setIsRecallModalOpen(false)}
        heldOrders={heldOrders}
        onRecall={handleRecall}
        onDiscard={discardHeldOrder}
      />

      <AiAssistant 
        isOpen={isAiModalOpen} 
        onClose={() => setIsAiModalOpen(false)} 
        inventory={branchProducts} 
        onAddItemsToCart={handleAiItemsAdded} 
      />

      <BarcodeScanner 
        isOpen={isScannerOpen} 
        onClose={() => setIsScannerOpen(false)} 
        onScan={performScan} 
        dummyCodes={barcodeList as string[]} 
      />

      {productForSelector && (
        <VariantSelectorModal 
          product={productForSelector}
          isOpen={!!productForSelector}
          onClose={() => setProductForSelector(null)}
          onConfirm={handleConfirmSelection}
          formatPrice={formatPrice}
        />
      )}
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Product, Category } from '../../types';
import { Search, Box, ScanBarcode, LayoutGrid, List, Plus, Layers } from 'lucide-react';
import { useGlobal } from '../../context/GlobalContext';

interface ProductGridProps {
  products: (Product & { displayPrice?: number })[]; // Updated type to accept displayPrice
  onScanClick: () => void;
  searchTerm: string;
  setSearchTerm: (term: string) => void;
  onScan: (code: string) => void; 
  onProductSelect: (product: Product) => void;
}

export const ProductGrid: React.FC<ProductGridProps> = ({ 
  products, 
  onScanClick,
  searchTerm,
  setSearchTerm,
  onScan,
  onProductSelect
}) => {
  const { formatPrice, t } = useGlobal();
  const [selectedCategory, setSelectedCategory] = useState<string>('all');
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const searchLower = searchTerm.toLowerCase();
      const matchesMain = 
        p.name.toLowerCase().includes(searchLower) ||
        p.sku?.toLowerCase().includes(searchLower) ||
        p.barcode?.includes(searchLower);

      const matchesVariant = p.variants && p.variants.some(v => 
        v.code.toLowerCase().includes(searchLower) || 
        v.barcode.includes(searchLower)
      );

      const matchesCategory = selectedCategory === 'all' || p.category === selectedCategory;
      return (matchesMain || matchesVariant) && matchesCategory;
    });
  }, [products, searchTerm, selectedCategory]);

  const handleFormSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchTerm) return;
    onScan(searchTerm);
  };

  return (
    <div className="flex flex-col h-full bg-white">
      {/* Search & Filter Bar - Style A */}
      <div className="px-6 pb-4 pt-0 space-y-4">
        <div className="flex flex-col md:flex-row gap-3">
          <form onSubmit={handleFormSubmit} className="relative flex-1 flex gap-3">
            <div className="relative flex-1 group">
               <Search className="absolute left-4 top-1/2 transform -translate-y-1/2 text-slate-400 w-5 h-5 group-focus-within:text-slate-800 transition-colors" />
               <input
                 id="pos-search-input"
                 type="text"
                 placeholder={t('pos.scanPlaceholder')}
                 className="w-full pl-12 pr-4 py-3.5 border-none rounded-xl bg-slate-100 text-slate-800 font-medium placeholder:text-slate-400 focus:outline-none focus:ring-2 focus:ring-slate-200 transition-all"
                 value={searchTerm}
                 onChange={(e) => setSearchTerm(e.target.value)}
                 autoFocus
               />
            </div>
            <button type="button" onClick={onScanClick} className="bg-slate-100 text-slate-600 px-4 rounded-xl hover:bg-slate-200 transition-colors">
               <ScanBarcode className="w-6 h-6" />
            </button>
          </form>

          <div className="flex bg-slate-100 p-1 rounded-xl shrink-0 items-center self-end md:self-auto h-[52px]">
             <button 
                onClick={() => setViewMode('list')} 
                className={`p-2.5 rounded-lg transition-all ${viewMode === 'list' ? 'bg-white shadow-sm text-slate-900' : 'text-slate-400 hover:text-slate-600'}`}
                title="List View"
             >
                <List className="w-5 h-5" />
             </button>
             <button 
                onClick={() => setViewMode('grid')} 
                className={`p-2.5 rounded-lg transition-all ${viewMode === 'grid' ? 'bg-white shadow-sm text-slate-900' : 'text-slate-400 hover:text-slate-600'}`}
                title="Grid View"
             >
                <LayoutGrid className="w-5 h-5" />
             </button>
          </div>
        </div>

        <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide -mx-6 px-6">
          <button 
            onClick={() => setSelectedCategory('all')} 
            className={`px-5 py-2.5 rounded-full text-sm font-bold whitespace-nowrap transition-all ${selectedCategory === 'all' ? 'bg-slate-900 text-white shadow-md' : 'bg-white text-slate-500 hover:bg-slate-50 border border-slate-100'}`}
          >
            {t('pos.allItems')}
          </button>
          {Object.values(Category).map(cat => (
            <button 
              key={cat} 
              onClick={() => setSelectedCategory(cat)} 
              className={`px-5 py-2.5 rounded-full text-sm font-bold whitespace-nowrap transition-all ${selectedCategory === cat ? 'bg-slate-900 text-white shadow-md' : 'bg-white text-slate-500 hover:bg-slate-50 border border-slate-100'}`}
            >
              {cat}
            </button>
          ))}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto px-6 pb-24 md:pb-6 custom-scrollbar bg-white">
        {filteredProducts.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-64 text-slate-400 mt-10">
            <div className="bg-slate-50 p-6 rounded-full mb-4">
               <Box className="w-12 h-12 text-slate-300" />
            </div>
            <p className="font-medium">No products found.</p>
            <p className="text-sm">Try adjusting your search or category.</p>
          </div>
        ) : viewMode === 'grid' ? (
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-3 xl:grid-cols-4 gap-4">
            {filteredProducts.map((product) => {
               const hasVariants = product.variants && product.variants.length > 0;
               const stock = product.stock;
               const isLowStock = stock <= (product.minStock || 0);

               // Use injected displayPrice if available (Customer Tier), else standard price logic
               let displayPrice = product.displayPrice !== undefined ? product.displayPrice : product.price;

               // If variants exist, show "From X" unless specific price is overridden by tier for the main product
               if (hasVariants && product.displayPrice === undefined) {
                  const prices = product.variants!.map(v => v.price);
                  displayPrice = Math.min(...prices);
               }

               const isTierPrice = product.displayPrice !== undefined && product.displayPrice !== product.price;

               return (
                <div 
                  key={product.id} 
                  onClick={() => onProductSelect(product)} 
                  className="bg-white rounded-2xl border border-slate-100 overflow-hidden hover:shadow-xl hover:border-slate-200 transition-all cursor-pointer flex flex-col group relative h-full"
                >
                  <div className="h-40 bg-slate-50 relative flex items-center justify-center overflow-hidden">
                    {product.imageUrl ? (
                      <img src={product.imageUrl} alt={product.name} className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105" />
                    ) : (
                      <Box className="w-12 h-12 text-slate-200" />
                    )}

                    <span className={`absolute top-3 right-3 px-2 py-1 rounded-md text-[10px] font-bold shadow-sm backdrop-blur-md ${isLowStock ? 'bg-red-500 text-white' : 'bg-white/90 text-slate-800'}`}>
                      {stock} {product.unit}
                    </span>
                  </div>

                  <div className="p-4 flex-1 flex flex-col">
                    <div className="mb-2">
                        <h3 className="font-bold text-slate-900 text-sm leading-tight line-clamp-2">
                           {product.name}
                        </h3>
                        <p className="text-[10px] text-slate-400 mt-1 font-mono">{product.sku}</p>
                    </div>

                    <div className="mt-auto pt-2">
                      <div className="flex items-center justify-between">
                         <div className={`px-3 py-1.5 rounded-full text-sm font-bold shadow-sm flex items-center ${isTierPrice ? 'bg-indigo-50 text-indigo-700 border border-indigo-100' : hasVariants ? 'bg-slate-100 text-slate-700' : 'bg-slate-900 text-white'}`}>
                            {hasVariants && !isTierPrice && <span className="text-[10px] mr-1 text-slate-500 font-normal">From</span>}
                            {formatPrice(displayPrice)}
                         </div>
                         {hasVariants ? (
                            <Layers className="w-5 h-5 text-blue-500 group-hover:text-blue-700 transition-colors" />
                         ) : (
                            <Plus className="w-5 h-5 text-slate-300 group-hover:text-slate-900 transition-colors" />
                         )}
                      </div>
                      {hasVariants && <p className="text-[10px] text-blue-600 mt-1 text-right font-medium">{product.variants!.length} Options</p>}
                    </div>
                  </div>
                </div>
               );
            })}
          </div>
        ) : (
          <div className="bg-white rounded-2xl border border-slate-200 overflow-hidden">
             <table className="w-full text-left border-collapse">
                <thead className="bg-slate-50 border-b border-slate-100 text-xs font-bold text-slate-500 uppercase sticky top-0 z-10">
                   <tr>
                      <th className="p-4 w-16 pl-6">Img</th>
                      <th className="p-4">Item Details</th>
                      <th className="p-4 text-right">Price</th>
                      <th className="p-4 text-center">Stock</th>
                      <th className="p-4 text-right w-32 pr-6">Action</th>
                   </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 text-sm">
                   {filteredProducts.map(product => {
                      const hasVariants = product.variants && product.variants.length > 0;
                      let displayPrice = product.displayPrice !== undefined ? product.displayPrice : product.price;
                      const isTierPrice = product.displayPrice !== undefined && product.displayPrice !== product.price;

                      return (
                         <tr 
                            key={product.id} 
                            className="hover:bg-slate-50 transition-colors cursor-pointer group"
                            onClick={() => onProductSelect(product)}
                         >
                            <td className="p-3 pl-6">
                               <div className="w-10 h-10 rounded-lg bg-slate-100 border border-slate-200 flex items-center justify-center overflow-hidden shrink-0">
                                  {product.imageUrl ? <img src={product.imageUrl} className="w-full h-full object-cover"/> : <Box className="w-5 h-5 text-slate-300"/>}
                               </div>
                            </td>
                            <td className="p-3">
                               <div className="font-bold text-slate-800">{product.name}</div>
                               <div className="flex items-center gap-2 mt-0.5">
                                  <span className="text-[10px] text-slate-400 font-mono">{product.sku}</span>
                                  {hasVariants && <span className="text-[10px] bg-blue-50 text-blue-600 px-1.5 rounded border border-blue-100">Multiple Options</span>}
                               </div>
                            </td>
                            <td className="p-3 text-right font-bold text-slate-900 text-base">
                               {hasVariants && !isTierPrice ? 'Select...' : (
                                  <span className={isTierPrice ? 'text-indigo-600' : ''}>{formatPrice(displayPrice)}</span>
                               )}
                            </td>
                            <td className="p-3 text-center">
                               <span className={`text-xs font-bold px-2 py-1 rounded-full ${product.stock > (product.minStock||0) ? 'bg-slate-100 text-slate-600' : 'bg-red-50 text-red-700'}`}>
                                  {product.stock} {product.unit}
                               </span>
                            </td>
                            <td className="p-3 text-right pr-6">
                               <button className="p-2 bg-slate-100 text-slate-600 rounded-full hover:bg-slate-900 hover:text-white transition-all shadow-sm">
                                  <Plus className="w-5 h-5" />
                                </button>
                            </td>
                         </tr>
                      );
                   })}
                </tbody>
             </table>
          </div>
        )}
      </div>
    </div>
  );
};

import React from 'react';
import { ChevronLeft, ChevronRight, X } from 'lucide-react';
import { User, UserRole } from '../../types';
import { MhxIcon } from '../shared/MhxLogo';

interface NavItemConfig {
  id: string;
  icon: any;
  label: string;
  allowedRoles: UserRole[];
}

interface DesktopSidebarProps {
  navItems: NavItemConfig[];
  activeTab: string;
  onTabChange: (tab: string) => void;
  currentUser: User | null;
  t: (key: string) => string;
  mobileMenuOpen: boolean;
  setMobileMenuOpen: (open: boolean) => void;
  isCollapsed: boolean;
  onToggleCollapse: () => void;
}

export const DesktopSidebar: React.FC<DesktopSidebarProps> = ({
  navItems,
  activeTab,
  onTabChange,
  currentUser,
  t,
  mobileMenuOpen,
  setMobileMenuOpen,
  isCollapsed,
  onToggleCollapse
}) => {
  // Filter nav items based on user role
  const visibleNavItems = navItems.filter(item => 
    currentUser && item.allowedRoles.includes(currentUser.role)
  );

  return (
    <>
      {/* Mobile Overlay */}
      {mobileMenuOpen && (
        <div 
          className="fixed inset-0 bg-black/60 z-40 md:hidden backdrop-blur-sm transition-opacity"
          onClick={() => setMobileMenuOpen(false)}
        />
      )}

      {/* Sidebar */}
      <aside className={`
        fixed inset-y-0 left-0 z-50 bg-slate-900 text-white transition-transform duration-300 ease-in-out shadow-2xl flex flex-col
        md:relative md:translate-x-0
        ${mobileMenuOpen ? 'translate-x-0 w-[80%] max-w-[300px]' : '-translate-x-full'}
        ${isCollapsed ? 'md:w-20' : 'md:w-72'}
      `}>
        {/* Header */}
        <div className={`flex items-center h-20 border-b border-slate-800 bg-slate-950/50 shrink-0 relative ${isCollapsed ? 'justify-center' : 'justify-between px-6'}`}>
          <div className="flex items-center space-x-3 overflow-hidden">
            <div className="text-red-500 shrink-0">
              <MhxIcon className="w-9 h-9" />
            </div>
            <h1 className={`text-lg font-bold tracking-tight text-white transition-opacity duration-200 whitespace-nowrap ${isCollapsed ? 'opacity-0 w-0 hidden' : 'opacity-100'}`}>
              {t('app.name')}
            </h1>
          </div>

          {/* Mobile Close Button */}
          <button 
            onClick={() => setMobileMenuOpen(false)}
            className="md:hidden text-slate-400 hover:text-white"
          >
            <X className="w-6 h-6" />
          </button>

          {/* Desktop Collapse Button */}
          <button 
            onClick={onToggleCollapse}
            className="hidden md:flex absolute -right-3 top-7 bg-slate-800 text-slate-400 hover:text-white border border-slate-600 rounded-full w-6 h-6 items-center justify-center shadow-lg transition-colors z-50 hover:bg-slate-700"
            title={isCollapsed ? "Expand Sidebar" : "Collapse Sidebar"}
          >
             {isCollapsed ? <ChevronRight className="w-3 h-3" /> : <ChevronLeft className="w-3 h-3" />}
          </button>
        </div>

        {/* Main Nav */}
        <div className="p-3 flex-1 overflow-y-auto max-h-[calc(100vh-80px)] scrollbar-hide">
          <nav className="space-y-1">
            {visibleNavItems.map(item => {
              const Icon = item.icon;
              const isActive = activeTab === item.id;
              return (
                <button
                  key={item.id}
                  onClick={() => {
                    onTabChange(item.id);
                    setMobileMenuOpen(false);
                  }}
                  title={isCollapsed ? t(`nav.${item.id}`) : ''}
                  className={`flex items-center w-full px-3 py-3 rounded-xl transition-all duration-200 group relative ${
                    isActive 
                      ? 'bg-gradient-to-r from-red-600 to-red-500 text-white shadow-md font-semibold' 
                      : 'text-slate-400 hover:bg-slate-800 hover:text-white'
                  } ${isCollapsed ? 'justify-center' : ''}`}
                >
                  <Icon className={`w-5 h-5 shrink-0 transition-transform ${isActive ? 'scale-110' : 'group-hover:scale-110'} ${isCollapsed ? '' : 'mr-3'}`} />

                  {!isCollapsed && (
                     <span className="flex-1 text-left truncate text-sm">{t(`nav.${item.id}`)}</span>
                  )}

                  {/* Shortcuts hint */}
                  {!isCollapsed && item.id === 'dashboard' && <span className="text-[9px] bg-white/10 px-1.5 py-0.5 rounded text-white/70 hidden xl:inline font-mono">F1</span>}
                  {!isCollapsed && item.id === 'pos' && <span className="text-[9px] bg-white/10 px-1.5 py-0.5 rounded text-white/70 hidden xl:inline font-mono">F2</span>}

                  {/* Tooltip for collapsed state */}
                  {isCollapsed && (
                     <div className="absolute left-full ml-4 px-2 py-1.5 bg-slate-800 text-white text-xs font-medium rounded opacity-0 group-hover:opacity-100 pointer-events-none transition-all duration-200 whitespace-nowrap z-50 border border-slate-700 shadow-xl translate-x-2 group-hover:translate-x-0">
                        {t(`nav.${item.id}`)}
                        {/* Arrow for tooltip */}
                        <div className="absolute top-1/2 -left-1 w-2 h-2 bg-slate-800 border-l border-b border-slate-700 transform rotate-45 -translate-y-1/2"></div>
                     </div>
                  )}
                </button>
              );
            })}
          </nav>
        </div>

        {!isCollapsed && (
           <div className="p-4 border-t border-slate-800 text-[10px] text-slate-600 text-center uppercase tracking-widest font-bold">
              MAHAXAY POS v1.0
           </div>
        )}
      </aside>
    </>
  );
};

import React, { useState, useMemo } from 'react';
import { Product, Category } from '../../types';
import { Search, Box, ScanBarcode, LayoutGrid, List, Plus, Layers } from 'lucide-react';
import { useGlobal } from '../../context/GlobalContext';

interface ProductGridProps {
  products: (Product & { displayPrice?: number })[]; 
  onScanClick: () => void;
  searchTerm: string;
  setSearchTerm: (term: string) => void;
  onScan: (code: string) => void; 
  onProductSelect: (product: Product) => void;
}

export const ProductGrid: React.FC<ProductGridProps> = ({ 
  products, 
  onScanClick,
  searchTerm,
  setSearchTerm,
  onScan,
  onProductSelect
}) => {
  const { formatPrice, t } = useGlobal();
  const [selectedCategory, setSelectedCategory] = useState<string>('all');
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const searchLower = searchTerm.toLowerCase();
      const matchesMain = 
        p.name.toLowerCase().includes(searchLower) ||
        p.sku?.toLowerCase().includes(searchLower) ||
        p.barcode?.includes(searchLower);

      const matchesVariant = p.variants && p.variants.some(v => 
        v.code.toLowerCase().includes(searchLower) || 
        v.barcode.includes(searchLower)
      );

      const matchesCategory = selectedCategory === 'all' || p.category === selectedCategory;
      return (matchesMain || matchesVariant) && matchesCategory;
    });
  }, [products, searchTerm, selectedCategory]);

  const handleFormSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchTerm) return;
    onScan(searchTerm);
  };

  return (
    <div className="flex flex-col h-full bg-white">
      {/* Search & Filter Bar */}
      <div className="px-4 md:px-6 pb-4 pt-2 space-y-3 bg-white z-10">
        <div className="flex flex-col md:flex-row gap-3">
          <form onSubmit={handleFormSubmit} className="relative flex-1 flex gap-2">
            <div className="relative flex-1 group">
               <Search className="absolute left-4 top-1/2 transform -translate-y-1/2 text-slate-400 w-5 h-5 group-focus-within:text-slate-800 transition-colors" />
               <input
                 id="pos-search-input"
                 type="text"
                 placeholder={t('pos.scanPlaceholder')}
                 className="w-full pl-12 pr-4 py-3 border-none rounded-xl bg-slate-100 text-slate-800 font-medium placeholder:text-slate-400 focus:outline-none focus:ring-2 focus:ring-slate-200 transition-all text-sm md:text-base"
                 value={searchTerm}
                 onChange={(e) => setSearchTerm(e.target.value)}
                 autoFocus
               />
            </div>
            <button type="button" onClick={onScanClick} className="bg-slate-100 text-slate-600 px-3 md:px-4 rounded-xl hover:bg-slate-200 transition-colors flex items-center justify-center">
               <ScanBarcode className="w-6 h-6" />
            </button>
          </form>

          <div className="flex bg-slate-100 p-1 rounded-xl shrink-0 items-center self-end md:self-auto h-[48px] md:h-[52px]">
             <button 
                onClick={() => setViewMode('list')} 
                className={`p-2 rounded-lg transition-all flex-1 md:flex-none flex justify-center ${viewMode === 'list' ? 'bg-white shadow-sm text-slate-900' : 'text-slate-400 hover:text-slate-600'}`}
                title="List View"
             >
                <List className="w-5 h-5" />
             </button>
             <button 
                onClick={() => setViewMode('grid')} 
                className={`p-2 rounded-lg transition-all flex-1 md:flex-none flex justify-center ${viewMode === 'grid' ? 'bg-white shadow-sm text-slate-900' : 'text-slate-400 hover:text-slate-600'}`}
                title="Grid View"
             >
                <LayoutGrid className="w-5 h-5" />
             </button>
          </div>
        </div>

        {/* Categories - Horizontal Scroll */}
        <div className="flex gap-2 overflow-x-auto pb-2 -mx-4 px-4 md:mx-0 md:px-0 scrollbar-hide">
          <button 
            onClick={() => setSelectedCategory('all')} 
            className={`px-4 py-2 rounded-full text-xs md:text-sm font-bold whitespace-nowrap transition-all ${selectedCategory === 'all' ? 'bg-slate-900 text-white shadow-md' : 'bg-white text-slate-500 hover:bg-slate-50 border border-slate-100'}`}
          >
            {t('pos.allItems')}
          </button>
          {Object.values(Category).map(cat => (
            <button 
              key={cat} 
              onClick={() => setSelectedCategory(cat)} 
              className={`px-4 py-2 rounded-full text-xs md:text-sm font-bold whitespace-nowrap transition-all ${selectedCategory === cat ? 'bg-slate-900 text-white shadow-md' : 'bg-white text-slate-500 hover:bg-slate-50 border border-slate-100'}`}
            >
              {cat}
            </button>
          ))}
        </div>
      </div>

      {/* Product List/Grid */}
      <div className="flex-1 overflow-y-auto px-4 md:px-6 pb-24 md:pb-6 custom-scrollbar bg-white">
        {filteredProducts.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-64 text-slate-400 mt-10">
            <div className="bg-slate-50 p-6 rounded-full mb-4">
               <Box className="w-12 h-12 text-slate-300" />
            </div>
            <p className="font-medium">No products found.</p>
            <p className="text-sm">Try adjusting your search or category.</p>
          </div>
        ) : viewMode === 'grid' ? (
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-3 xl:grid-cols-4 gap-3 md:gap-4">
            {filteredProducts.map((product) => {
               const hasVariants = product.variants && product.variants.length > 0;
               const stock = product.stock;
               const isLowStock = stock <= (product.minStock || 0);

               let displayPrice = product.displayPrice !== undefined ? product.displayPrice : product.price;
               if (hasVariants && product.displayPrice === undefined) {
                  const prices = product.variants!.map(v => v.price);
                  displayPrice = Math.min(...prices);
               }
               const isTierPrice = product.displayPrice !== undefined && product.displayPrice !== product.price;

               return (
                <div 
                  key={product.id} 
                  onClick={() => onProductSelect(product)} 
                  className="bg-white rounded-xl md:rounded-2xl border border-slate-100 overflow-hidden hover:shadow-xl hover:border-slate-200 transition-all cursor-pointer flex flex-col group relative h-full shadow-sm"
                >
                  <div className="h-32 md:h-40 bg-slate-50 relative flex items-center justify-center overflow-hidden">
                    {product.imageUrl ? (
                      <img src={product.imageUrl} alt={product.name} className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105" />
                    ) : (
                      <Box className="w-10 h-10 md:w-12 md:h-12 text-slate-200" />
                    )}

                    <span className={`absolute top-2 right-2 px-1.5 py-0.5 rounded text-[9px] md:text-[10px] font-bold shadow-sm backdrop-blur-md ${isLowStock ? 'bg-red-500 text-white' : 'bg-white/90 text-slate-800'}`}>
                      {stock} {product.unit}
                    </span>
                  </div>

                  <div className="p-3 md:p-4 flex-1 flex flex-col">
                    <div className="mb-2">
                        <h3 className="font-bold text-slate-900 text-xs md:text-sm leading-tight line-clamp-2 min-h-[2.5em]">
                           {product.name}
                        </h3>
                        <p className="text-[10px] text-slate-400 mt-1 font-mono hidden md:block">{product.sku}</p>
                    </div>

                    <div className="mt-auto pt-2">
                      <div className="flex items-center justify-between">
                         <div className={`px-2 md:px-3 py-1 md:py-1.5 rounded-full text-xs md:text-sm font-bold shadow-sm flex items-center ${isTierPrice ? 'bg-indigo-50 text-indigo-700 border border-indigo-100' : hasVariants ? 'bg-slate-100 text-slate-700' : 'bg-slate-900 text-white'}`}>
                            {hasVariants && !isTierPrice && <span className="text-[9px] mr-1 text-slate-500 font-normal">From</span>}
                            {formatPrice(displayPrice)}
                         </div>
                         {hasVariants ? (
                            <Layers className="w-4 h-4 md:w-5 md:h-5 text-blue-500 group-hover:text-blue-700 transition-colors" />
                         ) : (
                            <Plus className="w-4 h-4 md:w-5 md:h-5 text-slate-300 group-hover:text-slate-900 transition-colors" />
                         )}
                      </div>
                    </div>
                  </div>
                </div>
               );
            })}
          </div>
        ) : (
          <div className="bg-white rounded-2xl border border-slate-200 overflow-hidden">
             <table className="w-full text-left border-collapse">
                <thead className="bg-slate-50 border-b border-slate-100 text-xs font-bold text-slate-500 uppercase sticky top-0 z-10 hidden md:table-header-group">
                   <tr>
                      <th className="p-4 w-16 pl-6">Img</th>
                      <th className="p-4">Item Details</th>
                      <th className="p-4 text-right">Price</th>
                      <th className="p-4 text-center">Stock</th>
                      <th className="p-4 text-right w-32 pr-6">Action</th>
                   </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 text-sm">
                   {filteredProducts.map(product => {
                      const hasVariants = product.variants && product.variants.length > 0;
                      let displayPrice = product.displayPrice !== undefined ? product.displayPrice : product.price;
                      const isTierPrice = product.displayPrice !== undefined && product.displayPrice !== product.price;

                      return (
                         <tr 
                            key={product.id} 
                            className="hover:bg-slate-50 transition-colors cursor-pointer group flex flex-col md:table-row p-4 md:p-0 border-b md:border-b-0"
                            onClick={() => onProductSelect(product)}
                         >
                            <td className="p-0 md:p-3 md:pl-6 flex items-center md:table-cell mb-2 md:mb-0">
                               <div className="w-12 h-12 md:w-10 md:h-10 rounded-lg bg-slate-100 border border-slate-200 flex items-center justify-center overflow-hidden shrink-0 mr-3 md:mr-0">
                                  {product.imageUrl ? <img src={product.imageUrl} className="w-full h-full object-cover"/> : <Box className="w-5 h-5 text-slate-300"/>}
                               </div>
                               <div className="md:hidden flex-1">
                                  <div className="font-bold text-slate-800">{product.name}</div>
                                  <div className="text-[10px] text-slate-400 font-mono">{product.sku}</div>
                               </div>
                               <div className="md:hidden text-right">
                                  <div className="font-bold text-slate-900 text-base">
                                     {hasVariants && !isTierPrice ? 'Select...' : (
                                        <span className={isTierPrice ? 'text-indigo-600' : ''}>{formatPrice(displayPrice)}</span>
                                     )}
                                  </div>
                               </div>
                            </td>
                            <td className="p-0 md:p-3 hidden md:table-cell">
                               <div className="font-bold text-slate-800">{product.name}</div>
                               <div className="flex items-center gap-2 mt-0.5">
                                  <span className="text-[10px] text-slate-400 font-mono">{product.sku}</span>
                                  {hasVariants && <span className="text-[10px] bg-blue-50 text-blue-600 px-1.5 rounded border border-blue-100">Multiple Options</span>}
                               </div>
                            </td>
                            <td className="p-0 md:p-3 text-right font-bold text-slate-900 text-base hidden md:table-cell">
                               {hasVariants && !isTierPrice ? 'Select...' : (
                                  <span className={isTierPrice ? 'text-indigo-600' : ''}>{formatPrice(displayPrice)}</span>
                               )}
                            </td>
                            <td className="p-0 md:p-3 text-center hidden md:table-cell">
                               <span className={`text-xs font-bold px-2 py-1 rounded-full ${product.stock > (product.minStock||0) ? 'bg-slate-100 text-slate-600' : 'bg-red-50 text-red-700'}`}>
                                  {product.stock} {product.unit}
                               </span>
                            </td>
                            <td className="p-0 md:p-3 text-right md:pr-6 hidden md:table-cell">
                               <button className="p-2 bg-slate-100 text-slate-600 rounded-full hover:bg-slate-900 hover:text-white transition-all shadow-sm">
                                  <Plus className="w-5 h-5" />
                                </button>
                            </td>
                         </tr>
                      );
                   })}
                </tbody>
             </table>
          </div>
        )}
      </div>
    </div>
  );
};

import React from 'react';
import { Customer, SystemSettings } from '../../types';
import { ShoppingCart, PauseCircle, X, Minus, Plus, Trash2, User, Tag, ChevronRight, ChevronDown } from 'lucide-react';
import { useGlobal } from '../../context/GlobalContext';
import { useCartStore } from '../../store/useCartStore';

interface CartSidebarProps {
  isOpen: boolean;
  onClose: () => void;
  selectedCustomer: Customer | null;
  onRemoveCustomer: () => void;
  onHoldOrder: () => void;
  onCheckout: () => void;
  onDiscountClick: () => void;
  subtotal: number;
  discount: number;
  tax: number;
  total: number;
  settings?: SystemSettings;
}

export const CartSidebar: React.FC<CartSidebarProps> = ({
  isOpen,
  onClose,
  selectedCustomer,
  onRemoveCustomer,
  onHoldOrder,
  onCheckout,
  onDiscountClick,
  subtotal,
  discount,
  tax,
  total,
  settings
}) => {
  const { formatPrice } = useGlobal();
  const { cart, removeFromCart, updateQuantity } = useCartStore();

  const renderVariantDetails = (item: any) => {
    if (!item.selectedVariantId || !item.variants) return null;
    const variant = item.variants.find((v: any) => v.id === item.selectedVariantId);
    if (!variant || !variant.attributes) return null;

    return (
      <div className="flex flex-wrap gap-1 mt-1">
        {Object.values(variant.attributes).map((val: any, idx: number) => (
          <span key={idx} className="text-[10px] bg-slate-100 text-slate-500 px-1.5 rounded border border-slate-200">
            {val}
          </span>
        ))}
      </div>
    );
  };

  return (
    <div className="flex flex-col h-full bg-white relative w-full">
      {/* Header */}
      <div className="p-4 md:p-5 border-b border-slate-100 bg-white flex justify-between items-center z-10 shrink-0 shadow-sm">
        <div>
           <div className="flex items-center gap-2">
              <h3 className="font-extrabold text-slate-900 text-lg md:text-xl">Order Ticket</h3>
              <span className="bg-slate-100 text-slate-600 text-xs font-bold px-2 py-0.5 rounded-full">{cart.reduce((a,c)=>a+c.quantity,0)}</span>
           </div>
           <div className="text-xs text-slate-400 mt-0.5 font-medium">
              {new Date().toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}
           </div>
        </div>
        <div className="flex space-x-2">
           <button 
              onClick={onHoldOrder} 
              disabled={cart.length === 0} 
              className="p-2.5 bg-slate-50 text-slate-500 rounded-full hover:bg-orange-50 hover:text-orange-600 transition-colors disabled:opacity-30" 
              title="Hold Order"
           >
              <PauseCircle className="w-5 h-5" />
           </button>
           <button onClick={onClose} className="lg:hidden p-2.5 bg-slate-100 text-slate-600 hover:bg-slate-200 rounded-full transition-colors">
             <ChevronDown className="w-5 h-5" />
           </button>
        </div>
      </div>

      {/* Customer Bar */}
      {selectedCustomer && (
         <div className="px-5 py-3 border-b border-slate-100 bg-blue-50/50 flex justify-between items-center shrink-0">
            <div className="flex items-center">
               <div className="w-8 h-8 rounded-full bg-white border border-blue-200 text-blue-700 flex items-center justify-center mr-3 shadow-sm">
                  <User className="w-4 h-4" />
               </div>
               <div>
                  <p className="text-sm font-bold text-slate-800">{selectedCustomer.name}</p>
                  <p className="text-[10px] text-slate-500 font-medium">Points: {selectedCustomer.loyaltyPoints}</p>
               </div>
            </div>
            <button onClick={onRemoveCustomer} className="text-slate-400 hover:text-red-500 bg-white p-1 rounded-full border border-slate-200"><X className="w-3 h-3" /></button>
         </div>
      )}

      {/* Cart Items List */}
      <div className="flex-1 overflow-y-auto bg-white p-4 space-y-3 custom-scrollbar">
        {cart.length === 0 ? (
          <div className="h-full flex flex-col items-center justify-center text-slate-300 space-y-4">
            <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center">
               <ShoppingCart className="w-8 h-8 text-slate-200" />
            </div>
            <div className="text-center">
               <p className="font-bold text-slate-400">Cart is empty</p>
               <p className="text-xs mt-1">Scan items to start</p>
            </div>
          </div>
        ) : (
          cart.map((item, index) => {
            const minQty = item.minOrderQuantity || 1;
            const isMin = item.quantity <= minQty;

            return (
              <div key={`${item.id}-${index}-${item.selectedVariantId}`} className="flex gap-3 group bg-white rounded-xl border border-slate-100 p-2 hover:border-slate-300 transition-colors shadow-sm">
                {/* Qty Controls */}
                <div className="flex flex-col items-center justify-center bg-slate-50 rounded-lg w-10 shrink-0 border border-slate-200">
                   <button 
                     onClick={() => updateQuantity(index, 1)} 
