import React, { useState, useEffect } from 'react';
import { Product, ProductVariant } from '../../types';
import { X, Minus, Plus, ShoppingCart, Box, Tag, Check, ArrowRight } from 'lucide-react';

interface VariantSelectorModalProps {
  product: Product;
  isOpen: boolean;
  onClose: () => void;
  onConfirm: (product: Product, quantity: number, variantId?: string) => void;
  formatPrice: (val: number) => string;
}

export const VariantSelectorModal: React.FC<VariantSelectorModalProps> = ({
  product,
  isOpen,
  onClose,
  onConfirm,
  formatPrice
}) => {
  // undefined variantId implies the Base Product (Single Unit)
  const [selectedVariantId, setSelectedVariantId] = useState<string | undefined>(undefined);
  const [quantity, setQuantity] = useState(product.minOrderQuantity || 1);

  // Reset state when product changes
  useEffect(() => {
    setSelectedVariantId(undefined); // Default to base product
    setQuantity(product.minOrderQuantity || 1);
  }, [product]);

  if (!isOpen) return null;

  // Determine current active selection details
  const activeVariant = selectedVariantId ? product.variants?.find(v => v.id === selectedVariantId) : null;
  const currentPrice = activeVariant ? activeVariant.price : product.price;
  const currentUnit = activeVariant ? activeVariant.name : product.unit;
  const currentCode = activeVariant ? activeVariant.code : product.sku;

  const handleConfirm = () => {
    onConfirm(product, quantity, selectedVariantId);
  };

  const adjustQty = (delta: number) => {
    const min = product.minOrderQuantity || 1;
    setQuantity(prev => Math.max(min, prev + delta));
  };

  const renderAttributes = (attributes?: Record<string, string>) => {
    if (!attributes) return null;
    return (
      <div className="flex flex-wrap gap-1 mt-1">
        {Object.entries(attributes).map(([key, val]) => (
          <span key={key} className="text-[10px] bg-slate-100 border border-slate-200 text-slate-600 px-1.5 py-0.5 rounded font-medium">
            {val}
          </span>
        ))}
      </div>
    );
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-end sm:items-center justify-center bg-black/60 backdrop-blur-sm p-0 sm:p-4 animate-fade-in">
      <div className="bg-white w-full sm:max-w-2xl rounded-t-3xl sm:rounded-3xl shadow-2xl flex flex-col overflow-hidden max-h-[85vh] sm:max-h-[90vh]">

        {/* Header */}
        <div className="p-5 md:p-6 border-b border-slate-100 flex justify-between items-start shrink-0 bg-white">
          <div className="flex items-center gap-4">
             <div className="w-14 h-14 md:w-16 md:h-16 rounded-2xl bg-slate-50 border border-slate-100 flex items-center justify-center overflow-hidden shrink-0">
                {product.imageUrl ? (
                   <img src={product.imageUrl} alt={product.name} className="w-full h-full object-cover" />
                ) : (
                   <Box className="w-8 h-8 text-slate-300" />
                )}
             </div>
             <div>
                <h3 className="text-lg md:text-xl font-extrabold text-slate-900 leading-tight line-clamp-2">{product.name}</h3>
                <p className="text-slate-500 font-medium text-xs md:text-sm mt-1">{product.sku} • {product.category}</p>
             </div>
          </div>
          <button onClick={onClose} className="p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-100 rounded-full transition-colors">
            <X className="w-6 h-6" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-5 md:p-6 flex flex-col md:flex-row gap-6">

           {/* Left: Options List */}
           <div className="flex-1 space-y-3">
              <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-2 flex items-center">
                 <Tag className="w-3.5 h-3.5 mr-1.5" /> Select Option
              </label>

              {/* Option 1: Base Product (Single Unit) */}
              <button
                 onClick={() => setSelectedVariantId(undefined)}
                 className={`w-full p-3 rounded-xl border-2 text-left transition-all relative overflow-hidden flex justify-between items-center group ${
                    selectedVariantId === undefined
                       ? 'border-slate-900 bg-slate-50' 
                       : 'border-slate-100 bg-white hover:border-slate-300'
                 }`}
              >
                 <div>
                    <div className="flex items-center gap-2">
                       <span className={`font-bold ${selectedVariantId === undefined ? 'text-slate-900' : 'text-slate-700'}`}>
                          Single Unit ({product.unit})
                       </span>
                       {selectedVariantId === undefined && <Check className="w-4 h-4 text-green-600" />}
                    </div>
                    <p className="text-xs text-slate-400 mt-0.5 font-mono">{product.sku}</p>
                 </div>
                 <div className="text-right">
                    <p className="font-bold text-slate-900">{formatPrice(product.price)}</p>
                    <p className="text-[10px] text-slate-500">Stock: {product.stock}</p>
                 </div>
              </button>

              {/* Variants List */}
              {product.variants?.map((v) => {
                 const isSelected = selectedVariantId === v.id;
                 return (
                    <button
                       key={v.id}
                       onClick={() => setSelectedVariantId(v.id)}
                       className={`w-full p-3 rounded-xl border-2 text-left transition-all relative overflow-hidden flex justify-between items-center group ${
                          isSelected 
                             ? 'border-slate-900 bg-slate-50' 
                             : 'border-slate-100 bg-white hover:border-slate-300'
                       }`}
                    >
                       <div>
                          <div className="flex items-center gap-2">
                             <span className={`font-bold ${isSelected ? 'text-slate-900' : 'text-slate-700'}`}>
                                {v.name}
                             </span>
                             {renderAttributes(v.attributes)}
                             {isSelected && <Check className="w-4 h-4 text-green-600" />}
                          </div>
                          <p className="text-xs text-slate-400 mt-0.5 font-mono">{v.code}</p>
                       </div>
                       <div className="text-right">
                          <p className="font-bold text-slate-900">{formatPrice(v.price)}</p>
                          {v.conversionFactor > 1 && (
                             <p className="text-[10px] text-slate-500 bg-slate-100 px-1.5 rounded inline-block">
                                1 {v.name} = {v.conversionFactor} {product.unit}
                             </p>
                          )}
                       </div>
                    </button>
                 );
              })}
           </div>

           {/* Right: Quantity & Summary */}
           <div className="w-full md:w-64 flex flex-col bg-slate-50 p-5 rounded-2xl h-fit border border-slate-100 shrink-0">
              <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-4">Quantity</label>

              <div className="flex items-center justify-between mb-6">
                 <button 
                    onClick={() => adjustQty(-1)}
                    className="w-12 h-12 rounded-xl bg-white border border-slate-200 text-slate-700 flex items-center justify-center hover:bg-slate-100 transition-colors shadow-sm"
                 >
                    <Minus className="w-5 h-5" />
                 </button>
                 <div className="text-center">
                    <span className="text-4xl font-black text-slate-900">{quantity}</span>
                    <p className="text-xs font-bold text-slate-500 uppercase mt-1">{currentUnit}</p>
                 </div>
                 <button 
                    onClick={() => adjustQty(1)}
                    className="w-12 h-12 rounded-xl bg-white border border-slate-200 text-slate-700 flex items-center justify-center hover:bg-slate-100 transition-colors shadow-sm"
                 >
                    <Plus className="w-5 h-5" />
                 </button>
              </div>

              <div className="flex gap-2 mb-6">
                 {[5, 10, 20].map(val => (
                    <button 
                       key={val}
                       onClick={() => setQuantity(val)}
                       className="flex-1 py-1.5 rounded-lg bg-white border border-slate-200 text-xs font-bold text-slate-600 hover:border-slate-400 transition-all"
                    >
                       {val}
                    </button>
                 ))}
              </div>

              <div className="border-t border-slate-200 pt-4 mt-auto space-y-2">
                 <div className="flex justify-between text-sm text-slate-500">
                    <span>Unit Price</span>
                    <span>{formatPrice(currentPrice)}</span>
                 </div>
                 <div className="flex justify-between items-end">
                    <span className="text-sm font-bold text-slate-800">Total</span>
                    <span className="text-2xl font-black text-slate-900 tracking-tight">{formatPrice(currentPrice * quantity)}</span>
                 </div>
              </div>
           </div>
        </div>

        {/* Footer */}
        <div className="p-4 border-t border-slate-100 bg-white pb-safe">
           <button 
              onClick={handleConfirm}
              className="w-full py-4 bg-slate-900 text-white rounded-xl font-bold text-lg hover:bg-slate-800 shadow-lg shadow-slate-200 transition-all flex items-center justify-center active:scale-[0.98]"
           >
              <ShoppingCart className="w-5 h-5 mr-2" />
              Add {quantity} {currentUnit} to Cart
           </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Customer } from '../../types';
import { X, Banknote, QrCode, CreditCard, FileText, ChevronLeft, CheckCircle } from 'lucide-react';
import { useGlobal } from '../../context/GlobalContext';
import { PaymentMethodList } from './checkout/PaymentMethodList';
import { PaymentNumpad } from './checkout/PaymentNumpad';

interface CheckoutModalProps {
  isOpen: boolean;
  onClose: () => void;
  total: number;
  onProcessPayment: (method: 'cash' | 'card' | 'transfer' | 'qr' | 'credit', receivedAmount: number, change: number) => Promise<void>;
  selectedCustomer: Customer | null;
  isProcessing: boolean;
}

export const CheckoutModal: React.FC<CheckoutModalProps> = ({
  isOpen,
  onClose,
  total,
  onProcessPayment,
  selectedCustomer,
  isProcessing
}) => {
  const { formatPrice } = useGlobal();
  const [paymentMethod, setPaymentMethod] = useState<'cash' | 'card' | 'transfer' | 'qr' | 'credit'>('cash');
  const [receivedAmountStr, setReceivedAmountStr] = useState('');
  const [checkoutStep, setCheckoutStep] = useState<'method' | 'detail'>('method');

  // Keyboard support for immediate confirm
  const receivedAmount = parseFloat(receivedAmountStr) || 0;
  const change = Math.max(0, receivedAmount - total);

  const handleProcess = () => {
    let finalReceived = paymentMethod === 'cash' || paymentMethod === 'credit' ? receivedAmount : total;
    let finalChange = paymentMethod === 'cash' ? change : 0;

    // Auto-fill exact amount for non-cash methods if not set
    if (paymentMethod !== 'cash' && paymentMethod !== 'credit') {
        finalReceived = total;
    }

    onProcessPayment(paymentMethod, finalReceived, finalChange);
  };

  useEffect(() => {
    if (!isOpen) return;
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Enter') {
         e.preventDefault();
         // Check validity before submitting
         if (isProcessing) return;
         if (paymentMethod === 'cash' && receivedAmount < total) return;
         if (paymentMethod === 'credit' && receivedAmount > total) return;
         handleProcess();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, paymentMethod, receivedAmount, total, isProcessing]);

  if (!isOpen) return null;

  const selectPaymentMethod = (method: 'cash' | 'card' | 'transfer' | 'qr' | 'credit') => {
    if (method === 'credit' && !selectedCustomer) {
      alert("Credit payment requires a registered customer.");
      return;
    }
    setPaymentMethod(method);
    setReceivedAmountStr(''); // Reset for clean entry
    setCheckoutStep('detail');
  };

  const handleQuickCash = (amount: number) => {
    setReceivedAmountStr(amount.toString());
  };

  const getConfirmButtonText = () => {
    if (isProcessing) return 'Processing...';

    if (paymentMethod === 'cash') {
      if (receivedAmount < total) return `Enter Amount (Due: ${formatPrice(total)})`;
      if (change > 0) return `Confirm Pay & Return ${formatPrice(change)}`;
      return `Confirm Payment ${formatPrice(total)}`;
    }

    if (paymentMethod === 'credit') {
       const debt = Math.max(0, total - receivedAmount);
       if (receivedAmount > total) return `Amount exceeds total`;
       if (receivedAmount > 0) return `Pay Deposit ${formatPrice(receivedAmount)} (Debt: ${formatPrice(debt)})`;
       return `Confirm Full Credit (Debt: ${formatPrice(total)})`;
    }

    return `Confirm Payment ${formatPrice(total)}`;
  };

  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center bg-black/60 backdrop-blur-sm p-0 sm:p-4 animate-fade-in">
      <div className="bg-white w-full h-[100vh] sm:h-[650px] sm:max-w-5xl rounded-t-xl sm:rounded-2xl shadow-2xl flex flex-col sm:flex-row overflow-hidden">

        {/* Method Selection Sidebar (Hidden on Mobile if Detail step active) */}
        <PaymentMethodList 
            paymentMethod={paymentMethod}
            onSelect={selectPaymentMethod}
            onClose={onClose}
            total={total}
            selectedCustomer={selectedCustomer}
            className={`${checkoutStep === 'detail' ? 'hidden sm:flex' : 'flex'} h-full sm:h-auto`}
        />

        {/* Detail / Numpad Area (Hidden on Mobile if Method step active) */}
        <div className={`flex-1 bg-white flex flex-col ${checkoutStep === 'method' ? 'hidden sm:flex' : 'flex'} h-full`}>
           <div className="p-4 border-b border-slate-100 flex items-center justify-between">
              <button onClick={() => setCheckoutStep('method')} className="sm:hidden flex items-center text-slate-500 font-bold hover:text-slate-800 bg-slate-100 px-3 py-1.5 rounded-lg">
                 <ChevronLeft className="w-5 h-5 mr-1" /> Back
              </button>
              <div className="sm:hidden font-bold text-slate-800">Payment</div>
              <button onClick={onClose} className="p-2 hover:bg-slate-100 rounded-full text-slate-400">
                 <X className="w-6 h-6" />
              </button>
           </div>

           <div className="flex-1 p-4 sm:p-8 overflow-y-auto">
              <div className="text-center mb-6">
                 <h3 className="text-xl font-bold text-slate-800 flex items-center justify-center gap-2">
                    {paymentMethod === 'cash' ? <Banknote className="text-blue-600"/> : paymentMethod === 'qr' ? <QrCode className="text-blue-600"/> : paymentMethod === 'credit' ? <FileText className="text-orange-500"/> : <CreditCard className="text-blue-600"/>}
                    {paymentMethod === 'cash' ? 'Cash Payment' : paymentMethod === 'qr' ? 'Scan to Pay' : paymentMethod === 'credit' ? 'Credit / Debt Sale' : 'Digital Payment'}
                 </h3>
              </div>

              {/* Show Numpad for Cash OR Credit */}
              {paymentMethod === 'cash' || paymentMethod === 'credit' ? (
                 <PaymentNumpad 
                    receivedAmountStr={receivedAmountStr}
                    setReceivedAmountStr={setReceivedAmountStr}
                    total={total}
                    change={paymentMethod === 'cash' ? change : 0} 
                    handleQuickCash={handleQuickCash}
                 />
              ) : paymentMethod === 'qr' ? (
                 <div className="flex-1 flex flex-col items-center justify-center">
                    <div className="bg-white p-6 rounded-3xl border-2 border-slate-100 shadow-lg mb-6">
                       <img src={`https://api.qrserver.com/v1/create-qr-code/?size=250x250&data=Payment_OnePay_${total}`} className="w-56 h-56 md:w-64 md:h-64 object-contain" alt="QR" />
                    </div>
                    <p className="text-lg font-bold text-slate-700">Scan to pay {formatPrice(total)}</p>
                 </div>
              ) : (
                 <div className="flex-1 flex flex-col items-center justify-center text-center">
                    <div className="w-32 h-32 bg-slate-100 rounded-full flex items-center justify-center mb-6 animate-pulse">
                       <CreditCard className="w-16 h-16 text-blue-500" />
                    </div>
                    <h4 className="text-xl font-bold text-slate-800 mb-2">
                       Waiting for Terminal
                    </h4>
                    <p className="text-slate-500">Total amount: <strong>{formatPrice(total)}</strong></p>
                 </div>
              )}
           </div>
           <div className="p-4 border-t border-slate-100 bg-white pb-safe">
              <button 
                 onClick={handleProcess}
                 disabled={isProcessing || (paymentMethod === 'cash' && receivedAmount < total) || (paymentMethod === 'credit' && receivedAmount > total)}
                 className={`w-full py-4 rounded-xl font-bold text-xl text-white shadow-lg flex items-center justify-center transition-all active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed ${paymentMethod === 'credit' ? 'bg-orange-600' : 'bg-slate-900 hover:bg-slate-800'}`}
              >
                 {isProcessing ? 'Processing...' : (
                    <>
                       <CheckCircle className="w-6 h-6 mr-2" /> 
                       {getConfirmButtonText()}
                    </>
                 )}
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Product, Category } from '../../types';
import { Search, Box, ScanBarcode, LayoutGrid, List, Plus, Layers, Package } from 'lucide-react';
import { useGlobal } from '../../context/GlobalContext';

interface ProductGridProps {
  products: (Product & { displayPrice?: number })[]; 
  onScanClick: () => void;
  searchTerm: string;
  setSearchTerm: (term: string) => void;
  onScan: (code: string) => void; 
  onProductSelect: (product: Product) => void;
}

export const ProductGrid: React.FC<ProductGridProps> = ({ 
  products, 
  onScanClick,
  searchTerm,
  setSearchTerm,
  onScan,
  onProductSelect
}) => {
  const { formatPrice, t } = useGlobal();
  const [selectedCategory, setSelectedCategory] = useState<string>('all');
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const searchLower = searchTerm.toLowerCase();
      const matchesMain = 
        p.name.toLowerCase().includes(searchLower) ||
        p.sku?.toLowerCase().includes(searchLower) ||
        p.barcode?.includes(searchLower);

      // Search inside variants too
      const matchesVariant = p.variants && p.variants.some(v => 
        v.code.toLowerCase().includes(searchLower) || 
        v.barcode.includes(searchLower) ||
        v.name.toLowerCase().includes(searchLower)
      );

      const matchesCategory = selectedCategory === 'all' || p.category === selectedCategory;
      return (matchesMain || matchesVariant) && matchesCategory;
    });
  }, [products, searchTerm, selectedCategory]);

  const handleFormSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchTerm) return;
    onScan(searchTerm);
  };

  return (
    <div className="flex flex-col h-full bg-white">
      {/* Search & Filter Bar */}
      <div className="px-4 md:px-6 pb-4 pt-2 space-y-3 bg-white z-10">
        <div className="flex flex-col md:flex-row gap-3">
          <form onSubmit={handleFormSubmit} className="relative flex-1 flex gap-2">
            <div className="relative flex-1 group">
               <Search className="absolute left-4 top-1/2 transform -translate-y-1/2 text-slate-400 w-5 h-5 group-focus-within:text-slate-800 transition-colors" />
               <input
                 id="pos-search-input"
                 type="text"
                 placeholder={t('pos.scanPlaceholder')}
                 className="w-full pl-12 pr-4 py-3 border-none rounded-xl bg-slate-100 text-slate-800 font-medium placeholder:text-slate-400 focus:outline-none focus:ring-2 focus:ring-slate-200 transition-all text-sm md:text-base"
                 value={searchTerm}
                 onChange={(e) => setSearchTerm(e.target.value)}
                 autoFocus
               />
            </div>
            <button type="button" onClick={onScanClick} className="bg-slate-100 text-slate-600 px-3 md:px-4 rounded-xl hover:bg-slate-200 transition-colors flex items-center justify-center">
               <ScanBarcode className="w-6 h-6" />
            </button>
          </form>

          <div className="flex bg-slate-100 p-1 rounded-xl shrink-0 items-center self-end md:self-auto h-[48px] md:h-[52px]">
             <button onClick={() => setViewMode('list')} className={`p-2 rounded-lg transition-all flex-1 md:flex-none flex justify-center ${viewMode === 'list' ? 'bg-white shadow-sm text-slate-900' : 'text-slate-400 hover:text-slate-600'}`}>
                <List className="w-5 h-5" />
             </button>
             <button onClick={() => setViewMode('grid')} className={`p-2 rounded-lg transition-all flex-1 md:flex-none flex justify-center ${viewMode === 'grid' ? 'bg-white shadow-sm text-slate-900' : 'text-slate-400 hover:text-slate-600'}`}>
                <LayoutGrid className="w-5 h-5" />
             </button>
          </div>
        </div>

        <div className="flex gap-2 overflow-x-auto pb-2 -mx-4 px-4 md:mx-0 md:px-0 scrollbar-hide">
          <button onClick={() => setSelectedCategory('all')} className={`px-4 py-2 rounded-full text-xs md:text-sm font-bold whitespace-nowrap transition-all ${selectedCategory === 'all' ? 'bg-slate-900 text-white shadow-md' : 'bg-white text-slate-500 hover:bg-slate-50 border border-slate-100'}`}>
            {t('pos.allItems')}
          </button>
          {Object.values(Category).map(cat => (
            <button key={cat} onClick={() => setSelectedCategory(cat)} className={`px-4 py-2 rounded-full text-xs md:text-sm font-bold whitespace-nowrap transition-all ${selectedCategory === cat ? 'bg-slate-900 text-white shadow-md' : 'bg-white text-slate-500 hover:bg-slate-50 border border-slate-100'}`}>
              {cat}
            </button>
          ))}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto px-4 md:px-6 pb-24 md:pb-6 custom-scrollbar bg-white">
        {filteredProducts.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-64 text-slate-400 mt-10">
            <div className="bg-slate-50 p-6 rounded-full mb-4">
               <Box className="w-12 h-12 text-slate-300" />
            </div>
            <p className="font-medium">No products found.</p>
          </div>
        ) : viewMode === 'grid' ? (
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-3 xl:grid-cols-4 gap-3 md:gap-4">
            {filteredProducts.map((product) => {
               // Logic to detect if product has options (Variants OR Units)
               const hasVariants = product.variants && product.variants.length > 0;
               const stock = product.stock;
               const isLowStock = stock <= (product.minStock || 0);

               // Price Logic: If has variants, show Lowest Price
               let displayPrice = product.displayPrice !== undefined ? product.displayPrice : product.price;
               if (hasVariants && product.displayPrice === undefined) {
                  const prices = product.variants!.map(v => v.price);
                  displayPrice = Math.min(...prices, product.price);
               }

               // Check if pricing is overridden by Customer Level (Tier Price)
               const isTierPrice = product.displayPrice !== undefined && product.displayPrice !== product.price;

               return (
                <div 
                  key={product.id} 
                  onClick={() => onProductSelect(product)} 
                  className="bg-white rounded-xl md:rounded-2xl border border-slate-100 overflow-hidden hover:shadow-xl hover:border-slate-200 transition-all cursor-pointer flex flex-col group relative h-full shadow-sm"
                >
                  <div className="h-32 md:h-40 bg-slate-50 relative flex items-center justify-center overflow-hidden">
                    {product.imageUrl ? (
                      <img src={product.imageUrl} alt={product.name} className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105" />
                    ) : (
                      <Box className="w-10 h-10 md:w-12 md:h-12 text-slate-200" />
                    )}

                    <span className={`absolute top-2 right-2 px-1.5 py-0.5 rounded text-[9px] md:text-[10px] font-bold shadow-sm backdrop-blur-md ${isLowStock ? 'bg-red-500 text-white' : 'bg-white/90 text-slate-800'}`}>
                      {stock} {product.unit}
                    </span>
                  </div>

                  <div className="p-3 md:p-4 flex-1 flex flex-col">
                    <div className="mb-2">
                        <h3 className="font-bold text-slate-900 text-xs md:text-sm leading-tight line-clamp-2 min-h-[2.5em]">
                           {product.name}
                        </h3>
                        <p className="text-[10px] text-slate-400 mt-1 font-mono hidden md:block">{product.sku}</p>
                    </div>

                    <div className="mt-auto pt-2">
                      <div className="flex items-center justify-between">
                         <div className={`px-2 md:px-3 py-1 md:py-1.5 rounded-full text-xs md:text-sm font-bold shadow-sm flex items-center ${isTierPrice ? 'bg-indigo-50 text-indigo-700 border border-indigo-100' : hasVariants ? 'bg-slate-100 text-slate-700' : 'bg-slate-900 text-white'}`}>
                            {hasVariants && !isTierPrice && <span className="text-[9px] mr-1 text-slate-500 font-normal">From</span>}
                            {formatPrice(displayPrice)}
                         </div>
                         {hasVariants ? (
                            <Layers className="w-4 h-4 md:w-5 md:h-5 text-blue-500 group-hover:text-blue-700 transition-colors" />
                         ) : (
                            <Plus className="w-4 h-4 md:w-5 md:h-5 text-slate-300 group-hover:text-slate-900 transition-colors" />
                         )}
                      </div>
                      {hasVariants && <p className="text-[10px] text-blue-600 mt-1 text-right font-medium">{product.variants!.length} Options</p>}
                    </div>
                  </div>
                </div>
               );
            })}
          </div>
        ) : (
          <div className="bg-white rounded-2xl border border-slate-200 overflow-hidden">
             {/* List view implementation... (similar logic) */}
             <table className="w-full text-left border-collapse">
                <tbody className="divide-y divide-slate-100 text-sm">
                   {filteredProducts.map(product => {
                      const hasVariants = product.variants && product.variants.length > 0;
                      let displayPrice = product.displayPrice !== undefined ? product.displayPrice : product.price;
                      if (hasVariants && product.displayPrice === undefined) {
                          const prices = product.variants!.map(v => v.price);
                          displayPrice = Math.min(...prices, product.price);
                      }

                      return (
                         <tr key={product.id} className="hover:bg-slate-50 transition-colors cursor-pointer" onClick={() => onProductSelect(product)}>
                            <td className="p-3 pl-4 flex items-center">
                               <div className="w-10 h-10 rounded-lg bg-slate-100 mr-3 flex items-center justify-center">
                                  {product.imageUrl ? <img src={product.imageUrl} className="w-full h-full object-cover rounded-lg"/> : <Box className="w-5 h-5 text-slate-300"/>}
                               </div>
                               <div>
                                  <div className="font-bold text-slate-800">{product.name}</div>
                                  <div className="text-[10px] text-slate-400">{product.sku}</div>
                               </div>
                            </td>
                            <td className="p-3 text-right">
                               <div className="font-bold text-slate-900">
                                  {hasVariants && <span className="text-[10px] font-normal text-slate-500 mr-1">From</span>}
                                  {formatPrice(displayPrice)}
                               </div>
                               {hasVariants && <span className="text-[10px] text-blue-600 bg-blue-50 px-1 rounded">Has Options</span>}
                            </td>
                         </tr>
                      );
                   })}
                </tbody>
             </table>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Product, ProductVariant } from '../../types';
import { X, Minus, Plus, ShoppingCart, Box, Tag, Check, Package, Layers } from 'lucide-react';

interface VariantSelectorModalProps {
  product: Product;
  isOpen: boolean;
  onClose: () => void;
  onConfirm: (product: Product, quantity: number, variantId?: string) => void;
  formatPrice: (val: number) => string;
}

export const VariantSelectorModal: React.FC<VariantSelectorModalProps> = ({
  product,
  isOpen,
  onClose,
  onConfirm,
  formatPrice
}) => {
  // undefined variantId implies the Base Product (Single Unit)
  const [selectedVariantId, setSelectedVariantId] = useState<string | undefined>(undefined);
  const [quantity, setQuantity] = useState(product.minOrderQuantity || 1);

  // Reset state when product changes
  useEffect(() => {
    setSelectedVariantId(undefined); // Default to base product
    setQuantity(product.minOrderQuantity || 1);
  }, [product]);

  if (!isOpen) return null;

  // Determine current active selection details
  const activeVariant = selectedVariantId ? product.variants?.find(v => v.id === selectedVariantId) : null;

  // Use tier price if available (from parent logic passing), otherwise regular price
  // Note: product.price might already be the tier price if passed from POS
  const currentPrice = activeVariant ? activeVariant.price : product.price;
  const currentUnit = activeVariant ? activeVariant.name : product.unit;
  const currentCode = activeVariant ? activeVariant.code : product.sku;

  const handleConfirm = () => {
    onConfirm(product, quantity, selectedVariantId);
  };

  const adjustQty = (delta: number) => {
    const min = product.minOrderQuantity || 1;
    setQuantity(prev => Math.max(min, prev + delta));
  };

  const renderAttributes = (attributes?: Record<string, string>) => {
    if (!attributes) return null;
    return (
      <div className="flex flex-wrap gap-1 mt-1">
        {Object.entries(attributes).map(([key, val]) => (
          <span key={key} className="text-[10px] bg-indigo-50 text-indigo-700 px-1.5 py-0.5 rounded border border-indigo-100 font-medium">
            {val}
          </span>
        ))}
      </div>
    );
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-end sm:items-center justify-center bg-black/60 backdrop-blur-sm p-0 sm:p-4 animate-fade-in">
      <div className="bg-white w-full sm:max-w-2xl rounded-t-3xl sm:rounded-3xl shadow-2xl flex flex-col overflow-hidden max-h-[85vh] sm:max-h-[90vh]">

        {/* Header */}
        <div className="p-5 md:p-6 border-b border-slate-100 flex justify-between items-start shrink-0 bg-white">
          <div className="flex items-center gap-4">
             <div className="w-14 h-14 md:w-16 md:h-16 rounded-2xl bg-slate-50 border border-slate-100 flex items-center justify-center overflow-hidden shrink-0">
                {product.imageUrl ? (
                   <img src={product.imageUrl} alt={product.name} className="w-full h-full object-cover" />
                ) : (
                   <Box className="w-8 h-8 text-slate-300" />
                )}
             </div>
             <div>
                <h3 className="text-lg md:text-xl font-extrabold text-slate-900 leading-tight line-clamp-2">{product.name}</h3>
                <p className="text-slate-500 font-medium text-xs md:text-sm mt-1">{product.sku} • {product.category}</p>
             </div>
          </div>
          <button onClick={onClose} className="p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-100 rounded-full transition-colors">
            <X className="w-6 h-6" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-5 md:p-6 flex flex-col md:flex-row gap-6">

           {/* Left: Options List */}
           <div className="flex-1 space-y-4">

              {/* SECTION 1: BASE UNIT */}
              <div>
                 <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-2 flex items-center">
                    <Box className="w-3.5 h-3.5 mr-1.5" /> Base Unit
                 </label>
                 <button
                    onClick={() => setSelectedVariantId(undefined)}
                    className={`w-full p-3 rounded-xl border-2 text-left transition-all relative overflow-hidden flex justify-between items-center group ${
                       selectedVariantId === undefined
                          ? 'border-slate-900 bg-slate-50' 
                          : 'border-slate-100 bg-white hover:border-slate-300'
                    }`}
                 >
                    <div>
                       <div className="flex items-center gap-2">
                          <span className={`font-bold ${selectedVariantId === undefined ? 'text-slate-900' : 'text-slate-700'}`}>
                             1 {product.unit} (Single)
                          </span>
                          {selectedVariantId === undefined && <Check className="w-4 h-4 text-green-600" />}
                       </div>
                       <p className="text-xs text-slate-400 mt-0.5 font-mono">{product.sku}</p>
                    </div>
                    <div className="text-right">
                       <p className="font-bold text-slate-900">{formatPrice(product.price)}</p>
                       <p className="text-[10px] text-slate-500">Stock: {product.stock}</p>
                    </div>
                 </button>
              </div>

              {/* SECTION 2: VARIANTS & PACKS */}
              {product.variants && product.variants.length > 0 && (
                 <div>
                    <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-2 flex items-center mt-4">
                       <Layers className="w-3.5 h-3.5 mr-1.5" /> Options & Packs
                    </label>
                    <div className="space-y-2">
                       {product.variants.map((v) => {
                          const isSelected = selectedVariantId === v.id;
                          const isPack = v.conversionFactor && v.conversionFactor > 1;

                          return (
                             <button
                                key={v.id}
                                onClick={() => setSelectedVariantId(v.id)}
                                className={`w-full p-3 rounded-xl border-2 text-left transition-all relative overflow-hidden flex justify-between items-center group ${
                                   isSelected 
                                      ? 'border-slate-900 bg-slate-50' 
                                      : 'border-slate-100 bg-white hover:border-slate-300'
                                }`}
                             >
                                <div>
                                   <div className="flex items-center gap-2">
                                      {isPack ? <Package className="w-4 h-4 text-orange-500" /> : <Tag className="w-4 h-4 text-blue-500" />}
                                      <span className={`font-bold ${isSelected ? 'text-slate-900' : 'text-slate-700'}`}>
                                         {v.name}
                                      </span>
                                      {isSelected && <Check className="w-4 h-4 text-green-600" />}
                                   </div>

                                   {/* Variant Attributes (Color, Size) */}
                                   {renderAttributes(v.attributes)}

                                   <p className="text-xs text-slate-400 mt-0.5 font-mono">{v.code}</p>
                                </div>
                                <div className="text-right">
                                   <p className="font-bold text-slate-900">{formatPrice(v.price)}</p>
                                   {isPack && (
                                      <p className="text-[10px] text-slate-500 bg-orange-50 text-orange-700 px-1.5 py-0.5 rounded inline-block font-bold mt-1">
                                         Contains {v.conversionFactor} {product.unit}
                                      </p>
                                   )}
                                </div>
                             </button>
                          );
                       })}
                    </div>
                 </div>
              )}
           </div>

           {/* Right: Quantity & Summary */}
           <div className="w-full md:w-64 flex flex-col bg-slate-50 p-5 rounded-2xl h-fit border border-slate-100 shrink-0">
              <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-4">Quantity</label>

              <div className="flex items-center justify-between mb-6">
                 <button 
                    onClick={() => adjustQty(-1)}
                    className="w-12 h-12 rounded-xl bg-white border border-slate-200 text-slate-700 flex items-center justify-center hover:bg-slate-100 transition-colors shadow-sm"
                 >
                    <Minus className="w-5 h-5" />
                 </button>
                 <div className="text-center">
                    <span className="text-4xl font-black text-slate-900">{quantity}</span>
                    <p className="text-xs font-bold text-slate-500 uppercase mt-1">{currentUnit}</p>
                 </div>
                 <button 
                    onClick={() => adjustQty(1)}
                    className="w-12 h-12 rounded-xl bg-white border border-slate-200 text-slate-700 flex items-center justify-center hover:bg-slate-100 transition-colors shadow-sm"
                 >
                    <Plus className="w-5 h-5" />
                 </button>
              </div>

              <div className="flex gap-2 mb-6">
                 {[5, 10, 20].map(val => (
                    <button 
                       key={val}
                       onClick={() => setQuantity(val)}
                       className="flex-1 py-1.5 rounded-lg bg-white border border-slate-200 text-xs font-bold text-slate-600 hover:border-slate-400 transition-all"
                    >
                       {val}
                    </button>
                 ))}
              </div>

              <div className="border-t border-slate-200 pt-4 mt-auto space-y-2">
                 <div className="flex justify-between text-sm text-slate-500">
                    <span>Unit Price</span>
                    <span>{formatPrice(currentPrice)}</span>
                 </div>
                 <div className="flex justify-between items-end">
                    <span className="text-sm font-bold text-slate-800">Total</span>
                    <span className="text-2xl font-black text-slate-900 tracking-tight">{formatPrice(currentPrice * quantity)}</span>
                 </div>
              </div>
           </div>
        </div>

        {/* Footer */}
        <div className="p-4 border-t border-slate-100 bg-white pb-safe">
           <button 
              onClick={handleConfirm}
              className="w-full py-4 bg-slate-900 text-white rounded-xl font-bold text-lg hover:bg-slate-800 shadow-lg shadow-slate-200 transition-all flex items-center justify-center active:scale-[0.98]"
           >
              <ShoppingCart className="w-5 h-5 mr-2" />
              Add {quantity} {currentUnit} to Cart
           </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { ProductVariant, UnitDefinition, VariantAttribute } from '../../../types';
import { Plus, Trash2, Tag, Barcode, CheckSquare, Square, ArrowRightLeft } from 'lucide-react';

interface VariantsTabProps {
  variants: Partial<ProductVariant>[];
  setVariants: React.Dispatch<React.SetStateAction<Partial<ProductVariant>[]>>;
  handleAddVariant: () => void;
  handleVariantChange: (index: number, field: keyof ProductVariant | 'attributes', value: any, attributeName?: string) => void;
  unitsByCategory: Record<string, UnitDefinition[]>;
  availableAttributes: VariantAttribute[];
}

export const VariantsTab: React.FC<VariantsTabProps> = ({
  variants, setVariants, handleAddVariant, handleVariantChange, unitsByCategory, availableAttributes
}) => {
  // Local state to track which attributes are "enabled" for this product form
  const [activeAttributeIds, setActiveAttributeIds] = useState<string[]>([]);

  // Initialize active attributes based on existing variant data
  useEffect(() => {
    if (variants.length > 0) {
      const usedAttrs = new Set<string>();
      variants.forEach(v => {
        if (v.attributes) {
          Object.keys(v.attributes).forEach(attrName => {
             const attrDef = availableAttributes.find(a => a.name === attrName);
             if (attrDef) usedAttrs.add(attrDef.id);
          });
        }
      });
      if (usedAttrs.size > 0) {
         setActiveAttributeIds(Array.from(usedAttrs));
      }
    }
  }, []); // Run once on mount

  const toggleAttribute = (attrId: string) => {
    if (activeAttributeIds.includes(attrId)) {
      setActiveAttributeIds(prev => prev.filter(id => id !== attrId));
    } else {
      setActiveAttributeIds(prev => [...prev, attrId]);
    }
  };

  const activeAttributes = availableAttributes.filter(a => activeAttributeIds.includes(a.id));

  return (
    <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm animate-fade-in">
       {/* Attribute Selector Section */}
       <div className="mb-6 p-4 bg-slate-50 rounded-xl border border-slate-100">
          <h5 className="font-bold text-slate-700 text-sm mb-3">Active Variant Attributes</h5>
          <div className="flex flex-wrap gap-3">
             {availableAttributes.length === 0 ? (
                <p className="text-xs text-slate-400 italic">No global attributes defined. Go to Unit Mgmt to add attributes.</p>
             ) : (
                availableAttributes.map(attr => {
                   const isActive = activeAttributeIds.includes(attr.id);
                   return (
                      <button
                         key={attr.id}
                         type="button"
                         onClick={() => toggleAttribute(attr.id)}
                         className={`flex items-center px-3 py-1.5 rounded-lg text-sm border transition-all ${
                            isActive 
                               ? 'bg-indigo-50 border-indigo-200 text-indigo-700 font-bold' 
                               : 'bg-white border-slate-200 text-slate-600 hover:border-slate-300'
                         }`}
                      >
                         {isActive ? <CheckSquare className="w-4 h-4 mr-2" /> : <Square className="w-4 h-4 mr-2 text-slate-400" />}
                         {attr.name}
                      </button>
                   );
                })
             )}
          </div>
       </div>

       <div className="flex justify-between items-center mb-6">
         <div>
            <h4 className="font-bold text-slate-800 flex items-center">
               <Tag className="w-5 h-5 mr-2 text-slate-500" />
               Product Variants
            </h4>
            <p className="text-xs text-slate-500 mt-1">Define different units or versions with specific pricing.</p>
         </div>
         <button 
            type="button" 
            onClick={handleAddVariant} 
            className="text-sm flex items-center text-white font-bold bg-slate-900 px-4 py-2 rounded-lg hover:bg-slate-800 transition-colors shadow-sm"
         >
            <Plus className="w-4 h-4 mr-1.5" /> Add Variant
         </button>
       </div>

       <div className="space-y-4">
          {variants.map((v, i) => (
             <div key={i} className="bg-slate-50 p-5 rounded-xl border border-slate-200 relative group transition-all hover:shadow-md hover:border-slate-300">
                <button 
                   type="button" 
                   onClick={() => setVariants(prev => prev.filter((_, idx) => idx !== i))} 
                   className="absolute top-3 right-3 p-1.5 text-slate-400 hover:text-red-500 bg-white rounded-lg border border-slate-200 shadow-sm transition-colors z-10"
                   title="Remove Variant"
                >
                   <Trash2 className="w-4 h-4" />
                </button>

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4">
                   {/* Unit Selection */}
                   <div className="lg:col-span-1">
                      <label className="block text-xs font-bold text-slate-500 mb-1.5 uppercase">Unit / Type</label>
                      <select 
                         value={v.name} 
                         onChange={e => handleVariantChange(i, 'name', e.target.value)} 
                         className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm bg-white focus:ring-2 focus:ring-slate-400 outline-none"
                      >
                         <option value="">Select Unit</option>
                         {Object.entries(unitsByCategory).map(([c, uList]) => (
                           <optgroup key={c} label={c}>
                             {(uList as UnitDefinition[]).map(u => <option key={u.id} value={u.symbol}>{u.name} ({u.symbol})</option>)}
                           </optgroup>
                         ))}
                      </select>
                   </div>

                   {/* Conversion Factor */}
                   <div className="lg:col-span-1">
                      <label className="block text-xs font-bold text-slate-500 mb-1.5 uppercase">Qty per Unit</label>
                      <div className="relative">
                         <input 
                            type="number" 
                            min="0"
                            step="0.01"
                            value={v.conversionFactor} 
                            onChange={e => handleVariantChange(i, 'conversionFactor', e.target.value)} 
                            className="w-full pl-3 pr-8 py-2 border border-slate-300 rounded-lg text-sm font-bold text-center focus:ring-2 focus:ring-indigo-400 outline-none" 
                         />
                         <div className="absolute right-3 top-2.5 text-slate-400 pointer-events-none">
                            <ArrowRightLeft className="w-4 h-4" />
                         </div>
                      </div>
                   </div>

                   {/* Dynamic Attributes */}
                   {activeAttributes.map(attr => (
                      <div key={attr.id} className="lg:col-span-1">
                         <label className="block text-xs font-bold text-slate-500 mb-1.5 uppercase">{attr.name}</label>
                         <select
                            value={v.attributes?.[attr.name] || ''}
                            onChange={e => handleVariantChange(i, 'attributes', e.target.value, attr.name)}
                            className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm bg-white focus:ring-2 focus:ring-indigo-400 outline-none"
                         >
                            <option value="">Any</option>
                            {attr.values.map(val => (
                               <option key={val} value={val}>{val}</option>
                            ))}
                         </select>
                      </div>
                   ))}

                   {/* SKU / Code */}
                   <div className="lg:col-span-1">
                      <label className="block text-xs font-bold text-slate-500 mb-1.5 uppercase">SKU Code</label>
                      <div className="relative">
                         <Barcode className="absolute left-3 top-2.5 w-4 h-4 text-slate-400" />
                         <input 
                            type="text" 
                            value={v.code} 
                            onChange={e => handleVariantChange(i, 'code', e.target.value)} 
                            placeholder="SKU-001" 
                            className="w-full pl-9 pr-3 py-2 border border-slate-300 rounded-lg text-sm font-mono focus:ring-2 focus:ring-slate-400 outline-none" 
                         />
                      </div>
                   </div>

                   {/* Selling Price */}
                   <div className="lg:col-span-1">
                      <label className="block text-xs font-bold text-slate-500 mb-1.5 uppercase">Selling Price</label>
                      <input 
                         type="number" 
                         min="0" 
                         step="0.01"
                         value={v.price} 
                         onChange={e => handleVariantChange(i, 'price', e.target.value)} 
                         placeholder="0.00" 
                         className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm font-bold text-slate-900 bg-white focus:ring-2 focus:ring-blue-500 outline-none" 
                      />
                   </div>
                </div>

                {/* Conversion Hint */}
                {v.name && (
                   <div className="mt-3 flex items-center text-[10px] text-slate-500 font-medium">
                      <span className="bg-slate-100 px-2 py-1 rounded border border-slate-200">
                         1 <strong>{v.name}</strong> contains <strong>{v.conversionFactor}</strong> base units
                      </span>
                   </div>
                )}
             </div>
          ))}

          {variants.length === 0 && (
             <div className="text-center py-12 text-slate-400 border-2 border-dashed border-slate-200 rounded-xl bg-slate-50">
                <Tag className="w-12 h-12 mx-auto mb-3 opacity-20" />
                <p className="font-medium text-sm">No variants added yet.</p>
                <p className="text-xs mt-1">Add variants for different units (e.g. Box, Pallet) with custom pricing.</p>
             </div>
          )}
       </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Product, ProductVariant, UnitDefinition, CategoryItem, VariantAttribute, CustomerLevel } from '../../types';
import { Box, Scale, DollarSign, Layers, X, Check } from 'lucide-react';
import { GeneralTab } from './product-form/GeneralTab';
import { PhysicalTab } from './product-form/PhysicalTab';
import { PricingTab } from './product-form/PricingTab';
import { VariantsTab } from './product-form/VariantsTab';

interface ProductFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (product: Product) => void;
  initialData?: Product;
  categories: CategoryItem[];
  units: UnitDefinition[];
  attributes: VariantAttribute[];
  currencySymbol: string;
  customerLevels: CustomerLevel[];
}

const MAX_FILE_SIZE_MB = 5;

export const ProductFormModal: React.FC<ProductFormModalProps> = ({
  isOpen, onClose, onSubmit, initialData, categories, units, attributes, currencySymbol, customerLevels
}) => {
  const [activeTab, setActiveTab] = useState<'general' | 'physical' | 'pricing' | 'variants'>('general');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<Product>>({
    name: '', sku: '', barcode: '', category: '', price: 0, costPrice: 0,
    stock: 0, minStock: 20, unit: '', physical: { weight: 0, width: 0, height: 0, depth: 0 },
    branchPrices: [], imageUrl: '', tierPrices: {}
  });

  const [variants, setVariants] = useState<Partial<ProductVariant>[]>([]);

  useEffect(() => {
    if (initialData) {
      setFormData({ ...initialData, tierPrices: initialData.tierPrices || {} });
      setVariants(initialData.variants ? initialData.variants.map(v => ({...v})) : []);
    } else {
      setFormData({
        name: '', sku: '', barcode: '', category: categories[0]?.id || '', price: 0, costPrice: 0,
        stock: 0, minStock: 20, unit: units[0]?.symbol || 'pc',
        physical: { weight: 0, width: 0, height: 0, depth: 0 }, branchPrices: [], imageUrl: '', tierPrices: {}
      });
      setVariants([]);
    }
    setActiveTab('general');
  }, [initialData, isOpen, categories, units]);

  if (!isOpen) return null;

  const categoryOptions: { id: string; name: string; level: number }[] = [];
  const buildCatOptions = (parentId: string | null, level: number) => {
    categories.filter(c => c.parentId === parentId).forEach(c => {
      categoryOptions.push({ id: c.id, name: c.name, level });
      buildCatOptions(c.id, level + 1);
    });
  };
  buildCatOptions(null, 0);

  const unitsByCategory = units.reduce((acc, unit) => {
    if (!acc[unit.category]) acc[unit.category] = [];
    acc[unit.category].push(unit);
    return acc;
  }, {} as Record<string, UnitDefinition[]>);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    const isNum = ['price', 'costPrice', 'stock', 'minStock'].includes(name);

    setFormData(prev => ({ ...prev, [name]: isNum ? (parseFloat(value) || 0) : value }));

    if (name === 'price') {
      const newMainPrice = parseFloat(value) || 0;
      // Recalculate variant prices based on their factor
      setVariants(prev => prev.map(v => {
         const factor = v.conversionFactor || 1;
         return { ...v, price: factor !== 0 ? newMainPrice * factor : 0 };
      }));
    }
  };

  const handlePhysicalChange = (field: string, value: string) => {
    setFormData(prev => ({
      ...prev, physical: { ...prev.physical, [field]: parseFloat(value) || 0 }
    }));
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.size > MAX_FILE_SIZE_MB * 1024 * 1024) {
      alert(`File size exceeds ${MAX_FILE_SIZE_MB}MB.`);
      return;
    }
    const reader = new FileReader();
    reader.onloadend = () => setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
    reader.readAsDataURL(file);
  };

  // Variant Logic
  const handleAddVariant = () => {
    const suffix = (variants.length + 1).toString().padStart(3, '0');
    setVariants(prev => [...prev, {
      id: `v-${Date.now()}`,
      name: '', code: `${formData.sku || 'SKU'}-${suffix}`, barcode: formData.barcode ? `${formData.barcode}${suffix}` : '',
      conversionFactor: 1, price: formData.price, costPrice: formData.costPrice,
      attributes: {}, tierPrices: {}
    }]);
  };

  const handleVariantChange = (index: number, field: keyof ProductVariant | 'attributes', value: any, attributeName?: string) => {
    setVariants(prev => {
      const newVars = [...prev];

      if (field === 'attributes' && attributeName) {
         const currentAttrs = newVars[index].attributes || {};
         newVars[index] = { 
            ...newVars[index], 
            attributes: { ...currentAttrs, [attributeName]: value } 
         };
      } else {
         newVars[index] = { ...newVars[index], [field]: field === 'name' ? value : (['price', 'costPrice', 'conversionFactor'].includes(field as string) ? parseFloat(value) || 0 : value) };

         // Auto-calculate conversion factor and price when Unit changes
         if (field === 'name') {
            const main = units.find(u => u.symbol === formData.unit);
            const sub = units.find(u => u.symbol === value);
            if (main && sub && main.category === sub.category) {
               // Calculate ratio: e.g. Base=Piece(1), Variant=Box(12). Ratio = 12/1 = 12.
               // e.g. Base=Meter(100cm), Variant=CM(1cm). Ratio = 1/100 = 0.01.
               const factor = sub.baseFactor / main.baseFactor;
               newVars[index].conversionFactor = factor;

               // Suggest price based on factor (e.g. 1 Box = 12 * Piece Price)
               newVars[index].price = (formData.price || 0) * factor;
            }
         }

         // Auto-update price when conversion factor is manually changed
         if (field === 'conversionFactor') {
             const factor = parseFloat(value) || 0;
             newVars[index].price = (formData.price || 0) * factor;
         }
      }
      return newVars;
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.name && formData.unit) {
      const productData: Product = {
        ...initialData,
        ...formData as Product,
        id: initialData?.id || `P-${Date.now()}`,
        variants: variants.length > 0 ? variants as ProductVariant[] : undefined,
        warehouseInventory: initialData?.warehouseInventory || [{ warehouseId: 'wh1', quantity: formData.stock || 0 }],
      };
      onSubmit(productData);
      onClose();
    }
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-5xl max-h-[90vh] flex flex-col overflow-hidden">
        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 shrink-0">
          <h3 className="text-xl font-bold text-slate-800">{initialData ? 'Edit' : 'Add'} Product</h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600"><X className="w-6 h-6" /></button>
        </div>

        <div className="flex border-b border-slate-200 bg-white overflow-x-auto no-scrollbar">
           {[
             { id: 'general', label: 'General Info', icon: Box },
             { id: 'physical', label: 'Physical Attributes', icon: Scale },
             { id: 'pricing', label: 'Pricing & Branches', icon: DollarSign },
             { id: 'variants', label: 'Variants', icon: Layers },
           ].map(tab => (
             <button
               key={tab.id}
               onClick={() => setActiveTab(tab.id as any)}
               className={`flex-1 flex items-center justify-center px-6 py-5 text-lg font-semibold transition-all whitespace-nowrap min-w-fit outline-none focus:outline-none select-none ${
                 activeTab === tab.id ? 'border-b-4 border-construction-orange text-construction-orange bg-orange-50' : 'text-slate-500 hover:text-slate-700 hover:bg-slate-50 border-b-4 border-transparent'
               }`}
             >
               <tab.icon className="w-6 h-6 mr-3" />
               {tab.label}
             </button>
           ))}
        </div>

        <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto p-6 bg-slate-50/50">
          {activeTab === 'general' && (
            <GeneralTab 
              formData={formData} 
              setFormData={setFormData} 
              handleInputChange={handleInputChange} 
              categoryOptions={categoryOptions} 
              units={units}
              fileInputRef={fileInputRef}
              handleImageUpload={handleImageUpload}
            />
          )}

          {activeTab === 'physical' && (
             <PhysicalTab formData={formData} handlePhysicalChange={handlePhysicalChange} />
          )}

          {activeTab === 'pricing' && (
            <PricingTab 
              formData={formData} 
              setFormData={setFormData}
              handleInputChange={handleInputChange} 
              currencySymbol={currencySymbol} 
              customerLevels={customerLevels} 
            />
          )}

          {activeTab === 'variants' && (
            <VariantsTab 
              variants={variants} 
              setVariants={setVariants} 
              handleAddVariant={handleAddVariant} 
              handleVariantChange={handleVariantChange} 
              unitsByCategory={unitsByCategory}
              availableAttributes={attributes}
            />
          )}
        </form>

        <div className="p-4 border-t border-slate-100 flex justify-end space-x-3 bg-white shrink-0">
            <button onClick={onClose} className="px-5 py-2 text-slate-600 font-medium hover:bg-slate-100 rounded-lg">Cancel</button>
            <button type="button" onClick={handleSubmit} className="px-5 py-2 bg-construction-orange text-white font-medium rounded-lg hover:bg-orange-600 shadow-sm flex items-center"><Check className="w-4 h-4 mr-2" /> Save</button>
        </div>
      </div>
    </div>
  );
};

import { GoogleGenAI, Type } from "@google/genai";
import { EstimateResultItem, Product, InventoryAnalysisResult, Sale, BusinessInsight } from "../types";

const API_KEY = process.env.API_KEY || '';

// Initialize the client only if the key is present
const ai = API_KEY ? new GoogleGenAI({ apiKey: API_KEY }) : null;

export const getConstructionEstimate = async (
  query: string, 
  inventory: Product[]
): Promise<EstimateResultItem[]> => {
  if (!ai) {
    console.warn("Gemini API Key is missing.");
    return [
      {
        productName: "System Error",
        estimatedQuantity: 0,
        unit: "N/A",
        reasoning: "API Key not configured. Please check metadata or environment."
      }
    ];
  }

  // Optimize inventory context to save tokens, but include Price for value estimation
  const inventoryList = inventory.map(p => 
    `{id: "${p.id}", name: "${p.name}", unit: "${p.unit}", price: ${p.price}}`
  ).join('\n');

  const systemInstruction = `
    You are an expert construction estimator and civil engineer (Quantity Surveyor).

    Current Store Inventory:
    ${inventoryList}

    Your Task:
    Analyze the user's construction project request (e.g., "build a 4x3m brick wall").
    Calculate the required materials with a standard 5-10% waste margin included.

    Rules:
    1. MATCHING: Attempt to match requirements to items in the 'Current Store Inventory'. 
       - If a match is found, return the exact 'id' as 'matchedProductId' and the exact 'name' from inventory.
       - If no match is found, suggest a generic product name and leave 'matchedProductId' null.
    2. QUANTITY: Return the total quantity required in the product's unit.
       - Example: If the inventory unit is 'bag' (50kg) and 200kg is needed, return 4.
    3. REASONING: Briefly explain the formula used (e.g., "Area = 12m2, approx 125 bricks/m2 + 10% waste").
    4. VARIETY: Suggest complementary items (e.g., if asking for bricks, also suggest cement and sand).

    Return ONLY a JSON array.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: query,
      config: {
        systemInstruction: systemInstruction,
        temperature: 0.2, // Low temperature for math consistency
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              productName: { type: Type.STRING },
              estimatedQuantity: { type: Type.NUMBER },
              unit: { type: Type.STRING },
              reasoning: { type: Type.STRING },
              matchedProductId: { type: Type.STRING, nullable: true },
            },
            required: ['productName', 'estimatedQuantity', 'unit', 'reasoning']
          }
        }
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as EstimateResultItem[];
    }
    return [];
  } catch (error) {
    console.error("Gemini Estimate Error:", error);
    throw error;
  }
};

export const analyzeInventory = async (products: Product[], sales: Sale[]): Promise<InventoryAnalysisResult | null> => {
  if (!ai) {
    console.warn("Gemini API Key is missing.");
    return null;
  }

  // Create a condensed view of inventory
  const productSummary = products.map(p => ({
    id: p.id,
    name: p.name,
    stock: p.stock,
    min: p.minStock || 20,
    unit: p.unit,
    category: p.category
  }));

  // Create a summary of sales transactions (condensed to save tokens)
  // We only send the last 20 transactions to analyze recent trends
  const recentSales = sales.slice(0, 20).map(s => ({
    items: s.items.map(i => i.name)
  }));

  const systemInstruction = `
    You are an intelligent retail inventory manager for a construction materials store.

    Data Provided:
    1. Current Product Inventory (Stock levels).
    2. Recent Sales Transactions (Items bought together).

    Your tasks:
    1. REORDERS: Identify items critically low (stock <= minStock) and suggest reorder qty.
    2. NEW PRODUCTS: Suggest NEW products we should add based on gaps in our catalog.
    3. BUNDLES: Analyze the sales transactions. If certain items are frequently bought together (e.g. Cement + Sand), suggest a "Bundle" or "Combo Pack" product we could create to simplify purchasing or offer a deal.

    Return the result strictly as a JSON object with 'reorders', 'newProducts', and 'bundles' arrays.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: JSON.stringify({ inventory: productSummary, sales: recentSales }),
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            reorders: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  productId: { type: Type.STRING },
                  productName: { type: Type.STRING },
                  currentStock: { type: Type.NUMBER },
                  suggestedReorderQty: { type: Type.NUMBER },
                  priority: { type: Type.STRING, enum: ['High', 'Medium', 'Low'] },
                  reasoning: { type: Type.STRING }
                }
              }
            },
            newProducts: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  name: { type: Type.STRING },
                  categoryName: { type: Type.STRING },
                  estimatedPrice: { type: Type.NUMBER },
                  suggestedUnit: { type: Type.STRING },
                  reasoning: { type: Type.STRING }
                }
              }
            },
            bundles: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  bundleName: { type: Type.STRING },
                  components: { type: Type.ARRAY, items: { type: Type.STRING } },
                  estimatedPrice: { type: Type.NUMBER },
                  reasoning: { type: Type.STRING },
                  targetAudience: { type: Type.STRING }
                }
              }
            }
          },
          required: ['reorders', 'newProducts', 'bundles']
        }
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as InventoryAnalysisResult;
    }
    return null;
  } catch (error) {
    console.error("Gemini Inventory Analysis Error:", error);
    return null;
  }
};

export const generateBusinessInsights = async (sales: Sale[], products: Product[]): Promise<BusinessInsight | null> => {
  if (!ai) {
    // Return dummy data if no key, ensuring UI works
    return {
      summary: "Simulated Insight: Revenue is trending positively. Consider restocking fast-moving items like Cement.",
      trendDirection: "up",
      actionItems: ["Restock Cement", "Review pricing for Red Brick", "Promote slow-moving Tiles"],
      predictedRevenueNextWeek: 12500,
      topPerformingCategory: "Cement & Concrete"
    };
  }

  // Summarize daily sales for the last 30 days
  const dailyRevenue: Record<string, number> = {};
  const categoryRevenue: Record<string, number> = {};

  sales.forEach(s => {
    const date = new Date(s.date).toISOString().split('T')[0];
    dailyRevenue[date] = (dailyRevenue[date] || 0) + s.total;

    s.items.forEach(item => {
       // Simplified category tracking using item name keywords or ID if available
       // In production, map ID to Category Name properly
       const cat = item.category || 'General'; 
       categoryRevenue[cat] = (categoryRevenue[cat] || 0) + (item.sellPrice * item.quantity);
    });
  });

  const lowStockCount = products.filter(p => p.stock <= (p.minStock || 0)).length;

  const context = {
    dailySales: dailyRevenue,
    categoryPerformance: categoryRevenue,
    lowStockItemsCount: lowStockCount,
    totalProducts: products.length
  };

  const systemInstruction = `
    You are a senior business analyst for a retail store.
    Analyze the provided sales data (Daily Revenue map) and Inventory status.

    Tasks:
    1. Write a 1-sentence Executive Summary of performance.
    2. Determine the trend direction ('up', 'down', 'stable').
    3. List 3 actionable bullet points for the manager (e.g., restock, run promo, cut costs).
    4. Predict the TOTAL revenue for the NEXT 7 DAYS based on the recent daily trend.
    5. Identify the top performing category name.

    Return JSON matching the BusinessInsight interface.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: JSON.stringify(context),
      config: {
        systemInstruction: systemInstruction,
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            summary: { type: Type.STRING },
            trendDirection: { type: Type.STRING, enum: ['up', 'down', 'stable'] },
            actionItems: { type: Type.ARRAY, items: { type: Type.STRING } },
            predictedRevenueNextWeek: { type: Type.NUMBER },
            topPerformingCategory: { type: Type.STRING }
          },
          required: ['summary', 'trendDirection', 'actionItems', 'predictedRevenueNextWeek', 'topPerformingCategory']
        }
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as BusinessInsight;
    }
    return null;
  } catch (error) {
    console.error("Gemini Business Insight Error:", error);
    return null;
  }
};

import React, { useState } from 'react';
import { Bot, X, Loader2, Calculator, Check, ShoppingCart, Info, AlertTriangle, Plus, CheckSquare, Square } from 'lucide-react';
import { EstimateResultItem, Product } from '../types';
import { getConstructionEstimate } from '../services/geminiService';

interface AiAssistantProps {
  isOpen: boolean;
  onClose: () => void;
  inventory: Product[];
  onAddItemsToCart: (items: EstimateResultItem[]) => void;
}

export const AiAssistant: React.FC<AiAssistantProps> = ({ isOpen, onClose, inventory, onAddItemsToCart }) => {
  const [query, setQuery] = useState('');
  const [loading, setLoading] = useState(false);
  const [estimate, setEstimate] = useState<EstimateResultItem[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [selectedItems, setSelectedItems] = useState<Set<number>>(new Set());

  if (!isOpen) return null;

  const handleEstimate = async () => {
    if (!query.trim()) return;

    setLoading(true);
    setError(null);
    setEstimate(null);
    setSelectedItems(new Set());

    try {
      const result = await getConstructionEstimate(query, inventory);
      setEstimate(result);
      // Auto-select all matched items by default
      const allIndexes = result.map((_, idx) => idx);
      setSelectedItems(new Set(allIndexes));
    } catch (err) {
      setError("Failed to generate estimate. Please check your connection or API key.");
    } finally {
      setLoading(false);
    }
  };

  const toggleItemSelection = (index: number) => {
    const newSet = new Set(selectedItems);
    if (newSet.has(index)) {
      newSet.delete(index);
    } else {
      newSet.add(index);
    }
    setSelectedItems(newSet);
  };

  const handleAddSelected = () => {
    if (estimate) {
      const itemsToAdd = estimate.filter((_, idx) => selectedItems.has(idx));
      onAddItemsToCart(itemsToAdd);
      onClose();
    }
