import React, { useMemo } from 'react';
import { UnitDefinition, UnitCategory } from '../../types';
import { Ruler, Weight, Hash, Edit2, Trash2, ArrowRight, CornerDownRight, Box, CheckCircle2 } from 'lucide-react';

interface UnitListProps {
  units: UnitDefinition[];
  activeCategory: UnitCategory;
  onCategoryChange: (category: UnitCategory) => void;
  onEdit: (unit: UnitDefinition) => void;
  onDelete: (id: string) => void;
}

export const UnitList: React.FC<UnitListProps> = ({ 
  units, activeCategory, onCategoryChange, onEdit, onDelete 
}) => {
  const categories: { id: UnitCategory; icon: any; label: string }[] = [
    { id: 'Length', icon: Ruler, label: 'Length' },
    { id: 'Weight', icon: Weight, label: 'Weight' },
    { id: 'Quantity', icon: Hash, label: 'Quantity' },
  ];

  // Logic to organize units into a hierarchy based on Base Factor
  const { baseUnit, derivedUnits } = useMemo(() => {
    const filtered = units.filter(u => u.category === activeCategory);
    const base = filtered.find(u => u.isBase);
    const others = filtered.filter(u => !u.isBase).sort((a, b) => a.baseFactor - b.baseFactor);
    return { baseUnit: base, derivedUnits: others };
  }, [units, activeCategory]);

  return (
    <div className="flex flex-col h-full">
      {/* Category Tabs */}
      <div className="bg-slate-100 p-1 rounded-xl flex overflow-x-auto shrink-0 mb-6 w-fit">
        {categories.map((cat) => {
          const Icon = cat.icon;
          const isActive = activeCategory === cat.id;
          return (
            <button
              key={cat.id}
              onClick={() => onCategoryChange(cat.id)}
              className={`flex items-center justify-center px-6 py-2.5 rounded-lg transition-all text-sm font-bold whitespace-nowrap ${
                isActive 
                  ? 'bg-white text-slate-900 shadow-sm' 
                  : 'text-slate-500 hover:text-slate-700'
              }`}
            >
              <Icon className="w-4 h-4 mr-2" />
              <span>{cat.label}</span>
            </button>
          );
        })}
      </div>

      <div className="flex-1 overflow-y-auto bg-slate-50 p-6 rounded-2xl border border-slate-200">
         {!baseUnit && derivedUnits.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-64 text-slate-400">
               <Box className="w-16 h-16 mb-4 opacity-20" />
               <p className="font-medium">No units defined for {activeCategory}.</p>
               <p className="text-xs">Create a Base Unit to start.</p>
            </div>
         ) : (
            <div className="max-w-3xl mx-auto">

               {/* ROOT NODE (Base Unit) */}
               {baseUnit ? (
                  <div className="relative z-10">
                     <div className="bg-white p-5 rounded-2xl border-2 border-blue-100 shadow-sm flex justify-between items-center relative overflow-hidden group">
                        <div className="absolute top-0 left-0 w-1.5 h-full bg-blue-500"></div>
                        <div className="flex items-center gap-4 pl-2">
                           <div className="w-12 h-12 rounded-xl bg-blue-50 text-blue-600 flex items-center justify-center">
                              <CheckCircle2 className="w-6 h-6" />
                           </div>
                           <div>
                              <div className="flex items-center gap-2">
                                 <h3 className="text-lg font-bold text-slate-900">{baseUnit.name}</h3>
                                 <span className="px-2 py-0.5 bg-blue-100 text-blue-700 text-[10px] font-bold uppercase rounded-full tracking-wide">Base Unit</span>
                              </div>
                              <p className="text-sm text-slate-500 mt-0.5">
                                 Symbol: <span className="font-mono font-bold text-slate-700 bg-slate-100 px-1.5 rounded">{baseUnit.symbol}</span>
                              </p>
                           </div>
                        </div>
                        <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                           <button onClick={() => onEdit(baseUnit)} className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"><Edit2 className="w-4 h-4"/></button>
                        </div>
                     </div>

                     {/* Connecting Line to Children */}
                     {derivedUnits.length > 0 && (
                        <div className="absolute left-8 top-full h-8 w-0.5 bg-slate-300"></div>
                     )}
                  </div>
               ) : (
                  <div className="bg-red-50 border border-red-200 p-4 rounded-xl text-red-700 text-sm mb-6 flex items-center">
                     <Trash2 className="w-5 h-5 mr-3" />
                     Warning: No Base Unit defined. Please create one (e.g., 'Piece', 'Gram').
                  </div>
               )}

               {/* CHILDREN NODES (Derived Units) */}
               <div className="mt-8 ml-8 space-y-4">
                  {derivedUnits.map((unit, index) => {
                     const isLast = index === derivedUnits.length - 1;
                     return (
                        <div key={unit.id} className="relative pl-10">
                           {/* Tree Lines */}
                           <div className="absolute left-0 top-0 bottom-0 w-0.5 bg-slate-300 -mt-4"></div>
                           <div className="absolute left-0 top-1/2 w-8 h-0.5 bg-slate-300"></div>
                           {isLast && <div className="absolute left-0 top-1/2 bottom-0 w-0.5 bg-slate-50"></div>} {/* Mask line for last item */}

                           <div className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm hover:shadow-md transition-all flex justify-between items-center group relative">
                              <div className="flex items-center gap-4">
                                 <div className="w-10 h-10 rounded-lg bg-slate-50 text-slate-400 flex items-center justify-center font-bold text-xs border border-slate-100">
                                    {unit.symbol}
                                 </div>
                                 <div>
                                    <h4 className="font-bold text-slate-800">{unit.name}</h4>
                                    <div className="flex items-center text-xs text-slate-500 mt-1 bg-slate-50 px-2 py-1 rounded-lg w-fit">
                                       <span className="font-semibold text-slate-700">1 {unit.symbol}</span>
                                       <ArrowRight className="w-3 h-3 mx-2 text-slate-400" />
                                       <span className="font-mono text-slate-700">{unit.baseFactor} {baseUnit?.symbol || 'base'}</span>
                                    </div>
                                 </div>
                              </div>

                              <div className="flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                                 <button onClick={() => onEdit(unit)} className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"><Edit2 className="w-4 h-4"/></button>
                                 <button onClick={() => onDelete(unit.id)} className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors"><Trash2 className="w-4 h-4"/></button>
                              </div>
                           </div>
                        </div>
                     );
                  })}
               </div>
            </div>
         )}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Branch } from '../../types';
import { Server, ArrowUpCircle, ArrowDownCircle, CheckSquare, Square, RefreshCw, CheckCircle, AlertCircle } from 'lucide-react';

interface MasterSyncControlProps {
  branches: Branch[];
  onSync: (type: 'Push' | 'Pull', targetBranchIds: string[]) => void;
  isSyncing: boolean;
}

export const MasterSyncControl: React.FC<MasterSyncControlProps> = ({ branches, onSync, isSyncing }) => {
  const [selectedIds, setSelectedIds] = useState<string[]>([]);

  const activeBranches = branches.filter(b => b.isActive);

  const handleToggleAll = () => {
    if (selectedIds.length === activeBranches.length) {
      setSelectedIds([]);
    } else {
      setSelectedIds(activeBranches.map(b => b.id));
    }
  };

  const handleToggleOne = (id: string) => {
    if (selectedIds.includes(id)) {
      setSelectedIds(prev => prev.filter(bid => bid !== id));
    } else {
      setSelectedIds(prev => [...prev, id]);
    }
  };

  const handleAction = (type: 'Push' | 'Pull') => {
    if (selectedIds.length === 0) return;
    onSync(type, selectedIds);
  };

  return (
    <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 mb-6">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h3 className="text-lg font-bold text-slate-800 flex items-center">
            <Server className="w-5 h-5 mr-2 text-indigo-600" />
            Master Server Control
          </h3>
          <p className="text-sm text-slate-500">Select branches to synchronize data.</p>
        </div>
        <div className="flex gap-3">
          <button
            onClick={() => handleAction('Pull')}
            disabled={isSyncing || selectedIds.length === 0}
            className="flex items-center px-4 py-2 bg-white border border-blue-200 text-blue-700 rounded-lg hover:bg-blue-50 disabled:opacity-50 transition-colors font-bold text-sm shadow-sm"
          >
            <ArrowDownCircle className={`w-4 h-4 mr-2 ${isSyncing ? 'animate-bounce' : ''}`} />
            Pull from Branch
          </button>
          <button
            onClick={() => handleAction('Push')}
            disabled={isSyncing || selectedIds.length === 0}
            className="flex items-center px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:opacity-50 transition-colors font-bold text-sm shadow-md"
          >
            <ArrowUpCircle className={`w-4 h-4 mr-2 ${isSyncing ? 'animate-bounce' : ''}`} />
            Push to Branch
          </button>
        </div>
      </div>

      {/* Branch Selection List */}
      <div className="border rounded-xl overflow-hidden">
        <div className="bg-slate-50 p-3 border-b border-slate-200 flex items-center justify-between">
          <div 
            onClick={handleToggleAll}
            className="flex items-center cursor-pointer text-sm font-bold text-slate-700"
          >
            {selectedIds.length === activeBranches.length && activeBranches.length > 0 ? (
              <CheckSquare className="w-5 h-5 text-indigo-600 mr-2" />
            ) : (
              <Square className="w-5 h-5 text-slate-400 mr-2" />
            )}
            Select All Active Branches ({activeBranches.length})
          </div>
          <span className="text-xs text-slate-500">
            {selectedIds.length} Selected
          </span>
        </div>

        <div className="divide-y divide-slate-100 max-h-60 overflow-y-auto">
          {activeBranches.length === 0 ? (
             <div className="p-6 text-center text-slate-400 text-sm">No active branches found.</div>
          ) : (
             activeBranches.map(branch => {
                const isSelected = selectedIds.includes(branch.id);
                return (
                  <div 
                    key={branch.id} 
                    onClick={() => handleToggleOne(branch.id)}
                    className={`p-3 flex items-center justify-between cursor-pointer transition-colors ${isSelected ? 'bg-indigo-50/50' : 'hover:bg-slate-50'}`}
                  >
                    <div className="flex items-center">
                      {isSelected ? (
                        <CheckSquare className="w-5 h-5 text-indigo-600 mr-3" />
                      ) : (
                        <Square className="w-5 h-5 text-slate-300 mr-3" />
                      )}
                      <div>
                        <p className={`text-sm font-bold ${isSelected ? 'text-indigo-900' : 'text-slate-700'}`}>{branch.name}</p>
                        <p className="text-xs text-slate-500">{branch.phone || 'No IP Configured'}</p>
                      </div>
                    </div>

                    {/* Simulated Status Indicator */}
                    <div className="flex items-center">
                       {isSyncing && isSelected ? (
                          <span className="flex items-center text-xs text-indigo-600 font-medium">
                             <RefreshCw className="w-3 h-3 mr-1 animate-spin" /> Syncing...
                          </span>
                       ) : (
                          <span className="flex items-center text-xs text-green-600 font-medium">
                             <CheckCircle className="w-3 h-3 mr-1" /> Ready
                          </span>
                       )}
                    </div>
                  </div>
                );
             })
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { SyncLog, Sale, SystemSettings, Branch } from '../types';
import { Wifi, WifiOff } from 'lucide-react';
import { SyncStatusCards } from './sync/SyncStatusCards';
import { SyncActions } from './sync/SyncActions';
import { SyncLogTable } from './sync/SyncLogTable';
import { MasterSyncControl } from './sync/MasterSyncControl';

interface SyncManagementProps {
  settings: SystemSettings;
  logs: SyncLog[];
  sales: Sale[];
  branches?: Branch[];
  onSync: (type: 'Auto' | 'Manual' | 'Push' | 'Pull', targetBranchIds?: string[]) => void;
}

export const SyncManagement: React.FC<SyncManagementProps> = ({ settings, logs, sales, branches = [], onSync }) => {
  const [syncingType, setSyncingType] = useState<'Auto' | 'Manual' | 'Push' | 'Pull' | null>(null);

  // Calculate stats
  const pendingSales = sales.filter(s => s.syncStatus === 'pending');
  const lastSuccess = logs.find(l => l.status === 'Success');

  // Mock Connection Check
  const isConnected = !!settings.masterApiUrl || settings.deviceRole === 'Master'; 

  const handleSyncAction = (type: 'Auto' | 'Manual' | 'Push' | 'Pull') => {
    setSyncingType(type);
    setTimeout(() => {
      onSync(type);
      setSyncingType(null);
    }, 1500);
  };

  const handleMasterSync = (type: 'Push' | 'Pull', targetIds: string[]) => {
    setSyncingType(type);
    setTimeout(() => {
      onSync(type, targetIds);
      setSyncingType(null);
    }, 2000); // Slightly longer simulation for multi-branch
  };

  return (
    <div className="space-y-6 h-full flex flex-col pb-20 md:pb-0">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Data Synchronization</h2>
          <p className="text-slate-500">Monitor and manage data transfer between POS and Master Server.</p>
        </div>
        <div className="flex items-center space-x-2">
           <span className={`flex items-center px-3 py-1 rounded-full text-sm font-medium ${isConnected ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'}`}>
              {isConnected ? <Wifi className="w-4 h-4 mr-2" /> : <WifiOff className="w-4 h-4 mr-2" />}
              {isConnected ? 'Online' : 'Offline'}
           </span>
        </div>
      </div>

      <SyncStatusCards 
        settings={settings}
        pendingSalesCount={pendingSales.length}
        lastSuccessLog={lastSuccess}
      />

      {settings.deviceRole === 'Master' ? (
        <MasterSyncControl 
          branches={branches} 
          onSync={handleMasterSync} 
          isSyncing={!!syncingType} 
        />
      ) : (
        <SyncActions 
          onSyncAction={handleSyncAction}
          syncingType={syncingType}
          masterApiUrl={settings.masterApiUrl}
        />
      )}

      <SyncLogTable logs={logs} />
    </div>
  );
};

