import React from 'react';
import { Product, Branch } from '../../../types';
import { Store, ArrowRight, Info } from 'lucide-react';

interface BranchPricingTabProps {
  formData: Partial<Product>;
  setFormData: React.Dispatch<React.SetStateAction<Partial<Product>>>;
  branches: Branch[];
  currencySymbol: string;
}

export const BranchPricingTab: React.FC<BranchPricingTabProps> = ({ 
  formData, setFormData, branches, currencySymbol 
}) => {

  const handleBranchPriceChange = (branchId: string, value: string) => {
    const currentPrices = formData.branchPrices || [];
    const newPrice = value === '' ? undefined : parseFloat(value);

    // Remove existing entry for this branch
    const otherPrices = currentPrices.filter(bp => bp.branchId !== branchId);

    if (newPrice !== undefined && !isNaN(newPrice)) {
      // Add new entry
      setFormData({
        ...formData,
        branchPrices: [...otherPrices, { branchId, price: newPrice }]
      });
    } else {
      // If empty/invalid, just remove the override (reverts to base price)
      setFormData({
        ...formData,
        branchPrices: otherPrices
      });
    }
  };

  const activeBranches = branches.filter(b => b.isActive);

  return (
    <div className="space-y-6 bg-white p-6 rounded-xl border border-slate-200 shadow-sm animate-fade-in">
      <div className="flex items-start justify-between mb-2">
         <div>
            <h4 className="font-bold text-slate-800 flex items-center">
               <Store className="w-5 h-5 mr-2 text-slate-500" /> 
               Branch Specific Pricing
            </h4>
            <p className="text-sm text-slate-500 mt-1">
               Set different selling prices for specific locations. If left blank, the <strong>Standard Selling Price ({currencySymbol}{formData.price || 0})</strong> will be used.
            </p>
         </div>
      </div>

      <div className="overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
         <table className="w-full text-left text-sm">
            <thead className="bg-slate-100 text-slate-600 font-semibold border-b border-slate-200">
               <tr>
                  <th className="px-4 py-3">Branch Name</th>
                  <th className="px-4 py-3">Standard Price</th>
                  <th className="px-4 py-3 text-center">Status</th>
                  <th className="px-4 py-3 text-right">Branch Price</th>
               </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
               {activeBranches.length === 0 ? (
                  <tr>
                     <td colSpan={4} className="p-6 text-center text-slate-400 italic">
                        No active branches found. Go to Branch Management to create branches.
                     </td>
                  </tr>
               ) : (
                  activeBranches.map(branch => {
                     const override = formData.branchPrices?.find(bp => bp.branchId === branch.id);
                     const hasOverride = override !== undefined;

                     return (
                        <tr key={branch.id} className={`hover:bg-slate-50 transition-colors ${hasOverride ? 'bg-blue-50/30' : ''}`}>
                           <td className="px-4 py-3 font-medium text-slate-800">
                              {branch.name}
                              <div className="text-xs text-slate-400 font-normal">{branch.address || 'No Address'}</div>
                           </td>
                           <td className="px-4 py-3 text-slate-500">
                              {currencySymbol} {formData.price || 0}
                           </td>
                           <td className="px-4 py-3 text-center">
                              {hasOverride ? (
                                 <span className="bg-blue-100 text-blue-700 px-2 py-1 rounded text-[10px] font-bold uppercase border border-blue-200">
                                    Custom Price
                                 </span>
                              ) : (
                                 <span className="bg-slate-100 text-slate-500 px-2 py-1 rounded text-[10px] font-bold uppercase border border-slate-200">
                                    Default
                                 </span>
                              )}
                           </td>
                           <td className="px-4 py-3 text-right">
                              <div className="relative inline-block w-32">
                                 <span className="absolute left-3 top-2 text-slate-400 font-bold text-xs">{currencySymbol}</span>
                                 <input 
                                    type="number" 
                                    min="0" 
                                    step="0.01" 
                                    placeholder={formData.price?.toString()}
                                    value={override?.price ?? ''}
                                    onChange={(e) => handleBranchPriceChange(branch.id, e.target.value)}
                                    className={`w-full pl-7 pr-3 py-1.5 border rounded-lg text-right font-bold focus:ring-2 focus:ring-blue-500 outline-none text-sm ${hasOverride ? 'border-blue-300 text-blue-700 bg-white' : 'border-slate-200 bg-slate-50 text-slate-500'}`}
                                 />
                              </div>
                           </td>
                        </tr>
                     );
                  })
               )}
            </tbody>
         </table>
      </div>

      <div className="flex items-start gap-2 text-xs text-blue-700 bg-blue-50 p-3 rounded-lg border border-blue-100">
         <Info className="w-4 h-4 text-blue-500 mt-0.5 shrink-0" />
         <p>
            <strong>Tip:</strong> Branch prices override the base price but are still subject to customer membership discounts calculated at the POS.
         </p>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Product, ProductVariant, UnitDefinition, CategoryItem, VariantAttribute, CustomerLevel, ProductInventory, Branch } from '../../types';
import { Box, Scale, DollarSign, Layers, X, Check, Store } from 'lucide-react';
import { GeneralTab } from './product-form/GeneralTab';
import { PhysicalTab } from './product-form/PhysicalTab';
import { PricingTab } from './product-form/PricingTab';
import { VariantsTab } from './product-form/VariantsTab';
