'use client';

import React, { useState } from 'react';
import { useGlobal } from '../context/GlobalContext';
import { Lock, User as UserIcon, LogIn, Loader2, AlertCircle } from 'lucide-react';
import { verifyPasswordSync } from '../lib/auth';
import { MhxIcon } from './shared/MhxLogo';

export const LoginPage: React.FC = () => {
  const { setCurrentUser, users, t } = useGlobal();

  const [loginUsername, setLoginUsername] = useState('admin');
  const [loginPassword, setLoginPassword] = useState('123');
  const [loginError, setLoginError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleLoginSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoginError('');
    setLoading(true);

    try {
      const cleanUsername = loginUsername.trim().toLowerCase();
      const cleanPassword = loginPassword.trim();

      // 1. Client-Side Check (Fastest, supports session-created users)
      const clientMatch = users.find(u => 
        u.username.toLowerCase() === cleanUsername
      );

      // Try local auth first or as fallback
      const attemptLocalAuth = () => {
        if (clientMatch && clientMatch.password) {
          const isValid = verifyPasswordSync(cleanPassword, clientMatch.password);
          if (isValid) {
            document.cookie = `user_role=${clientMatch.role}; path=/; max-age=86400`;
            const { password, ...safeUser } = clientMatch;
            setCurrentUser(safeUser as any);
            return true;
          }
        }
        return false;
      };

      // 2. Attempt API Login (if available)
      try {
        const res = await fetch('/api/auth/login', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ username: cleanUsername, password: cleanPassword })
        });

        if (res.ok) {
          const data = await res.json();
          if (data.user) {
            setCurrentUser(data.user);
            setLoading(false);
            return;
          }
        } else {
           // API returned error (e.g. 401 or 500)
           // Fallback to local if API failed due to DB/Server issue
           if (res.status >= 500 && attemptLocalAuth()) {
              setLoading(false);
              return;
           }
        }
      } catch (apiError) {
        console.warn("API Login failed (network error), attempting local fallback", apiError);
        if (attemptLocalAuth()) {
           setLoading(false);
           return;
        }
      }

      // If we reached here, both API and Local failed (or Local failed after API error)
      // Check local one last time if we didn't check it inside the catch blocks
      if (attemptLocalAuth()) {
         setLoading(false);
         return;
      }

      throw new Error('Invalid username or password');

    } catch (err: any) {
      console.error(err);
      setLoginError(err.message || 'Login failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 flex items-center justify-center bg-slate-900 z-50">
        <div className="bg-white rounded-2xl shadow-2xl overflow-hidden w-full max-w-4xl flex flex-col md:flex-row mx-4 md:mx-0 animate-fade-in">

           {/* Left Brand Side - Red Theme */}
           <div className="md:w-1/2 bg-gradient-to-br from-red-600 to-red-800 p-12 text-white flex flex-col justify-center items-center text-center relative overflow-hidden">
              <div className="absolute inset-0 bg-[url('https://images.unsplash.com/photo-1541888946425-d81bb19240f5?auto=format&fit=crop&q=80&w=1000')] bg-cover bg-center opacity-10 mix-blend-overlay"></div>

              <div className="bg-white/20 p-6 rounded-3xl mb-6 backdrop-blur-sm shadow-lg relative z-10 border border-white/10">
                <MhxIcon className="w-20 h-20 text-white" />
              </div>
              <h1 className="text-4xl font-bold mb-4 relative z-10">{t('app.name')}</h1>
              <p className="text-red-100 text-lg relative z-10 max-w-xs">{t('app.subtitle')}</p>
           </div>

           {/* Right Login Form Side */}
           <div className="md:w-1/2 p-8 md:p-12 flex flex-col justify-center bg-white">
              <div className="mb-8">
                <h2 className="text-2xl font-bold text-slate-800 flex items-center">
                  <LogIn className="w-6 h-6 mr-2 text-red-600" />
                  {t('common.signIn')}
                </h2>
                <p className="text-slate-500 text-sm mt-1">Access your POS dashboard</p>
              </div>

              <form onSubmit={handleLoginSubmit} className="space-y-5">
                 <div>
                   <label className="block text-sm font-medium text-slate-700 mb-1.5">{t('common.username')}</label>
                   <div className="relative group">
                     <UserIcon className="absolute left-3 top-3 w-5 h-5 text-slate-400 group-focus-within:text-red-500 transition-colors" />
                     <input 
                       type="text"
                       required
                       value={loginUsername}
                       onChange={e => setLoginUsername(e.target.value)}
                       className="w-full pl-10 pr-4 py-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-red-500 focus:border-red-500 transition-all outline-none bg-slate-50 focus:bg-white"
                       placeholder="Enter your username"
                     />
                   </div>
                 </div>

                 <div>
                   <label className="block text-sm font-medium text-slate-700 mb-1.5">{t('common.password')}</label>
                   <div className="relative group">
                     <Lock className="absolute left-3 top-3 w-5 h-5 text-slate-400 group-focus-within:text-red-500 transition-colors" />
                     <input 
                       type="password"
                       required
                       value={loginPassword}
                       onChange={e => setLoginPassword(e.target.value)}
                       className="w-full pl-10 pr-4 py-2.5 border border-slate-300 rounded-xl focus:ring-2 focus:ring-red-500 focus:border-red-500 transition-all outline-none bg-slate-50 focus:bg-white"
                       placeholder="Enter your password"
                     />
                   </div>
                 </div>

                 {loginError && (
                   <div className="bg-red-50 text-red-600 text-sm p-3 rounded-xl border border-red-100 flex items-start animate-pulse">
                     <AlertCircle className="w-5 h-5 mr-2 shrink-0 mt-0.5" />
                     {loginError}
                   </div>
                 )}

                 <button 
                   type="submit"
                   disabled={loading}
                   className="w-full bg-slate-900 text-white py-3.5 rounded-xl font-bold hover:bg-red-600 active:bg-red-700 active:scale-[0.98] transition-all shadow-lg disabled:opacity-70 disabled:cursor-not-allowed flex justify-center items-center"
                 >
                   {loading ? (
                     <>
                       <Loader2 className="w-5 h-5 animate-spin mr-2" />
                       {t('common.loading')}
                     </>
                   ) : t('common.login')}
                 </button>
              </form>

              <div className="mt-8 pt-6 border-t border-slate-100 text-center">
                 <p className="text-xs text-slate-400 font-medium uppercase tracking-wider mb-2">
                   {t('common.demo')}
                 </p>
                 <div className="flex justify-center space-x-2 text-xs">
                    <button onClick={() => { setLoginUsername('admin'); setLoginPassword('123'); }} className="bg-slate-100 px-2 py-1 rounded text-slate-600 font-mono hover:bg-slate-200 transition-colors">admin / 123</button>
                    <button onClick={() => { setLoginUsername('cashier'); setLoginPassword('123'); }} className="bg-slate-100 px-2 py-1 rounded text-slate-600 font-mono hover:bg-slate-200 transition-colors">cashier / 123</button>
                 </div>
              </div>
           </div>
        </div>
    </div>
  );
};

import React, { createContext, useContext } from 'react';
import { 
  User, Product, Sale, UnitDefinition, CategoryItem, Branch, PosMachine, 
  Warehouse, StorageLocation, StockTransfer, StockCount, StockReservation, 
  StockReceipt, StockAdjustment, SyncLog, Customer, CustomerLevel, Shift, 
  ShiftSchedule, Promotion, SystemSettings, AppNotification, CartItem, 
  DocumentStatus, CashTransaction, Department, SystemRole, VariantAttribute,
  Quotation
} from '../types';
import { useSystemStore } from '../store/useSystemStore';
import { useInventoryStore } from '../store/useInventoryStore';
import { useSalesStore } from '../store/useSalesStore';
import { useStockStore } from '../store/useStockStore';
import { translations } from '../services/translations';

interface GlobalContextType {
  // System
  currentUser: User | null;
  setCurrentUser: (user: User | null) => void;
  users: User[];
  addUser: (user: User) => void;
  updateUser: (user: User) => void;
  deleteUser: (id: string) => void;

  departments: Department[];
  addDepartment: (dept: Department) => void;
  updateDepartment: (dept: Department) => void;
  deleteDepartment: (id: string) => void;

  systemRoles: SystemRole[];
  addSystemRole: (role: SystemRole) => void;
  updateSystemRole: (role: SystemRole) => void;
  deleteSystemRole: (id: string) => void;

  settings: SystemSettings;
  updateSettings: (settings: SystemSettings) => void;
  notifications: AppNotification[];
  markNotificationRead: (id: string) => void;
  clearAllNotifications: () => void;
  auditLogs: any[];
  syncLogs: SyncLog[];

  // Inventory
  products: Product[];
  addProduct: (product: Product) => void;
  updateProduct: (product: Product) => void;
  deleteProduct: (id: string) => void;
  units: UnitDefinition[];
  addUnit: (unit: UnitDefinition) => void;
  updateUnit: (unit: UnitDefinition) => void;
  deleteUnit: (id: string) => void;
  categories: CategoryItem[];
  addCategory: (category: CategoryItem) => void;
  updateCategory: (category: CategoryItem) => void;
  deleteCategory: (id: string) => void;
  attributes: VariantAttribute[];
  addAttribute: (attr: VariantAttribute) => void;
  updateAttribute: (attr: VariantAttribute) => void;
  deleteAttribute: (id: string) => void;

  // Sales
  sales: Sale[];
  processSale: (
    items: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number,
    paymentMethod?: 'cash' | 'card' | 'transfer' | 'qr' | 'credit',
    amountReceived?: number,
    change?: number,
    pointsRedeemed?: number,
    source?: 'pos' | 'back-office'
  ) => Promise<Sale>;
  handleVoidSale: (id: string) => void;
  settleSaleDebt: (id: string, amount: number, method: string) => Promise<void>;
  processReturn: (originalSale: Sale, itemsToReturn: { itemIndex: number, quantity: number }[], refundMethod: string) => Promise<void>;
  customers: Customer[];
  addCustomer: (customer: Customer) => void;
  updateCustomer: (customer: Customer) => void;
  deleteCustomer: (id: string) => void;
  customerLevels: CustomerLevel[];
  addCustomerLevel: (level: CustomerLevel) => void;
  updateCustomerLevel: (level: CustomerLevel) => void;
  deleteCustomerLevel: (id: string) => void;
  promotions: Promotion[];
  addPromotion: (promo: Promotion) => void;
  updatePromotion: (promo: Promotion) => void;
  deletePromotion: (id: string) => void;

  // Shifts
  shifts: Shift[];
  startShift: (branchId: string, startCash: number, notes?: string, posId?: string) => void;
  endShift: (shiftId: string, endCash: number, notes?: string) => void;
  addCashTransaction: (type: 'in' | 'out', amount: number, reason: string) => void;
  shiftSchedules: ShiftSchedule[];
  addShiftSchedule: (schedule: ShiftSchedule) => void;
  updateShiftSchedule: (schedule: ShiftSchedule) => void;
  deleteShiftSchedule: (id: string) => void;

  // Locations & Stock
  branches: Branch[];
  addBranch: (branch: Branch) => void;
  updateBranch: (branch: Branch) => void;
  deleteBranch: (id: string) => void;
  posMachines: PosMachine[];
  addPos: (pos: PosMachine) => void;
  updatePos: (pos: PosMachine) => void;
  deletePos: (id: string) => void;
  warehouses: Warehouse[];
  addWarehouse: (w: Warehouse) => void;
  updateWarehouse: (w: Warehouse) => void;
  deleteWarehouse: (id: string) => void;
  locations: StorageLocation[];
  addLocation: (l: StorageLocation) => void;
  updateLocation: (l: StorageLocation) => void;
  deleteLocation: (id: string) => void;

  transfers: StockTransfer[];
  updateTransfer: (t: StockTransfer) => void;
  deleteTransfer: (id: string) => void;
  counts: StockCount[];
  updateCount: (c: StockCount) => void;
  deleteCount: (id: string) => void;
  reservations: StockReservation[];
  updateReservation: (r: StockReservation) => void;
  deleteReservation: (id: string) => void;
  receipts: StockReceipt[];
  updateReceipt: (r: StockReceipt) => void;
  deleteReceipt: (id: string) => void;
  adjustments: StockAdjustment[];
  updateAdjustment: (a: StockAdjustment) => void;
  deleteAdjustment: (id: string) => void;

  handleStockStatusChange: (type: 'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment', id: string, status: DocumentStatus) => void;
  handleSyncOperation: (type: 'Auto' | 'Manual' | 'Push' | 'Pull', targetBranchIds?: string[]) => void;
  restoreSystemData: (data: any) => void;

  // Utilities
  t: (key: string) => string;
  formatPrice: (amount: number) => string;
}

const GlobalContext = createContext<GlobalContextType | undefined>(undefined);

export const useGlobal = () => {
  const context = useContext(GlobalContext);
  if (!context) {
    throw new Error('useGlobal must be used within a GlobalProvider');
  }
  return context;
};

export const GlobalProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const systemStore = useSystemStore();
  const inventoryStore = useInventoryStore();
  const salesStore = useSalesStore();
  const stockStore = useStockStore();

  // Translation helper
  const t = (key: string): string => {
    const lang = systemStore.settings.language || 'en';
    const keys = key.split('.');
    let value: any = (translations as any)[lang];
    for (const k of keys) {
      value = value?.[k];
    }
    return value || key;
  };

  const formatPrice = (amount: number) => {
    const lang = systemStore.settings.language;
    let locale = 'en-US';
    if (lang === 'th') locale = 'th-TH';
    else if (lang === 'lo') locale = 'lo-LA';

    let currencyCode = 'USD';
    if (systemStore.settings.currencySymbol === '฿') currencyCode = 'THB';
    else if (systemStore.settings.currencySymbol === '₭') currencyCode = 'LAK';
    else if (systemStore.settings.currencySymbol === '$') currencyCode = 'USD';

    return new Intl.NumberFormat(locale, {
      style: 'currency',
      currency: currencyCode,
      currencyDisplay: 'symbol',
      minimumFractionDigits: currencyCode === 'LAK' ? 0 : 2,
      maximumFractionDigits: currencyCode === 'LAK' ? 0 : 2,
    }).format(amount);
  };

  // Complex Actions
  const processSale = async (
    items: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number,
    paymentMethod: 'cash' | 'card' | 'transfer' | 'qr' | 'credit' = 'cash',
    amountReceived?: number,
    change?: number,
    pointsRedeemed?: number,
    source: 'pos' | 'back-office' = 'pos'
  ): Promise<Sale> => {

    // Client-side Inventory Check for Back Office Sales
    if (source === 'back-office') {
      for (const item of items) {
        const product = inventoryStore.products.find(p => p.id === item.id);
        // Simple stock check. 
        if (!product || product.stock < item.quantity) {
          throw new Error(`Insufficient stock for "${item.name}". Back-office sales cannot result in negative inventory.`);
        }
      }
    }

    // Create Sale Object
    const newSale: Sale = {
      id: `S-${Date.now()}`,
      items: items,
      total: total,
      subtotal: subtotal || total,
      discountAmount: discountAmount || 0,
      date: new Date().toISOString(),
      paymentMethod: paymentMethod,
      paymentStatus: paymentMethod === 'credit' ? 'unpaid' : 'paid',
      remainingAmount: paymentMethod === 'credit' ? total - (amountReceived || 0) : 0,
      amountReceived: amountReceived,
      change: change,
      status: 'completed',
      syncStatus: 'pending',
      customerId: customerId,
      customerName: customerId ? salesStore.customers.find(c => c.id === customerId)?.name : undefined,
      userId: systemStore.currentUser?.id,
      userName: systemStore.currentUser?.name,
      pointsRedeemed: pointsRedeemed
    };

    salesStore.addSale(newSale);

    // Update Inventory
    items.forEach(item => {
      // Logic for variant deduction could be complex if tracking separately.
      // Assuming variants share base stock in this simplified model or simple deduction
      inventoryStore.updateProductStock(item.id, -item.quantity);
    });

    // Update Customer Loyalty/Stats if applicable
    if (customerId) {
       const customer = salesStore.customers.find(c => c.id === customerId);
       if (customer) {
          // Add points (e.g., 1 point per 10000 Kip based on config)
          const earnRate = systemStore.settings.loyaltyProgram?.earnRate || 10000;
          const pointsEarned = Math.floor(total / earnRate);
          const newPoints = (customer.loyaltyPoints || 0) - (pointsRedeemed || 0) + pointsEarned;

          salesStore.updateCustomer({
             ...customer,
             loyaltyPoints: newPoints
          });
       }
    }

    return newSale;
  };

  const handleVoidSale = (id: string) => {
    const sale = salesStore.sales.find(s => s.id === id);
    if (sale && sale.status !== 'voided') {
      salesStore.updateSale({ ...sale, status: 'voided' });

      // Restore Inventory
      sale.items.forEach(item => {
        inventoryStore.updateProductStock(item.id, item.quantity);
      });

      // Log Audit
      if (systemStore.currentUser) {
         systemStore.logAction({
            id: `aud-${Date.now()}`,
            action: 'SALE_VOID',
            userId: systemStore.currentUser.id,
            userName: systemStore.currentUser.name,
            details: `Voided Sale #${id}`,
            timestamp: new Date().toISOString(),
            severity: 'high',
            resourceId: id
         });
      }
    }
  };

  const settleSaleDebt = async (id: string, amount: number, method: string) => {
     const sale = salesStore.sales.find(s => s.id === id);
     if (sale) {
        const newPaid = (sale.amountReceived || 0) + amount;
        const newRemaining = Math.max(0, (sale.remainingAmount || sale.total) - amount);

        salesStore.updateSale({
           ...sale,
           amountReceived: newPaid,
           remainingAmount: newRemaining,
           paymentStatus: newRemaining <= 0.01 ? 'paid' : 'partial'
        });

        // Add cash transaction if settled via cash (Debt payments ARE Cash In events not tracked by sales creation)
        if (method === 'cash') {
           const shift = salesStore.shifts.find(s => s.userId === systemStore.currentUser?.id && s.status === 'Open');
           if (shift) {
              salesStore.addCashTransaction({
                 id: `ctx-${Date.now()}`,
                 shiftId: shift.id,
                 userId: shift.userId,
                 type: 'in',
                 amount: amount,
                 reason: `Debt Settle #${sale.id.slice(-6)}`,
                 timestamp: new Date().toISOString()
              });
           }
        }
     }
  };

  const processReturn = async (originalSale: Sale, itemsToReturn: { itemIndex: number, quantity: number }[], refundMethod: string) => {
     // Create a return record (negative sale)
     const returnItems: CartItem[] = [];
     let refundTotal = 0;

     itemsToReturn.forEach(({ itemIndex, quantity }) => {
        const originalItem = originalSale.items[itemIndex];
        if (originalItem) {
           returnItems.push({
              ...originalItem,
              quantity: quantity
           });
           refundTotal += originalItem.sellPrice * quantity;

           // Restore Stock
           inventoryStore.updateProductStock(originalItem.id, quantity);
        }
     });

     const returnSale: Sale = {
        id: `R-${Date.now()}`,
        type: 'return',
        originalSaleId: originalSale.id,
        items: returnItems,
        total: -refundTotal,
        date: new Date().toISOString(),
        paymentMethod: refundMethod as any,
        paymentStatus: 'paid', // Refunded immediately
        status: 'completed',
        syncStatus: 'pending',
        customerId: originalSale.customerId,
        customerName: originalSale.customerName,
        userId: systemStore.currentUser?.id,
        userName: systemStore.currentUser?.name,
     };

     salesStore.addSale(returnSale);
  };

  const handleStockStatusChange = (type: 'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment', id: string, status: DocumentStatus) => {
    // 1. Update Document Status
    const docList = stockStore[type === 'transfer' ? 'transfers' : type === 'count' ? 'counts' : type === 'reservation' ? 'reservations' : type === 'receipt' ? 'receipts' : 'adjustments'];
    const doc = docList.find((d: any) => d.id === id);
    if (!doc) return;

    stockStore.updateDocument(type === 'transfer' ? 'transfers' : type === 'count' ? 'counts' : type === 'reservation' ? 'reservations' : type === 'receipt' ? 'receipts' : 'adjustments', { ...doc, status });

    // 2. Effectuate Stock Changes if approved/completed
    if (status === 'Completed' || status === 'Approved') {
       if (type === 'transfer') {
          const t = doc as StockTransfer;
          // In local mode, we might not move stock across different "warehouses" effectively if product only tracks total stock in main inventoryStore.
          // But theoretically we could if inventoryStore.products supported per-warehouse stock.
          // For now, simplify to just status update.
       }
       else if (type === 'receipt') {
          const r = doc as StockReceipt;
          r.items.forEach(item => {
             inventoryStore.updateProductStock(item.productId, item.quantity);
          });
       }
       else if (type === 'adjustment') {
          const a = doc as StockAdjustment;
          a.items.forEach(item => {
             inventoryStore.updateProductStock(item.productId, item.quantity); // Quantity can be negative
          });
       }
       else if (type === 'count') {
          const c = doc as StockCount;
          c.items.forEach(item => {
             // For count, we usually replace stock or adjust by diff.
             // item.diff = counted - system. 
             if (item.diff) {
                inventoryStore.updateProductStock(item.productId, item.diff);
             }
          });
       }
    }
  };

  const startShift = (branchId: string, startCash: number, notes?: string, posId?: string) => {
    if (!systemStore.currentUser) return;
    salesStore.startShift({
      id: `sh-${Date.now()}`,
      userId: systemStore.currentUser.id,
      branchId,
      posId,
      startTime: new Date().toISOString(),
      startCash,
      notes,
      status: 'Open',
      cashTransactions: []
    });
  };

  const endShift = (shiftId: string, endCash: number, notes?: string) => {
    salesStore.endShift(shiftId, {
      endTime: new Date().toISOString(),
      endCash,
      notes,
      status: 'Closed'
    });
  };

  const addCashTransaction = (type: 'in' | 'out', amount: number, reason: string) => {
     const shift = salesStore.shifts.find(s => s.userId === systemStore.currentUser?.id && s.status === 'Open');
     if (shift) {
        salesStore.addCashTransaction({
           id: `ctx-${Date.now()}`,
           shiftId: shift.id,
           userId: shift.userId,
           type,
           amount,
           reason,
           timestamp: new Date().toISOString()
        });
     }
  };

  const handleSyncOperation = (type: 'Auto' | 'Manual' | 'Push' | 'Pull', targetBranchIds: string[] = []) => {
     // Mock Sync Logic - Pure Client Side Simulation
     const start = Date.now();

     // Simulate network delay
     setTimeout(() => {
        const duration = Date.now() - start;
        let details = `Synced successfully (${salesStore.sales.length} records checked)`;

        if (targetBranchIds.length > 0) {
           const targetNames = systemStore.branches.filter(b => targetBranchIds.includes(b.id)).map(b => b.name).join(', ');
           details = `Synced with: ${targetNames}`;
        }

        systemStore.addSyncLog({
           id: `log-${Date.now()}`,
           timestamp: new Date().toISOString(),
           type,
           status: 'Success',
           details: details,
           durationMs: duration
        });

        // Update sync status on sales (Simulate server confirming sync)
        salesStore.sales.forEach(s => {
           if (s.syncStatus === 'pending') {
              salesStore.updateSale({ ...s, syncStatus: 'synced' });
           }
        });
     }, 1000);
  };

  const restoreSystemData = (data: any) => {
     systemStore.restoreSystemData(data);
     inventoryStore.restoreInventoryData(data);
     salesStore.restoreSalesData(data);
     stockStore.restoreStockData(data);
  };

  return (
    <GlobalContext.Provider value={{
      // System
      currentUser: systemStore.currentUser,
      setCurrentUser: systemStore.setCurrentUser,
      users: systemStore.users,
      addUser: systemStore.addUser,
      updateUser: systemStore.updateUser,
      deleteUser: systemStore.deleteUser,

      departments: systemStore.departments,
      addDepartment: systemStore.addDepartment,
      updateDepartment: systemStore.updateDepartment,
      deleteDepartment: systemStore.deleteDepartment,

      systemRoles: systemStore.systemRoles,
      addSystemRole: systemStore.addSystemRole,
      updateSystemRole: systemStore.updateSystemRole,
      deleteSystemRole: systemStore.deleteSystemRole,

      settings: systemStore.settings,
      updateSettings: systemStore.updateSettings,
      notifications: systemStore.notifications,
      markNotificationRead: systemStore.markNotificationRead,
      clearAllNotifications: systemStore.clearAllNotifications,
      auditLogs: systemStore.auditLogs,
      syncLogs: systemStore.syncLogs,

      // Inventory
      products: inventoryStore.products,
      addProduct: inventoryStore.addProduct,
      updateProduct: inventoryStore.updateProduct,
      deleteProduct: inventoryStore.deleteProduct,
      units: inventoryStore.units,
      addUnit: inventoryStore.addUnit,
      updateUnit: inventoryStore.updateUnit,
      deleteUnit: inventoryStore.deleteUnit,
      categories: inventoryStore.categories,
      addCategory: inventoryStore.addCategory,
      updateCategory: inventoryStore.updateCategory,
      deleteCategory: inventoryStore.deleteCategory,
      attributes: inventoryStore.attributes,
      addAttribute: inventoryStore.addAttribute,
      updateAttribute: inventoryStore.updateAttribute,
      deleteAttribute: inventoryStore.deleteAttribute,

      // Sales
      sales: salesStore.sales,
      processSale,
      handleVoidSale,
      settleSaleDebt,
      processReturn,
      customers: salesStore.customers,
      addCustomer: salesStore.addCustomer,
      updateCustomer: salesStore.updateCustomer,
      deleteCustomer: salesStore.deleteCustomer,
      customerLevels: salesStore.customerLevels,
      addCustomerLevel: salesStore.addCustomerLevel,
      updateCustomerLevel: salesStore.updateCustomerLevel,
      deleteCustomerLevel: salesStore.deleteCustomerLevel,
      promotions: salesStore.promotions,
      addPromotion: salesStore.addPromotion,
      updatePromotion: salesStore.updatePromotion,
      deletePromotion: salesStore.deletePromotion,

      // Shifts
      shifts: salesStore.shifts,
      startShift,
      endShift,
      addCashTransaction,
      shiftSchedules: salesStore.shiftSchedules,
      addShiftSchedule: salesStore.addShiftSchedule,
      updateShiftSchedule: salesStore.updateShiftSchedule,
      deleteShiftSchedule: salesStore.deleteShiftSchedule,

      // Locations & Stock
      branches: systemStore.branches,
      addBranch: systemStore.addBranch,
      updateBranch: systemStore.updateBranch,
      deleteBranch: systemStore.deleteBranch,
      posMachines: systemStore.posMachines,
      addPos: systemStore.addPos,
      updatePos: systemStore.updatePos,
      deletePos: systemStore.deletePos,
      warehouses: stockStore.warehouses,
      addWarehouse: stockStore.addWarehouse,
      updateWarehouse: stockStore.updateWarehouse,
      deleteWarehouse: stockStore.deleteWarehouse,
      locations: stockStore.locations,
      addLocation: stockStore.addLocation,
      updateLocation: stockStore.updateLocation,
      deleteLocation: stockStore.deleteLocation,

      transfers: stockStore.transfers,
      updateTransfer: (t) => stockStore.updateDocument('transfers', t),
      deleteTransfer: (id) => stockStore.deleteDocument('transfers', id),
      counts: stockStore.counts,
      updateCount: (c) => stockStore.updateDocument('counts', c),
      deleteCount: (id) => stockStore.deleteDocument('counts', id),
      reservations: stockStore.reservations,
      updateReservation: (r) => stockStore.updateDocument('reservations', r),
      deleteReservation: (id) => stockStore.deleteDocument('reservations', id),
      receipts: stockStore.receipts,
      updateReceipt: (r) => stockStore.updateDocument('receipts', r),
      deleteReceipt: (id) => stockStore.deleteDocument('receipts', id),
      adjustments: stockStore.adjustments,
      updateAdjustment: (a) => stockStore.updateDocument('adjustments', a),
      deleteAdjustment: (id) => stockStore.deleteDocument('adjustments', id),

      handleStockStatusChange,
      handleSyncOperation,
      restoreSystemData,

      t,
      formatPrice
    }}>
      {children}
    </GlobalContext.Provider>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Product, ProductVariant, UnitDefinition, CategoryItem, VariantAttribute, CustomerLevel, ProductInventory, Branch } from '../../types';
import { Box, Scale, DollarSign, Layers, X, Check, Store } from 'lucide-react';
import { GeneralTab } from './product-form/GeneralTab';
import { PhysicalTab } from './product-form/PhysicalTab';
import { PricingTab } from './product-form/PricingTab';
import { VariantsTab } from './product-form/VariantsTab';
import { BranchPricingTab } from './product-form/BranchPricingTab';

interface ProductFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (product: Product) => void;
  initialData?: Product;
  categories: CategoryItem[];
  units: UnitDefinition[];
  attributes: VariantAttribute[];
  currencySymbol: string;
  customerLevels: CustomerLevel[];
  branches: Branch[];
}

const MAX_FILE_SIZE_MB = 5;

export const ProductFormModal: React.FC<ProductFormModalProps> = ({
  isOpen, onClose, onSubmit, initialData, categories, units, attributes, currencySymbol, customerLevels, branches
}) => {
  const [activeTab, setActiveTab] = useState<'general' | 'physical' | 'pricing' | 'branch-pricing' | 'variants'>('general');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<Product>>({
    name: '', sku: '', barcode: '', category: '', price: 0, costPrice: 0,
    stock: 0, minStock: 20, unit: '', physical: { weight: 0, width: 0, height: 0, depth: 0 },
    branchPrices: [], imageUrl: '', tierPrices: {}
  });

  const [variants, setVariants] = useState<Partial<ProductVariant>[]>([]);

  useEffect(() => {
    if (initialData) {
      setFormData({ ...initialData, tierPrices: initialData.tierPrices || {}, branchPrices: initialData.branchPrices || [] });

      // Map existing warehouse inventory to the variant 'stock' property for the UI
      const mappedVariants = initialData.variants ? initialData.variants.map(v => {
         const variantStock = initialData.warehouseInventory?.filter(i => i.variantId === v.id)
            .reduce((acc, inv) => acc + inv.quantity, 0);
         return {
            ...v,
            stock: variantStock !== undefined ? variantStock : 0
         };
      }) : [];
      setVariants(mappedVariants);
    } else {
      setFormData({
        name: '', sku: '', barcode: '', category: categories[0]?.id || '', price: 0, costPrice: 0,
        stock: 0, minStock: 20, unit: units[0]?.symbol || 'pc',
        physical: { weight: 0, width: 0, height: 0, depth: 0 }, branchPrices: [], imageUrl: '', tierPrices: {}
      });
      setVariants([]);
    }
    setActiveTab('general');
  }, [initialData, isOpen, categories, units]);

  if (!isOpen) return null;

  const categoryOptions: { id: string; name: string; level: number }[] = [];
  const buildCatOptions = (parentId: string | null, level: number) => {
    categories.filter(c => c.parentId === parentId).forEach(c => {
      categoryOptions.push({ id: c.id, name: c.name, level });
      buildCatOptions(c.id, level + 1);
    });
  };
  buildCatOptions(null, 0);

  const unitsByCategory = units.reduce((acc, unit) => {
    if (!acc[unit.category]) acc[unit.category] = [];
    acc[unit.category].push(unit);
    return acc;
  }, {} as Record<string, UnitDefinition[]>);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    const isNum = ['price', 'costPrice', 'stock', 'minStock'].includes(name);

    setFormData(prev => ({ ...prev, [name]: isNum ? (parseFloat(value) || 0) : value }));

    if (name === 'price') {
      const newMainPrice = parseFloat(value) || 0;
      // Recalculate variant prices based on their factor
      setVariants(prev => prev.map(v => {
         const factor = v.conversionFactor || 1;
         return { ...v, price: factor !== 0 ? newMainPrice * factor : 0 };
      }));
    }
  };

  const handlePhysicalChange = (field: string, value: string) => {
    setFormData(prev => ({
      ...prev, physical: { ...prev.physical, [field]: parseFloat(value) || 0 }
    }));
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.size > MAX_FILE_SIZE_MB * 1024 * 1024) {
      alert(`File size exceeds ${MAX_FILE_SIZE_MB}MB.`);
      return;
    }
    const reader = new FileReader();
    reader.onloadend = () => setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
    reader.readAsDataURL(file);
  };

  // Variant Logic
  const handleAddVariant = () => {
    const suffix = (variants.length + 1).toString().padStart(3, '0');
    setVariants(prev => [...prev, {
      id: `v-${Date.now()}`,
      name: '', code: `${formData.sku || 'SKU'}-${suffix}`, barcode: formData.barcode ? `${formData.barcode}${suffix}` : '',
      conversionFactor: 1, price: formData.price, stock: 0, costPrice: formData.costPrice,
      attributes: {}, tierPrices: {}
    }]);
  };

  const handleVariantChange = (index: number, field: keyof ProductVariant | 'attributes', value: any, attributeName?: string) => {
    setVariants(prev => {
      const newVars = [...prev];

      if (field === 'attributes' && attributeName) {
         const currentAttrs = newVars[index].attributes || {};
         newVars[index] = { 
            ...newVars[index], 
            attributes: { ...currentAttrs, [attributeName]: value } 
         };
      } else {
         newVars[index] = { 
            ...newVars[index], 
            [field]: field === 'name' ? value : (['price', 'costPrice', 'conversionFactor', 'stock'].includes(field as string) ? parseFloat(value) || 0 : value) 
         };

         // Auto-calculate conversion factor and price when Unit changes
         if (field === 'name') {
            const main = units.find(u => u.symbol === formData.unit);
            const sub = units.find(u => u.symbol === value);
            if (main && sub && main.category === sub.category) {
               // Calculate ratio
               const factor = sub.baseFactor / main.baseFactor;
               newVars[index].conversionFactor = factor;

               // Suggest price based on factor
               newVars[index].price = (formData.price || 0) * factor;
            }
         }

         // Auto-update price when conversion factor is manually changed
         if (field === 'conversionFactor') {
             const factor = parseFloat(value) || 0;
             newVars[index].price = (formData.price || 0) * factor;
         }
      }
      return newVars;
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.name && formData.unit) {

      // Construct Inventory: Base Stock + Variant Stock
      // Note: This simplified logic uses 'wh1' as default warehouse. 
      // In a real scenario, we'd handle multiple warehouses.
      const defaultWarehouse = 'wh1';

      const newInventory: ProductInventory[] = [
         { warehouseId: defaultWarehouse, quantity: formData.stock || 0 } // Base product stock
      ];

      variants.forEach(v => {
         if (v.stock !== undefined && v.stock > 0) {
            newInventory.push({ 
               warehouseId: defaultWarehouse, 
               quantity: v.stock,
               variantId: v.id 
            });
         }
      });

      const productData: Product = {
        ...initialData,
        ...formData as Product,
        id: initialData?.id || `P-${Date.now()}`,
        variants: variants.length > 0 ? variants as ProductVariant[] : undefined,
        warehouseInventory: newInventory,
        // Update aggregated stock for display
        stock: (formData.stock || 0) + variants.reduce((acc, v) => acc + (v.stock || 0), 0)
      };

      onSubmit(productData);
      onClose();
    }
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-5xl max-h-[90vh] flex flex-col overflow-hidden">
        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 shrink-0">
          <h3 className="text-xl font-bold text-slate-800">{initialData ? 'Edit' : 'Add'} Product</h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600"><X className="w-6 h-6" /></button>
        </div>

        <div className="flex border-b border-slate-200 bg-white overflow-x-auto no-scrollbar">
           {[
             { id: 'general', label: 'General Info', icon: Box },
             { id: 'physical', label: 'Physical Attributes', icon: Scale },
             { id: 'pricing', label: 'Base Pricing', icon: DollarSign },
             { id: 'branch-pricing', label: 'Branch Pricing', icon: Store },
             { id: 'variants', label: 'Variants', icon: Layers },
           ].map(tab => (
             <button
               key={tab.id}
               onClick={() => setActiveTab(tab.id as any)}
               className={`flex-1 flex items-center justify-center px-6 py-5 text-lg font-semibold transition-all whitespace-nowrap min-w-fit outline-none focus:outline-none select-none ${
                 activeTab === tab.id ? 'border-b-4 border-construction-orange text-construction-orange bg-orange-50' : 'text-slate-500 hover:text-slate-700 hover:bg-slate-50 border-b-4 border-transparent'
               }`}
             >
               <tab.icon className="w-6 h-6 mr-3" />
               {tab.label}
             </button>
           ))}
        </div>

        <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto p-6 bg-slate-50/50">
          {activeTab === 'general' && (
            <GeneralTab 
              formData={formData} 
              setFormData={setFormData} 
              handleInputChange={handleInputChange} 
              categoryOptions={categoryOptions} 
              units={units}
              fileInputRef={fileInputRef}
              handleImageUpload={handleImageUpload}
            />
          )}

          {activeTab === 'physical' && (
             <PhysicalTab formData={formData} handlePhysicalChange={handlePhysicalChange} />
          )}

          {activeTab === 'pricing' && (
            <PricingTab 
              formData={formData} 
              setFormData={setFormData}
              handleInputChange={handleInputChange} 
              currencySymbol={currencySymbol} 
              customerLevels={customerLevels} 
            />
          )}

          {activeTab === 'branch-pricing' && (
            <BranchPricingTab 
              formData={formData} 
              setFormData={setFormData} 
              branches={branches}
              currencySymbol={currencySymbol}
            />
          )}

          {activeTab === 'variants' && (
            <VariantsTab 
              variants={variants} 
              setVariants={setVariants} 
              handleAddVariant={handleAddVariant} 
              handleVariantChange={handleVariantChange} 
              unitsByCategory={unitsByCategory}
              availableAttributes={attributes}
              baseCostPrice={formData.costPrice || 0}
            />
          )}
        </form>

        <div className="p-4 border-t border-slate-100 flex justify-end space-x-3 bg-white shrink-0">
            <button onClick={onClose} className="px-5 py-2 text-slate-600 font-medium hover:bg-slate-100 rounded-lg">Cancel</button>
            <button type="button" onClick={handleSubmit} className="px-5 py-2 bg-construction-orange text-white font-medium rounded-lg hover:bg-orange-600 shadow-sm flex items-center"><Check className="w-4 h-4 mr-2" /> Save</button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { ProductVariant, UnitDefinition, VariantAttribute } from '../../../types';
import { Plus, Trash2, Tag, Barcode, CheckSquare, Square, ArrowRightLeft, Box, Sparkles, TrendingUp, Info } from 'lucide-react';

interface VariantsTabProps {
  variants: Partial<ProductVariant>[];
  setVariants: React.Dispatch<React.SetStateAction<Partial<ProductVariant>[]>>;
  handleAddVariant: () => void;
  handleVariantChange: (index: number, field: keyof ProductVariant | 'attributes', value: any, attributeName?: string) => void;
  unitsByCategory: Record<string, UnitDefinition[]>;
  availableAttributes: VariantAttribute[];
  baseCostPrice: number;
}

export const VariantsTab: React.FC<VariantsTabProps> = ({
  variants, setVariants, handleAddVariant, handleVariantChange, unitsByCategory, availableAttributes, baseCostPrice
}) => {
  // Local state to track which attributes are "enabled" for this product form
  const [activeAttributeIds, setActiveAttributeIds] = useState<string[]>([]);
  const [suggestionOpenIndex, setSuggestionOpenIndex] = useState<number | null>(null);
  const suggestionRef = useRef<HTMLDivElement>(null);

  // Initialize active attributes based on existing variant data
  useEffect(() => {
    if (variants.length > 0) {
      const usedAttrs = new Set<string>();
      variants.forEach(v => {
        if (v.attributes) {
          Object.keys(v.attributes).forEach(attrName => {
             const attrDef = availableAttributes.find(a => a.name === attrName);
             if (attrDef) usedAttrs.add(attrDef.id);
          });
        }
      });
      if (usedAttrs.size > 0) {
         setActiveAttributeIds(Array.from(usedAttrs));
      }
    }
  }, []); // Run once on mount

  // Close suggestion dropdown when clicking outside
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (suggestionRef.current && !suggestionRef.current.contains(event.target as Node)) {
        setSuggestionOpenIndex(null);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const toggleAttribute = (attrId: string) => {
    if (activeAttributeIds.includes(attrId)) {
      setActiveAttributeIds(prev => prev.filter(id => id !== attrId));
    } else {
      setActiveAttributeIds(prev => [...prev, attrId]);
    }
  };

  const activeAttributes = availableAttributes.filter(a => activeAttributeIds.includes(a.id));

  // Generate suggestions based on cost
  const getPriceSuggestions = (variant: Partial<ProductVariant>) => {
    const factor = variant.conversionFactor || 1;
    // Use base cost if variant doesn't have specific override (currently we only have base cost in form)
    const cost = baseCostPrice * factor;

    if (cost <= 0) return null;

    return [
      { label: 'Low Margin (20%)', price: cost * 1.2, color: 'text-yellow-600 bg-yellow-50 border-yellow-100', icon: TrendingUp },
      { label: 'Standard (35%)', price: cost * 1.35, color: 'text-blue-600 bg-blue-50 border-blue-100', icon: Tag },
      { label: 'High Margin (50%)', price: cost * 1.5, color: 'text-green-600 bg-green-50 border-green-100', icon: TrendingUp },
      { label: 'AI Market Analysis', price: cost * 1.42, color: 'text-purple-600 bg-purple-50 border-purple-100', icon: Sparkles, note: 'Based on competitor data' }
    ];
  };

  const applySuggestedPrice = (index: number, price: number) => {
    handleVariantChange(index, 'price', price.toFixed(2));
    setSuggestionOpenIndex(null);
  };

  return (
    <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm animate-fade-in" style={{ minHeight: '400px' }}>
       {/* Attribute Selector Section */}
       <div className="mb-6 p-4 bg-slate-50 rounded-xl border border-slate-100">
          <h5 className="font-bold text-slate-700 text-sm mb-3">Select Active Attributes</h5>
          <div className="flex flex-wrap gap-3">
             {availableAttributes.length === 0 ? (
                <p className="text-xs text-slate-400 italic">No global attributes defined. Go to Unit Mgmt to add attributes.</p>
             ) : (
                availableAttributes.map(attr => {
                   const isActive = activeAttributeIds.includes(attr.id);
                   return (
                      <button
                         key={attr.id}
                         type="button"
                         onClick={() => toggleAttribute(attr.id)}
                         className={`flex items-center px-3 py-1.5 rounded-lg text-sm border transition-all ${
                            isActive 
                               ? 'bg-indigo-50 border-indigo-200 text-indigo-700 font-bold' 
                               : 'bg-white border-slate-200 text-slate-600 hover:border-slate-300'
                         }`}
                      >
                         {isActive ? <CheckSquare className="w-4 h-4 mr-2" /> : <Square className="w-4 h-4 mr-2 text-slate-400" />}
                         {attr.name}
                      </button>
                   );
                })
             )}
          </div>
       </div>

       <div className="flex justify-between items-center mb-6">
         <div>
            <h4 className="font-bold text-slate-800 flex items-center">
               <Tag className="w-5 h-5 mr-2 text-slate-500" />
               Product Variants
            </h4>
            <p className="text-xs text-slate-500 mt-1">Define different versions (size, color, unit) with specific pricing and stock.</p>
         </div>
         <button 
            type="button" 
            onClick={handleAddVariant} 
            className="text-sm flex items-center text-white font-bold bg-slate-900 px-4 py-2 rounded-lg hover:bg-slate-800 transition-colors shadow-sm"
         >
            <Plus className="w-4 h-4 mr-1.5" /> Add Variant
         </button>
       </div>

       <div className="space-y-4 pb-20">
          {variants.map((v, i) => {
             const suggestions = getPriceSuggestions(v);
             const hasSuggestions = suggestions !== null;

             return (
             <div key={i} className="bg-slate-50 p-5 rounded-xl border border-slate-200 relative group transition-all hover:shadow-md hover:border-slate-300">
                <button 
                   type="button" 
                   onClick={() => setVariants(prev => prev.filter((_, idx) => idx !== i))} 
                   className="absolute top-3 right-3 p-1.5 text-slate-400 hover:text-red-500 bg-white rounded-lg border border-slate-200 shadow-sm transition-colors z-10"
                   title="Remove Variant"
                >
                   <Trash2 className="w-4 h-4" />
                </button>

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-6 gap-4">
                   {/* Unit Selection */}
                   <div className="lg:col-span-1">
                      <label className="block text-xs font-bold text-slate-500 mb-1.5 uppercase">Unit / Type</label>
                      <select 
                         value={v.name} 
                         onChange={e => handleVariantChange(i, 'name', e.target.value)} 
                         className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm bg-white focus:ring-2 focus:ring-slate-400 outline-none"
                      >
                         <option value="">Select Unit</option>
                         {Object.entries(unitsByCategory).map(([c, uList]) => (
                           <optgroup key={c} label={c}>
                             {(uList as UnitDefinition[]).map(u => <option key={u.id} value={u.symbol}>{u.name} ({u.symbol})</option>)}
                           </optgroup>
                         ))}
                      </select>
                   </div>

                   {/* Dynamic Attributes */}
                   {activeAttributes.map(attr => (
                      <div key={attr.id} className="lg:col-span-1">
                         <label className="block text-xs font-bold text-slate-500 mb-1.5 uppercase">{attr.name}</label>
                         <select
                            value={v.attributes?.[attr.name] || ''}
                            onChange={e => handleVariantChange(i, 'attributes', e.target.value, attr.name)}
                            className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm bg-white focus:ring-2 focus:ring-indigo-400 outline-none"
                         >
                            <option value="">Any</option>
                            {attr.values.map(val => (
                               <option key={val} value={val}>{val}</option>
                            ))}
                         </select>
                      </div>
                   ))}

                   {/* Conversion Factor */}
                   <div className="lg:col-span-1">
                      <label className="block text-xs font-bold text-slate-500 mb-1.5 uppercase">Factor</label>
                      <div className="relative">
                         <input 
                            type="number" 
                            min="0"
                            step="0.01"
                            value={v.conversionFactor} 
                            onChange={e => handleVariantChange(i, 'conversionFactor', e.target.value)} 
                            className="w-full px-2 py-2 border border-slate-300 rounded-lg text-sm font-bold text-center focus:ring-2 focus:ring-indigo-400 outline-none" 
                            title="How many base units this variant contains"
                         />
                      </div>
                   </div>

                   {/* SKU / Code */}
                   <div className="lg:col-span-1">
                      <label className="block text-xs font-bold text-slate-500 mb-1.5 uppercase">SKU Code</label>
                      <div className="relative">
                         <Barcode className="absolute left-3 top-2.5 w-3 h-3 text-slate-400" />
                         <input 
                            type="text" 
                            value={v.code} 
                            onChange={e => handleVariantChange(i, 'code', e.target.value)} 
                            placeholder="SKU-001" 
                            className="w-full pl-8 pr-3 py-2 border border-slate-300 rounded-lg text-sm font-mono focus:ring-2 focus:ring-slate-400 outline-none" 
                         />
                      </div>
                   </div>

                   {/* Stock Input */}
                   <div className="lg:col-span-1">
                      <label className="block text-xs font-bold text-slate-500 mb-1.5 uppercase">Stock Qty</label>
                      <div className="relative">
                         <Box className="absolute left-3 top-2.5 w-3 h-3 text-slate-400" />
                         <input 
                            type="number" 
                            min="0"
                            value={v.stock || 0} 
                            onChange={e => handleVariantChange(i, 'stock', e.target.value)} 
                            className="w-full pl-8 pr-3 py-2 border border-slate-300 rounded-lg text-sm font-bold bg-white focus:ring-2 focus:ring-blue-500 outline-none" 
                         />
                      </div>
                   </div>

                   {/* Selling Price with AI Suggestion */}
                   <div className="lg:col-span-1 relative">
                      <label className="block text-xs font-bold text-slate-500 mb-1.5 uppercase flex justify-between">
                         Price
                         {hasSuggestions && (
                            <button 
                               type="button" 
                               onClick={() => setSuggestionOpenIndex(suggestionOpenIndex === i ? null : i)}
                               className="text-purple-600 hover:text-purple-800 transition-colors"
                               title="Get Price Suggestions"
                            >
                               <Sparkles className="w-3.5 h-3.5" />
                            </button>
                         )}
                      </label>
                      <input 
                         type="number" 
                         min="0" 
                         step="0.01"
                         value={v.price} 
                         onChange={e => handleVariantChange(i, 'price', e.target.value)} 
                         placeholder="0.00" 
                         className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm font-bold text-slate-900 bg-white focus:ring-2 focus:ring-blue-500 outline-none" 
                      />

                      {/* Suggestions Popover */}
                      {suggestionOpenIndex === i && hasSuggestions && (
                         <div ref={suggestionRef} className="absolute top-full right-0 mt-2 w-64 bg-white rounded-xl shadow-xl border border-slate-200 z-50 overflow-hidden animate-fade-in">
                            <div className="bg-purple-50 p-3 border-b border-purple-100 flex justify-between items-center">
                               <h6 className="font-bold text-xs text-purple-900 flex items-center">
                                  <Sparkles className="w-3 h-3 mr-1.5" /> Price Suggestions
                               </h6>
                               <span className="text-[10px] text-purple-700 font-mono">Cost: {(baseCostPrice * (v.conversionFactor || 1)).toFixed(2)}</span>
                            </div>
                            <div className="p-2 space-y-1">
                               {suggestions.map((s, idx) => {
                                  const Icon = s.icon;
                                  return (
                                     <button
                                        key={idx}
                                        type="button"
                                        onClick={() => applySuggestedPrice(i, s.price)}
                                        className={`w-full text-left p-2 rounded-lg text-xs hover:shadow-sm transition-all flex items-center justify-between group ${s.color} bg-opacity-30 border border-opacity-50`}
                                     >
                                        <div className="flex items-center">
                                           <Icon className="w-3.5 h-3.5 mr-2 opacity-70" />
                                           <div className="flex flex-col">
                                              <span className="font-bold">{s.label}</span>
                                              {s.note && <span className="text-[9px] opacity-70">{s.note}</span>}
                                           </div>
                                        </div>
                                        <span className="font-bold text-sm">{s.price.toFixed(2)}</span>
                                     </button>
                                  );
                               })}
                            </div>
                         </div>
                      )}
                   </div>
                </div>

                {/* Hints */}
                <div className="mt-2 flex flex-wrap gap-2">
                   {v.name && v.conversionFactor && (
                      <span className="text-[10px] text-slate-500 bg-slate-100 px-2 py-1 rounded border border-slate-200">
                         1 <strong>{v.name}</strong> = <strong>{v.conversionFactor}</strong> base units
                      </span>
                   )}
                </div>
             </div>
          })}

          {variants.length === 0 && (
             <div className="text-center py-12 text-slate-400 border-2 border-dashed border-slate-200 rounded-xl bg-slate-50">
                <Tag className="w-12 h-12 mx-auto mb-3 opacity-20" />
                <p className="font-medium text-sm">No variants added yet.</p>
                <p className="text-xs mt-1">Add variants for different sizes, colors, or units with custom pricing and stock.</p>
             </div>
          )}
       </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Product, ProductVariant, UnitDefinition, CategoryItem, VariantAttribute, CustomerLevel, ProductInventory, Branch } from '../../types';
import { Box, Scale, DollarSign, Layers, X, Check, Store } from 'lucide-react';
import { GeneralTab } from './product-form/GeneralTab';
import { PhysicalTab } from './product-form/PhysicalTab';
import { PricingTab } from './product-form/PricingTab';
import { VariantsTab } from './product-form/VariantsTab';
import { BranchPricingTab } from './product-form/BranchPricingTab';

interface ProductFormModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSubmit: (product: Product) => void;
  initialData?: Product;
  categories: CategoryItem[];
  units: UnitDefinition[];
  attributes: VariantAttribute[];
  currencySymbol: string;
  customerLevels: CustomerLevel[];
  branches: Branch[];
}

const MAX_FILE_SIZE_MB = 5;

export const ProductFormModal: React.FC<ProductFormModalProps> = ({
  isOpen, onClose, onSubmit, initialData, categories, units, attributes, currencySymbol, customerLevels, branches
}) => {
  const [activeTab, setActiveTab] = useState<'general' | 'physical' | 'pricing' | 'branch-pricing' | 'variants'>('general');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<Product>>({
    name: '', sku: '', barcode: '', category: '', price: 0, costPrice: 0,
    stock: 0, minStock: 20, unit: '', physical: { weight: 0, width: 0, height: 0, depth: 0 },
    branchPrices: [], imageUrl: '', tierPrices: {}
  });

  const [variants, setVariants] = useState<Partial<ProductVariant>[]>([]);

  useEffect(() => {
    if (initialData) {
      setFormData({ ...initialData, tierPrices: initialData.tierPrices || {}, branchPrices: initialData.branchPrices || [] });

      // Map existing warehouse inventory to the variant 'stock' property for the UI
      const mappedVariants = initialData.variants ? initialData.variants.map(v => {
         const variantStock = initialData.warehouseInventory?.filter(i => i.variantId === v.id)
            .reduce((acc, inv) => acc + inv.quantity, 0);
         return {
            ...v,
            stock: variantStock !== undefined ? variantStock : 0
         };
      }) : [];
      setVariants(mappedVariants);
    } else {
      setFormData({
        name: '', sku: '', barcode: '', category: categories[0]?.id || '', price: 0, costPrice: 0,
        stock: 0, minStock: 20, unit: units[0]?.symbol || 'pc',
        physical: { weight: 0, width: 0, height: 0, depth: 0 }, branchPrices: [], imageUrl: '', tierPrices: {}
      });
      setVariants([]);
    }
    setActiveTab('general');
  }, [initialData, isOpen, categories, units]);

  if (!isOpen) return null;

  const categoryOptions: { id: string; name: string; level: number }[] = [];
  const buildCatOptions = (parentId: string | null, level: number) => {
    categories.filter(c => c.parentId === parentId).forEach(c => {
      categoryOptions.push({ id: c.id, name: c.name, level });
      buildCatOptions(c.id, level + 1);
    });
  };
  buildCatOptions(null, 0);

  const unitsByCategory = units.reduce((acc, unit) => {
    if (!acc[unit.category]) acc[unit.category] = [];
    acc[unit.category].push(unit);
    return acc;
  }, {} as Record<string, UnitDefinition[]>);

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    const isNum = ['price', 'costPrice', 'stock', 'minStock'].includes(name);

    setFormData(prev => ({ ...prev, [name]: isNum ? (parseFloat(value) || 0) : value }));

    if (name === 'price') {
      const newMainPrice = parseFloat(value) || 0;
      // Recalculate variant prices based on their factor
      setVariants(prev => prev.map(v => {
         const factor = v.conversionFactor || 1;
         return { ...v, price: factor !== 0 ? newMainPrice * factor : 0 };
      }));
    }
  };

  const handlePhysicalChange = (field: string, value: string) => {
    setFormData(prev => ({
      ...prev, physical: { ...prev.physical, [field]: parseFloat(value) || 0 }
    }));
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    if (file.size > MAX_FILE_SIZE_MB * 1024 * 1024) {
      alert(`File size exceeds ${MAX_FILE_SIZE_MB}MB.`);
      return;
    }
    const reader = new FileReader();
    reader.onloadend = () => setFormData(prev => ({ ...prev, imageUrl: reader.result as string }));
    reader.readAsDataURL(file);
  };

  // Variant Logic
  const handleAddVariant = () => {
    const suffix = (variants.length + 1).toString().padStart(3, '0');
    setVariants(prev => [...prev, {
      id: `v-${Date.now()}`,
      name: '', code: `${formData.sku || 'SKU'}-${suffix}`, barcode: formData.barcode ? `${formData.barcode}${suffix}` : '',
      conversionFactor: 1, price: formData.price, stock: 0, costPrice: formData.costPrice,
      attributes: {}, tierPrices: {}
    }]);
  };

  const handleVariantChange = (index: number, field: keyof ProductVariant | 'attributes', value: any, attributeName?: string) => {
    setVariants(prev => {
      const newVars = [...prev];

      if (field === 'attributes' && attributeName) {
         const currentAttrs = newVars[index].attributes || {};
         newVars[index] = { 
            ...newVars[index], 
            attributes: { ...currentAttrs, [attributeName]: value } 
         };
      } else {
         newVars[index] = { 
            ...newVars[index], 
            [field]: field === 'name' ? value : (['price', 'costPrice', 'conversionFactor', 'stock'].includes(field as string) ? parseFloat(value) || 0 : value) 
         };

         // Auto-calculate conversion factor and price when Unit changes
         if (field === 'name') {
            const main = units.find(u => u.symbol === formData.unit);
            const sub = units.find(u => u.symbol === value);
            if (main && sub && main.category === sub.category) {
               // Calculate ratio
               const factor = sub.baseFactor / main.baseFactor;
               newVars[index].conversionFactor = factor;

               // Suggest price based on factor
               newVars[index].price = (formData.price || 0) * factor;
            }
         }

         // Auto-update price when conversion factor is manually changed
         if (field === 'conversionFactor') {
             const factor = parseFloat(value) || 0;
             newVars[index].price = (formData.price || 0) * factor;
         }
      }
      return newVars;
    });
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (formData.name && formData.unit) {

      // Construct Inventory: Base Stock + Variant Stock
      // Note: This simplified logic uses 'wh1' as default warehouse. 
      // In a real scenario, we'd handle multiple warehouses.
      const defaultWarehouse = 'wh1';

      const newInventory: ProductInventory[] = [
         { warehouseId: defaultWarehouse, quantity: formData.stock || 0 } // Base product stock
      ];

      variants.forEach(v => {
         if (v.stock !== undefined && v.stock > 0) {
            newInventory.push({ 
               warehouseId: defaultWarehouse, 
               quantity: v.stock,
               variantId: v.id 
            });
         }
      });

      const productData: Product = {
        ...initialData,
        ...formData as Product,
        id: initialData?.id || `P-${Date.now()}`,
        variants: variants.length > 0 ? variants as ProductVariant[] : undefined,
        warehouseInventory: newInventory,
        // Update aggregated stock for display
        stock: (formData.stock || 0) + variants.reduce((acc, v) => acc + (v.stock || 0), 0)
      };

      onSubmit(productData);
      onClose();
    }
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-5xl max-h-[90vh] flex flex-col overflow-hidden">
        <div className="p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 shrink-0">
          <h3 className="text-xl font-bold text-slate-800">{initialData ? 'Edit' : 'Add'} Product</h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600"><X className="w-6 h-6" /></button>
        </div>

        <div className="flex border-b border-slate-200 bg-white overflow-x-auto no-scrollbar">
           {[
             { id: 'general', label: 'General Info', icon: Box },
             { id: 'physical', label: 'Physical Attributes', icon: Scale },
             { id: 'pricing', label: 'Base Pricing', icon: DollarSign },
             { id: 'branch-pricing', label: 'Branch Pricing', icon: Store },
             { id: 'variants', label: 'Variants', icon: Layers },
           ].map(tab => (
             <button
               key={tab.id}
               onClick={() => setActiveTab(tab.id as any)}
               className={`flex-1 flex items-center justify-center px-6 py-5 text-lg font-semibold transition-all whitespace-nowrap min-w-fit outline-none focus:outline-none select-none ${
                 activeTab === tab.id ? 'border-b-4 border-construction-orange text-construction-orange bg-orange-50' : 'text-slate-500 hover:text-slate-700 hover:bg-slate-50 border-b-4 border-transparent'
               }`}
             >
               <tab.icon className="w-6 h-6 mr-3" />
               {tab.label}
             </button>
           ))}
        </div>

        <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto p-6 bg-slate-50/50">
          {activeTab === 'general' && (
            <GeneralTab 
              formData={formData} 
              setFormData={setFormData} 
              handleInputChange={handleInputChange} 
              categoryOptions={categoryOptions} 
              units={units}
              fileInputRef={fileInputRef}
              handleImageUpload={handleImageUpload}
            />
          )}

          {activeTab === 'physical' && (
             <PhysicalTab formData={formData} handlePhysicalChange={handlePhysicalChange} />
          )}

          {activeTab === 'pricing' && (
            <PricingTab 
              formData={formData} 
              setFormData={setFormData}
              handleInputChange={handleInputChange} 
              currencySymbol={currencySymbol} 
              customerLevels={customerLevels} 
            />
          )}

          {activeTab === 'branch-pricing' && (
            <BranchPricingTab 
              formData={formData} 
              setFormData={setFormData} 
              branches={branches}
              currencySymbol={currencySymbol}
            />
          )}

          {activeTab === 'variants' && (
            <VariantsTab 
              variants={variants} 
              setVariants={setVariants} 
              handleAddVariant={handleAddVariant} 
              handleVariantChange={handleVariantChange} 
              unitsByCategory={unitsByCategory}
              availableAttributes={attributes}
              baseCostPrice={formData.costPrice || 0}
            />
          )}
        </form>

        <div className="p-4 border-t border-slate-100 flex justify-end space-x-3 bg-white shrink-0">
            <button onClick={onClose} className="px-5 py-2 text-slate-600 font-medium hover:bg-slate-100 rounded-lg">Cancel</button>
            <button type="button" onClick={handleSubmit} className="px-5 py-2 bg-construction-orange text-white font-medium rounded-lg hover:bg-orange-600 shadow-sm flex items-center"><Check className="w-4 h-4 mr-2" /> Save</button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { ProductVariant, UnitDefinition, VariantAttribute } from '../../../types';
import { Plus, Trash2, Tag, Barcode, CheckSquare, Square, ArrowRightLeft, Box, Sparkles, TrendingUp, Info } from 'lucide-react';

interface VariantsTabProps {
  variants: Partial<ProductVariant>[];
  setVariants: React.Dispatch<React.SetStateAction<Partial<ProductVariant>[]>>;
  handleAddVariant: () => void;
  handleVariantChange: (index: number, field: keyof ProductVariant | 'attributes', value: any, attributeName?: string) => void;
  unitsByCategory: Record<string, UnitDefinition[]>;
  availableAttributes: VariantAttribute[];
  baseCostPrice: number;
}

export const VariantsTab: React.FC<VariantsTabProps> = ({
  variants, setVariants, handleAddVariant, handleVariantChange, unitsByCategory, availableAttributes, baseCostPrice
}) => {
  // Local state to track which attributes are "enabled" for this product form
  const [activeAttributeIds, setActiveAttributeIds] = useState<string[]>([]);
  const [suggestionOpenIndex, setSuggestionOpenIndex] = useState<number | null>(null);
  const suggestionRef = useRef<HTMLDivElement>(null);

  // Initialize active attributes based on existing variant data
  useEffect(() => {
    if (variants.length > 0) {
      const usedAttrs = new Set<string>();
      variants.forEach(v => {
        if (v.attributes) {
          Object.keys(v.attributes).forEach(attrName => {
             const attrDef = availableAttributes.find(a => a.name === attrName);
             if (attrDef) usedAttrs.add(attrDef.id);
          });
        }
      });
      if (usedAttrs.size > 0) {
         setActiveAttributeIds(Array.from(usedAttrs));
      }
    }
  }, []); // Run once on mount

  // Close suggestion dropdown when clicking outside
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (suggestionRef.current && !suggestionRef.current.contains(event.target as Node)) {
        setSuggestionOpenIndex(null);
      }
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const toggleAttribute = (attrId: string) => {
    if (activeAttributeIds.includes(attrId)) {
      setActiveAttributeIds(prev => prev.filter(id => id !== attrId));
    } else {
      setActiveAttributeIds(prev => [...prev, attrId]);
    }
  };

  const activeAttributes = availableAttributes.filter(a => activeAttributeIds.includes(a.id));

  // Generate suggestions based on cost
  const getPriceSuggestions = (variant: Partial<ProductVariant>) => {
    const factor = variant.conversionFactor || 1;
    // Use base cost if variant doesn't have specific override (currently we only have base cost in form)
    const cost = baseCostPrice * factor;

    if (cost <= 0) return null;

    return [
      { label: 'Low Margin (20%)', price: cost * 1.2, color: 'text-yellow-600 bg-yellow-50 border-yellow-100', icon: TrendingUp },
      { label: 'Standard (35%)', price: cost * 1.35, color: 'text-blue-600 bg-blue-50 border-blue-100', icon: Tag },
      { label: 'High Margin (50%)', price: cost * 1.5, color: 'text-green-600 bg-green-50 border-green-100', icon: TrendingUp },
      { label: 'AI Market Analysis', price: cost * 1.42, color: 'text-purple-600 bg-purple-50 border-purple-100', icon: Sparkles, note: 'Based on competitor data' }
    ];
  };

  const applySuggestedPrice = (index: number, price: number) => {
    handleVariantChange(index, 'price', price.toFixed(2));
    setSuggestionOpenIndex(null);
  };

  return (
    <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm animate-fade-in" style={{ minHeight: '400px' }}>
       {/* Attribute Selector Section */}
       <div className="mb-6 p-4 bg-slate-50 rounded-xl border border-slate-100">
          <h5 className="font-bold text-slate-700 text-sm mb-3">Select Active Attributes</h5>
          <div className="flex flex-wrap gap-3">
             {availableAttributes.length === 0 ? (
                <p className="text-xs text-slate-400 italic">No global attributes defined. Go to Unit Mgmt to add attributes.</p>
             ) : (
                availableAttributes.map(attr => {
                   const isActive = activeAttributeIds.includes(attr.id);
                   return (
                      <button
                         key={attr.id}
                         type="button"
                         onClick={() => toggleAttribute(attr.id)}
                         className={`flex items-center px-3 py-1.5 rounded-lg text-sm border transition-all ${
                            isActive 
                               ? 'bg-indigo-50 border-indigo-200 text-indigo-700 font-bold' 
                               : 'bg-white border-slate-200 text-slate-600 hover:border-slate-300'
                         }`}
                      >
                         {isActive ? <CheckSquare className="w-4 h-4 mr-2" /> : <Square className="w-4 h-4 mr-2 text-slate-400" />}
                         {attr.name}
                      </button>
                   );
                })
             )}
          </div>
       </div>

       <div className="flex justify-between items-center mb-6">
         <div>
            <h4 className="font-bold text-slate-800 flex items-center">
               <Tag className="w-5 h-5 mr-2 text-slate-500" />
               Product Variants
            </h4>
            <p className="text-xs text-slate-500 mt-1">Define different versions (size, color, unit) with specific pricing and stock.</p>
         </div>
         <button 
            type="button" 
            onClick={handleAddVariant} 
            className="text-sm flex items-center text-white font-bold bg-slate-900 px-4 py-2 rounded-lg hover:bg-slate-800 transition-colors shadow-sm"
         >
            <Plus className="w-4 h-4 mr-1.5" /> Add Variant
         </button>
       </div>

       <div className="space-y-4 pb-20">
          {variants.map((v, i) => {
             const suggestions = getPriceSuggestions(v);
             const hasSuggestions = suggestions !== null;

             return (
             <div key={i} className="bg-slate-50 p-5 rounded-xl border border-slate-200 relative group transition-all hover:shadow-md hover:border-slate-300">
                <button 
                   type="button" 
                   onClick={() => setVariants(prev => prev.filter((_, idx) => idx !== i))} 
                   className="absolute top-3 right-3 p-1.5 text-slate-400 hover:text-red-500 bg-white rounded-lg border border-slate-200 shadow-sm transition-colors z-10"
                   title="Remove Variant"
                >
                   <Trash2 className="w-4 h-4" />
                </button>

                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-6 gap-4">
                   {/* Unit Selection */}
                   <div className="lg:col-span-1">
                      <label className="block text-xs font-bold text-slate-500 mb-1.5 uppercase">Unit / Type</label>
                      <select 
                         value={v.name} 
                         onChange={e => handleVariantChange(i, 'name', e.target.value)} 
                         className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm bg-white focus:ring-2 focus:ring-slate-400 outline-none"
                      >
                         <option value="">Select Unit</option>
                         {Object.entries(unitsByCategory).map(([c, uList]) => (
                           <optgroup key={c} label={c}>
                             {(uList as UnitDefinition[]).map(u => <option key={u.id} value={u.symbol}>{u.name} ({u.symbol})</option>)}
                           </optgroup>
                         ))}
                      </select>
                   </div>

                   {/* Dynamic Attributes */}
                   {activeAttributes.map(attr => (
                      <div key={attr.id} className="lg:col-span-1">
                         <label className="block text-xs font-bold text-slate-500 mb-1.5 uppercase">{attr.name}</label>
                         <select
                            value={v.attributes?.[attr.name] || ''}
                            onChange={e => handleVariantChange(i, 'attributes', e.target.value, attr.name)}
                            className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm bg-white focus:ring-2 focus:ring-indigo-400 outline-none"
                         >
                            <option value="">Any</option>
                            {attr.values.map(val => (
                               <option key={val} value={val}>{val}</option>
                            ))}
                         </select>
                      </div>
                   ))}

                   {/* Conversion Factor */}
                   <div className="lg:col-span-1">
                      <label className="block text-xs font-bold text-slate-500 mb-1.5 uppercase">Factor</label>
                      <div className="relative">
                         <input 
                            type="number" 
                            min="0"
                            step="0.01"
                            value={v.conversionFactor} 
                            onChange={e => handleVariantChange(i, 'conversionFactor', e.target.value)} 
                            className="w-full px-2 py-2 border border-slate-300 rounded-lg text-sm font-bold text-center focus:ring-2 focus:ring-indigo-400 outline-none" 
                            title="How many base units this variant contains"
                         />
                      </div>
                   </div>

                   {/* SKU / Code */}
                   <div className="lg:col-span-1">
                      <label className="block text-xs font-bold text-slate-500 mb-1.5 uppercase">SKU Code</label>
                      <div className="relative">
                         <Barcode className="absolute left-3 top-2.5 w-3 h-3 text-slate-400" />
                         <input 
                            type="text" 
                            value={v.code} 
                            onChange={e => handleVariantChange(i, 'code', e.target.value)} 
                            placeholder="SKU-001" 
                            className="w-full pl-8 pr-3 py-2 border border-slate-300 rounded-lg text-sm font-mono focus:ring-2 focus:ring-slate-400 outline-none" 
                         />
                      </div>
                   </div>

                   {/* Stock Input */}
                   <div className="lg:col-span-1">
                      <label className="block text-xs font-bold text-slate-500 mb-1.5 uppercase">Stock Qty</label>
                      <div className="relative">
                         <Box className="absolute left-3 top-2.5 w-3 h-3 text-slate-400" />
                         <input 
                            type="number" 
                            min="0"
                            value={v.stock || 0} 
                            onChange={e => handleVariantChange(i, 'stock', e.target.value)} 
                            className="w-full pl-8 pr-3 py-2 border border-slate-300 rounded-lg text-sm font-bold bg-white focus:ring-2 focus:ring-blue-500 outline-none" 
                         />
                      </div>
                   </div>

                   {/* Selling Price with AI Suggestion */}
                   <div className="lg:col-span-1 relative">
                      <label className="block text-xs font-bold text-slate-500 mb-1.5 uppercase flex justify-between">
                         Price
                         {hasSuggestions && (
                            <button 
                               type="button" 
                               onClick={() => setSuggestionOpenIndex(suggestionOpenIndex === i ? null : i)}
                               className="text-purple-600 hover:text-purple-800 transition-colors"
                               title="Get Price Suggestions"
                            >
                               <Sparkles className="w-3.5 h-3.5" />
                            </button>
                         )}
                      </label>
                      <input 
                         type="number" 
                         min="0" 
                         step="0.01"
                         value={v.price} 
                         onChange={e => handleVariantChange(i, 'price', e.target.value)} 
                         placeholder="0.00" 
                         className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm font-bold text-slate-900 bg-white focus:ring-2 focus:ring-blue-500 outline-none" 
                      />

                      {/* Suggestions Popover */}
                      {suggestionOpenIndex === i && hasSuggestions && (
                         <div ref={suggestionRef} className="absolute top-full right-0 mt-2 w-64 bg-white rounded-xl shadow-xl border border-slate-200 z-50 overflow-hidden animate-fade-in">
                            <div className="bg-purple-50 p-3 border-b border-purple-100 flex justify-between items-center">
                               <h6 className="font-bold text-xs text-purple-900 flex items-center">
                                  <Sparkles className="w-3 h-3 mr-1.5" /> Price Suggestions
                               </h6>
                               <span className="text-[10px] text-purple-700 font-mono">Cost: {(baseCostPrice * (v.conversionFactor || 1)).toFixed(2)}</span>
                            </div>
                            <div className="p-2 space-y-1">
                               {suggestions.map((s, idx) => {
                                  const Icon = s.icon;
                                  return (
                                     <button
                                        key={idx}
                                        type="button"
                                        onClick={() => applySuggestedPrice(i, s.price)}
                                        className={`w-full text-left p-2 rounded-lg text-xs hover:shadow-sm transition-all flex items-center justify-between group ${s.color} bg-opacity-30 border border-opacity-50`}
                                     >
                                        <div className="flex items-center">
                                           <Icon className="w-3.5 h-3.5 mr-2 opacity-70" />
                                           <div className="flex flex-col">
                                              <span className="font-bold">{s.label}</span>
                                              {s.note && <span className="text-[9px] opacity-70">{s.note}</span>}
                                           </div>
                                        </div>
                                        <span className="font-bold text-sm">{s.price.toFixed(2)}</span>
                                     </button>
                                  );
                               })}
                            </div>
                         </div>
                      )}
                   </div>
                </div>

                {/* Hints */}
                <div className="mt-2 flex flex-wrap gap-2">
                   {v.name && v.conversionFactor && (
                      <span className="text-[10px] text-slate-500 bg-slate-100 px-2 py-1 rounded border border-slate-200">
                         1 <strong>{v.name}</strong> = <strong>{v.conversionFactor}</strong> base units
                      </span>
                   )}
                </div>
             </div>
          })}

          {variants.length === 0 && (
             <div className="text-center py-12 text-slate-400 border-2 border-dashed border-slate-200 rounded-xl bg-slate-50">
                <Tag className="w-12 h-12 mx-auto mb-3 opacity-20" />
                <p className="font-medium text-sm">No variants added yet.</p>
                <p className="text-xs mt-1">Add variants for different sizes, colors, or units with custom pricing and stock.</p>
             </div>
          )}
       </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Customer, CustomerLevel } from '../../types';
import { Search, Plus, User, Phone, Mail, Award, Edit2, Trash2, Star, ChevronRight } from 'lucide-react';

interface CustomerListProps {
  customers: Customer[];
  levels: CustomerLevel[];
  onAdd: () => void;
  onEdit: (customer: Customer) => void;
  onDelete: (id: string) => void;
  onView: (customer: Customer) => void;
}

export const CustomerList: React.FC<CustomerListProps> = ({ 
  customers, 
  levels, 
  onAdd, 
  onEdit, 
  onDelete, 
  onView 
}) => {
  const [searchTerm, setSearchTerm] = useState('');

  const filteredCustomers = customers.filter(c => {
    const term = searchTerm.toLowerCase();
    const nameMatch = (c.name || '').toLowerCase().includes(term);
    const phoneMatch = (c.phone || '').toLowerCase().includes(term);
    const codeMatch = (c.code || '').toLowerCase().includes(term);
    return nameMatch || phoneMatch || codeMatch;
  });

  return (
    <div className="flex flex-col h-full space-y-4">
      {/* Header & Search */}
      <div className="flex flex-col md:flex-row gap-4">
        <div className="relative flex-1 bg-white p-4 rounded-xl shadow-sm border border-slate-200">
          <Search className="absolute left-7 top-1/2 transform -translate-y-1/2 text-slate-400 w-5 h-5" />
          <input
            type="text"
            placeholder="Search by Name, Phone or Code..."
            className="w-full pl-10 pr-4 py-2 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500 text-slate-700"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <button 
          onClick={onAdd}
          className="flex items-center justify-center px-6 py-4 bg-slate-900 text-white rounded-xl hover:bg-slate-800 transition-colors font-bold shadow-sm whitespace-nowrap"
        >
          <Plus className="w-5 h-5 mr-2" />
          Add Customer
        </button>
      </div>

      {/* Card List View */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex-1 flex flex-col">
        <div className="p-4 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
           <h3 className="font-bold text-slate-700">Registered Customers</h3>
           <span className="text-xs font-bold bg-white px-2 py-1 rounded border border-slate-200 text-slate-500">
              {filteredCustomers.length} Total
           </span>
        </div>

        <div className="overflow-y-auto flex-1 p-4 space-y-3 bg-slate-50/50">
          {filteredCustomers.length === 0 ? (
            <div className="text-center py-12 text-slate-400 flex flex-col items-center">
               <div className="w-16 h-16 bg-slate-100 rounded-full flex items-center justify-center mb-3">
                  <User className="w-8 h-8 opacity-20" />
               </div>
               <p>{customers.length > 0 ? `No customers found matching "${searchTerm}"` : "No customers yet."}</p>
            </div>
          ) : (
            filteredCustomers.map((customer) => {
              const level = customer.level || levels.find(l => l.id === customer.levelId);

              return (
                <div 
                  key={customer.id} 
                  onClick={() => onView(customer)}
                  className="bg-white p-4 rounded-xl border border-slate-200 shadow-sm hover:border-blue-400 hover:shadow-md transition-all cursor-pointer group flex flex-col md:flex-row items-start md:items-center gap-4 relative overflow-hidden"
                >
                  {/* Left Highlight Bar based on Level Color */}
                  <div className="absolute left-0 top-0 bottom-0 w-1" style={{ backgroundColor: level?.color || '#e2e8f0' }}></div>

                  {/* Avatar & Info */}
                  <div className="flex items-center flex-1 w-full md:w-auto">
                     <div className="w-12 h-12 rounded-full bg-slate-100 flex items-center justify-center text-slate-500 font-bold text-lg mr-4 border border-slate-200 shrink-0">
                        {customer.name.charAt(0).toUpperCase()}
                     </div>
                     <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2">
                           <h4 className="font-bold text-slate-800 truncate text-base">{customer.name}</h4>
                           <span className="text-[10px] font-mono bg-slate-100 text-slate-500 px-1.5 py-0.5 rounded border border-slate-200">
                              {customer.code}
                           </span>
                        </div>
                        <div className="flex flex-col sm:flex-row sm:items-center text-sm text-slate-500 mt-0.5 gap-x-3">
                           {customer.phone && (
                              <span className="flex items-center"><Phone className="w-3 h-3 mr-1" /> {customer.phone}</span>
                           )}
                           {customer.email && (
                              <span className="flex items-center"><Mail className="w-3 h-3 mr-1" /> {customer.email}</span>
                           )}
                        </div>
                     </div>
                  </div>

                  {/* Status Badges */}
                  <div className="flex items-center gap-3 w-full md:w-auto justify-between md:justify-end pl-16 md:pl-0">
                     {/* Level Badge */}
                     {level ? (
                        <div className="flex items-center px-3 py-1 rounded-full text-xs font-bold border" style={{ 
                           backgroundColor: `${level.color}15`, 
                           borderColor: `${level.color}30`,
                           color: level.color 
                        }}>
                           <Star className="w-3 h-3 mr-1.5 fill-current" />
                           {level.name}
                           <span className="ml-1 opacity-70">(-{level.discountPercentage}%)</span>
                        </div>
                     ) : (
                        <span className="text-xs text-slate-400 font-medium px-2">No Level</span>
                     )}

                     {/* Points Badge */}
                     <div className="flex items-center px-3 py-1 bg-yellow-50 text-yellow-700 rounded-full text-xs font-bold border border-yellow-200">
                        <Award className="w-3 h-3 mr-1.5" />
                        {customer.loyaltyPoints.toLocaleString()} pts
                     </div>
                  </div>

                  {/* Action Buttons (Visible on hover on desktop, always on mobile if needed) */}
                  <div className="flex items-center gap-2 pl-16 md:pl-0 w-full md:w-auto justify-end md:opacity-0 group-hover:opacity-100 transition-opacity">
                     <button 
                        onClick={(e) => { e.stopPropagation(); onEdit(customer); }} 
                        className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                        title="Edit"
                     >
                        <Edit2 className="w-4 h-4" />
                     </button>
                     <button 
                        onClick={(e) => { e.stopPropagation(); onDelete(customer.id); }} 
                        className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                        title="Delete"
                     >
                        <Trash2 className="w-4 h-4" />
                     </button>
                     <ChevronRight className="w-5 h-5 text-slate-300 ml-1" />
                  </div>
                </div>
              );
            })
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Customer, CustomerLevel, Sale } from '../types';
import { useGlobal } from '../context/GlobalContext';
import { Plus, Search } from 'lucide-react';

// Sub-components
import { CustomerList } from './customer/CustomerList';
import { CustomerFormModal } from './customer/CustomerFormModal';
import { LevelManagement } from './customer/LevelManagement';
import { LevelFormModal } from './customer/LevelFormModal';
import { CustomerDetailProfile } from './customer/CustomerDetailProfile';

interface CustomerManagementProps {
  customers: Customer[];
  sales?: Sale[];
  onAddCustomer: (customer: Customer) => void;
  onUpdateCustomer: (customer: Customer) => void;
  onDeleteCustomer: (id: string) => void;
}

export const CustomerManagement: React.FC<CustomerManagementProps> = ({
  customers = [],
  sales = [],
  onAddCustomer,
  onUpdateCustomer,
  onDeleteCustomer
}) => {
  const { 
    customerLevels, 
    addCustomerLevel, 
    updateCustomerLevel, 
    deleteCustomerLevel, 
    formatPrice 
  } = useGlobal();

  const safeLevels = customerLevels || []; 

  const [activeTab, setActiveTab] = useState<'customers' | 'levels'>('customers');
  const [viewingCustomer, setViewingCustomer] = useState<Customer | null>(null);

  // Modal States
  const [isCustomerModalOpen, setIsCustomerModalOpen] = useState(false);
  const [editingCustomer, setEditingCustomer] = useState<Customer | undefined>(undefined);

  const [isLevelModalOpen, setIsLevelModalOpen] = useState(false);
  const [editingLevel, setEditingLevel] = useState<CustomerLevel | undefined>(undefined);

  // --- Handlers for Customer ---
  const handleOpenCustomerModal = (customer?: Customer) => {
    setEditingCustomer(customer);
    setIsCustomerModalOpen(true);
  };

  const handleCustomerSubmit = (customer: Customer) => {
    if (customer.id) {
      onUpdateCustomer(customer);
    } else {
      onAddCustomer({ ...customer, id: `c-${Date.now()}` });
    }
  };

  const handleDeleteCustomer = (id: string) => {
    if(confirm('Are you sure you want to delete this customer?')) {
      onDeleteCustomer(id);
      if (viewingCustomer?.id === id) setViewingCustomer(null);
    }
  };

  // --- Handlers for Levels ---
  const handleOpenLevelModal = (level?: CustomerLevel) => {
    setEditingLevel(level);
    setIsLevelModalOpen(true);
  };

  const handleLevelSubmit = (level: CustomerLevel) => {
    if (level.id) {
      updateCustomerLevel(level);
    } else {
      addCustomerLevel({ ...level, id: `lvl-${Date.now()}` });
    }
  };

  const handleDeleteLevel = (id: string) => {
    if(confirm('Delete this membership level?')) {
      deleteCustomerLevel(id);
    }
  };

  if (viewingCustomer) {
    return (
      <CustomerDetailProfile 
        customer={viewingCustomer}
        sales={sales}
        formatPrice={formatPrice}
        onBack={() => setViewingCustomer(null)}
        onEdit={() => handleOpenCustomerModal(viewingCustomer)}
      />
    );
  }

  return (
    <div className="space-y-6 h-full flex flex-col pb-20 md:pb-0">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">Customer Management</h2>
          <p className="text-slate-500">Manage customer profiles and membership tiers.</p>
        </div>
      </div>

      {/* Style A: Pill Tabs */}
      <div className="flex bg-slate-100 p-1 rounded-xl w-fit">
         <button 
          onClick={() => setActiveTab('customers')}
          className={`px-6 py-2.5 rounded-lg text-sm font-bold transition-all whitespace-nowrap ${
             activeTab === 'customers' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'
          }`}
        >
          Customers
        </button>
        <button 
          onClick={() => setActiveTab('levels')}
          className={`px-6 py-2.5 rounded-lg text-sm font-bold transition-all whitespace-nowrap ${
             activeTab === 'levels' ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500 hover:text-slate-700'
          }`}
        >
          Membership Levels
        </button>
      </div>

      {activeTab === 'customers' && (
        <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden flex-1 flex flex-col">
           <CustomerList 
             customers={customers}
             levels={safeLevels}
             onAdd={() => handleOpenCustomerModal()}
             onEdit={handleOpenCustomerModal}
             onDelete={handleDeleteCustomer}
             onView={setViewingCustomer}
           />
        </div>
      )}

      {activeTab === 'levels' && (
        <LevelManagement 
          levels={safeLevels}
          onAdd={() => handleOpenLevelModal()}
          onEdit={handleOpenLevelModal}
          onDelete={handleDeleteLevel}
        />
      )}

      {/* Modals */}
      <CustomerFormModal 
        isOpen={isCustomerModalOpen}
        onClose={() => setIsCustomerModalOpen(false)}
        onSubmit={handleCustomerSubmit}
        initialData={editingCustomer}
        levels={safeLevels}
      />

      <LevelFormModal 
        isOpen={isLevelModalOpen}
        onClose={() => setIsLevelModalOpen(false)}
        onSubmit={handleLevelSubmit}
        initialData={editingLevel}
      />
    </div>
  );
};

import React, { useMemo, useState } from 'react';
import { 
  StockTransfer, 
  StockCount, 
  StockReservation, 
  StockReceipt, 
  StockAdjustment,
  DocumentStatus,
  Warehouse
} from '../types';
import { 
  ArrowRightLeft, 
  CheckSquare, 
  CalendarClock, 
  Truck, 
  Clock,
  SlidersHorizontal
} from 'lucide-react';
import { ApprovalList } from './approval/ApprovalList';
import { StockDocumentModal } from './stock/StockDocumentModal';
import { useGlobal } from '../context/GlobalContext';

interface ApprovalManagementProps {
  transfers: StockTransfer[];
  counts: StockCount[];
  reservations: StockReservation[];
  receipts: StockReceipt[];
  adjustments: StockAdjustment[];
  warehouses: Warehouse[];
  onStatusChange: (type: 'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment', id: string, status: DocumentStatus) => void;
}

export const ApprovalManagement: React.FC<ApprovalManagementProps> = ({
  transfers,
  counts,
  reservations,
  receipts,
  adjustments,
  warehouses,
  onStatusChange
}) => {
  const { products, updateTransfer, updateCount, updateReservation, updateReceipt, updateAdjustment } = useGlobal();

  // Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [selectedItem, setSelectedItem] = useState<any>(null);
  const [activeTab, setActiveTab] = useState<'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment'>('transfer');

  const getWarehouseName = (id: string) => warehouses.find(w => w.id === id)?.name || id;

  // Flatten and normalize data for the list
  const pendingItems = useMemo(() => {
    const list: any[] = [];

    // 1. Transfers
    transfers.filter(i => i.status === 'Draft').forEach(item => {
      list.push({
        ...item,
        type: 'transfer',
        typeLabel: 'Stock Transfer',
        icon: ArrowRightLeft,
        description: `Transfer from ${getWarehouseName(item.sourceWarehouseId)} to ${getWarehouseName(item.targetWarehouseId)}`,
        color: 'text-blue-600 bg-blue-50 border-blue-200'
      });
    });

    // 2. Stock Counts
    counts.filter(i => i.status === 'Draft').forEach(item => {
      list.push({
        ...item,
        type: 'count',
        typeLabel: 'Stock Audit',
        icon: CheckSquare,
        description: `Audit at ${getWarehouseName(item.warehouseId)} by ${item.counterName}`,
        color: 'text-purple-600 bg-purple-50 border-purple-200'
      });
    });

    // 3. Reservations
    reservations.filter(i => i.status === 'Draft').forEach(item => {
      list.push({
        ...item,
        type: 'reservation',
        typeLabel: 'Reservation',
        icon: CalendarClock,
        description: `Reserved for ${item.customerName}`,
        meta: `Exp: ${new Date(item.expiryDate).toLocaleDateString()}`,
        color: 'text-orange-600 bg-orange-50 border-orange-200'
      });
    });

    // 4. Receipts
    receipts.filter(i => i.status === 'Draft').forEach(item => {
      list.push({
        ...item,
        type: 'receipt',
        typeLabel: 'Goods Receipt',
        icon: Truck,
        description: `Received from ${item.vendorName}`,
        meta: item.vendorInvoiceNo ? `Inv: ${item.vendorInvoiceNo}` : undefined,
        color: 'text-green-600 bg-green-50 border-green-200'
      });
    });

    // 5. Adjustments
    adjustments.filter(i => i.status === 'Draft').forEach(item => {
      list.push({
        ...item,
        type: 'adjustment',
        typeLabel: 'Stock Adjustment',
        icon: SlidersHorizontal,
        description: `Adjustment at ${getWarehouseName(item.warehouseId)}`,
        meta: item.reason,
        color: 'text-pink-600 bg-pink-50 border-pink-200'
      });
    });

    // Sort by date (newest first)
    return list.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [transfers, counts, reservations, receipts, adjustments, warehouses]);

  const handleApprove = (e: React.MouseEvent, item: any) => {
    e.stopPropagation();
    if (window.confirm('Are you sure you want to Approve this request?')) {
      onStatusChange(item.type, item.id, 'Approved');
    }
  };

  const handleReject = (e: React.MouseEvent, item: any) => {
    e.stopPropagation();
    if (window.confirm('Are you sure you want to Reject this request?')) {
      onStatusChange(item.type, item.id, 'Cancelled');
    }
  };

  const handleOpenModal = (item: any) => {
    setSelectedItem(item);
    setActiveTab(item.type);
    setIsModalOpen(true);
  };

  const handleModalSave = (data: any) => {
    // Support Editing before Approval
    switch(activeTab) {
      case 'transfer': updateTransfer(data); break;
      case 'count': updateCount(data); break;
      case 'reservation': updateReservation(data); break;
      case 'receipt': updateReceipt(data); break;
      case 'adjustment': updateAdjustment(data); break;
    }
    // Don't close immediately, user might want to approve next
    alert("Changes saved.");
  };

  const handleModalComplete = (data: any) => {
    // "Complete" in the modal context here effectively means "Approve" for the Draft stage
    // But StockDocumentModal emits onComplete when the 'Complete' button is clicked (usually for Approved -> Completed)
    // We can reuse it to trigger Approval if the current status is Draft.

    if (window.confirm('Approve this document?')) {
        // First save any changes
        handleModalSave(data);
        // Then change status
        onStatusChange(activeTab, data.id, 'Approved');
        setIsModalOpen(false);
    }
  };

  return (
    <div className="space-y-6 h-full flex flex-col pb-20 md:pb-0">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">Approval Center</h2>
          <p className="text-slate-500">Review and approve pending document requests.</p>
        </div>
        <div className="flex items-center space-x-2 bg-white px-4 py-2 rounded-xl shadow-sm border border-slate-200 w-fit">
          <Clock className="w-5 h-5 text-orange-500" />
          <span className="font-bold text-slate-900 text-lg">{pendingItems.length}</span>
          <span className="text-slate-500 text-sm font-medium">Pending</span>
        </div>
      </div>

      <div className="bg-white rounded-2xl shadow-sm border border-slate-100 flex-1 overflow-hidden flex flex-col">
        <ApprovalList 
          items={pendingItems}
          onApprove={handleApprove}
          onReject={handleReject}
          onView={handleOpenModal}
        />
      </div>

      <StockDocumentModal 
        isOpen={isModalOpen}
        onClose={() => setIsModalOpen(false)}
        activeTab={activeTab}
        editingId={selectedItem?.id}
        initialData={selectedItem}
        warehouses={warehouses}
        products={products}
        onSave={handleModalSave}
        onComplete={handleModalComplete}
      />
    </div>
  );
};

import React from 'react';
import { CheckCircle, XCircle } from 'lucide-react';

interface ApprovalItem {
  id: string;
  type: 'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment';
  typeLabel: string;
  icon: any;
  description: string;
  meta?: string;
  color: string;
  referenceNo: string;
  date: string;
  items: any[];
}

interface ApprovalListProps {
  items: ApprovalItem[];
  onApprove: (e: React.MouseEvent, item: ApprovalItem) => void;
  onReject: (e: React.MouseEvent, item: ApprovalItem) => void;
  onView?: (item: ApprovalItem) => void;
}

export const ApprovalList: React.FC<ApprovalListProps> = ({ items, onApprove, onReject, onView }) => {
  if (items.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center flex-1 text-slate-400 p-8">
        <div className="bg-slate-50 p-6 rounded-full mb-4">
          <CheckCircle className="w-12 h-12 text-green-200" />
        </div>
        <h3 className="text-lg font-bold text-slate-700">All caught up!</h3>
        <p className="text-sm">No pending approvals found.</p>
      </div>
    );
  }

  return (
    <div className="overflow-y-auto flex-1 bg-slate-50/50 p-4">
      <div className="grid grid-cols-1 gap-4">
        {items.map((item) => {
          const Icon = item.icon;
          return (
            <div 
                key={item.id} 
                className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex flex-col lg:flex-row gap-5 relative overflow-hidden group hover:shadow-md transition-shadow cursor-pointer"
                onClick={() => onView && onView(item)}
            >
              {/* Left Border Status Indicator */}
              <div className={`absolute left-0 top-0 bottom-0 w-1.5 ${item.color.split(' ')[0].replace('text-', 'bg-')}`}></div>

              <div className="flex-1 flex items-start gap-4">
                <div className={`p-3.5 rounded-xl border shrink-0 ${item.color}`}>
                  <Icon className="w-6 h-6" />
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center flex-wrap gap-2 mb-1.5">
                    <span className={`px-2.5 py-0.5 text-[10px] font-bold uppercase tracking-wider rounded-full border bg-white ${item.color.replace('text-', 'border-').replace('bg-', '')}`}>
                      {item.typeLabel}
                    </span>
                    <span className="text-xs text-slate-400 font-mono flex items-center bg-slate-50 px-2 py-0.5 rounded">
                       {item.referenceNo}
                       <span className="mx-1">•</span>
                       {new Date(item.date).toLocaleDateString()}
                    </span>
                  </div>

                  <h3 className="font-bold text-slate-900 text-lg mb-1 leading-tight">
                    {item.description}
                  </h3>
                  {item.meta && <p className="text-sm text-slate-500 mb-3 bg-slate-50 p-2 rounded-lg border border-slate-100 inline-block">{item.meta}</p>}

                  {/* Compact Items Preview */}
                  <div className="flex flex-wrap gap-2 mt-1">
                     {item.items.slice(0, 3).map((prod: any, idx: number) => {
                       const displayQty = item.type === 'count' ? prod.countedQuantity : prod.quantity;
                       const prefix = (item.type === 'adjustment' && prod.quantity > 0) ? '+' : '';

                       return (
                         <div key={idx} className="flex items-center px-2.5 py-1.5 bg-slate-100 text-slate-700 text-xs rounded-lg border border-slate-200 font-medium">
                           <span className="truncate max-w-[120px]">{prod.productName}</span>
                           <span className={`ml-2 font-bold ${item.type === 'adjustment' && prod.quantity < 0 ? 'text-red-600' : 'text-slate-900'}`}>
                             {prefix}{displayQty}
                           </span>
                         </div>
                       );
                     })}
                     {item.items.length > 3 && (
                       <span className="flex items-center px-2 py-1 bg-slate-100 text-slate-500 text-xs rounded-lg border border-slate-200 font-bold">
                         +{item.items.length - 3} more
                       </span>
                     )}
                  </div>
                </div>
              </div>

              {/* Actions - Full width on Mobile, Side on Desktop */}
              <div className="flex flex-row lg:flex-col xl:flex-row items-center justify-end gap-3 pt-4 lg:pt-0 border-t lg:border-t-0 border-slate-100 lg:pl-4 lg:border-l">
                <button 
                  onClick={(e) => onReject(e, item)}
                  className="flex-1 lg:flex-none flex items-center justify-center px-4 py-3 border-2 border-red-100 text-red-600 rounded-xl hover:bg-red-50 hover:border-red-200 transition-colors font-bold text-sm w-full lg:w-auto"
                >
                  <XCircle className="w-4 h-4 mr-2" />
                  Reject
                </button>
                <button 
                  onClick={(e) => onApprove(e, item)}
                  className="flex-1 lg:flex-none flex items-center justify-center px-6 py-3 bg-slate-900 text-white rounded-xl hover:bg-slate-800 transition-colors font-bold text-sm shadow-md w-full lg:w-auto active:scale-95"
                >
                  <CheckCircle className="w-4 h-4 mr-2" />
                  Approve
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Warehouse, Product } from '../../types';
import { Edit2, Plus, X, AlertCircle, CheckCircle, PlayCircle, ThumbsUp } from 'lucide-react';
import { StockHeaderFields } from './document-form/StockHeaderFields';
import { StockItemsTable } from './document-form/StockItemsTable';

interface StockDocumentModalProps {
  isOpen: boolean;
  onClose: () => void;
  activeTab: 'transfer' | 'count' | 'reservation' | 'receipt' | 'adjustment';
  editingId: string | null;
  initialData: any;
  warehouses: Warehouse[];
  products: Product[];
  onSave: (data: any) => void;
  onComplete: (data: any) => void;
}

export const StockDocumentModal: React.FC<StockDocumentModalProps> = ({
  isOpen, onClose, activeTab, editingId, initialData, warehouses, products, onSave, onComplete
}) => {
  const [formData, setFormData] = useState<any>(initialData);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    setFormData(initialData);
    setError(null);
  }, [initialData, isOpen]);

  if (!isOpen) return null;

  // Allow editing if Draft. If Approved or Completed, read only.
  const isReadOnly = formData.status !== 'Draft';

  const validateForm = () => {
    if (!formData.date) return 'Date is required';
    if (activeTab === 'transfer') {
        if (!formData.sourceWarehouseId) return 'Source Warehouse is required';
        if (!formData.targetWarehouseId) return 'Target Warehouse is required';
        if (formData.sourceWarehouseId === formData.targetWarehouseId) return 'Source and Target warehouses cannot be the same';
    }
    if (['adjustment', 'count', 'receipt', 'reservation'].includes(activeTab)) {
        if (!formData.warehouseId) return 'Warehouse is required';
    }
    if (activeTab === 'receipt' && !formData.vendorName) return 'Vendor Name is required';
    if (activeTab === 'reservation') {
        if (!formData.customerName) return 'Customer Name is required';
        if (!formData.expiryDate) return 'Expiry Date is required';
    }
    if (activeTab === 'count' && !formData.counterName) return 'Counter Name is required';
    if (activeTab === 'adjustment' && !formData.reason) return 'Reason is required';
    return null;
  };

  const handleSaveClick = () => {
    const err = validateForm();
    if (err) {
      setError(err);
      return;
    }
    onSave(formData);
  };

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-[60] p-4">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-4xl max-h-[95vh] flex flex-col overflow-hidden animate-fade-in">
        <div className="p-4 md:p-6 border-b border-slate-100 flex justify-between items-center bg-slate-50 shrink-0">
          <h3 className="text-lg md:text-xl font-bold text-slate-800 uppercase flex items-center">
            {editingId ? <Edit2 className="w-5 h-5 mr-2 text-blue-500" /> : <Plus className="w-5 h-5 mr-2 text-green-500" />}
            {editingId ? 'Edit' : 'New'} {activeTab}
          </h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600">
            <X className="w-6 h-6" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto">
          <div className="p-4 md:p-6 space-y-4">

            {error && (
              <div className="p-3 bg-red-50 border border-red-100 rounded-lg text-red-600 text-sm flex items-center">
                <AlertCircle className="w-4 h-4 mr-2 flex-shrink-0" />
                {error}
              </div>
            )}

            <StockHeaderFields 
              activeTab={activeTab}
              formData={formData}
              setFormData={setFormData}
              warehouses={warehouses}
              isReadOnly={isReadOnly}
            />

            <StockItemsTable 
              items={formData.items}
              setItems={(items) => setFormData({...formData, items})}
              products={products}
              isReadOnly={isReadOnly}
              activeTab={activeTab}
            />
          </div>
        </div>

        <div className="p-4 border-t border-slate-100 flex justify-end space-x-3 bg-slate-50 shrink-0">
          <button
            type="button"
            onClick={onClose}
            className="px-5 py-2.5 text-slate-600 font-medium hover:bg-slate-200 rounded-lg transition-colors"
          >
            {isReadOnly ? 'Close' : 'Cancel'}
          </button>

          {formData.status === 'Draft' && (
             <>
                <button
                    type="button"
                    onClick={handleSaveClick}
                    className="px-6 py-2.5 bg-white border border-slate-300 text-slate-700 font-bold rounded-lg hover:bg-slate-50 transition-colors shadow-sm"
                >
                    Save Changes
                </button>
                {/* 
                   Special case: If accessed via Approval page, onComplete is passed to trigger Approve.
                   Check context or button label if needed. Assuming context is handled by parent.
                   Usually 'Complete' moves to Approved or Completed depending on logic.
                */}
                <button
                    type="button"
                    onClick={() => onComplete(formData)}
                    className="flex items-center px-6 py-2.5 bg-construction-orange text-white font-bold rounded-lg hover:bg-orange-600 transition-colors shadow-sm"
                >
                    <ThumbsUp className="w-4 h-4 mr-2" />
                    Approve / Submit
                </button>
             </>
          )}

          {formData.status === 'Approved' && (
             <button
                type="button"
                onClick={() => onComplete(formData)}
                className="flex items-center px-6 py-2.5 bg-green-600 text-white font-bold rounded-lg hover:bg-green-700 transition-colors shadow-sm"
             >
                <PlayCircle className="w-4 h-4 mr-2" />
                Complete & Execute
             </button>
          )}

          {(formData.status === 'Completed' || formData.status === 'Cancelled') && (
             <span className={`flex items-center font-bold px-4 py-2 ${formData.status === 'Completed' ? 'text-green-600 bg-green-50 rounded-lg' : 'text-red-600 bg-red-50 rounded-lg'}`}>
                {formData.status === 'Completed' ? <CheckCircle className="w-5 h-5 mr-2" /> : <AlertCircle className="w-5 h-5 mr-2" />} 
                {formData.status}
             </span>
          )}
        </div>
      </div>
    </div>
  );
};

