// Define Permissions Map
const PERMISSIONS: Record<string, UserRole[]> = {
  'dashboard': ['Admin', 'Manager'],
  'reports': ['Admin', 'Manager'],
  'pos': ['Admin', 'Manager', 'Staff', 'Cashier'],
  'shifts': ['Admin', 'Manager', 'Staff', 'Cashier'],
  'sales': ['Admin', 'Manager', 'Cashier'],
  'quotations': ['Admin', 'Manager', 'Cashier'],
  'inventory': ['Admin', 'Manager', 'Staff'],
  'stock': ['Admin', 'Manager', 'Staff'],
  'customers': ['Admin', 'Manager', 'Cashier', 'Staff'],
  'approvals': ['Admin', 'Manager'],
  'promotions': ['Admin', 'Manager', 'Staff'],
  'sync': ['Admin', 'Manager'],
  'categories': ['Admin', 'Staff', 'Manager'],
  'units': ['Admin', 'Staff', 'Manager'],
  'branches': ['Admin', 'Manager'],
  'warehouses': ['Admin', 'Staff', 'Manager'],
  'users': ['Admin', 'Manager'],
  'settings': ['Admin'],
  'profile': ['Admin', 'Manager', 'Staff', 'Cashier']
};

const ProtectedRoute: React.FC<{ children: React.ReactNode; requiredRoles?: UserRole[] }> = ({ children, requiredRoles }) => {
  const { currentUser } = useGlobal();
  const location = useLocation();

  if (!currentUser) {
    return <Navigate to="/login" state={{ from: location }} replace />;
  }

  if (requiredRoles && !requiredRoles.includes(currentUser.role)) {
    return (
      <div className="flex flex-col items-center justify-center h-full text-center p-8">
        <h2 className="text-2xl font-bold text-red-600 mb-2">Access Denied</h2>
        <p className="text-slate-500">You do not have permission to view this page.</p>
        <a href="/" className="mt-4 text-blue-600 hover:underline">Go to Home</a>
      </div>
    );
  }

  return <>{children}</>;
};

function AppContent() {
  const {
    currentUser, setCurrentUser,
    users, products, sales, units, categories, branches, posMachines, warehouses, locations,
    transfers, counts, reservations, receipts, adjustments, syncLogs, customers, shifts, shiftSchedules, promotions,
    processSale, addProduct, updateProduct, deleteProduct,
    addUnit, updateUnit, deleteUnit, addCategory, updateCategory, deleteCategory,
    addBranch, updateBranch, deleteBranch, addPos, updatePos, deletePos,
    addWarehouse, updateWarehouse, deleteWarehouse, addLocation, updateLocation, deleteLocation,
    addUser, updateUser, deleteUser, addCustomer, updateCustomer, deleteCustomer,
    updateTransfer, deleteTransfer, updateCount, deleteCount, updateReservation, deleteReservation,
    updateReceipt, deleteReceipt, updateAdjustment, deleteAdjustment,
    handleStockStatusChange, handleSyncOperation,
    startShift, endShift,
    addPromotion, updatePromotion, deletePromotion,
    settings, updateSettings,
    t, handleVoidSale
  } = useGlobal();

  const handleLogout = () => {
    setCurrentUser(null);
  };

  if (!currentUser) {
    return <LoginPage />;
  }

  return (
    <Layout currentUser={currentUser} onLogout={handleLogout}>
      <Routes>
        <Route path="/" element={<Navigate to="/dashboard" replace />} />

        <Route path="/dashboard" element={<ProtectedRoute requiredRoles={PERMISSIONS.dashboard}><Dashboard sales={sales} products={products} /></ProtectedRoute>} />
        <Route path="/reports" element={<ProtectedRoute requiredRoles={PERMISSIONS.reports}><ReportsManagement sales={sales} products={products} /></ProtectedRoute>} />
        <Route path="/pos" element={<ProtectedRoute requiredRoles={PERMISSIONS.pos}><PosTerminal products={products} onProcessSale={processSale} settings={settings} /></ProtectedRoute>} />
        <Route path="/shifts" element={<ProtectedRoute requiredRoles={PERMISSIONS.shifts}><ShiftManagement shifts={shifts} branches={branches} users={users} currentUser={currentUser} onStartShift={startShift} onEndShift={endShift} /></ProtectedRoute>} />
        <Route path="/sales" element={<ProtectedRoute requiredRoles={PERMISSIONS.sales}><SalesHistory sales={sales} onVoidSale={handleVoidSale} /></ProtectedRoute>} />
        <Route path="/quotations" element={<ProtectedRoute requiredRoles={PERMISSIONS.quotations}><QuotationsManagement /></ProtectedRoute>} />
        <Route path="/inventory" element={<ProtectedRoute requiredRoles={PERMISSIONS.inventory}><Inventory products={products} units={units} categories={categories} warehouses={warehouses} sales={sales} onAddProduct={addProduct} onUpdateProduct={updateProduct} onDeleteProduct={deleteProduct} /></ProtectedRoute>} />
        <Route path="/stock" element={<ProtectedRoute requiredRoles={PERMISSIONS.stock}><StockManagement warehouses={warehouses} products={products} transfers={transfers} counts={counts} reservations={reservations} receipts={receipts} adjustments={adjustments} defaultItemsPerPage={settings.defaultItemsPerPage} onUpdateTransfer={updateTransfer} onUpdateCount={updateCount} onUpdateReservation={updateReservation} onUpdateReceipt={updateReceipt} onUpdateAdjustment={updateAdjustment} onDeleteTransfer={deleteTransfer} onDeleteCount={deleteCount} onDeleteReservation={deleteReservation} onDeleteReceipt={deleteReceipt} onDeleteAdjustment={deleteAdjustment} onStatusChange={handleStockStatusChange} /></ProtectedRoute>} />
        <Route path="/approvals" element={<ProtectedRoute requiredRoles={PERMISSIONS.approvals}><ApprovalManagement transfers={transfers} counts={counts} reservations={reservations} receipts={receipts} adjustments={adjustments} warehouses={warehouses} onStatusChange={handleStockStatusChange} /></ProtectedRoute>} />
        <Route path="/promotions" element={<ProtectedRoute requiredRoles={PERMISSIONS.promotions}><PromotionsManagement promotions={promotions} onAddPromotion={addPromotion} onUpdatePromotion={updatePromotion} onDeletePromotion={deletePromotion} /></ProtectedRoute>} />
        <Route path="/customers" element={<ProtectedRoute requiredRoles={PERMISSIONS.customers}><CustomerManagement customers={customers} sales={sales} onAddCustomer={addCustomer} onUpdateCustomer={updateCustomer} onDeleteCustomer={deleteCustomer} /></ProtectedRoute>} />
        <Route path="/sync" element={<ProtectedRoute requiredRoles={PERMISSIONS.sync}><SyncManagement settings={settings} logs={syncLogs} sales={sales} onSync={handleSyncOperation} /></ProtectedRoute>} />
        <Route path="/units" element={<ProtectedRoute requiredRoles={PERMISSIONS.units}><UnitManagement units={units} onAddUnit={addUnit} onUpdateUnit={updateUnit} onDeleteUnit={deleteUnit} /></ProtectedRoute>} />
        <Route path="/categories" element={<ProtectedRoute requiredRoles={PERMISSIONS.categories}><CategoryManagement categories={categories} onAddCategory={addCategory} onUpdateCategory={updateCategory} onDeleteCategory={deleteCategory} /></ProtectedRoute>} />
        <Route path="/branches" element={<ProtectedRoute requiredRoles={PERMISSIONS.branches}><BranchManagement branches={branches} posMachines={posMachines} onAddBranch={addBranch} onUpdateBranch={updateBranch} onDeleteBranch={deleteBranch} onAddPosMachine={addPos} onUpdatePosMachine={updatePos} onDeletePosMachine={deletePos} /></ProtectedRoute>} />
        <Route path="/warehouses" element={<ProtectedRoute requiredRoles={PERMISSIONS.warehouses}><WarehouseManagement branches={branches} warehouses={warehouses} locations={locations} onAddWarehouse={addWarehouse} onUpdateWarehouse={updateWarehouse} onDeleteWarehouse={deleteWarehouse} onAddLocation={addLocation} onUpdateLocation={updateLocation} onDeleteLocation={deleteLocation} /></ProtectedRoute>} />
        <Route path="/users" element={<ProtectedRoute requiredRoles={PERMISSIONS.users}><UserManagement users={users} onAddUser={addUser} onUpdateUser={updateUser} onDeleteUser={deleteUser} /></ProtectedRoute>} />
        <Route path="/settings" element={<ProtectedRoute requiredRoles={PERMISSIONS.settings}><Settings settings={settings} onUpdateSettings={updateSettings} branches={branches} posMachines={posMachines} /></ProtectedRoute>} />
        <Route path="/profile" element={<ProtectedRoute requiredRoles={PERMISSIONS.profile}><UserProfile user={currentUser} shifts={shifts} sales={sales} /></ProtectedRoute>} />

        {/* Fallback */}
        <Route path="*" element={<Navigate to="/dashboard" replace />} />
      </Routes>
    </Layout>
  );
}

function App() {
  return (
    <BrowserRouter>
      <AppContent />
    </BrowserRouter>
  );
}

export default App;

