  const navigate = useNavigate();
  const location = useLocation();
  // Extract active tab from pathname (e.g. /dashboard -> dashboard)
  const activeTab = location.pathname.substring(1) || 'dashboard';

  // Global Keyboard Shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'F1') { e.preventDefault(); navigate('/dashboard'); }
      if (e.key === 'F2') { e.preventDefault(); navigate('/pos'); }
      if (e.key === 'F3') { e.preventDefault(); navigate('/inventory'); }
      if (e.shiftKey && e.key === '?') {
        e.preventDefault();
        setShowKeyboardHelp(prev => !prev);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [navigate]);

  return (
    <div className="flex h-screen bg-slate-50 overflow-hidden font-sans">
      <DesktopSidebar 
        navItems={NAV_ITEMS}
        activeTab={activeTab}
        currentUser={currentUser}
        t={t}
        mobileMenuOpen={mobileMenuOpen}
        setMobileMenuOpen={setMobileMenuOpen}
        isCollapsed={isSidebarCollapsed}
        onToggleCollapse={() => setIsSidebarCollapsed(!isSidebarCollapsed)}
      />

      <div className="flex-1 flex flex-col h-screen overflow-hidden">
        <TopBar 
          setMobileMenuOpen={setMobileMenuOpen}
          mobileMenuOpen={mobileMenuOpen}
          setShowKeyboardHelp={setShowKeyboardHelp}
          notifications={notifications}
          clearAllNotifications={clearAllNotifications}
          markNotificationRead={markNotificationRead}
          currentUser={currentUser}
          onLogout={onLogout}
        />

        {/* Content Area */}
        <main className="flex-1 overflow-y-auto p-4 md:p-6 bg-slate-50/50 relative scroll-smooth">
          {children}
        </main>
      </div>

      {/* Overlay for mobile menu */}
      {mobileMenuOpen && (
        <div 
          className="fixed inset-0 bg-slate-900/60 z-40 md:hidden backdrop-blur-sm"
          onClick={() => setMobileMenuOpen(false)}
        />
      )}

      <KeyboardShortcuts 
        isOpen={showKeyboardHelp} 
        onClose={() => setShowKeyboardHelp(false)} 
      />
    </div>
  );
};

