import { Elysia, t } from 'elysia';
import { cors } from '@elysiajs/cors';
import { swagger } from '@elysiajs/swagger';
import { PrismaClient } from '@prisma/client';
import { compare, hash } from 'bcryptjs';

const db = new PrismaClient();

const app = new Elysia()
  .use(cors())
  .use(swagger())

  // --- Auth Routes ---
  .group('/auth', (app) => app
    .post('/login', async ({ body, set }) => {
      const { username, password } = body;
      const user = await db.user.findFirst({ where: { username } });

      if (!user || !(await compare(password, user.password || ''))) {
        set.status = 401;
        throw new Error('Invalid credentials');
      }

      const { password: _, ...safeUser } = user;
      return { user: safeUser };
    }, {
      body: t.Object({
        username: t.String(),
        password: t.String()
      })
    })
  )

  // --- Product & Inventory Routes ---
  .group('/products', (app) => app
    .get('/', async () => {
      return await db.product.findMany({
        include: { variants: true, category: true, inventory: true },
        orderBy: { name: 'asc' }
      });
    })
    .post('/', async ({ body }) => {
      // Logic to create product + inventory
      const product = await db.product.create({
        data: {
          name: body.name,
          sku: body.sku,
          price: body.price,
          unit: body.unit,
          categoryId: body.categoryId,
          inventory: {
            create: { warehouseId: 'wh1', quantity: body.stock || 0 }
          }
        }
      });
      return product;
    }, {
      body: t.Object({
        name: t.String(),
        sku: t.String(),
        price: t.Number(),
        unit: t.String(),
        categoryId: t.String(),
        stock: t.Optional(t.Number())
      })
    })
  )

  // --- Sales Routes ---
  .group('/sales', (app) => app
    .get('/', async () => {
      return await db.sale.findMany({
        include: { items: true, customer: true },
        orderBy: { date: 'desc' },
        take: 100
      });
    })
    .post('/', async ({ body }) => {
      // Transactional Sale Creation
      return await db.$transaction(async (tx) => {
        const sale = await tx.sale.create({
          data: {
            total: body.total,
            paymentMethod: body.paymentMethod,
            customerId: body.customerId,
            items: {
              create: body.items.map((item: any) => ({
                productId: item.productId,
                quantity: item.quantity,
                sellPrice: item.sellPrice
              }))
            }
          }
        });

        // Deduct Inventory
        for (const item of body.items) {
           // Simple inventory deduction logic for default warehouse
           const inv = await tx.inventory.findFirst({
             where: { productId: item.productId, warehouseId: 'wh1' }
           });
           if (inv) {
             await tx.inventory.update({
               where: { id: inv.id },
               data: { quantity: { decrement: item.quantity } }
             });
           }
        }
        return sale;
      });
    }, {
      body: t.Object({
        total: t.Number(),
        paymentMethod: t.String(),
        customerId: t.Optional(t.String()),
        items: t.Array(t.Object({
          productId: t.String(),
          quantity: t.Number(),
          sellPrice: t.Number()
        }))
      })
    })
  )

  // --- Dashboard Stats ---
  .get('/dashboard/stats', async () => {
    const totalRevenue = await db.sale.aggregate({
      _sum: { total: true }
    });

    const lowStock = await db.product.findMany({
      include: { inventory: true },
      take: 10
    }); // Needs filtering logic for actual low stock based on minStock

    return {
      revenue: totalRevenue._sum.total || 0,
      lowStockItems: lowStock
    };
  })

  .listen(3000);

console.log(`🦊 Elysia is running at ${app.server?.hostname}:${app.server?.port}`);

export type App = typeof app;

import { treaty } from '@elysiajs/eden';
import type { App } from '../../../server/src/index';

const apiUrl = import.meta.env.VITE_API_URL || 'http://localhost:3000';

export const api = treaty<App>(apiUrl);

import { create } from 'zustand';
import { Product, UnitDefinition, CategoryItem, VariantAttribute } from '../types';
import { api } from '../utils/api';

// Initial data kept for fallback/offline structure, but fetch will override
import { INITIAL_UNITS, INITIAL_CATEGORIES_TREE, INITIAL_VARIANT_ATTRIBUTES } from '../services/data';

interface InventoryState {
  products: Product[];
  units: UnitDefinition[];
  categories: CategoryItem[];
  attributes: VariantAttribute[];
  loading: boolean;

  fetchProducts: () => Promise<void>;
  addProduct: (product: Product) => Promise<void>;
  updateProduct: (product: Product) => void;
  deleteProduct: (id: string) => void;

  updateProductStock: (productId: string, quantityDelta: number) => void;

  addUnit: (unit: UnitDefinition) => void;
  updateUnit: (unit: UnitDefinition) => void;
  deleteUnit: (id: string) => void;

  addCategory: (category: CategoryItem) => void;
  updateCategory: (category: CategoryItem) => void;
  deleteCategory: (id: string) => void;

  addAttribute: (attribute: VariantAttribute) => void;
  updateAttribute: (attribute: VariantAttribute) => void;
  deleteAttribute: (id: string) => void;
}

export const useInventoryStore = create<InventoryState>((set, get) => ({
  products: [],
  units: INITIAL_UNITS,
  categories: INITIAL_CATEGORIES_TREE,
  attributes: INITIAL_VARIANT_ATTRIBUTES,
  loading: false,

  fetchProducts: async () => {
    set({ loading: true });
    try {
      const { data, error } = await api.products.get();
      if (data) {
        // Transform Prisma data to frontend Product type if necessary
        // Assuming the backend returns shape matching frontend interfaces roughly
        set({ products: data as unknown as Product[] });
      } else {
        console.error("Failed to fetch products:", error);
      }
    } catch (err) {
      console.error(err);
    } finally {
      set({ loading: false });
    }
  },

  addProduct: async (product) => {
    // Optimistic Update
    set((state) => ({ products: [...state.products, product] }));

    // API Call
    const { data, error } = await api.products.post({
      name: product.name,
      sku: product.sku,
      price: product.price,
      unit: product.unit,
      categoryId: typeof product.category === 'string' ? product.category : 'misc',
      stock: product.stock
    });

    if (error) {
       console.error("API Error adding product", error);
       // Revert optimistic update in real app
    }
  },

  updateProduct: (product) => set((state) => ({ products: state.products.map(p => p.id === product.id ? product : p) })),
  deleteProduct: (id) => set((state) => ({ products: state.products.filter(p => p.id !== id) })),

  updateProductStock: (productId, quantityDelta) => set((state) => ({
    products: state.products.map(p => 
      p.id === productId ? { ...p, stock: p.stock + quantityDelta } : p
    )
  })),

  addUnit: (unit) => set((state) => ({ units: [...state.units, unit] })),
  updateUnit: (unit) => set((state) => ({ units: state.units.map(u => u.id === unit.id ? unit : u) })),
  deleteUnit: (id) => set((state) => ({ units: state.units.filter(u => u.id !== id) })),

  addCategory: (category) => set((state) => ({ categories: [...state.categories, category] })),
  updateCategory: (category) => set((state) => ({ categories: state.categories.map(c => c.id === category.id ? category : c) })),
  deleteCategory: (id) => set((state) => ({ categories: state.categories.filter(c => c.id !== id) })),

  addAttribute: (attribute) => set((state) => ({ attributes: [...state.attributes, attribute] })),
  updateAttribute: (attribute) => set((state) => ({ attributes: state.attributes.map(a => a.id === attribute.id ? attribute : a) })),
  deleteAttribute: (id) => set((state) => ({ attributes: state.attributes.filter(a => a.id !== id) })),
}));

import { treaty } from '@elysiajs/eden';
import type { App } from '../../../server/src/index';

const apiUrl = (import.meta as any).env.VITE_API_URL || 'http://localhost:3000';

