import { Elysia, t } from 'elysia';
import { cors } from '@elysiajs/cors';
import { swagger } from '@elysiajs/swagger';
import { PrismaClient } from '@prisma/client';
import { compare, hash } from 'bcryptjs';

const db = new PrismaClient();

const app = new Elysia()
  .use(cors())
  .use(swagger())

  // --- Auth Routes ---
  .group('/auth', (app) => app
    .post('/login', async ({ body, set }) => {
      const { username, password } = body;
      const user = await db.user.findFirst({ where: { username } });

      if (!user || !(await compare(password, user.password || ''))) {
        set.status = 401;
        throw new Error('Invalid credentials');
      }

      const { password: _, ...safeUser } = user;
      return { user: safeUser };
    }, {
      body: t.Object({
        username: t.String(),
        password: t.String()
      })
    })
  )

  // --- Users Management ---
  .group('/users', (app) => app
    .get('/', async () => {
      return await db.user.findMany({
        select: { id: true, username: true, name: true, role: true, email: true, avatarUrl: true, department: true, branchId: true }
      });
    })
    .post('/', async ({ body }) => {
      const hashedPassword = await hash(body.password, 10);
      const user = await db.user.create({
        data: { ...body, password: hashedPassword }
      });
      const { password: _, ...safeUser } = user;
      return safeUser;
    }, {
      body: t.Object({
        username: t.String(),
        password: t.String(),
        name: t.String(),
        role: t.String(),
        email: t.Optional(t.String()),
        avatarUrl: t.Optional(t.String()),
        department: t.Optional(t.String()),
        branchId: t.Optional(t.String())
      })
    })
    .put('/:id', async ({ params: { id }, body }) => {
      const updateData: any = { ...body };
      if (updateData.password) {
        updateData.password = await hash(updateData.password, 10);
      } else {
        delete updateData.password;
      }
      const user = await db.user.update({ where: { id }, data: updateData });
      const { password: _, ...safeUser } = user;
      return safeUser;
    }, {
      body: t.Object({
        username: t.Optional(t.String()),
        password: t.Optional(t.String()),
        name: t.Optional(t.String()),
        role: t.Optional(t.String()),
        email: t.Optional(t.String()),
        avatarUrl: t.Optional(t.String()),
        department: t.Optional(t.String()),
        branchId: t.Optional(t.String())
      })
    })
    .delete('/:id', async ({ params: { id } }) => {
      return await db.user.delete({ where: { id } });
    })
  )

  // --- Products & Inventory ---
  .group('/products', (app) => app
    .get('/', async () => {
      const products = await db.product.findMany({
        include: { variants: true, category: true, inventory: true },
        orderBy: { name: 'asc' }
      });
      // Transform for frontend compatibility if needed
      return products.map(p => ({
        ...p,
        stock: p.inventory.reduce((acc, inv) => acc + inv.quantity, 0),
        warehouseInventory: p.inventory,
        category: p.categoryId
      }));
    })
    .post('/', async ({ body }) => {
      const product = await db.product.create({
        data: {
          name: body.name,
          sku: body.sku,
          price: body.price,
          unit: body.unit,
          categoryId: body.categoryId,
          minStock: body.minStock || 20,
          inventory: {
            create: { warehouseId: 'wh1', quantity: body.stock || 0 }
          }
        },
        include: { variants: true }
      });
      return product;
    }, {
      body: t.Object({
        name: t.String(),
        sku: t.String(),
        price: t.Number(),
        unit: t.String(),
        categoryId: t.String(),
        stock: t.Optional(t.Number()),
        minStock: t.Optional(t.Number())
      })
    })
  )

  // --- Sales ---
  .group('/sales', (app) => app
    .get('/', async () => {
      return await db.sale.findMany({
        include: { items: true, customer: true },
        orderBy: { date: 'desc' },
        take: 100
      });
    })
    .post('/', async ({ body }) => {
      return await db.$transaction(async (tx) => {
        const sale = await tx.sale.create({
          data: {
            total: body.total,
            paymentMethod: body.paymentMethod,
            customerId: body.customerId,
            items: {
              create: body.items.map((item: any) => ({
                productId: item.productId,
                quantity: item.quantity,
                sellPrice: item.sellPrice,
                variantId: item.variantId
              }))
            }
          },
          include: { items: true }
        });

        // Deduct Inventory
        for (const item of body.items) {
           const inv = await tx.inventory.findFirst({
             where: { productId: item.productId, warehouseId: 'wh1' }
           });
           if (inv) {
             await tx.inventory.update({
               where: { id: inv.id },
               data: { quantity: { decrement: item.quantity } }
             });
           }
        }
        return sale;
      });
    }, {
      body: t.Object({
        total: t.Number(),
        paymentMethod: t.String(),
        customerId: t.Optional(t.String()),
        items: t.Array(t.Object({
          productId: t.String(),
          variantId: t.Optional(t.String()),
          quantity: t.Number(),
          sellPrice: t.Number()
        }))
      })
    })
  )

  // --- Customers ---
  .group('/customers', (app) => app
    .get('/', async () => {
      return await db.customer.findMany({ include: { level: true }, orderBy: { name: 'asc' } });
    })
    .post('/', async ({ body }) => {
      return await db.customer.create({ data: body as any });
    }, {
      body: t.Object({
        name: t.String(),
        code: t.String(),
        phone: t.Optional(t.String()),
        levelId: t.Optional(t.String())
      })
    })
  )

  // --- Settings ---
  .get('/settings', async () => {
    const settings = await db.systemSetting.findFirst();
    return settings || { companyName: 'MAHAXAY', currencySymbol: '₭', language: 'lo' };
  })
  .post('/settings', async ({ body }) => {
    // Assuming single row ID 'default-settings'
    return await db.systemSetting.upsert({
      where: { id: 'default-settings' },
      update: body as any,
      create: { id: 'default-settings', ...(body as any) }
    });
  })

  // --- Dashboard Stats ---
  .get('/dashboard/stats', async () => {
    const totalRevenue = await db.sale.aggregate({ _sum: { total: true } });
    const lowStock = await db.product.findMany({ include: { inventory: true }, take: 10 });
    return {
      revenue: totalRevenue._sum.total || 0,
      lowStockItems: lowStock
    };
  })

  .listen(3000);

console.log(`🦊 Elysia is running at ${app.server?.hostname}:${app.server?.port}`);

