  'profile': ['Admin', 'Manager', 'Staff', 'Cashier']
};

const ProtectedRoute: React.FC<{ children: React.ReactNode; requiredRoles?: UserRole[] }> = ({ children, requiredRoles }) => {
  const { currentUser } = useGlobal();
  const location = useLocation();

  if (!currentUser) {
    return <Navigate to="/login" state={{ from: location }} replace />;
  }

  if (requiredRoles && !requiredRoles.includes(currentUser.role)) {
    return (
      <div className="flex flex-col items-center justify-center h-full text-center p-8">
        <h2 className="text-2xl font-bold text-red-600 mb-2">Access Denied</h2>
        <p className="text-slate-500">You do not have permission to view this page.</p>
        <a href="/" className="mt-4 text-blue-600 hover:underline">Go to Home</a>
      </div>
    );
  }

  return <>{children}</>;
};

function AppContent() {
  const global = useGlobal();
  const { currentUser, setCurrentUser } = global;

  const handleLogout = () => {
    setCurrentUser(null);
  };

  if (!currentUser) {
    return <LoginPage />;
  }

  return (
    <Layout currentUser={currentUser} onLogout={handleLogout}>
      <Routes>
        <Route path="/" element={<Navigate to="/dashboard" replace />} />

        <Route path="/dashboard" element={<ProtectedRoute requiredRoles={PERMISSIONS.dashboard}><Dashboard sales={global.sales} products={global.products} /></ProtectedRoute>} />
        <Route path="/reports" element={<ProtectedRoute requiredRoles={PERMISSIONS.reports}><ReportsManagement sales={global.sales} products={global.products} /></ProtectedRoute>} />
        <Route path="/pos" element={<ProtectedRoute requiredRoles={PERMISSIONS.pos}><PosTerminal products={global.products} onProcessSale={global.processSale} settings={global.settings} /></ProtectedRoute>} />
        <Route path="/shifts" element={<ProtectedRoute requiredRoles={PERMISSIONS.shifts}><ShiftManagement shifts={global.shifts} branches={global.branches} users={global.users} currentUser={currentUser} onStartShift={global.startShift} onEndShift={global.endShift} /></ProtectedRoute>} />
        <Route path="/sales" element={<ProtectedRoute requiredRoles={PERMISSIONS.sales}><SalesHistory sales={global.sales} onVoidSale={global.handleVoidSale} /></ProtectedRoute>} />
        <Route path="/quotations" element={<ProtectedRoute requiredRoles={PERMISSIONS.quotations}><QuotationsManagement /></ProtectedRoute>} />
        <Route path="/inventory" element={<ProtectedRoute requiredRoles={PERMISSIONS.inventory}><Inventory products={global.products} units={global.units} categories={global.categories} warehouses={global.warehouses} sales={global.sales} onAddProduct={global.addProduct} onUpdateProduct={global.updateProduct} onDeleteProduct={global.deleteProduct} /></ProtectedRoute>} />
        <Route path="/stock" element={<ProtectedRoute requiredRoles={PERMISSIONS.stock}><StockManagement warehouses={global.warehouses} products={global.products} transfers={global.transfers} counts={global.counts} reservations={global.reservations} receipts={global.receipts} adjustments={global.adjustments} defaultItemsPerPage={global.settings.defaultItemsPerPage} onUpdateTransfer={global.updateTransfer} onUpdateCount={global.updateCount} onUpdateReservation={global.updateReservation} onUpdateReceipt={global.updateReceipt} onUpdateAdjustment={global.updateAdjustment} onDeleteTransfer={global.deleteTransfer} onDeleteCount={global.deleteCount} onDeleteReservation={global.deleteReservation} onDeleteReceipt={global.deleteReceipt} onDeleteAdjustment={global.deleteAdjustment} onStatusChange={global.handleStockStatusChange} /></ProtectedRoute>} />
        <Route path="/approvals" element={<ProtectedRoute requiredRoles={PERMISSIONS.approvals}><ApprovalManagement transfers={global.transfers} counts={global.counts} reservations={global.reservations} receipts={global.receipts} adjustments={global.adjustments} warehouses={global.warehouses} onStatusChange={global.handleStockStatusChange} /></ProtectedRoute>} />
        <Route path="/promotions" element={<ProtectedRoute requiredRoles={PERMISSIONS.promotions}><PromotionsManagement promotions={global.promotions} onAddPromotion={global.addPromotion} onUpdatePromotion={global.updatePromotion} onDeletePromotion={global.deletePromotion} /></ProtectedRoute>} />
        <Route path="/customers" element={<ProtectedRoute requiredRoles={PERMISSIONS.customers}><CustomerManagement customers={global.customers} sales={global.sales} onAddCustomer={global.addCustomer} onUpdateCustomer={global.updateCustomer} onDeleteCustomer={global.deleteCustomer} /></ProtectedRoute>} />
        <Route path="/sync" element={<ProtectedRoute requiredRoles={PERMISSIONS.sync}><SyncManagement settings={global.settings} logs={global.syncLogs} sales={global.sales} onSync={global.handleSyncOperation} /></ProtectedRoute>} />
        <Route path="/units" element={<ProtectedRoute requiredRoles={PERMISSIONS.units}><UnitManagement units={global.units} onAddUnit={global.addUnit} onUpdateUnit={global.updateUnit} onDeleteUnit={global.deleteUnit} /></ProtectedRoute>} />
        <Route path="/categories" element={<ProtectedRoute requiredRoles={PERMISSIONS.categories}><CategoryManagement categories={global.categories} onAddCategory={global.addCategory} onUpdateCategory={global.updateCategory} onDeleteCategory={global.deleteCategory} /></ProtectedRoute>} />
        <Route path="/branches" element={<ProtectedRoute requiredRoles={PERMISSIONS.branches}><BranchManagement branches={global.branches} posMachines={global.posMachines} onAddBranch={global.addBranch} onUpdateBranch={global.updateBranch} onDeleteBranch={global.deleteBranch} onAddPosMachine={global.addPos} onUpdatePosMachine={global.updatePos} onDeletePosMachine={global.deletePos} /></ProtectedRoute>} />
        <Route path="/warehouses" element={<ProtectedRoute requiredRoles={PERMISSIONS.warehouses}><WarehouseManagement branches={global.branches} warehouses={global.warehouses} locations={global.locations} onAddWarehouse={global.addWarehouse} onUpdateWarehouse={global.updateWarehouse} onDeleteWarehouse={global.deleteWarehouse} onAddLocation={global.addLocation} onUpdateLocation={global.updateLocation} onDeleteLocation={global.deleteLocation} /></ProtectedRoute>} />
        <Route path="/users" element={<ProtectedRoute requiredRoles={PERMISSIONS.users}><UserManagement users={global.users} onAddUser={global.addUser} onUpdateUser={global.updateUser} onDeleteUser={global.deleteUser} /></ProtectedRoute>} />
        <Route path="/settings" element={<ProtectedRoute requiredRoles={PERMISSIONS.settings}><Settings settings={global.settings} onUpdateSettings={global.updateSettings} branches={global.branches} posMachines={global.posMachines} /></ProtectedRoute>} />
        <Route path="/profile" element={<ProtectedRoute requiredRoles={PERMISSIONS.profile}><UserProfile user={currentUser} shifts={global.shifts} sales={global.sales} /></ProtectedRoute>} />

        {/* Fallback */}
        <Route path="*" element={<Navigate to="/dashboard" replace />} />
      </Routes>
    </Layout>
  );
}

function App() {
  return (
    <BrowserRouter>
      <AppContent />
    </BrowserRouter>
  );
}

