                title="Grid View"
             >
                <LayoutGrid className="w-5 h-5" />
             </button>
          </div>
        </div>
      </div>

      {/* Inventory List */}
      <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden flex-1 flex flex-col relative">
        <InventoryList 
          products={filteredProducts} 
          categories={categories} 
          formatPrice={formatPrice} 
          viewMode={viewMode}
          onEdit={handleEdit} 
          onDelete={deleteProduct} 
          onPrintLabel={(p) => setLabelProduct(p)} 
        />
      </div>

      {/* Mobile FAB */}
      <button onClick={handleAdd} className="md:hidden fixed bottom-20 right-6 w-14 h-14 bg-slate-900 text-white rounded-full shadow-xl flex items-center justify-center z-40 hover:bg-slate-800 active:scale-95 transition-all">
          <Plus className="w-8 h-8" />
      </button>

      {/* Modals */}
      <BarcodeScanner isOpen={isScannerOpen} onClose={() => setIsScannerOpen(false)} onScan={handleScan} />

      <ProductFormModal 
        isOpen={isFormOpen} 
        onClose={() => setIsFormOpen(false)} 
        onSubmit={handleFormSubmit} 
        initialData={editingProduct} 
        categories={categories} 
        units={units}
        attributes={attributes}
        currencySymbol={settings.currencySymbol}
        customerLevels={customerLevels || []} 
        branches={branches}
      />

      <ImportModal 
        isOpen={isImportOpen} 
        onClose={() => setIsImportOpen(false)} 
        onImport={handleImport}
        currencySymbol={settings.currencySymbol}
        formatPrice={formatPrice}
      />

      <InventoryAiModal 
        isOpen={isAiOpen} 
        onClose={() => setIsAiOpen(false)} 
        products={products} 
        sales={sales} 
        formatPrice={formatPrice} 
      />

      {labelProduct && (
        <LabelPrintModal 
          isOpen={!!labelProduct} 
          onClose={() => setLabelProduct(null)} 
          product={labelProduct} 
          formatPrice={formatPrice} 
        />
      )}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Product, Customer, CartItem } from '../../types';
import { X, Plus, Trash2, Save, AlertCircle, Search } from 'lucide-react';
import { useGlobal } from '../../context/GlobalContext';

interface BackOfficeSaleModalProps {
  isOpen: boolean;
  onClose: () => void;
  products: Product[];
  customers: Customer[];
  onProcessSale: (
    items: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number,
    paymentMethod?: 'cash' | 'card' | 'transfer' | 'qr' | 'credit',
    amountReceived?: number,
    change?: number,
    pointsRedeemed?: number,
    source?: 'pos' | 'back-office'
  ) => Promise<any>;
}

export const BackOfficeSaleModal: React.FC<BackOfficeSaleModalProps> = ({
  isOpen,
  onClose,
  products,
  customers,
  onProcessSale
}) => {
  const { formatPrice } = useGlobal();
  const [selectedCustomerId, setSelectedCustomerId] = useState<string>('');
  const [selectedItems, setSelectedItems] = useState<CartItem[]>([]);
  const [paymentMethod, setPaymentMethod] = useState<'cash' | 'card' | 'transfer' | 'credit'>('cash');
  const [error, setError] = useState<string | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Item adding state
  const [searchProduct, setSearchProduct] = useState('');
  const [qtyInput, setQtyInput] = useState(1);

  // Reset form on open
  useEffect(() => {
    if (isOpen) {
      setSelectedCustomerId('');
      setSelectedItems([]);
      setPaymentMethod('cash');
      setError(null);
      setSearchProduct('');
      setQtyInput(1);
    }
  }, [isOpen]);

  const handleAddItem = (product: Product) => {
    // Check if already exists
    const existingIdx = selectedItems.findIndex(i => i.id === product.id);

    if (existingIdx >= 0) {
      const newItems = [...selectedItems];
      newItems[existingIdx].quantity += qtyInput;
      setSelectedItems(newItems);
    } else {
      const newItem: CartItem = {
        ...product,
        quantity: qtyInput,
        sellPrice: product.price,
        sellUnit: product.unit,
        sellConversionFactor: 1
      };
      setSelectedItems([...selectedItems, newItem]);
    }
    setQtyInput(1);
    setSearchProduct(''); // Clear search to allow quick adding next item
  };

  const handleRemoveItem = (index: number) => {
    const newItems = [...selectedItems];
    newItems.splice(index, 1);
    setSelectedItems(newItems);
  };

  const calculateTotal = () => {
    return selectedItems.reduce((acc, item) => acc + (item.sellPrice * item.quantity), 0);
  };

  const handleSubmit = async () => {
    if (selectedItems.length === 0) {
      setError("Please add at least one product.");
      return;
    }

    setIsSubmitting(true);
    setError(null);

    const total = calculateTotal();

    try {
      // Calling processSale with 'back-office' source to trigger strict stock check
      await onProcessSale(
        selectedItems,
        total,
        selectedCustomerId || undefined,
        0, // discount
        total, // subtotal
        paymentMethod,
        total, // amountReceived (assume full payment unless credit)
        0, // change
        0, // points
        'back-office' // <--- CRITICAL: This flags strict stock check
      );

      onClose();
      alert("Sale created successfully!");
    } catch (err: any) {
      console.error(err);
      setError(err.message || "Failed to create sale");
    } finally {
      setIsSubmitting(false);
    }
  };

  if (!isOpen) return null;

  // Updated Search Logic: Includes Barcode and Variant check
  const filteredProducts = products.filter(p => {
    const searchLower = searchProduct.toLowerCase();
    const matchesMain = 
      p.name.toLowerCase().includes(searchLower) || 
      p.sku?.toLowerCase().includes(searchLower) ||
      p.barcode?.toLowerCase().includes(searchLower);

    const matchesVariant = p.variants && p.variants.some(v => 
      v.code.toLowerCase().includes(searchLower) ||
      v.barcode?.toLowerCase().includes(searchLower) ||
      v.name.toLowerCase().includes(searchLower)
    );

    return matchesMain || matchesVariant;
  }).slice(0, 5); // Limit suggestions

  return (
    <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-[70] p-4 backdrop-blur-sm animate-fade-in">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-4xl max-h-[90vh] flex flex-col overflow-hidden">

        {/* Header */}
        <div className="p-5 border-b border-slate-100 flex justify-between items-center bg-slate-50">
          <div>
            <h3 className="text-xl font-bold text-slate-800">New Back Office Sale</h3>
            <p className="text-xs text-slate-500">Create invoice / wholesale order (Strict Stock Check)</p>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600"><X className="w-6 h-6" /></button>
        </div>

        <div className="flex-1 overflow-y-auto p-6 space-y-6">

          {error && (
            <div className="bg-red-50 border border-red-200 text-red-700 p-4 rounded-lg flex items-start">
              <AlertCircle className="w-5 h-5 mr-2 flex-shrink-0 mt-0.5" />
              <div>
                <p className="font-bold">Transaction Failed</p>
                <p className="text-sm">{error}</p>
              </div>
            </div>
          )}

          {/* Customer & Settings */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-bold text-black mb-1">Customer</label>
              <select 
                value={selectedCustomerId} 
                onChange={e => setSelectedCustomerId(e.target.value)}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 bg-white text-black"
              >
                <option value="">Walk-in Customer</option>
                {customers.map(c => (
                  <option key={c.id} value={c.id}>{c.name} ({c.code})</option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-sm font-bold text-black mb-1">Payment Method</label>
              <select 
                value={paymentMethod} 
                onChange={e => setPaymentMethod(e.target.value as any)}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-blue-500 bg-white text-black"
              >
                <option value="cash">Cash</option>
                <option value="transfer">Bank Transfer</option>
                <option value="card">Credit Card</option>
                <option value="credit">Credit / Debt ( ติดหนี้ )</option>
              </select>
            </div>
          </div>

          {/* Product Selection */}
          <div className="bg-slate-50 p-4 rounded-xl border border-slate-200">
            <label className="block text-sm font-bold text-black mb-2">Add Products</label>
            <div className="flex gap-2 mb-2">
              <div className="relative flex-1">
                <Search className="absolute left-3 top-2.5 w-4 h-4 text-slate-400" />
                <input 
                  type="text" 
                  placeholder="Search by Name, SKU, Barcode, or Variant..." 
                  className="w-full pl-9 pr-4 py-2 border border-slate-300 rounded-lg text-black placeholder:text-slate-400"
                  value={searchProduct}
                  onChange={e => setSearchProduct(e.target.value)}
                />
                {/* Autocomplete Dropdown */}
                {searchProduct && (
                  <div className="absolute top-full left-0 right-0 bg-white border border-slate-200 shadow-lg rounded-lg mt-1 z-10 max-h-48 overflow-y-auto">
                    {filteredProducts.length > 0 ? filteredProducts.map(p => (
                      <div 
                        key={p.id} 
                        className="p-2 hover:bg-slate-50 cursor-pointer flex justify-between items-center"
                        onClick={() => handleAddItem(p)}
                      >
                        <div>
                          <p className="text-sm font-bold text-black">{p.name}</p>
                          <p className="text-xs text-black">{p.sku} | Barcode: {p.barcode || '-'} | Stock: {p.stock}</p>
                          {p.variants && p.variants.length > 0 && (
                             <p className="text-[10px] text-slate-500">Variants: {p.variants.map(v => v.name).join(', ')}</p>
                          )}
                        </div>
                        <span className="text-sm font-bold text-blue-600">{formatPrice(p.price)}</span>
                      </div>
                    )) : (
                      <div className="p-3 text-sm text-slate-400 text-center">No products found</div>
                    )}
                  </div>
                )}
              </div>
              <input 
                type="number" 
                min="1" 
                value={qtyInput}
                onChange={e => setQtyInput(parseInt(e.target.value) || 1)}
                className="w-20 px-3 py-2 border border-slate-300 rounded-lg text-center text-black font-bold"
              />
            </div>
          </div>

          {/* Items Table */}
          <div className="border rounded-lg overflow-hidden">
            <table className="w-full text-left text-sm">
              <thead className="bg-slate-100 text-black font-bold border-b">
                <tr>
                  <th className="p-3">Product</th>
                  <th className="p-3 text-right">Price</th>
                  <th className="p-3 text-center">Qty</th>
                  <th className="p-3 text-right">Total</th>
                  <th className="p-3 w-10"></th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {selectedItems.length === 0 ? (
                  <tr>
                    <td colSpan={5} className="p-8 text-center text-slate-400">No items added to invoice.</td>
                  </tr>
                ) : (
                  selectedItems.map((item, idx) => (
                    <tr key={idx}>
                      <td className="p-3">
                        <div className="font-bold text-black">{item.name}</div>
                        <div className="text-xs text-black">{item.sku}</div>
                      </td>
                      <td className="p-3 text-right text-black">{formatPrice(item.sellPrice)}</td>
                      <td className="p-3 text-center text-black">{item.quantity}</td>
                      <td className="p-3 text-right font-bold text-black">{formatPrice(item.sellPrice * item.quantity)}</td>
                      <td className="p-3 text-center">
                        <button onClick={() => handleRemoveItem(idx)} className="text-red-400 hover:text-red-600">
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
              <tfoot className="bg-slate-50 font-bold border-t">
                <tr>
                  <td colSpan={3} className="p-3 text-right text-black">Grand Total:</td>
                  <td className="p-3 text-right text-lg text-black">{formatPrice(calculateTotal())}</td>
                  <td></td>
                </tr>
              </tfoot>
            </table>
          </div>

        </div>

        {/* Footer */}
        <div className="p-4 border-t border-slate-100 bg-white flex justify-end gap-3">
          <button 
            onClick={onClose}
            className="px-5 py-2.5 text-slate-600 font-medium hover:bg-slate-100 rounded-lg border border-slate-200"
          >
            Cancel
          </button>
          <button 
            onClick={handleSubmit}
            disabled={isSubmitting || selectedItems.length === 0}
            className="px-6 py-2.5 bg-green-600 text-white font-bold rounded-lg hover:bg-green-700 shadow-sm flex items-center disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {isSubmitting ? 'Processing...' : (
              <>
                <Save className="w-4 h-4 mr-2" />
                Confirm Sale
              </>
            )}
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Product, Category } from '../../types';
import { Search, Box, ScanBarcode, LayoutGrid, List, Plus, Layers, ChevronLeft, ChevronRight } from 'lucide-react';
import { useGlobal } from '../../context/GlobalContext';

interface ProductGridProps {
  products: (Product & { displayPrice?: number })[]; 
  onScanClick: () => void;
  searchTerm: string;
  setSearchTerm: (term: string) => void;
  onScan: (code: string) => void; 
  onProductSelect: (product: Product) => void;
}

const ITEMS_PER_PAGE = 24; // Multiples of 2, 3, and 4 for clean grids

export const ProductGrid: React.FC<ProductGridProps> = ({ 
  products, 
  onScanClick,
  searchTerm,
  setSearchTerm,
  onScan,
  onProductSelect
}) => {
  const { formatPrice, t } = useGlobal();
  const [selectedCategory, setSelectedCategory] = useState<string>('all');
  const [viewMode, setViewMode] = useState<'grid' | 'list'>('grid');

  // Pagination State
  const [currentPage, setCurrentPage] = useState(1);

  // Reset page when filters change
  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm, selectedCategory]);

  const filteredProducts = useMemo(() => {
    return products.filter(p => {
      const searchLower = searchTerm.toLowerCase();
      const matchesMain = 
        p.name.toLowerCase().includes(searchLower) ||
        p.sku?.toLowerCase().includes(searchLower) ||
        p.barcode?.includes(searchLower);

      // Search inside variants too
      const matchesVariant = p.variants && p.variants.some(v => 
        v.code.toLowerCase().includes(searchLower) || 
        v.barcode.includes(searchLower) ||
        v.name.toLowerCase().includes(searchLower)
      );

      const matchesCategory = selectedCategory === 'all' || p.category === selectedCategory;
      return (matchesMain || matchesVariant) && matchesCategory;
    });
  }, [products, searchTerm, selectedCategory]);

  // Pagination Logic
  const totalPages = Math.ceil(filteredProducts.length / ITEMS_PER_PAGE);
  const paginatedProducts = useMemo(() => {
    const start = (currentPage - 1) * ITEMS_PER_PAGE;
    return filteredProducts.slice(start, start + ITEMS_PER_PAGE);
  }, [filteredProducts, currentPage]);

  const handleFormSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!searchTerm) return;
    onScan(searchTerm);
  };

  return (
    <div className="flex flex-col h-full bg-white">
      {/* Search & Filter Bar */}
      <div className="px-4 md:px-6 pb-4 pt-2 space-y-3 bg-white z-10">
        <div className="flex flex-col md:flex-row gap-3">
          <form onSubmit={handleFormSubmit} className="relative flex-1 flex gap-2">
            <div className="relative flex-1 group">
               <Search className="absolute left-4 top-1/2 transform -translate-y-1/2 text-slate-400 w-5 h-5 group-focus-within:text-slate-800 transition-colors" />
               <input
                 id="pos-search-input"
                 type="text"
                 placeholder={t('pos.scanPlaceholder')}
                 className="w-full pl-12 pr-4 py-3 border-none rounded-xl bg-slate-100 text-slate-800 font-medium placeholder:text-slate-400 focus:outline-none focus:ring-2 focus:ring-slate-200 transition-all text-sm md:text-base"
                 value={searchTerm}
                 onChange={(e) => setSearchTerm(e.target.value)}
                 autoFocus
               />
            </div>
            <button type="button" onClick={onScanClick} className="bg-slate-100 text-slate-600 px-3 md:px-4 rounded-xl hover:bg-slate-200 transition-colors flex items-center justify-center">
               <ScanBarcode className="w-6 h-6" />
            </button>
          </form>

          <div className="flex bg-slate-100 p-1 rounded-xl shrink-0 items-center self-end md:self-auto h-[48px] md:h-[52px]">
             <button onClick={() => setViewMode('list')} className={`p-2 rounded-lg transition-all flex-1 md:flex-none flex justify-center ${viewMode === 'list' ? 'bg-white shadow-sm text-slate-900' : 'text-slate-400 hover:text-slate-600'}`}>
                <List className="w-5 h-5" />
             </button>
             <button onClick={() => setViewMode('grid')} className={`p-2 rounded-lg transition-all flex-1 md:flex-none flex justify-center ${viewMode === 'grid' ? 'bg-white shadow-sm text-slate-900' : 'text-slate-400 hover:text-slate-600'}`}>
                <LayoutGrid className="w-5 h-5" />
             </button>
          </div>
        </div>

        <div className="flex gap-2 overflow-x-auto pb-2 -mx-4 px-4 md:mx-0 md:px-0 scrollbar-hide">
          <button onClick={() => setSelectedCategory('all')} className={`px-4 py-2 rounded-full text-xs md:text-sm font-bold whitespace-nowrap transition-all ${selectedCategory === 'all' ? 'bg-slate-900 text-white shadow-md' : 'bg-white text-slate-500 hover:bg-slate-50 border border-slate-100'}`}>
            {t('pos.allItems')}
          </button>
          {Object.values(Category).map(cat => (
            <button key={cat} onClick={() => setSelectedCategory(cat)} className={`px-4 py-2 rounded-full text-xs md:text-sm font-bold whitespace-nowrap transition-all ${selectedCategory === cat ? 'bg-slate-900 text-white shadow-md' : 'bg-white text-slate-500 hover:bg-slate-50 border border-slate-100'}`}>
              {cat}
            </button>
          ))}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto px-4 md:px-6 pb-2 custom-scrollbar bg-white">
        {filteredProducts.length === 0 ? (
          <div className="flex flex-col items-center justify-center h-64 text-slate-400 mt-10">
            <div className="bg-slate-50 p-6 rounded-full mb-4">
               <Box className="w-12 h-12 text-slate-300" />
            </div>
            <p className="font-medium">No products found.</p>
          </div>
        ) : viewMode === 'grid' ? (
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-3 xl:grid-cols-4 gap-3 md:gap-4 pb-20">
            {paginatedProducts.map((product) => {
               // Logic to detect if product has options (Variants OR Units)
               const hasVariants = product.variants && product.variants.length > 0;
               const stock = product.stock;
               const isLowStock = stock <= (product.minStock || 0);

               // Price Logic: If has variants, show Lowest Price
               let displayPrice = product.displayPrice !== undefined ? product.displayPrice : product.price;
               if (hasVariants && product.displayPrice === undefined) {
                  const prices = product.variants!.map(v => v.price);
                  displayPrice = Math.min(...prices, product.price);
               }

               // Check if pricing is overridden by Customer Level (Tier Price)
               const isTierPrice = product.displayPrice !== undefined && product.displayPrice !== product.price;

               return (
                <div 
                  key={product.id} 
                  onClick={() => onProductSelect(product)} 
                  className="bg-white rounded-xl md:rounded-2xl border border-slate-100 overflow-hidden hover:shadow-xl hover:border-slate-200 transition-all cursor-pointer flex flex-col group relative h-full shadow-sm"
                >
                  <div className="h-32 md:h-40 bg-slate-50 relative flex items-center justify-center overflow-hidden">
                    {product.imageUrl ? (
                      <img src={product.imageUrl} alt={product.name} className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105" />
                    ) : (
                      <Box className="w-10 h-10 md:w-12 md:h-12 text-slate-200" />
                    )}

                    <span className={`absolute top-2 right-2 px-1.5 py-0.5 rounded text-[9px] md:text-[10px] font-bold shadow-sm backdrop-blur-md ${isLowStock ? 'bg-red-500 text-white' : 'bg-white/90 text-slate-800'}`}>
                      {stock} {product.unit}
                    </span>
                  </div>

                  <div className="p-3 md:p-4 flex-1 flex flex-col">
                    <div className="mb-2">
                        <h3 className="font-bold text-slate-900 text-xs md:text-sm leading-tight line-clamp-2 min-h-[2.5em]">
                           {product.name}
                        </h3>
                        <p className="text-[10px] text-slate-400 mt-1 font-mono hidden md:block">{product.sku}</p>
                    </div>

                    <div className="mt-auto pt-2">
                      <div className="flex items-center justify-between">
                         <div className={`px-2 md:px-3 py-1 md:py-1.5 rounded-full text-xs md:text-sm font-bold shadow-sm flex items-center ${isTierPrice ? 'bg-indigo-50 text-indigo-700 border border-indigo-100' : hasVariants ? 'bg-slate-100 text-slate-700' : 'bg-slate-900 text-white'}`}>
                            {hasVariants && !isTierPrice && <span className="text-[9px] mr-1 text-slate-500 font-normal">From</span>}
                            {formatPrice(displayPrice)}
                         </div>
                         {hasVariants ? (
                            <Layers className="w-4 h-4 md:w-5 md:h-5 text-blue-500 group-hover:text-blue-700 transition-colors" />
                         ) : (
                            <Plus className="w-4 h-4 md:w-5 md:h-5 text-slate-300 group-hover:text-slate-900 transition-colors" />
                         )}
                      </div>
                      {hasVariants && <p className="text-[10px] text-blue-600 mt-1 text-right font-medium">{product.variants!.length} Options</p>}
                    </div>
                  </div>
                </div>
               );
            })}
          </div>
        ) : (
          <div className="bg-white rounded-2xl border border-slate-200 overflow-hidden mb-20">
             <table className="w-full text-left border-collapse">
                <tbody className="divide-y divide-slate-100 text-sm">
                   {paginatedProducts.map(product => {
                      const hasVariants = product.variants && product.variants.length > 0;
                      let displayPrice = product.displayPrice !== undefined ? product.displayPrice : product.price;
                      if (hasVariants && product.displayPrice === undefined) {
                          const prices = product.variants!.map(v => v.price);
                          displayPrice = Math.min(...prices, product.price);
                      }

                      return (
                         <tr key={product.id} className="hover:bg-slate-50 transition-colors cursor-pointer" onClick={() => onProductSelect(product)}>
                            <td className="p-3 pl-4 flex items-center">
                               <div className="w-10 h-10 rounded-lg bg-slate-100 mr-3 flex items-center justify-center">
                                  {product.imageUrl ? <img src={product.imageUrl} className="w-full h-full object-cover rounded-lg"/> : <Box className="w-5 h-5 text-slate-300"/>}
                               </div>
                               <div>
                                  <div className="font-bold text-slate-800">{product.name}</div>
                                  <div className="text-[10px] text-slate-400">{product.sku}</div>
                               </div>
                            </td>
                            <td className="p-3 text-right">
                               <div className="font-bold text-slate-900">
                                  {hasVariants && <span className="text-[10px] font-normal text-slate-500 mr-1">From</span>}
                                  {formatPrice(displayPrice)}
                               </div>
                               {hasVariants && <span className="text-[10px] text-blue-600 bg-blue-50 px-1 rounded">Has Options</span>}
                            </td>
                         </tr>
                      );
                   })}
                </tbody>
             </table>
          </div>
        )}
      </div>

      {/* Pagination Footer */}
      {totalPages > 1 && (
        <div className="p-3 border-t border-slate-100 bg-white flex justify-between items-center z-10 shrink-0">
           <button 
             onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
             disabled={currentPage === 1}
             className="p-2 rounded-lg hover:bg-slate-100 text-slate-600 disabled:opacity-30 disabled:hover:bg-transparent"
           >
             <ChevronLeft className="w-5 h-5" />
           </button>

           <span className="text-sm font-medium text-slate-600">
              Page {currentPage} of {totalPages}
           </span>

           <button 
             onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
             disabled={currentPage === totalPages}
             className="p-2 rounded-lg hover:bg-slate-100 text-slate-600 disabled:opacity-30 disabled:hover:bg-transparent"
           >
             <ChevronRight className="w-5 h-5" />
           </button>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { Product, CategoryItem } from '../../types';
import { AlertTriangle, Box, Edit2, Tag, Trash2, ChevronLeft, ChevronRight } from 'lucide-react';

interface InventoryListProps {
  products: Product[];
  categories: CategoryItem[];
  formatPrice: (price: number) => string;
  viewMode: 'list' | 'grid';
  onEdit: (product: Product) => void;
  onDelete: (id: string) => void;
  onPrintLabel: (product: Product) => void;
}

const ITEMS_PER_PAGE = 20;

export const InventoryList: React.FC<InventoryListProps> = ({ 
  products, 
  categories, 
  formatPrice, 
  viewMode,
  onEdit, 
  onDelete, 
  onPrintLabel 
}) => {
  const [currentPage, setCurrentPage] = useState(1);

  // Reset page when products change (e.g. filter changes)
  useEffect(() => {
    setCurrentPage(1);
  }, [products]);

  const getCategoryName = (idOrName: string) => {
    const cat = categories.find(c => c.id === idOrName);
    return cat ? cat.name : idOrName; 
  };

  const totalPages = Math.ceil(products.length / ITEMS_PER_PAGE);
  const paginatedProducts = useMemo(() => {
    const start = (currentPage - 1) * ITEMS_PER_PAGE;
    return products.slice(start, start + ITEMS_PER_PAGE);
  }, [products, currentPage]);

  if (products.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center flex-1 py-12 text-slate-400">
        <Box className="w-12 h-12 mb-2 opacity-20" />
        <p>No products found matching your filters.</p>
      </div>
    );
  }

  return (
    <div className="flex flex-col flex-1 overflow-hidden">
      <div className="flex-1 overflow-y-auto">
        {/* LIST VIEW (TABLE) */}
        {viewMode === 'list' && (
          <table className="w-full text-left border-collapse">
            <thead className="bg-slate-50 sticky top-0 z-10 shadow-sm">
              <tr>
                <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider whitespace-nowrap pl-8">Product Name</th>
                <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider whitespace-nowrap">SKU / Code</th>
                <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider whitespace-nowrap">Category</th>
                <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider text-right whitespace-nowrap">Price</th>
                <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider text-right whitespace-nowrap">Stock</th>
                <th className="px-6 py-4 text-xs font-bold text-slate-500 uppercase tracking-wider text-center whitespace-nowrap pr-8">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {paginatedProducts.map((product) => {
                const isLowStock = product.stock < (product.minStock || 20);
                return (
                  <tr key={product.id} className={`hover:bg-slate-50 transition-colors group ${isLowStock ? 'bg-red-50/30' : ''}`}>
                    <td className="px-6 py-4 whitespace-nowrap pl-8">
                      <div className="flex items-center space-x-4">
                        <div className="w-10 h-10 rounded-xl overflow-hidden bg-slate-100 flex items-center justify-center shrink-0 border border-slate-100">
                           {product.imageUrl ? (
                             <img src={product.imageUrl} alt={product.name} className="w-full h-full object-cover" />
                           ) : (
                             <Box className="w-5 h-5 text-slate-300" />
                           )}
                        </div>
                        <div>
                          <div className="font-bold text-slate-900 truncate max-w-[200px]" title={product.name}>{product.name}</div>
                          <div className="text-[10px] text-slate-400 mt-0.5 font-mono">ID: {product.id.slice(-6)}</div>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="mb-1">
                         <div className="flex items-center text-xs">
                           <span className="font-mono bg-slate-100 px-1.5 py-0.5 rounded text-slate-600 mr-2 border border-slate-200">{product.sku}</span>
                         </div>
                      </div>
                      {product.variants?.slice(0, 2).map((v) => (
                        <div key={v.id} className="text-[10px] text-slate-500 ml-1 truncate max-w-[150px]">
                           • {v.name}
                        </div>
                      ))}
                      {product.variants && product.variants.length > 2 && <div className="text-[10px] text-slate-400 ml-1">+{product.variants.length - 2} more</div>}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className="px-2.5 py-1 text-xs font-bold bg-slate-100 text-slate-600 rounded-full">
                        {getCategoryName(product.category)}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-right whitespace-nowrap">
                       <div className="text-sm font-bold text-slate-900">{formatPrice(product.price)}</div>
                       <div className="text-[10px] text-slate-400 uppercase">{product.unit}</div>
                    </td>
                    <td className="px-6 py-4 text-right whitespace-nowrap">
                      <div className="flex flex-col items-end">
                        <div className={`font-bold flex items-center justify-end ${isLowStock ? 'text-red-600' : 'text-slate-900'}`}>
                          {isLowStock && (
                            <AlertTriangle className="w-3 h-3 mr-1 text-red-500" />
                          )}
                          {product.stock}
                        </div>
                        <span className="text-[10px] text-slate-400">Min: {product.minStock || 20}</span>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-center whitespace-nowrap pr-8">
                      <div className="flex items-center justify-center space-x-2">
                        <button 
                          onClick={() => onPrintLabel(product)}
                          className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                          title="Print Label"
                        >
                          <Tag className="w-4 h-4" />
                        </button>
                        <button 
                          onClick={() => onEdit(product)}
                          className="p-2 text-slate-400 hover:text-slate-900 hover:bg-slate-100 rounded-lg transition-colors"
                        >
                          <Edit2 className="w-4 h-4" />
                        </button>
                        <button 
                          onClick={() => onDelete(product.id)}
                          className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors"
                        >
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}

        {/* GRID VIEW (CARDS) */}
        {viewMode === 'grid' && (
          <div className="p-4">
             <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
               {paginatedProducts.map((product) => {
                  const isLowStock = product.stock < (product.minStock || 20);
                  return (
                     <div 
                        key={product.id}
                        className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden relative flex flex-col group hover:shadow-md transition-all hover:border-slate-300"
                     >
                        <div className="p-4 flex gap-4 items-start">
                           {/* Image */}
                           <div className="w-16 h-16 bg-slate-50 rounded-xl flex-shrink-0 overflow-hidden flex items-center justify-center relative">
                              {product.imageUrl ? (
                                 <img src={product.imageUrl} alt={product.name} className="w-full h-full object-cover" />
                              ) : (
                                 <Box className="w-6 h-6 text-slate-300" />
                              )}
                           </div>

                           {/* Content */}
                           <div className="flex-1 min-w-0">
                              <h3 className="font-bold text-slate-900 text-sm truncate" title={product.name}>{product.name}</h3>
                              <p className="text-xs text-slate-500 truncate mt-0.5">{getCategoryName(product.category)}</p>
                              <div className="flex items-center gap-2 mt-2">
                                 <span className="text-[10px] font-mono bg-slate-100 px-1.5 py-0.5 rounded text-slate-600 border border-slate-200">{product.sku}</span>
                                 {isLowStock && <span className="text-[10px] bg-red-100 text-red-700 px-1.5 py-0.5 rounded font-bold">Low Stock</span>}
                              </div>
                           </div>
                        </div>

                        <div className="px-4 pb-3 flex justify-between items-end mt-auto">
                           <div>
                              <span className="text-lg font-bold text-slate-900">{formatPrice(product.price)}</span>
                              <span className="text-xs text-slate-400 ml-1">/{product.unit}</span>
                           </div>
                           <div className={`text-sm font-bold ${isLowStock ? 'text-red-600' : 'text-slate-600'}`}>
                              {product.stock} available
                           </div>
                        </div>

                        {/* Actions Footer */}
                        <div className="grid grid-cols-3 border-t border-slate-100 divide-x divide-slate-100 bg-slate-50 opacity-0 group-hover:opacity-100 transition-opacity">
                           <button 
                              onClick={() => onPrintLabel(product)}
                              className="py-3 flex items-center justify-center text-slate-500 hover:bg-white text-xs font-bold hover:text-blue-600 transition-colors"
                           >
                              <Tag className="w-3.5 h-3.5 mr-1.5" /> Label
                           </button>
                           <button 
                              onClick={() => onEdit(product)}
                              className="py-3 flex items-center justify-center text-slate-500 hover:bg-white text-xs font-bold hover:text-slate-900 transition-colors"
                           >
                              <Edit2 className="w-3.5 h-3.5 mr-1.5" /> Edit
                           </button>
                           <button 
                              onClick={() => onDelete(product.id)}
                              className="py-3 flex items-center justify-center text-slate-500 hover:bg-white text-xs font-bold hover:text-red-600 transition-colors"
                           >
                              <Trash2 className="w-3.5 h-3.5 mr-1.5" /> Del
                           </button>
                        </div>
                     </div>
                  );
               })}
             </div>
          </div>
        )}
      </div>

      {/* PAGINATION CONTROLS */}
      {totalPages > 1 && (
        <div className="p-3 border-t border-slate-100 bg-white flex justify-between items-center z-10 shrink-0">
           <button 
             onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
             disabled={currentPage === 1}
             className="p-2 rounded-lg hover:bg-slate-100 text-slate-600 disabled:opacity-30 disabled:hover:bg-transparent transition-colors flex items-center text-sm font-medium"
           >
             <ChevronLeft className="w-4 h-4 mr-1" /> Previous
           </button>

           <span className="text-sm font-medium text-slate-600">
              Page {currentPage} of {totalPages}
              <span className="text-slate-400 ml-2 text-xs">({products.length} items)</span>
           </span>

           <button 
             onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
             disabled={currentPage === totalPages}
             className="p-2 rounded-lg hover:bg-slate-100 text-slate-600 disabled:opacity-30 disabled:hover:bg-transparent transition-colors flex items-center text-sm font-medium"
           >
             Next <ChevronRight className="w-4 h-4 ml-1" />
           </button>
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Customer, SystemSettings } from '../../types';
import { X, Banknote, QrCode, CreditCard, FileText, ChevronLeft, CheckCircle, Loader2, RefreshCw } from 'lucide-react';
import { useGlobal } from '../../context/GlobalContext';
import { PaymentMethodList } from './checkout/PaymentMethodList';
import { PaymentNumpad } from './checkout/PaymentNumpad';

interface CheckoutModalProps {
  isOpen: boolean;
  onClose: () => void;
  total: number;
  onProcessPayment: (method: 'cash' | 'card' | 'transfer' | 'qr' | 'credit', receivedAmount: number, change: number) => Promise<void>;
  selectedCustomer: Customer | null;
  isProcessing: boolean;
  settings?: SystemSettings;
}

export const CheckoutModal: React.FC<CheckoutModalProps> = ({
  isOpen,
  onClose,
  total,
  onProcessPayment,
  selectedCustomer,
  isProcessing,
  settings
}) => {
  const { formatPrice } = useGlobal();
  const [paymentMethod, setPaymentMethod] = useState<'cash' | 'card' | 'transfer' | 'qr' | 'credit'>('cash');
  const [receivedAmountStr, setReceivedAmountStr] = useState('');
  const [checkoutStep, setCheckoutStep] = useState<'method' | 'detail'>('method');

  // OnePay State
  const [qrStatus, setQrStatus] = useState<'generating' | 'waiting' | 'success'>('generating');
  const paymentCheckInterval = useRef<NodeJS.Timeout | null>(null);

  // Keyboard support for immediate confirm
  const receivedAmount = parseFloat(receivedAmountStr) || 0;
  const change = Math.max(0, receivedAmount - total);

  const handleProcess = () => {
    let finalReceived = paymentMethod === 'cash' || paymentMethod === 'credit' ? receivedAmount : total;
    let finalChange = paymentMethod === 'cash' ? change : 0;

    // Auto-fill exact amount for non-cash methods if not set
    if (paymentMethod !== 'cash' && paymentMethod !== 'credit') {
        finalReceived = total;
    }

    onProcessPayment(paymentMethod, finalReceived, finalChange);
  };

  useEffect(() => {
    if (!isOpen) return;
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Enter') {
         e.preventDefault();
         // Check validity before submitting
         if (isProcessing) return;
         if (paymentMethod === 'cash' && receivedAmount < total) return;
         if (paymentMethod === 'credit' && receivedAmount > total) return;

         // Don't auto-submit QR on enter unless success
         if (paymentMethod === 'qr' && qrStatus !== 'success') return;

         handleProcess();
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, paymentMethod, receivedAmount, total, isProcessing, qrStatus]);

  // QR Logic Simulation
  useEffect(() => {
    if (isOpen && paymentMethod === 'qr') {
      setQrStatus('generating');

      // Simulate API Call to generate QR
      setTimeout(() => {
        setQrStatus('waiting');

        // Simulate Polling for success (In real app, this calls an API)
        // Auto-success after 5 seconds for demo
        paymentCheckInterval.current = setTimeout(() => {
           setQrStatus('success');
        }, 5000);

      }, 800);
    } else {
      setQrStatus('generating');
      if (paymentCheckInterval.current) clearTimeout(paymentCheckInterval.current);
    }

    return () => {
      if (paymentCheckInterval.current) clearTimeout(paymentCheckInterval.current);
    };
  }, [isOpen, paymentMethod]);

  if (!isOpen) return null;

  const selectPaymentMethod = (method: 'cash' | 'card' | 'transfer' | 'qr' | 'credit') => {
    if (method === 'credit' && !selectedCustomer) {
      alert("Credit payment requires a registered customer.");
      return;
    }
    setPaymentMethod(method);
    setReceivedAmountStr(''); // Reset for clean entry
    setCheckoutStep('detail');
  };

  const handleQuickCash = (amount: number) => {
    setReceivedAmountStr(amount.toString());
  };

  const getConfirmButtonText = () => {
    if (isProcessing) return 'Processing...';

    if (paymentMethod === 'cash') {
      if (receivedAmount < total) return `Enter Amount (Due: ${formatPrice(total)})`;
      if (change > 0) return `Confirm Pay & Return ${formatPrice(change)}`;
      return `Confirm Payment ${formatPrice(total)}`;
    }

    if (paymentMethod === 'credit') {
       const debt = Math.max(0, total - receivedAmount);
       if (receivedAmount > total) return `Amount exceeds total`;
       if (receivedAmount > 0) return `Pay Deposit ${formatPrice(receivedAmount)} (Debt: ${formatPrice(debt)})`;
       return `Confirm Full Credit (Debt: ${formatPrice(total)})`;
    }

    if (paymentMethod === 'qr') {
       if (qrStatus === 'waiting') return 'Waiting for Scan...';
       if (qrStatus === 'success') return 'Payment Received - Finish';
       return 'Generating QR...';
    }

    return `Confirm Payment ${formatPrice(total)}`;
  };

  return (
    <div className="fixed inset-0 z-50 flex items-end sm:items-center justify-center bg-black/60 backdrop-blur-sm p-0 sm:p-4 animate-fade-in">
      <div className="bg-white w-full h-[100vh] sm:h-[650px] sm:max-w-5xl rounded-t-xl sm:rounded-2xl shadow-2xl flex flex-col sm:flex-row overflow-hidden">

        {/* Method Selection Sidebar (Hidden on Mobile if Detail step active) */}
        <PaymentMethodList 
            paymentMethod={paymentMethod}
            onSelect={selectPaymentMethod}
            onClose={onClose}
            total={total}
            selectedCustomer={selectedCustomer}
            className={`${checkoutStep === 'detail' ? 'hidden sm:flex' : 'flex'} h-full sm:h-auto`}
        />

        {/* Detail / Numpad Area (Hidden on Mobile if Method step active) */}
        <div className={`flex-1 bg-white flex flex-col ${checkoutStep === 'method' ? 'hidden sm:flex' : 'flex'} h-full`}>
           <div className="p-4 border-b border-slate-100 flex items-center justify-between">
              <button onClick={() => setCheckoutStep('method')} className="sm:hidden flex items-center text-slate-500 font-bold hover:text-slate-800 bg-slate-100 px-3 py-1.5 rounded-lg">
                 <ChevronLeft className="w-5 h-5 mr-1" /> Back
              </button>
              <div className="sm:hidden font-bold text-slate-800">Payment</div>
              <button onClick={onClose} className="p-2 hover:bg-slate-100 rounded-full text-slate-400">
                 <X className="w-6 h-6" />
              </button>
           </div>

           <div className="flex-1 p-4 sm:p-8 overflow-y-auto">
              <div className="text-center mb-6">
                 <h3 className="text-xl font-bold text-slate-800 flex items-center justify-center gap-2">
                    {paymentMethod === 'cash' ? <Banknote className="text-blue-600"/> : paymentMethod === 'qr' ? <QrCode className="text-red-600"/> : paymentMethod === 'credit' ? <FileText className="text-orange-500"/> : <CreditCard className="text-blue-600"/>}
                    {paymentMethod === 'cash' ? 'Cash Payment' : paymentMethod === 'qr' ? 'OnePay (BCEL One)' : paymentMethod === 'credit' ? 'Credit / Debt Sale' : 'Digital Payment'}
                 </h3>
              </div>

              {/* Show Numpad for Cash OR Credit */}
              {paymentMethod === 'cash' || paymentMethod === 'credit' ? (
                 <PaymentNumpad 
                    receivedAmountStr={receivedAmountStr}
                    setReceivedAmountStr={setReceivedAmountStr}
                    total={total}
                    change={paymentMethod === 'cash' ? change : 0} 
                    handleQuickCash={handleQuickCash}
                 />
              ) : paymentMethod === 'qr' ? (
                 <div className="flex-1 flex flex-col items-center justify-center">

                    {/* QR Display Container */}
                    <div className={`bg-white p-6 rounded-3xl border-2 shadow-lg mb-6 transition-all duration-500 relative ${qrStatus === 'success' ? 'border-green-500 ring-4 ring-green-100 scale-105' : 'border-slate-100'}`}>

                       {qrStatus === 'success' && (
                          <div className="absolute inset-0 z-10 flex flex-col items-center justify-center bg-white/90 rounded-3xl backdrop-blur-sm animate-fade-in">
                             <CheckCircle className="w-20 h-20 text-green-500 mb-2" />
                             <p className="text-xl font-bold text-green-700">Paid Successfully!</p>
                          </div>
                       )}

                       {/* Priority: Generated OnePay QR logic here */}
                       {qrStatus === 'generating' ? (
                          <div className="w-56 h-56 flex flex-col items-center justify-center">
                             <Loader2 className="w-12 h-12 text-slate-300 animate-spin mb-2" />
                             <p className="text-xs text-slate-400">Generating Code...</p>
                          </div>
                       ) : (
                          // Mock OnePay URL
                          <img 
                             src={`https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=OnePay_${total}_${Date.now()}`} 
                             className="w-56 h-56 md:w-64 md:h-64 object-contain rounded-lg" 
                             alt="OnePay QR" 
                          />
                       )}

                       {/* OnePay Logo Overlay Simulation */}
                       <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 bg-white p-1 rounded-full shadow-md">
                          <QrCode className="w-8 h-8 text-red-600" />
                       </div>
                    </div>

                    <div className="text-center">
                       {qrStatus === 'waiting' && (
                          <>
                             <p className="text-lg font-bold text-slate-800 animate-pulse">Waiting for customer to scan...</p>
                             <p className="text-sm text-slate-500 mt-1">Amount: <span className="font-bold text-red-600">{formatPrice(total)}</span></p>
                             <button 
                                onClick={() => setQrStatus('success')} 
                                className="mt-4 text-xs text-blue-500 underline hover:text-blue-700"
                             >
                                (Simulate Success)
                             </button>
                          </>
                       )}
                       {qrStatus === 'success' && (
                          <p className="text-lg font-bold text-green-600">Transaction Confirmed</p>
                       )}
                    </div>
                 </div>
              ) : (
                 <div className="flex-1 flex flex-col items-center justify-center text-center">
                    <div className="w-32 h-32 bg-slate-100 rounded-full flex items-center justify-center mb-6 animate-pulse">
                       <CreditCard className="w-16 h-16 text-blue-500" />
                    </div>
                    <h4 className="text-xl font-bold text-slate-800 mb-2">
                       Waiting for Terminal
                    </h4>
                    <p className="text-slate-500">Total amount: <strong>{formatPrice(total)}</strong></p>
                 </div>
              )}
           </div>
           <div className="p-4 border-t border-slate-100 bg-white pb-safe">
              <button 
                 onClick={handleProcess}
                 disabled={
                    isProcessing || 
                    (paymentMethod === 'cash' && receivedAmount < total) || 
                    (paymentMethod === 'credit' && receivedAmount > total) ||
                    (paymentMethod === 'qr' && qrStatus !== 'success')
                 }
                 className={`w-full py-4 rounded-xl font-bold text-xl text-white shadow-lg flex items-center justify-center transition-all active:scale-[0.98] disabled:opacity-50 disabled:cursor-not-allowed ${paymentMethod === 'credit' ? 'bg-orange-600' : paymentMethod === 'qr' && qrStatus === 'success' ? 'bg-green-600 hover:bg-green-700' : 'bg-slate-900 hover:bg-slate-800'}`}
              >
                 {isProcessing ? (
                    <>
                       <RefreshCw className="w-6 h-6 mr-2 animate-spin" />
                       Processing...
                    </>
                 ) : (
                    <>
                       <CheckCircle className="w-6 h-6 mr-2" /> 
                       {getConfirmButtonText()}
                    </>
                 )}
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

