import React, { useState, useRef } from 'react';
import { Product, UnitDefinition, CategoryItem, Warehouse, Sale } from '../types';
import { Search, Plus, Sparkles, Download, Upload, ScanBarcode, LayoutGrid, List } from 'lucide-react';
import { useGlobal } from '../context/GlobalContext';
import { BarcodeScanner } from './BarcodeScanner';
import { useInventoryStore } from '../store/useInventoryStore';

// Sub-components
import { InventoryList } from './inventory/InventoryList';
import { ProductFormModal } from './inventory/ProductFormModal';
import { ImportModal } from './inventory/ImportModal';
import { InventoryAiModal } from './inventory/InventoryAiModal';
import { LabelPrintModal } from './inventory/LabelPrintModal';

interface InventoryProps {
  products: Product[];
  units: UnitDefinition[];
  categories: CategoryItem[];
  warehouses?: Warehouse[];
  sales: Sale[];
  onUpdateProduct: (product: Product) => void;
  onDeleteProduct: (id: string) => void;
  onAddProduct: (product: Product) => void;
}

export const Inventory: React.FC<InventoryProps> = ({ sales }) => {
  const { settings, t, formatPrice, customerLevels, branches } = useGlobal(); // Access branches here

  // Store Access
  const products = useInventoryStore((state) => state.products);
  const units = useInventoryStore((state) => state.units);
  const categories = useInventoryStore((state) => state.categories);
  const attributes = useInventoryStore((state) => state.attributes);
  const addProduct = useInventoryStore((state) => state.addProduct);
  const updateProduct = useInventoryStore((state) => state.updateProduct);
  const deleteProduct = useInventoryStore((state) => state.deleteProduct);

  // State
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState<string>('all');
  const [viewMode, setViewMode] = useState<'list' | 'grid'>('list');
  const [isScannerOpen, setIsScannerOpen] = useState(false);

  // Modal States
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Partial<Product> | undefined>(undefined);

  const [isImportOpen, setIsImportOpen] = useState(false);
  const [isAiOpen, setIsAiOpen] = useState(false);

  const [labelProduct, setLabelProduct] = useState<Product | null>(null);

  // --- Filtering ---
  const getCategoryName = (idOrName: string) => {
    const cat = categories.find(c => c.id === idOrName);
    return cat ? cat.name : idOrName; 
  };

  const filteredProducts = products.filter(p => {
    const searchLower = searchTerm.toLowerCase();

    // Check Main Product Fields
    const matchesMain = 
      p.name.toLowerCase().includes(searchLower) || 
      p.sku?.toLowerCase().includes(searchLower) || 
      p.barcode?.includes(searchLower);

    // Check Variant Fields (Code, Barcode, Name/Unit)
    const matchesVariant = p.variants && p.variants.some(v => 
      v.code.toLowerCase().includes(searchLower) ||
      v.barcode?.toLowerCase().includes(searchLower) ||
      v.name.toLowerCase().includes(searchLower)
    );

    const pCatName = getCategoryName(p.category);
    const filterCatName = filterCategory === 'all' ? 'all' : getCategoryName(filterCategory);
    const matchesCategory = filterCategory === 'all' || p.category === filterCategory || pCatName === filterCatName;

    return (matchesMain || matchesVariant) && matchesCategory;
  });

  // --- Handlers ---
  const handleEdit = (product: Product) => {
    setEditingProduct(product);
    setIsFormOpen(true);
  };

  const handleAdd = () => {
    setEditingProduct(undefined);
    setIsFormOpen(true);
  };

  const handleFormSubmit = (product: Product) => {
    if (editingProduct && editingProduct.id) updateProduct(product);
    else addProduct(product);
  };

  const handleImport = (importedProducts: Partial<Product>[], action: 'Create' | 'Update') => {
    importedProducts.forEach(p => {
       const newProduct = {
          ...p,
          id: p.id || `P-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
          category: p.category || categories[0]?.id || 'Uncategorized',
          unit: p.unit || 'pc',
          warehouseInventory: [{ warehouseId: 'wh1', quantity: p.stock || 0 }]
       } as Product;

       if (action === 'Update') updateProduct(newProduct);
       else addProduct(newProduct);
    });
  };

  const handleScan = (code: string) => {
    const normalizedCode = code.trim().toLowerCase();

    // Check if product exists
    const foundProduct = products.find(p => 
      p.barcode?.toLowerCase() === normalizedCode || 
      p.sku?.toLowerCase() === normalizedCode ||
      (p.variants && p.variants.some(v => v.barcode?.toLowerCase() === normalizedCode || v.code.toLowerCase() === normalizedCode))
    );

    if (foundProduct) {
      setSearchTerm(code); // Just filter list to show it
      setIsScannerOpen(false);
    } else {
      // Not found - ask to create
      setIsScannerOpen(false); // Close scanner first

      // Delay confirm slightly to allow the Scanner UI to unmount cleanly
      // This prevents the confirm dialog from getting stuck or scanner staying open
      setTimeout(() => {
        if (window.confirm(`Product not found for barcode: ${code}.\n\nDo you want to create a NEW product with this barcode?`)) {
           setEditingProduct({
              barcode: code,
              sku: code, // Suggest SKU as Barcode initially
              name: '',
              price: 0,
              stock: 0
           });
           setIsFormOpen(true);
        }
      }, 300);
    }
  };

  const handleExportCSV = () => {
    const headers = ['ID', 'Name', 'Category', 'Price', 'Stock', 'SKU'];
    const csvContent = [
      headers.join(','),
      ...filteredProducts.map(p => [p.id, `"${p.name}"`, getCategoryName(p.category), p.price, p.stock, p.sku].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `inventory_export.csv`;
    link.click();
  };

  return (
    <div className="space-y-6 h-full flex flex-col relative pb-20 md:pb-0">
      {/* Header Actions */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">{t('inventory.title')}</h2>
          <p className="text-slate-500">{t('inventory.subtitle')}</p>
        </div>
        <div className="flex gap-2 overflow-x-auto pb-1 md:pb-0 scrollbar-hide">
          <button onClick={handleExportCSV} className="flex items-center px-4 py-2 bg-white border border-slate-200 text-slate-700 rounded-xl hover:bg-slate-50 font-bold text-sm shadow-sm whitespace-nowrap transition-colors">
            <Download className="w-4 h-4 md:mr-2" /> <span className="hidden md:inline">Export</span>
          </button>
          <button onClick={() => setIsImportOpen(true)} className="flex items-center px-4 py-2 bg-white border border-slate-200 text-slate-700 rounded-xl hover:bg-slate-50 font-bold text-sm shadow-sm whitespace-nowrap transition-colors">
            <Upload className="w-4 h-4 md:mr-2" /> <span className="hidden md:inline">Import</span>
          </button>
          <button onClick={() => setIsAiOpen(true)} className="flex items-center px-4 py-2 bg-violet-50 text-violet-700 border border-violet-100 rounded-xl hover:bg-violet-100 font-bold text-sm transition-colors whitespace-nowrap">
            <Sparkles className="w-4 h-4 mr-2" /> {t('inventory.aiInsights')}
          </button>
          <button onClick={handleAdd} className="hidden md:flex items-center px-6 py-2 bg-slate-900 text-white rounded-xl hover:bg-slate-800 font-bold text-sm shadow-md whitespace-nowrap transition-colors">
            <Plus className="w-4 h-4 mr-2" /> {t('inventory.addProduct')}
          </button>
        </div>
      </div>

      {/* Search & Filter - Style A */}
      <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 flex flex-col md:flex-row gap-4">
        <div className="relative flex-1 flex gap-2">
          <div className="relative flex-1">
             <Search className="absolute left-4 top-1/2 transform -translate-y-1/2 text-slate-400 w-5 h-5" />
             <input
               type="text"
               placeholder={t('inventory.searchPlaceholder')}
               className="w-full pl-12 pr-4 py-3 bg-slate-100 border-none rounded-xl text-slate-900 placeholder:text-slate-400 focus:outline-none focus:ring-2 focus:ring-slate-200 transition-all font-medium"
               value={searchTerm}
               onChange={(e) => setSearchTerm(e.target.value)}
             />
          </div>
          <button onClick={() => setIsScannerOpen(true)} className="px-4 py-2 bg-slate-100 rounded-xl hover:bg-slate-200 text-slate-600 transition-colors">
             <ScanBarcode className="w-6 h-6" />
          </button>
        </div>
        <div className="flex gap-2">
          <div className="relative">
             <select 
               value={filterCategory} 
               onChange={(e) => setFilterCategory(e.target.value)} 
               className="appearance-none w-full md:w-48 pl-4 pr-10 py-3 bg-slate-100 border-none rounded-xl text-slate-700 font-medium focus:outline-none focus:ring-2 focus:ring-slate-200 cursor-pointer"
             >
               <option value="all">{t('inventory.allCategories')}</option>
               {categories.map(cat => <option key={cat.id} value={cat.id}>{cat.name}</option>)}
             </select>
             <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-4 text-slate-500">
               <svg className="fill-current h-4 w-4" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20"><path d="M9.293 12.95l.707.707L15.657 8l-1.414-1.414L10 10.828 5.757 6.586 4.343 8z"/></svg>
             </div>
          </div>

          <div className="flex bg-slate-100 p-1 rounded-xl">
             <button 
                onClick={() => setViewMode('list')}
                className={`p-2.5 rounded-lg transition-all ${viewMode === 'list' ? 'bg-white shadow-sm text-slate-900' : 'text-slate-400 hover:text-slate-600'}`}
                title="List View"
             >
                <List className="w-5 h-5" />
             </button>
             <button 
                onClick={() => setViewMode('grid')}
                className={`p-2.5 rounded-lg transition-all ${viewMode === 'grid' ? 'bg-white shadow-sm text-slate-900' : 'text-slate-400 hover:text-slate-600'}`}
                title="Grid View"
             >
                <LayoutGrid className="w-5 h-5" />
             </button>
          </div>
        </div>
      </div>

      {/* Inventory List */}
      <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden flex-1 flex flex-col relative">
        <InventoryList 
          products={filteredProducts} 
          categories={categories} 
          formatPrice={formatPrice} 
          viewMode={viewMode}
          onEdit={handleEdit} 
          onDelete={deleteProduct} 
          onPrintLabel={(p) => setLabelProduct(p)} 
        />
      </div>

      {/* Mobile FAB */}
      <button onClick={handleAdd} className="md:hidden fixed bottom-20 right-6 w-14 h-14 bg-slate-900 text-white rounded-full shadow-xl flex items-center justify-center z-40 hover:bg-slate-800 active:scale-95 transition-all">
          <Plus className="w-8 h-8" />
      </button>

      {/* Modals */}
      <BarcodeScanner isOpen={isScannerOpen} onClose={() => setIsScannerOpen(false)} onScan={handleScan} />

      <ProductFormModal 
        isOpen={isFormOpen} 
        onClose={() => setIsFormOpen(false)} 
        onSubmit={handleFormSubmit} 
        initialData={editingProduct as Product} 
        categories={categories} 
        units={units}
        attributes={attributes}
        currencySymbol={settings.currencySymbol}
        customerLevels={customerLevels || []} 
        branches={branches}
      />

      <ImportModal 
        isOpen={isImportOpen} 
        onClose={() => setIsImportOpen(false)} 
        onImport={handleImport}
        currencySymbol={settings.currencySymbol}
        formatPrice={formatPrice}
      />

      <InventoryAiModal 
        isOpen={isAiOpen} 
        onClose={() => setIsAiOpen(false)} 
        products={products} 
        sales={sales} 
        formatPrice={formatPrice} 
      />

      {labelProduct && (
        <LabelPrintModal 
          isOpen={!!labelProduct} 
          onClose={() => setLabelProduct(null)} 
          product={labelProduct} 
          formatPrice={formatPrice} 
        />
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { Product, CartItem, EstimateResultItem, SystemSettings, Customer, Sale, ProductVariant } from '../types';
import { Sparkles, User, ClipboardList, Monitor, Menu, ChevronLeft } from 'lucide-react';
import { AiAssistant } from './AiAssistant';
import { BarcodeScanner } from './BarcodeScanner';
import { useGlobal } from '../context/GlobalContext';
import { useCartStore } from '../store/useCartStore';

// Sub-components
import { ProductGrid } from './pos/ProductGrid';
import { CartSidebar } from './pos/CartSidebar';
import { CheckoutModal } from './pos/CheckoutModal';
import { ReceiptModal } from './pos/ReceiptModal';
import { CustomerModal } from './pos/CustomerModal';
import { DiscountModal } from './pos/DiscountModal';
import { RecallModal } from './pos/RecallModal';
import { VariantSelectorModal } from './pos/VariantSelectorModal';

interface PosTerminalProps {
  products: Product[];
  onProcessSale: (
    items: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number,
    paymentMethod?: 'cash' | 'card' | 'transfer' | 'qr' | 'credit',
    amountReceived?: number,
    change?: number,
    pointsRedeemed?: number,
    source?: 'pos' | 'back-office'
  ) => Promise<Sale>;
  settings?: SystemSettings;
}

export const PosTerminal: React.FC<PosTerminalProps> = ({ products, onProcessSale, settings }) => {
  const { customers, customerLevels, t, branches, warehouses, currentUser, formatPrice } = useGlobal();
  const { 
    cart, addToCart, clearCart,
    heldOrders, holdCurrentOrder, recallOrder, discardHeldOrder
  } = useCartStore();

  const [searchTerm, setSearchTerm] = useState('');
  const [isAiModalOpen, setIsAiModalOpen] = useState(false);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isScannerOpen, setIsScannerOpen] = useState(false); 

  // Modal States
  const [isDiscountModalOpen, setIsDiscountModalOpen] = useState(false);
  const [isCustomerModalOpen, setIsCustomerModalOpen] = useState(false);
  const [isRecallModalOpen, setIsRecallModalOpen] = useState(false);
  const [isCheckoutOpen, setIsCheckoutOpen] = useState(false);
  const [isReceiptOpen, setIsReceiptOpen] = useState(false);
  const [productForSelector, setProductForSelector] = useState<Product | null>(null);

  // Transaction State
  const [manualDiscount, setManualDiscount] = useState<{ type: 'percent' | 'fixed', value: number } | null>(null);
  const [redeemPoints, setRedeemPoints] = useState<number>(0);
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);
  const [lastSale, setLastSale] = useState<Sale | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  // --- Branch Logic (Inventory Filtering) ---
  const activeBranchId = settings?.currentBranchId || currentUser?.branchId || (branches.length > 0 ? branches[0].id : '');

  const branchProducts = useMemo(() => {
    if (!activeBranchId) return products;

    const branchWarehouseIds = warehouses
      .filter(w => w.branchId === activeBranchId)
      .map(w => w.id);

    return products.map(p => {
      const branchStock = p.warehouseInventory?.reduce((acc, inv) => {
        if (branchWarehouseIds.includes(inv.warehouseId)) {
          return acc + inv.quantity;
        }
        return acc;
      }, 0) || 0;

      const branchPriceConfig = p.branchPrices?.find(bp => bp.branchId === activeBranchId);
      const effectivePrice = branchPriceConfig ? branchPriceConfig.price : p.price;

      return {
        ...p,
        stock: branchStock,
        price: effectivePrice
      };
    });
  }, [products, activeBranchId, warehouses]);

  // --- Helper: Get Dynamic Price based on Customer Level ---
  const getDynamicPrice = (product: Product, variantId?: string): number => {
    // 1. Determine Base Price (Variant or Product)
    let basePrice = product.price;
    let tierPrices = product.tierPrices;

    if (variantId && product.variants) {
      const variant = product.variants.find(v => v.id === variantId);
      if (variant) {
        basePrice = variant.price;
        tierPrices = variant.tierPrices || product.tierPrices; // Fallback to product tiers if variant doesn't have specific ones
      }
    }

    if (!selectedCustomer?.levelId) return basePrice;

    // 2. Check Specific Tier Price
    if (tierPrices && tierPrices[selectedCustomer.levelId]) {
      return tierPrices[selectedCustomer.levelId];
    }

    // 3. Check Level Percentage Discount
    const level = customerLevels.find(l => l.id === selectedCustomer.levelId);
    if (level && level.discountPercentage > 0) {
      return basePrice * (1 - level.discountPercentage / 100);
    }

    return basePrice;
  };

  // --- Handlers ---
  const handleProductSelect = (product: Product) => {
    if (product.variants && product.variants.length > 0) {
      setProductForSelector(product);
    } else {
      // Calculate price immediately
      const price = getDynamicPrice(product);
      addToCart({ ...product, price }, 1);
    }
  };

  const handleConfirmSelection = (product: Product, quantity: number, variantId?: string) => {
    const price = getDynamicPrice(product, variantId);
    addToCart({ ...product, price }, quantity, variantId);
    setProductForSelector(null);
  };

  // --- Calculations ---
  const customerLevel = useMemo(() => {
    if (!selectedCustomer?.levelId) return null;
    return customerLevels.find(l => l.id === selectedCustomer.levelId);
  }, [selectedCustomer, customerLevels]);

  const rawSubtotal = cart.reduce((sum, item) => sum + (item.sellPrice * item.quantity), 0);
  const customerDiscountAmount = 0; 

  let manualDiscountAmount = 0;
  if (manualDiscount) {
    if (manualDiscount.type === 'percent') {
      manualDiscountAmount = rawSubtotal * (manualDiscount.value / 100);
    } else {
      manualDiscountAmount = manualDiscount.value;
    }
  }

  const redeemRate = settings?.loyaltyProgram?.redeemRate || 100;
  const loyaltyDiscountAmount = redeemPoints > 0 ? redeemPoints / redeemRate : 0;

  let discountAmount = Math.min(customerDiscountAmount + manualDiscountAmount + loyaltyDiscountAmount, rawSubtotal);
  let discountedSubtotal = rawSubtotal - discountAmount;

  let taxAmount = 0;
  let finalTotal = discountedSubtotal;
  const taxConfig = settings?.tax;

  if (taxConfig && taxConfig.enabled) {
    const rate = taxConfig.rate / 100;
    if (taxConfig.calculationMode === 'excluded') {
       taxAmount = discountedSubtotal * rate;
       finalTotal = discountedSubtotal + taxAmount;
    } else {
       taxAmount = discountedSubtotal - (discountedSubtotal / (1 + rate));
       finalTotal = discountedSubtotal;
    }
  }

  // --- Broadcast Channel ---
  useEffect(() => {
    if (settings?.customerDisplay?.enabled) {
      const payload = {
        type: isCheckoutOpen ? 'CHECKOUT' : (cart.length === 0 ? 'RESET' : 'UPDATE'),
        cart,
        subtotal: rawSubtotal,
        discount: discountAmount,
        tax: taxAmount,
        total: finalTotal,
        customer: selectedCustomer,
        companyName: settings?.companyName,
        settings: settings?.customerDisplay
      };
      const channel = new BroadcastChannel('customer_display_channel');
      channel.postMessage(payload);
      return () => channel.close();
    }
  }, [cart, rawSubtotal, discountAmount, taxAmount, finalTotal, selectedCustomer, isCheckoutOpen, settings]);

  const handleOpenCustomerDisplay = () => {
    window.open('/customer-display', 'CustomerDisplay', 'width=1024,height=768,menubar=no,toolbar=no,location=no,status=no');
  };

  useEffect(() => {
     setRedeemPoints(0);
  }, [selectedCustomer]);

  // --- Keyboard Shortcuts ---
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement;

      if (e.key === 'F4') {
        e.preventDefault();
        setIsCustomerModalOpen(true);
      }
      else if (e.key === 'F6') {
        e.preventDefault();
        setIsRecallModalOpen(true);
      }
      else if (e.key === 'F8') {
        e.preventDefault();
        setIsDiscountModalOpen(true);
      }
      else if (e.key === 'F9') {
        e.preventDefault();
        const searchInput = document.getElementById('pos-search-input');
        if (searchInput) {
            searchInput.focus();
            (searchInput as HTMLInputElement).select();
        }
      }
      else if (e.key === 'F12' || (e.key === 'Enter' && e.ctrlKey)) {
        e.preventDefault();
        if (cart.length > 0 && !isCheckoutOpen && !isReceiptOpen) {
           setIsCheckoutOpen(true);
        }
      }
      else if (e.key === 'Escape') {
         if (isCheckoutOpen) setIsCheckoutOpen(false);
         else if (isDiscountModalOpen) setIsDiscountModalOpen(false);
         else if (isCustomerModalOpen) setIsCustomerModalOpen(false);
         else if (isRecallModalOpen) setIsRecallModalOpen(false);
         else if (isReceiptOpen) setIsReceiptOpen(false);
         else if (isAiModalOpen) setIsAiModalOpen(false);
         else if (isScannerOpen) setIsScannerOpen(false);
         else if (isCartOpen) setIsCartOpen(false);
         else if (productForSelector) setProductForSelector(null);
         else if (document.activeElement?.id === 'pos-search-input') {
            setSearchTerm('');
            (document.activeElement as HTMLInputElement).blur();
         }
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [
    cart.length, 
    isCheckoutOpen, 
    isDiscountModalOpen, 
    isCustomerModalOpen, 
    isRecallModalOpen, 
    isReceiptOpen, 
    isAiModalOpen, 
    isScannerOpen,
    isCartOpen,
    productForSelector
  ]);

  const performScan = (code: string) => {
    const normalizedCode = code.trim().toLowerCase();

    // 1. Priority: Check specific Variant Barcodes first (Direct Add)
    for (const p of branchProducts) {
      if (p.variants) {
        const variantMatch = p.variants.find(v => 
          (v.barcode && v.barcode.toLowerCase() === normalizedCode) || 
          (v.code && v.code.toLowerCase() === normalizedCode)
        );
        if (variantMatch) {
          const price = getDynamicPrice(p, variantMatch.id);
          addToCart({ ...p, price }, 1, variantMatch.id);
          setSearchTerm(''); // Clear for next scan
          return;
        }
      }
    }

    // 2. Check Top-level Product Barcodes/SKUs
    const mainMatch = branchProducts.find(p => 
      (p.barcode && p.barcode.toLowerCase() === normalizedCode) || 
      (p.sku && p.sku.toLowerCase() === normalizedCode)
    );

    if (mainMatch) {
      // If product has variants but user scanned the "Generic" barcode
      if (mainMatch.variants && mainMatch.variants.length > 0) {
         setProductForSelector(mainMatch);
         setSearchTerm('');
      } else {
         // Simple product, add directly
         handleProductSelect(mainMatch);
         setSearchTerm('');
      }
      return;
    }

    // 3. No exact match - The search box handles the filtering visually
    // If user hit Enter, and no exact match, we don't alert, just let them see the filter results
    // alert(`Product not found: ${code}`); // Removed annoying alert
  };

  const handleAiItemsAdded = (items: EstimateResultItem[]) => {
    items.forEach(est => {
      if (est.matchedProductId) {
        const product = branchProducts.find(p => p.id === est.matchedProductId);
        if (product) {
           const price = getDynamicPrice(product);
           addToCart({ ...product, price }, Math.ceil(est.estimatedQuantity), undefined);
        }
      }
    });
  };

  const handleHoldOrder = () => {
    if (cart.length === 0) return;
    const note = prompt("Optional note for this hold:");
    holdCurrentOrder(selectedCustomer, note || undefined);
    setSelectedCustomer(null);
    setManualDiscount(null);
    setRedeemPoints(0);
  };

  const handleRecall = (orderId: string) => {
    const restored = recallOrder(orderId);
    if (restored) {
      setSelectedCustomer(restored.customer || null);
      setIsRecallModalOpen(false);
    }
  };

  const handleProcessPayment = async (
    method: 'cash' | 'card' | 'transfer' | 'qr' | 'credit',
    receivedAmount: number,
    change: number
  ) => {
    setIsProcessing(true);
    try {
      const sale = await onProcessSale(
        cart, finalTotal, selectedCustomer?.id, discountAmount, rawSubtotal,
        method, receivedAmount, change, redeemPoints, 'pos'
      );

      setLastSale(sale);
      setIsCheckoutOpen(false);
      clearCart();
      setManualDiscount(null); 
      setRedeemPoints(0);
      setSelectedCustomer(null);
      setIsReceiptOpen(true);
    } catch (error) {
      console.error("Sale failed", error);
      alert("Transaction failed. Please try again.");
    } finally {
      setIsProcessing(false);
    }
  };

  const cartItemCount = cart.reduce((acc, item) => acc + item.quantity, 0);

  // Inject current pricing for grid display
  const productsWithDisplayPrice = useMemo(() => {
     return branchProducts.map(p => {
        return {
           ...p,
           displayPrice: getDynamicPrice(p) // used for display in grid
        };
     });
  }, [branchProducts, selectedCustomer, customerLevels]);

  return (
    <div className="flex flex-col lg:flex-row h-full overflow-hidden bg-white md:-m-6">
      {/* Main Product Area (Left Side) */}
      <div className="flex-1 flex flex-col min-w-0 h-full overflow-hidden relative border-r border-slate-200">

        {/* Header / Top Bar for POS - Style A */}
        <div className="px-6 py-4 bg-white flex items-center justify-between shrink-0">
          <div className="flex items-center gap-4">
            <h2 className="text-2xl font-extrabold text-slate-900 hidden md:block">{t('pos.newOrder')}</h2>

            <div className="flex space-x-2">
               <button 
                 onClick={() => setIsRecallModalOpen(true)}
                 disabled={heldOrders.length === 0}
                 title="Shortcut: F6"
                 className={`flex items-center px-4 py-2 rounded-full text-sm font-bold border transition-colors ${
                   heldOrders.length > 0 
                     ? 'bg-orange-50 text-orange-700 border-orange-200 hover:bg-orange-100' 
                     : 'bg-slate-50 text-slate-400 border-transparent cursor-not-allowed'
                 }`}
               >
                 <ClipboardList className="w-4 h-4 mr-2" />
                 Recall
                 {heldOrders.length > 0 && <span className="ml-2 bg-orange-200 text-orange-800 px-1.5 rounded-full text-xs font-bold">{heldOrders.length}</span>}
               </button>

               <button onClick={() => setIsAiModalOpen(true)} className="flex items-center px-4 py-2 bg-violet-50 text-violet-700 border border-violet-100 rounded-full hover:bg-violet-100 transition-all text-sm font-bold whitespace-nowrap">
                  <Sparkles className="w-4 h-4 mr-2" /> AI Estimate
               </button>
            </div>
          </div>

          <div className="flex items-center space-x-3">
             {settings?.customerDisplay?.enabled && (
               <button onClick={handleOpenCustomerDisplay} className="hidden xl:flex items-center px-3 py-2 text-slate-500 hover:text-slate-800 hover:bg-slate-100 rounded-lg transition-colors text-sm">
                 <Monitor className="w-4 h-4 mr-2" /> Screen
               </button>
             )}

             <button 
              onClick={() => setIsCustomerModalOpen(true)}
              title="Shortcut: F4"
              className={`flex items-center px-5 py-2.5 rounded-full shadow-sm font-bold text-sm border transition-all ${
                selectedCustomer 
                  ? 'bg-slate-900 text-white border-slate-900 hover:bg-slate-800' 
                  : 'bg-white text-slate-700 border-slate-200 hover:border-slate-400'
              }`}
            >
              <User className="w-4 h-4 mr-2" />
              {selectedCustomer ? (
                 <div className="flex flex-col items-start leading-none">
                    <span>{selectedCustomer.name}</span>
                    {customerLevel && <span className="text-[9px] opacity-80 font-normal uppercase">{customerLevel.name}</span>}
                 </div>
              ) : 'Select Customer'}
            </button>
          </div>
        </div>

        {/* Product Grid Container */}
        <div className="flex-1 overflow-hidden relative">
           <ProductGrid 
             products={productsWithDisplayPrice} 
             searchTerm={searchTerm}
             setSearchTerm={setSearchTerm}
             onScanClick={() => setIsScannerOpen(true)}
             onScan={performScan}
             onProductSelect={handleProductSelect}
           />
        </div>
      </div>

      {/* Cart Sidebar (Right Side) */}
      <div className={`
         fixed inset-0 z-40 bg-white transform transition-transform duration-300 lg:relative lg:translate-x-0 lg:w-[420px] xl:w-[480px] shadow-2xl lg:shadow-none
         ${isCartOpen ? 'translate-x-0' : 'translate-x-full lg:translate-x-0'}
      `}>
         <CartSidebar 
            isOpen={isCartOpen}
            onClose={() => setIsCartOpen(false)}
            selectedCustomer={selectedCustomer}
            onRemoveCustomer={() => setSelectedCustomer(null)}
            onHoldOrder={handleHoldOrder}
            onCheckout={() => setIsCheckoutOpen(true)}
            onDiscountClick={() => setIsDiscountModalOpen(true)}
            subtotal={rawSubtotal}
            discount={discountAmount}
            tax={taxAmount}
            total={finalTotal}
            settings={settings}
         />
      </div>

      {/* Mobile Cart Toggle Button */}
      {cartItemCount > 0 && !isCartOpen && (
        <button 
          onClick={() => setIsCartOpen(true)}
          className="lg:hidden fixed bottom-6 right-6 z-50 bg-slate-900 text-white pl-4 pr-6 py-4 rounded-full shadow-2xl flex items-center justify-between min-w-[200px] animate-bounce-in"
        >
          <div className="flex items-center">
            <span className="bg-orange-500 rounded-full w-8 h-8 flex items-center justify-center font-bold text-xs mr-3">
              {cartItemCount}
            </span>
            <span className="font-bold text-sm">Order Ticket</span>
          </div>
          <span className="font-bold text-lg ml-4">{formatPrice(finalTotal)}</span>
        </button>
      )}

      {/* Modals */}
      <CheckoutModal 
        isOpen={isCheckoutOpen}
        onClose={() => setIsCheckoutOpen(false)}
        total={finalTotal}
        onProcessPayment={handleProcessPayment}
        selectedCustomer={selectedCustomer}
        isProcessing={isProcessing}
        settings={settings} 
      />

      <ReceiptModal 
        isOpen={isReceiptOpen}
        onClose={() => setIsReceiptOpen(false)}
        sale={lastSale}
        settings={settings}
      />

      <CustomerModal 
        isOpen={isCustomerModalOpen}
        onClose={() => setIsCustomerModalOpen(false)}
        customers={customers}
        onSelectCustomer={(c) => { setSelectedCustomer(c); setIsCustomerModalOpen(false); }}
      />

      <DiscountModal 
        isOpen={isDiscountModalOpen}
        onClose={() => setIsDiscountModalOpen(false)}
        onApplyDiscount={setManualDiscount}
        currencySymbol={settings?.currencySymbol}
      />

      <RecallModal 
        isOpen={isRecallModalOpen}
        onClose={() => setIsRecallModalOpen(false)}
        heldOrders={heldOrders}
        onRecall={handleRecall}
        onDiscard={discardHeldOrder}
      />

      <AiAssistant 
        isOpen={isAiModalOpen} 
        onClose={() => setIsAiModalOpen(false)} 
        inventory={branchProducts} 
        onAddItemsToCart={handleAiItemsAdded} 
      />

      <BarcodeScanner 
        isOpen={isScannerOpen} 
        onClose={() => setIsScannerOpen(false)} 
        onScan={performScan} 
      />

      {productForSelector && (
        <VariantSelectorModal 
          product={productForSelector}
          isOpen={!!productForSelector}
          onClose={() => setProductForSelector(null)}
          onConfirm={handleConfirmSelection}
          formatPrice={formatPrice}
        />
      )}
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { Product, UnitDefinition, CategoryItem, Warehouse, Sale } from '../types';
import { Search, Plus, Sparkles, Download, Upload, ScanBarcode, LayoutGrid, List, AlertCircle, X } from 'lucide-react';
import { useGlobal } from '../context/GlobalContext';
import { BarcodeScanner } from './BarcodeScanner';
import { useInventoryStore } from '../store/useInventoryStore';

// Sub-components
import { InventoryList } from './inventory/InventoryList';
import { ProductFormModal } from './inventory/ProductFormModal';
import { ImportModal } from './inventory/ImportModal';
import { InventoryAiModal } from './inventory/InventoryAiModal';
import { LabelPrintModal } from './inventory/LabelPrintModal';

interface InventoryProps {
  products: Product[];
  units: UnitDefinition[];
  categories: CategoryItem[];
  warehouses?: Warehouse[];
  sales: Sale[];
  onUpdateProduct: (product: Product) => void;
  onDeleteProduct: (id: string) => void;
  onAddProduct: (product: Product) => void;
}

export const Inventory: React.FC<InventoryProps> = ({ sales }) => {
  const { settings, t, formatPrice, customerLevels, branches } = useGlobal(); // Access branches here

  // Store Access
  const products = useInventoryStore((state) => state.products);
  const units = useInventoryStore((state) => state.units);
  const categories = useInventoryStore((state) => state.categories);
  const attributes = useInventoryStore((state) => state.attributes);
  const addProduct = useInventoryStore((state) => state.addProduct);
  const updateProduct = useInventoryStore((state) => state.updateProduct);
  const deleteProduct = useInventoryStore((state) => state.deleteProduct);

  // State
  const [searchTerm, setSearchTerm] = useState('');
  const [filterCategory, setFilterCategory] = useState<string>('all');
  const [viewMode, setViewMode] = useState<'list' | 'grid'>('list');
  const [isScannerOpen, setIsScannerOpen] = useState(false);
  const [unknownCode, setUnknownCode] = useState<string | null>(null);

  // Modal States
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingProduct, setEditingProduct] = useState<Partial<Product> | undefined>(undefined);

  const [isImportOpen, setIsImportOpen] = useState(false);
  const [isAiOpen, setIsAiOpen] = useState(false);

  const [labelProduct, setLabelProduct] = useState<Product | null>(null);

  // --- Filtering ---
  const getCategoryName = (idOrName: string) => {
    const cat = categories.find(c => c.id === idOrName);
    return cat ? cat.name : idOrName; 
  };

  const filteredProducts = products.filter(p => {
    const searchLower = searchTerm.toLowerCase();

    // Check Main Product Fields
    const matchesMain = 
      p.name.toLowerCase().includes(searchLower) || 
      p.sku?.toLowerCase().includes(searchLower) || 
      p.barcode?.includes(searchLower);

    // Check Variant Fields (Code, Barcode, Name/Unit)
    const matchesVariant = p.variants && p.variants.some(v => 
      v.code.toLowerCase().includes(searchLower) ||
      v.barcode?.toLowerCase().includes(searchLower) ||
      v.name.toLowerCase().includes(searchLower)
    );

    const pCatName = getCategoryName(p.category);
    const filterCatName = filterCategory === 'all' ? 'all' : getCategoryName(filterCategory);
    const matchesCategory = filterCategory === 'all' || p.category === filterCategory || pCatName === filterCatName;

    return (matchesMain || matchesVariant) && matchesCategory;
  });

  // --- Handlers ---
  const handleEdit = (product: Product) => {
    setEditingProduct(product);
    setIsFormOpen(true);
  };

  const handleAdd = () => {
    setEditingProduct(undefined);
    setIsFormOpen(true);
  };

  const handleFormSubmit = (product: Product) => {
    if (editingProduct && editingProduct.id) updateProduct(product);
    else addProduct(product);
  };

  const handleImport = (importedProducts: Partial<Product>[], action: 'Create' | 'Update') => {
    importedProducts.forEach(p => {
       const newProduct = {
          ...p,
          id: p.id || `P-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
          category: p.category || categories[0]?.id || 'Uncategorized',
          unit: p.unit || 'pc',
          warehouseInventory: [{ warehouseId: 'wh1', quantity: p.stock || 0 }]
       } as Product;

       if (action === 'Update') updateProduct(newProduct);
       else addProduct(newProduct);
    });
  };

  const handleScan = (code: string) => {
    const normalizedCode = code.trim().toLowerCase();

    // Check if product exists
    const foundProduct = products.find(p => 
      p.barcode?.toLowerCase() === normalizedCode || 
      p.sku?.toLowerCase() === normalizedCode ||
      (p.variants && p.variants.some(v => v.barcode?.toLowerCase() === normalizedCode || v.code.toLowerCase() === normalizedCode))
    );

    if (foundProduct) {
      setSearchTerm(code); // Just filter list to show it
      setIsScannerOpen(false);
    } else {
      // Not found - close scanner and show custom modal
      setIsScannerOpen(false);
      setUnknownCode(code);
    }
  };

  const handleCreateFromScan = () => {
    if (!unknownCode) return;
    setEditingProduct({
       barcode: unknownCode,
       sku: unknownCode, // Suggest SKU as Barcode initially
       name: '',
       price: 0,
       stock: 0
    });
    setUnknownCode(null);
    setIsFormOpen(true);
  };

  const handleExportCSV = () => {
    const headers = ['ID', 'Name', 'Category', 'Price', 'Stock', 'SKU'];
    const csvContent = [
      headers.join(','),
      ...filteredProducts.map(p => [p.id, `"${p.name}"`, getCategoryName(p.category), p.price, p.stock, p.sku].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `inventory_export.csv`;
    link.click();
  };

  return (
    <div className="space-y-6 h-full flex flex-col relative pb-20 md:pb-0">
      {/* Header Actions */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-900">{t('inventory.title')}</h2>
          <p className="text-slate-500">{t('inventory.subtitle')}</p>
        </div>
        <div className="flex gap-2 overflow-x-auto pb-1 md:pb-0 scrollbar-hide">
          <button onClick={handleExportCSV} className="flex items-center px-4 py-2 bg-white border border-slate-200 text-slate-700 rounded-xl hover:bg-slate-50 font-bold text-sm shadow-sm whitespace-nowrap transition-colors">
            <Download className="w-4 h-4 md:mr-2" /> <span className="hidden md:inline">Export</span>
          </button>
          <button onClick={() => setIsImportOpen(true)} className="flex items-center px-4 py-2 bg-white border border-slate-200 text-slate-700 rounded-xl hover:bg-slate-50 font-bold text-sm shadow-sm whitespace-nowrap transition-colors">
            <Upload className="w-4 h-4 md:mr-2" /> <span className="hidden md:inline">Import</span>
          </button>
          <button onClick={() => setIsAiOpen(true)} className="flex items-center px-4 py-2 bg-violet-50 text-violet-700 border border-violet-100 rounded-xl hover:bg-violet-100 font-bold text-sm transition-colors whitespace-nowrap">
            <Sparkles className="w-4 h-4 mr-2" /> {t('inventory.aiInsights')}
          </button>
          <button onClick={handleAdd} className="hidden md:flex items-center px-6 py-2 bg-slate-900 text-white rounded-xl hover:bg-slate-800 font-bold text-sm shadow-md whitespace-nowrap transition-colors">
            <Plus className="w-4 h-4 mr-2" /> {t('inventory.addProduct')}
          </button>
        </div>
      </div>

      {/* Search & Filter - Style A */}
      <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100 flex flex-col md:flex-row gap-4">
        <div className="relative flex-1 flex gap-2">
          <div className="relative flex-1">
             <Search className="absolute left-4 top-1/2 transform -translate-y-1/2 text-slate-400 w-5 h-5" />
             <input
               type="text"
               placeholder={t('inventory.searchPlaceholder')}
               className="w-full pl-12 pr-4 py-3 bg-slate-100 border-none rounded-xl text-slate-900 placeholder:text-slate-400 focus:outline-none focus:ring-2 focus:ring-slate-200 transition-all font-medium"
               value={searchTerm}
               onChange={(e) => setSearchTerm(e.target.value)}
             />
          </div>
          <button onClick={() => setIsScannerOpen(true)} className="px-4 py-2 bg-slate-100 rounded-xl hover:bg-slate-200 text-slate-600 transition-colors">
             <ScanBarcode className="w-6 h-6" />
          </button>
        </div>
        <div className="flex gap-2">
          <div className="relative">
             <select 
               value={filterCategory} 
               onChange={(e) => setFilterCategory(e.target.value)} 
               className="appearance-none w-full md:w-48 pl-4 pr-10 py-3 bg-slate-100 border-none rounded-xl text-slate-700 font-medium focus:outline-none focus:ring-2 focus:ring-slate-200 cursor-pointer"
             >
               <option value="all">{t('inventory.allCategories')}</option>
               {categories.map(cat => <option key={cat.id} value={cat.id}>{cat.name}</option>)}
             </select>
             <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-4 text-slate-500">
               <svg className="fill-current h-4 w-4" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20"><path d="M9.293 12.95l.707.707L15.657 8l-1.414-1.414L10 10.828 5.757 6.586 4.343 8z"/></svg>
             </div>
          </div>

          <div className="flex bg-slate-100 p-1 rounded-xl">
             <button 
                onClick={() => setViewMode('list')}
                className={`p-2.5 rounded-lg transition-all ${viewMode === 'list' ? 'bg-white shadow-sm text-slate-900' : 'text-slate-400 hover:text-slate-600'}`}
                title="List View"
             >
                <List className="w-5 h-5" />
             </button>
             <button 
                onClick={() => setViewMode('grid')}
                className={`p-2.5 rounded-lg transition-all ${viewMode === 'grid' ? 'bg-white shadow-sm text-slate-900' : 'text-slate-400 hover:text-slate-600'}`}
                title="Grid View"
             >
                <LayoutGrid className="w-5 h-5" />
             </button>
          </div>
        </div>
      </div>

      {/* Inventory List */}
      <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden flex-1 flex flex-col relative">
        <InventoryList 
          products={filteredProducts} 
          categories={categories} 
          formatPrice={formatPrice} 
          viewMode={viewMode}
          onEdit={handleEdit} 
          onDelete={deleteProduct} 
          onPrintLabel={(p) => setLabelProduct(p)} 
        />
      </div>

      {/* Mobile FAB */}
      <button onClick={handleAdd} className="md:hidden fixed bottom-20 right-6 w-14 h-14 bg-slate-900 text-white rounded-full shadow-xl flex items-center justify-center z-40 hover:bg-slate-800 active:scale-95 transition-all">
          <Plus className="w-8 h-8" />
      </button>

      {/* Modals */}
      <BarcodeScanner isOpen={isScannerOpen} onClose={() => setIsScannerOpen(false)} onScan={handleScan} />

      {/* Product Not Found Modal */}
      {unknownCode && (
        <div className="fixed inset-0 bg-black/60 z-[80] flex items-center justify-center p-4 animate-fade-in">
           <div className="bg-white rounded-2xl shadow-xl w-full max-w-sm overflow-hidden">
              <div className="p-6 text-center">
                 <div className="w-16 h-16 bg-orange-100 rounded-full flex items-center justify-center mx-auto mb-4">
                    <ScanBarcode className="w-8 h-8 text-orange-600" />
                 </div>
                 <h3 className="text-lg font-bold text-slate-900 mb-2">Product Not Found</h3>
                 <p className="text-slate-500 text-sm mb-1">
                    The barcode <span className="font-mono font-bold text-slate-800">{unknownCode}</span> does not exist in the system.
                 </p>
                 <p className="text-slate-500 text-sm">Would you like to add it now?</p>
              </div>
              <div className="flex border-t border-slate-100">
                 <button 
                    onClick={() => setUnknownCode(null)}
                    className="flex-1 py-4 text-slate-600 font-bold hover:bg-slate-50 transition-colors border-r border-slate-100"
                 >
                    Cancel
                 </button>
                 <button 
                    onClick={handleCreateFromScan}
                    className="flex-1 py-4 text-blue-600 font-bold hover:bg-blue-50 transition-colors flex items-center justify-center"
                 >
                    <Plus className="w-4 h-4 mr-2" /> Create Product
                 </button>
              </div>
           </div>
        </div>
      )}

      <ProductFormModal 
        isOpen={isFormOpen} 
        onClose={() => setIsFormOpen(false)} 
        onSubmit={handleFormSubmit} 
        initialData={editingProduct as Product} 
        categories={categories} 
        units={units}
        attributes={attributes}
        currencySymbol={settings.currencySymbol}
        customerLevels={customerLevels || []} 
        branches={branches}
      />

      <ImportModal 
        isOpen={isImportOpen} 
        onClose={() => setIsImportOpen(false)} 
        onImport={handleImport}
        currencySymbol={settings.currencySymbol}
        formatPrice={formatPrice}
      />

      <InventoryAiModal 
        isOpen={isAiOpen} 
        onClose={() => setIsAiOpen(false)} 
        products={products} 
        sales={sales} 
        formatPrice={formatPrice} 
      />

      {labelProduct && (
        <LabelPrintModal 
          isOpen={!!labelProduct} 
          onClose={() => setLabelProduct(null)} 
          product={labelProduct} 
          formatPrice={formatPrice} 
        />
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { Product, CartItem, EstimateResultItem, SystemSettings, Customer, Sale, ProductVariant } from '../types';
import { Sparkles, User, ClipboardList, Monitor, Menu, ChevronLeft } from 'lucide-react';
import { AiAssistant } from './AiAssistant';
import { BarcodeScanner } from './BarcodeScanner';
import { useGlobal } from '../context/GlobalContext';
import { useCartStore } from '../store/useCartStore';

// Sub-components
import { ProductGrid } from './pos/ProductGrid';
import { CartSidebar } from './pos/CartSidebar';
import { CheckoutModal } from './pos/CheckoutModal';
import { ReceiptModal } from './pos/ReceiptModal';
import { CustomerModal } from './pos/CustomerModal';
import { DiscountModal } from './pos/DiscountModal';
import { RecallModal } from './pos/RecallModal';
import { VariantSelectorModal } from './pos/VariantSelectorModal';

interface PosTerminalProps {
  products: Product[];
  onProcessSale: (
    items: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number,
    paymentMethod?: 'cash' | 'card' | 'transfer' | 'qr' | 'credit',
    amountReceived?: number,
    change?: number,
    pointsRedeemed?: number,
    source?: 'pos' | 'back-office'
  ) => Promise<Sale>;
  settings?: SystemSettings;
}

export const PosTerminal: React.FC<PosTerminalProps> = ({ products, onProcessSale, settings }) => {
  const { customers, customerLevels, t, branches, warehouses, currentUser, formatPrice } = useGlobal();
  const { 
    cart, addToCart, clearCart,
    heldOrders, holdCurrentOrder, recallOrder, discardHeldOrder
  } = useCartStore();

  const [searchTerm, setSearchTerm] = useState('');
  const [isAiModalOpen, setIsAiModalOpen] = useState(false);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isScannerOpen, setIsScannerOpen] = useState(false); 

  // Modal States
  const [isDiscountModalOpen, setIsDiscountModalOpen] = useState(false);
  const [isCustomerModalOpen, setIsCustomerModalOpen] = useState(false);
  const [isRecallModalOpen, setIsRecallModalOpen] = useState(false);
  const [isCheckoutOpen, setIsCheckoutOpen] = useState(false);
  const [isReceiptOpen, setIsReceiptOpen] = useState(false);
  const [productForSelector, setProductForSelector] = useState<Product | null>(null);

  // Transaction State
  const [manualDiscount, setManualDiscount] = useState<{ type: 'percent' | 'fixed', value: number } | null>(null);
  const [redeemPoints, setRedeemPoints] = useState<number>(0);
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);
  const [lastSale, setLastSale] = useState<Sale | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  // --- Branch Logic (Inventory Filtering) ---
  const activeBranchId = settings?.currentBranchId || currentUser?.branchId || (branches.length > 0 ? branches[0].id : '');

  const branchProducts = useMemo(() => {
    if (!activeBranchId) return products;

    const branchWarehouseIds = warehouses
      .filter(w => w.branchId === activeBranchId)
      .map(w => w.id);

    return products.map(p => {
      const branchStock = p.warehouseInventory?.reduce((acc, inv) => {
        if (branchWarehouseIds.includes(inv.warehouseId)) {
          return acc + inv.quantity;
        }
        return acc;
      }, 0) || 0;

      const branchPriceConfig = p.branchPrices?.find(bp => bp.branchId === activeBranchId);
      const effectivePrice = branchPriceConfig ? branchPriceConfig.price : p.price;

      return {
        ...p,
        stock: branchStock,
        price: effectivePrice
      };
    });
  }, [products, activeBranchId, warehouses]);

  // --- Helper: Get Dynamic Price based on Customer Level ---
  const getDynamicPrice = (product: Product, variantId?: string): number => {
    // 1. Determine Base Price (Variant or Product)
    let basePrice = product.price;
    let tierPrices = product.tierPrices;

    if (variantId && product.variants) {
      const variant = product.variants.find(v => v.id === variantId);
      if (variant) {
        basePrice = variant.price;
        tierPrices = variant.tierPrices || product.tierPrices; // Fallback to product tiers if variant doesn't have specific ones
      }
    }

    if (!selectedCustomer?.levelId) return basePrice;

    // 2. Check Specific Tier Price
    if (tierPrices && tierPrices[selectedCustomer.levelId]) {
      return tierPrices[selectedCustomer.levelId];
    }

    // 3. Check Level Percentage Discount
    const level = customerLevels.find(l => l.id === selectedCustomer.levelId);
    if (level && level.discountPercentage > 0) {
      return basePrice * (1 - level.discountPercentage / 100);
    }

    return basePrice;
  };

  // --- Handlers ---
  const handleProductSelect = (product: Product) => {
    if (product.variants && product.variants.length > 0) {
      setProductForSelector(product);
    } else {
      // Calculate price immediately
      const price = getDynamicPrice(product);
      addToCart({ ...product, price }, 1);
    }
  };

  const handleConfirmSelection = (product: Product, quantity: number, variantId?: string) => {
    const price = getDynamicPrice(product, variantId);
    addToCart({ ...product, price }, quantity, variantId);
    setProductForSelector(null);
  };

  // --- Calculations ---
  const customerLevel = useMemo(() => {
    if (!selectedCustomer?.levelId) return null;
    return customerLevels.find(l => l.id === selectedCustomer.levelId);
  }, [selectedCustomer, customerLevels]);

  const rawSubtotal = cart.reduce((sum, item) => sum + (item.sellPrice * item.quantity), 0);
  const customerDiscountAmount = 0; 

  let manualDiscountAmount = 0;
  if (manualDiscount) {
    if (manualDiscount.type === 'percent') {
      manualDiscountAmount = rawSubtotal * (manualDiscount.value / 100);
    } else {
      manualDiscountAmount = manualDiscount.value;
    }
  }

  const redeemRate = settings?.loyaltyProgram?.redeemRate || 100;
  const loyaltyDiscountAmount = redeemPoints > 0 ? redeemPoints / redeemRate : 0;

  let discountAmount = Math.min(customerDiscountAmount + manualDiscountAmount + loyaltyDiscountAmount, rawSubtotal);
  let discountedSubtotal = rawSubtotal - discountAmount;

  let taxAmount = 0;
  let finalTotal = discountedSubtotal;
  const taxConfig = settings?.tax;

  if (taxConfig && taxConfig.enabled) {
    const rate = taxConfig.rate / 100;
    if (taxConfig.calculationMode === 'excluded') {
       taxAmount = discountedSubtotal * rate;
       finalTotal = discountedSubtotal + taxAmount;
    } else {
       taxAmount = discountedSubtotal - (discountedSubtotal / (1 + rate));
       finalTotal = discountedSubtotal;
    }
  }

  // --- ROUNDING LOGIC FOR LAK (KIP) ---
  // If currency is Kip (₭), round to nearest 500
  if (settings?.currencySymbol === '₭') {
     // Round to nearest 500
     finalTotal = Math.round(finalTotal / 500) * 500;
  } else {
     // Standard rounding for other currencies to 2 decimals
     finalTotal = Math.round(finalTotal * 100) / 100;
  }

  // --- Broadcast Channel ---
  useEffect(() => {
    if (settings?.customerDisplay?.enabled) {
      const payload = {
        type: isCheckoutOpen ? 'CHECKOUT' : (cart.length === 0 ? 'RESET' : 'UPDATE'),
        cart,
        subtotal: rawSubtotal,
        discount: discountAmount,
        tax: taxAmount,
        total: finalTotal,
        customer: selectedCustomer,
        companyName: settings?.companyName,
        settings: settings?.customerDisplay
      };
      const channel = new BroadcastChannel('customer_display_channel');
      channel.postMessage(payload);
      return () => channel.close();
    }
  }, [cart, rawSubtotal, discountAmount, taxAmount, finalTotal, selectedCustomer, isCheckoutOpen, settings]);

  const handleOpenCustomerDisplay = () => {
    window.open('/customer-display', 'CustomerDisplay', 'width=1024,height=768,menubar=no,toolbar=no,location=no,status=no');
  };

  useEffect(() => {
     setRedeemPoints(0);
  }, [selectedCustomer]);

  // --- Keyboard Shortcuts ---
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement;

      if (e.key === 'F4') {
        e.preventDefault();
        setIsCustomerModalOpen(true);
      }
      else if (e.key === 'F6') {
        e.preventDefault();
        setIsRecallModalOpen(true);
      }
      else if (e.key === 'F8') {
        e.preventDefault();
        setIsDiscountModalOpen(true);
      }
      else if (e.key === 'F9') {
        e.preventDefault();
        const searchInput = document.getElementById('pos-search-input');
        if (searchInput) {
            searchInput.focus();
            (searchInput as HTMLInputElement).select();
        }
      }
      else if (e.key === 'F12' || (e.key === 'Enter' && e.ctrlKey)) {
        e.preventDefault();
        if (cart.length > 0 && !isCheckoutOpen && !isReceiptOpen) {
           setIsCheckoutOpen(true);
        }
      }
      else if (e.key === 'Escape') {
         if (isCheckoutOpen) setIsCheckoutOpen(false);
         else if (isDiscountModalOpen) setIsDiscountModalOpen(false);
         else if (isCustomerModalOpen) setIsCustomerModalOpen(false);
         else if (isRecallModalOpen) setIsRecallModalOpen(false);
         else if (isReceiptOpen) setIsReceiptOpen(false);
         else if (isAiModalOpen) setIsAiModalOpen(false);
         else if (isScannerOpen) setIsScannerOpen(false);
         else if (isCartOpen) setIsCartOpen(false);
         else if (productForSelector) setProductForSelector(null);
         else if (document.activeElement?.id === 'pos-search-input') {
            setSearchTerm('');
            (document.activeElement as HTMLInputElement).blur();
         }
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [
    cart.length, 
    isCheckoutOpen, 
    isDiscountModalOpen, 
    isCustomerModalOpen, 
    isRecallModalOpen, 
    isReceiptOpen, 
    isAiModalOpen, 
    isScannerOpen,
    isCartOpen,
    productForSelector
  ]);

  const performScan = (code: string) => {
    const normalizedCode = code.trim().toLowerCase();

    // 1. Priority: Check specific Variant Barcodes first (Direct Add)
    for (const p of branchProducts) {
      if (p.variants) {
        const variantMatch = p.variants.find(v => 
          (v.barcode && v.barcode.toLowerCase() === normalizedCode) || 
          (v.code && v.code.toLowerCase() === normalizedCode)
        );
        if (variantMatch) {
          const price = getDynamicPrice(p, variantMatch.id);
          addToCart({ ...p, price }, 1, variantMatch.id);
          setSearchTerm(''); // Clear for next scan
          return;
        }
      }
    }

    // 2. Check Top-level Product Barcodes/SKUs
    const mainMatch = branchProducts.find(p => 
      (p.barcode && p.barcode.toLowerCase() === normalizedCode) || 
      (p.sku && p.sku.toLowerCase() === normalizedCode)
    );

    if (mainMatch) {
      // If product has variants but user scanned the "Generic" barcode
      if (mainMatch.variants && mainMatch.variants.length > 0) {
         setProductForSelector(mainMatch);
         setSearchTerm('');
      } else {
         // Simple product, add directly
         handleProductSelect(mainMatch);
         setSearchTerm('');
      }
      return;
    }

    // 3. No exact match - The search box handles the filtering visually
    // If user hit Enter, and no exact match, we don't alert, just let them see the filter results
    // alert(`Product not found: ${code}`); // Removed annoying alert
  };

  const handleAiItemsAdded = (items: EstimateResultItem[]) => {
    items.forEach(est => {
      if (est.matchedProductId) {
        const product = branchProducts.find(p => p.id === est.matchedProductId);
        if (product) {
           const price = getDynamicPrice(product);
           addToCart({ ...product, price }, Math.ceil(est.estimatedQuantity), undefined);
        }
      }
    });
  };

  const handleHoldOrder = () => {
    if (cart.length === 0) return;
    const note = prompt("Optional note for this hold:");
    holdCurrentOrder(selectedCustomer, note || undefined);
    setSelectedCustomer(null);
    setManualDiscount(null);
    setRedeemPoints(0);
  };

  const handleRecall = (orderId: string) => {
    const restored = recallOrder(orderId);
    if (restored) {
      setSelectedCustomer(restored.customer || null);
      setIsRecallModalOpen(false);
    }
  };

  const handleProcessPayment = async (
    method: 'cash' | 'card' | 'transfer' | 'qr' | 'credit',
    receivedAmount: number,
    change: number
  ) => {
    setIsProcessing(true);
    try {
      const sale = await onProcessSale(
        cart, finalTotal, selectedCustomer?.id, discountAmount, rawSubtotal,
        method, receivedAmount, change, redeemPoints, 'pos'
      );

      setLastSale(sale);
      setIsCheckoutOpen(false);
      clearCart();
      setManualDiscount(null); 
      setRedeemPoints(0);
      setSelectedCustomer(null);
      setIsReceiptOpen(true);
    } catch (error) {
      console.error("Sale failed", error);
      alert("Transaction failed. Please try again.");
    } finally {
      setIsProcessing(false);
    }
  };

  const cartItemCount = cart.reduce((acc, item) => acc + item.quantity, 0);

  // Inject current pricing for grid display
  const productsWithDisplayPrice = useMemo(() => {
     return branchProducts.map(p => {
        return {
           ...p,
           displayPrice: getDynamicPrice(p) // used for display in grid
        };
     });
  }, [branchProducts, selectedCustomer, customerLevels]);

  return (
    <div className="flex flex-col lg:flex-row h-full overflow-hidden bg-white md:-m-6">
      {/* Main Product Area (Left Side) */}
      <div className="flex-1 flex flex-col min-w-0 h-full overflow-hidden relative border-r border-slate-200">

        {/* Header / Top Bar for POS - Style A */}
        <div className="px-6 py-4 bg-white flex items-center justify-between shrink-0">
          <div className="flex items-center gap-4">
            <h2 className="text-2xl font-extrabold text-slate-900 hidden md:block">{t('pos.newOrder')}</h2>

            <div className="flex space-x-2">
               <button 
                 onClick={() => setIsRecallModalOpen(true)}
                 disabled={heldOrders.length === 0}
                 title="Shortcut: F6"
                 className={`flex items-center px-4 py-2 rounded-full text-sm font-bold border transition-colors ${
                   heldOrders.length > 0 
                     ? 'bg-orange-50 text-orange-700 border-orange-200 hover:bg-orange-100' 
                     : 'bg-slate-50 text-slate-400 border-transparent cursor-not-allowed'
                 }`}
               >
                 <ClipboardList className="w-4 h-4 mr-2" />
                 Recall
                 {heldOrders.length > 0 && <span className="ml-2 bg-orange-200 text-orange-800 px-1.5 rounded-full text-xs font-bold">{heldOrders.length}</span>}
               </button>

