export interface SystemSettings { 
  companyName: string; 
  taxId: string; 
  address: string; 
  phone: string; 
  monthlyTarget: number; 
  language: Language; 
  currencySymbol: string; 
  defaultItemsPerPage: number; 
  tax: TaxSettings; 
