import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { Product, CartItem, EstimateResultItem, SystemSettings, Customer, Sale, ProductVariant } from '../types';
import { Sparkles, User, ClipboardList, Monitor, Menu, ChevronLeft } from 'lucide-react';
import { AiAssistant } from './AiAssistant';
import { BarcodeScanner } from './BarcodeScanner';
import { useGlobal } from '../context/GlobalContext';
import { useCartStore } from '../store/useCartStore';

// Sub-components
import { ProductGrid } from './pos/ProductGrid';
import { CartSidebar } from './pos/CartSidebar';
import { CheckoutModal } from './pos/CheckoutModal';
import { ReceiptModal } from './pos/ReceiptModal';
import { CustomerModal } from './pos/CustomerModal';
import { DiscountModal } from './pos/DiscountModal';
import { RecallModal } from './pos/RecallModal';
import { VariantSelectorModal } from './pos/VariantSelectorModal';

interface PosTerminalProps {
  products: Product[];
  onProcessSale: (
    items: CartItem[], 
    total: number, 
    customerId?: string, 
    discountAmount?: number, 
    subtotal?: number,
    paymentMethod?: 'cash' | 'card' | 'transfer' | 'qr' | 'credit',
    amountReceived?: number,
    change?: number,
    pointsRedeemed?: number,
    source?: 'pos' | 'back-office',
    roundingDifference?: number // Added
  ) => Promise<Sale>;
  settings?: SystemSettings;
}

export const PosTerminal: React.FC<PosTerminalProps> = ({ products, onProcessSale, settings }) => {
  // ... existing code ...
  const { customers, customerLevels, t, branches, warehouses, currentUser, formatPrice } = useGlobal();
  const { 
    cart, addToCart, clearCart,
    heldOrders, holdCurrentOrder, recallOrder, discardHeldOrder
  } = useCartStore();

  const [searchTerm, setSearchTerm] = useState('');
  const [isAiModalOpen, setIsAiModalOpen] = useState(false);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [isScannerOpen, setIsScannerOpen] = useState(false); 

  // Modal States
  const [isDiscountModalOpen, setIsDiscountModalOpen] = useState(false);
  const [isCustomerModalOpen, setIsCustomerModalOpen] = useState(false);
  const [isRecallModalOpen, setIsRecallModalOpen] = useState(false);
  const [isCheckoutOpen, setIsCheckoutOpen] = useState(false);
  const [isReceiptOpen, setIsReceiptOpen] = useState(false);
  const [productForSelector, setProductForSelector] = useState<Product | null>(null);

  // Transaction State
  const [manualDiscount, setManualDiscount] = useState<{ type: 'percent' | 'fixed', value: number } | null>(null);
  const [redeemPoints, setRedeemPoints] = useState<number>(0);
  const [selectedCustomer, setSelectedCustomer] = useState<Customer | null>(null);
  const [lastSale, setLastSale] = useState<Sale | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  // --- Branch Logic (Inventory Filtering) ---
  const activeBranchId = settings?.currentBranchId || currentUser?.branchId || (branches.length > 0 ? branches[0].id : '');

  const branchProducts = useMemo(() => {
    if (!activeBranchId) return products;

    const branchWarehouseIds = warehouses
      .filter(w => w.branchId === activeBranchId)
      .map(w => w.id);

    return products.map(p => {
      const branchStock = p.warehouseInventory?.reduce((acc, inv) => {
        if (branchWarehouseIds.includes(inv.warehouseId)) {
          return acc + inv.quantity;
        }
        return acc;
      }, 0) || 0;

      const branchPriceConfig = p.branchPrices?.find(bp => bp.branchId === activeBranchId);
      const effectivePrice = branchPriceConfig ? branchPriceConfig.price : p.price;

      return {
        ...p,
        stock: branchStock,
        price: effectivePrice
      };
    });
  }, [products, activeBranchId, warehouses]);

  // --- Helper: Get Dynamic Price based on Customer Level ---
  const getDynamicPrice = (product: Product, variantId?: string): number => {
    // 1. Determine Base Price (Variant or Product)
    let basePrice = product.price;
    let tierPrices = product.tierPrices;

    if (variantId && product.variants) {
      const variant = product.variants.find(v => v.id === variantId);
      if (variant) {
        basePrice = variant.price;
        tierPrices = variant.tierPrices || product.tierPrices; // Fallback to product tiers if variant doesn't have specific ones
      }
    }

    if (!selectedCustomer?.levelId) return basePrice;

    // 2. Check Specific Tier Price
    if (tierPrices && tierPrices[selectedCustomer.levelId]) {
      return tierPrices[selectedCustomer.levelId];
    }

    // 3. Check Level Percentage Discount
    const level = customerLevels.find(l => l.id === selectedCustomer.levelId);
    if (level && level.discountPercentage > 0) {
      return basePrice * (1 - level.discountPercentage / 100);
    }

    return basePrice;
  };

  // --- Handlers ---
  const handleProductSelect = (product: Product) => {
    if (product.variants && product.variants.length > 0) {
      setProductForSelector(product);
    } else {
      // Calculate price immediately
      const price = getDynamicPrice(product);
      addToCart({ ...product, price }, 1);
    }
  };

  const handleConfirmSelection = (product: Product, quantity: number, variantId?: string) => {
    const price = getDynamicPrice(product, variantId);
    addToCart({ ...product, price }, quantity, variantId);
    setProductForSelector(null);
  };

  // --- Calculations ---
  const customerLevel = useMemo(() => {
    if (!selectedCustomer?.levelId) return null;
    return customerLevels.find(l => l.id === selectedCustomer.levelId);
  }, [selectedCustomer, customerLevels]);

  const rawSubtotal = cart.reduce((sum, item) => sum + (item.sellPrice * item.quantity), 0);
  const customerDiscountAmount = 0; 

  let manualDiscountAmount = 0;
  if (manualDiscount) {
    if (manualDiscount.type === 'percent') {
      manualDiscountAmount = rawSubtotal * (manualDiscount.value / 100);
    } else {
      manualDiscountAmount = manualDiscount.value;
    }
  }

  const redeemRate = settings?.loyaltyProgram?.redeemRate || 100;
  const loyaltyDiscountAmount = redeemPoints > 0 ? redeemPoints / redeemRate : 0;

  let discountAmount = Math.min(customerDiscountAmount + manualDiscountAmount + loyaltyDiscountAmount, rawSubtotal);
  let discountedSubtotal = rawSubtotal - discountAmount;

  let taxAmount = 0;
  let exactTotal = discountedSubtotal; // Track exact amount before rounding

  const taxConfig = settings?.tax;

  if (taxConfig && taxConfig.enabled) {
    const rate = taxConfig.rate / 100;
    if (taxConfig.calculationMode === 'excluded') {
       taxAmount = discountedSubtotal * rate;
       exactTotal = discountedSubtotal + taxAmount;
    } else {
       taxAmount = discountedSubtotal - (discountedSubtotal / (1 + rate));
       exactTotal = discountedSubtotal;
    }
  }

  // --- ROUNDING LOGIC ---
  let finalTotal = exactTotal;
  let roundingDifference = 0;

  // Use configured settings or fallback to default behavior (Check for Kip symbol or enabled flag)
  const isRoundingEnabled = settings?.rounding?.enabled ?? (settings?.currencySymbol === '₭');
  const roundingInterval = settings?.rounding?.interval || 500;

  if (isRoundingEnabled) {
     // Round to configured interval (Default 500)
     finalTotal = Math.round(exactTotal / roundingInterval) * roundingInterval;
     roundingDifference = finalTotal - exactTotal;
  } else {
     // Standard rounding for other currencies to 2 decimals
     finalTotal = Math.round(exactTotal * 100) / 100;
  }

  // ... rest of the file ...
  // (Broadcast Channel useEffect, performScan, handleAiItemsAdded, handleHoldOrder, handleRecall, handleProcessPayment)
  // Ensure we pass roundingDifference to onProcessSale in handleProcessPayment
  // ...
  const handleProcessPayment = async (
    method: 'cash' | 'card' | 'transfer' | 'qr' | 'credit',
    receivedAmount: number,
    change: number
  ) => {
    setIsProcessing(true);
    try {
      const sale = await onProcessSale(
        cart, 
        finalTotal, 
        selectedCustomer?.id, 
        discountAmount, 
        rawSubtotal,
        method, 
        receivedAmount, 
        change, 
        redeemPoints, 
        'pos',
        roundingDifference // Pass rounding info
      );

      setLastSale(sale);
      setIsCheckoutOpen(false);
      clearCart();
      setManualDiscount(null); 
      setRedeemPoints(0);
      setSelectedCustomer(null);
      setIsReceiptOpen(true);
    } catch (error) {
      console.error("Sale failed", error);
      alert("Transaction failed. Please try again.");
    } finally {
      setIsProcessing(false);
    }
  };

  // ... rest of rendering ...
  // Make sure to pass roundingDifference to CartSidebar
  // ...
  return (
    <div className="flex flex-col lg:flex-row h-full overflow-hidden bg-white md:-m-6">
      {/* ... Left Side ... */}
      <div className="flex-1 flex flex-col min-w-0 h-full overflow-hidden relative border-r border-slate-200">
         {/* ... Top Bar ... */}
         {/* ... Product Grid ... */}
         <div className="flex-1 overflow-hidden relative">
           <ProductGrid 
             products={productsWithDisplayPrice} 
             searchTerm={searchTerm}
             setSearchTerm={setSearchTerm}
             onScanClick={() => setIsScannerOpen(true)}
             onScan={performScan}
             onProductSelect={handleProductSelect}
           />
        </div>
      </div>

      {/* Cart Sidebar (Right Side) */}
      <div className={`
         fixed inset-0 z-40 bg-white transform transition-transform duration-300 lg:relative lg:translate-x-0 lg:w-[420px] xl:w-[480px] shadow-2xl lg:shadow-none
         ${isCartOpen ? 'translate-x-0' : 'translate-x-full lg:translate-x-0'}
      `}>
         <CartSidebar 
            isOpen={isCartOpen}
            onClose={() => setIsCartOpen(false)}
            selectedCustomer={selectedCustomer}
            onRemoveCustomer={() => setSelectedCustomer(null)}
            onHoldOrder={handleHoldOrder}
            onCheckout={() => setIsCheckoutOpen(true)}
            onDiscountClick={() => setIsDiscountModalOpen(true)}
            subtotal={rawSubtotal}
            discount={discountAmount}
            tax={taxAmount}
            total={finalTotal}
            roundingDifference={roundingDifference}
            settings={settings}
         />
      </div>
      {/* ... Mobile Toggle, Modals ... */}
      <CheckoutModal 
        isOpen={isCheckoutOpen}
        onClose={() => setIsCheckoutOpen(false)}
        total={finalTotal}
        onProcessPayment={handleProcessPayment}
        selectedCustomer={selectedCustomer}
        isProcessing={isProcessing}
        settings={settings} 
      />
      {/* ... Other Modals ... */}
      <ReceiptModal 
        isOpen={isReceiptOpen}
        onClose={() => setIsReceiptOpen(false)}
        sale={lastSale}
        settings={settings}
      />

      <CustomerModal 
        isOpen={isCustomerModalOpen}
        onClose={() => setIsCustomerModalOpen(false)}
        customers={customers}
        onSelectCustomer={(c) => { setSelectedCustomer(c); setIsCustomerModalOpen(false); }}
      />

      <DiscountModal 
        isOpen={isDiscountModalOpen}
        onClose={() => setIsDiscountModalOpen(false)}
        onApplyDiscount={setManualDiscount}
        currencySymbol={settings?.currencySymbol}
      />

      <RecallModal 
        isOpen={isRecallModalOpen}
        onClose={() => setIsRecallModalOpen(false)}
        heldOrders={heldOrders}
        onRecall={handleRecall}
        onDiscard={discardHeldOrder}
      />

      <AiAssistant 
        isOpen={isAiModalOpen} 
        onClose={() => setIsAiModalOpen(false)} 
        inventory={branchProducts} 
        onAddItemsToCart={handleAiItemsAdded} 
      />

      <BarcodeScanner 
        isOpen={isScannerOpen} 
        onClose={() => setIsScannerOpen(false)} 
        onScan={performScan} 
      />

      {productForSelector && (
        <VariantSelectorModal 
          product={productForSelector}
          isOpen={!!productForSelector}
          onClose={() => setProductForSelector(null)}
          onConfirm={handleConfirmSelection}
          formatPrice={formatPrice}
        />
      )}
    </div>
  );
};

import React from 'react';
import { Customer, SystemSettings } from '../../types';
import { ShoppingCart, PauseCircle, X, Minus, Plus, Trash2, User, Tag, ChevronRight, ChevronDown } from 'lucide-react';
import { useGlobal } from '../../context/GlobalContext';
import { useCartStore } from '../../store/useCartStore';

interface CartSidebarProps {
  isOpen: boolean;
  onClose: () => void;
  selectedCustomer: Customer | null;
  onRemoveCustomer: () => void;
  onHoldOrder: () => void;
  onCheckout: () => void;
  onDiscountClick: () => void;
  subtotal: number;
  discount: number;
  tax: number;
  total: number;
  roundingDifference?: number; // Added
  settings?: SystemSettings;
}

export const CartSidebar: React.FC<CartSidebarProps> = ({
  isOpen,
  onClose,
  selectedCustomer,
  onRemoveCustomer,
  onHoldOrder,
  onCheckout,
  onDiscountClick,
  subtotal,
  discount,
  tax,
  total,
  roundingDifference = 0, // Added default
  settings
}) => {
  const { formatPrice } = useGlobal();
  const { cart, removeFromCart, updateQuantity } = useCartStore();

  const renderVariantDetails = (item: any) => {
    if (!item.selectedVariantId || !item.variants) return null;
    const variant = item.variants.find((v: any) => v.id === item.selectedVariantId);
    if (!variant || !variant.attributes) return null;

    return (
      <div className="flex flex-wrap gap-1 mt-1">
        {Object.values(variant.attributes).map((val: any, idx: number) => (
          <span key={idx} className="text-[10px] bg-slate-100 text-slate-500 px-1.5 rounded border border-slate-200">
            {val}
          </span>
        ))}
      </div>
    );
  };

  return (
    <div className="flex flex-col h-full bg-white relative w-full">
      {/* Header */}
      <div className="p-4 md:p-5 border-b border-slate-100 bg-white flex justify-between items-center z-10 shrink-0 shadow-sm">
        <div>
           <div className="flex items-center gap-2">
              <h3 className="font-extrabold text-slate-900 text-lg md:text-xl">Order Ticket</h3>
              <span className="bg-slate-100 text-slate-600 text-xs font-bold px-2 py-0.5 rounded-full">{cart.reduce((a,c)=>a+c.quantity,0)}</span>
           </div>
           <div className="text-xs text-slate-400 mt-0.5 font-medium">
              {new Date().toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}
           </div>
        </div>
        <div className="flex space-x-2">
           <button 
              onClick={onHoldOrder} 
              disabled={cart.length === 0} 
              className="p-2.5 bg-slate-50 text-slate-500 rounded-full hover:bg-orange-50 hover:text-orange-600 transition-colors disabled:opacity-30" 
              title="Hold Order"
           >
              <PauseCircle className="w-5 h-5" />
           </button>
           <button onClick={onClose} className="lg:hidden p-2.5 bg-slate-100 text-slate-600 hover:bg-slate-200 rounded-full transition-colors">
             <ChevronDown className="w-5 h-5" />
           </button>
        </div>
      </div>

      {/* Customer Bar */}
      {selectedCustomer && (
         <div className="px-5 py-3 border-b border-slate-100 bg-blue-50/50 flex justify-between items-center shrink-0">
            <div className="flex items-center">
               <div className="w-8 h-8 rounded-full bg-white border border-blue-200 text-blue-700 flex items-center justify-center mr-3 shadow-sm">
                  <User className="w-4 h-4" />
               </div>
               <div>
                  <p className="text-sm font-bold text-slate-800">{selectedCustomer.name}</p>
                  <p className="text-[10px] text-slate-500 font-medium">Points: {selectedCustomer.loyaltyPoints}</p>
               </div>
            </div>
            <button onClick={onRemoveCustomer} className="text-slate-400 hover:text-red-500 bg-white p-1 rounded-full border border-slate-200"><X className="w-3 h-3" /></button>
         </div>
      )}

      {/* Cart Items List */}
      <div className="flex-1 overflow-y-auto bg-white p-4 space-y-3 custom-scrollbar">
        {cart.length === 0 ? (
          <div className="h-full flex flex-col items-center justify-center text-slate-300 space-y-4">
            <div className="w-20 h-20 bg-slate-50 rounded-full flex items-center justify-center">
               <ShoppingCart className="w-8 h-8 text-slate-200" />
            </div>
            <div className="text-center">
               <p className="font-bold text-slate-400">Cart is empty</p>
               <p className="text-xs mt-1">Scan items to start</p>
            </div>
          </div>
        ) : (
          cart.map((item, index) => {
            const minQty = item.minOrderQuantity || 1;
            const isMin = item.quantity <= minQty;

            return (
              <div key={`${item.id}-${index}-${item.selectedVariantId}`} className="flex gap-3 group bg-white rounded-xl border border-slate-100 p-2 hover:border-slate-300 transition-colors shadow-sm">
                {/* Qty Controls */}
                <div className="flex flex-col items-center justify-center bg-slate-50 rounded-lg w-10 shrink-0 border border-slate-200">
                   <button 
                     onClick={() => updateQuantity(index, 1)} 
                     className="w-full h-8 flex items-center justify-center text-slate-500 hover:text-slate-900 transition-colors hover:bg-white rounded-t-lg"
                   >
                      <Plus className="w-3 h-3" />
                   </button>
                   <span className="text-sm font-bold text-slate-900 h-6 flex items-center justify-center bg-white w-full border-y border-slate-200">{item.quantity}</span>
                   <button 
                     onClick={() => updateQuantity(index, -1)} 
                     disabled={isMin}
                     className={`w-full h-8 flex items-center justify-center transition-colors rounded-b-lg ${isMin ? 'text-slate-200' : 'text-slate-500 hover:text-red-500 hover:bg-white'}`}
                   >
                      <Minus className="w-3 h-3" />
                   </button>
                </div>

                <div className="flex-1 min-w-0 py-1 flex flex-col justify-between">
                   <div className="flex justify-between items-start gap-2">
                      <div>
                         <h4 className="font-bold text-slate-800 text-sm line-clamp-2 leading-tight">{item.name}</h4>
                         <div className="flex flex-wrap items-center gap-2 mt-1">
                            <span className="text-xs font-bold text-slate-600 bg-slate-100 px-1.5 py-0.5 rounded border border-slate-200">
                               {item.sellUnit}
                            </span>
                            {renderVariantDetails(item)}
                         </div>
                      </div>
                      <span className="font-bold text-slate-900 text-sm shrink-0">{formatPrice(item.sellPrice * item.quantity)}</span>
                   </div>

                   <div className="flex justify-between items-end mt-1">
                      <div className="text-xs text-slate-400 font-medium">
                         @ {formatPrice(item.sellPrice)}
                      </div>
                      <button onClick={() => removeFromCart(index)} className="text-slate-300 hover:text-red-500 transition-colors p-1">
                         <Trash2 className="w-4 h-4" />
                      </button>
                   </div>
                </div>
              </div>
            );
          })
        )}
      </div>

      {/* Footer */}
      <div className="bg-white border-t border-slate-100 shadow-[0_-10px_30px_rgba(0,0,0,0.03)] z-20 pb-6 pt-2">
        <div className="px-5 mb-4">
           <button 
              onClick={onDiscountClick} 
              className="w-full py-2.5 border-2 border-dashed border-slate-200 rounded-xl text-xs font-bold text-slate-500 hover:border-slate-300 hover:bg-slate-50 transition-colors flex justify-between items-center px-4"
           >
              <span className="flex items-center"><Tag className="w-3.5 h-3.5 mr-2" /> Add Discount / Coupon</span>
              {discount > 0 && <span className="bg-green-100 text-green-700 px-2 py-0.5 rounded text-[10px]">-{formatPrice(discount)}</span>}
           </button>
        </div>

        <div className="px-6 space-y-2 mb-4">
           <div className="flex justify-between text-sm text-slate-500 font-medium">
              <span>Subtotal</span>
              <span>{formatPrice(subtotal)}</span>
           </div>
           {settings?.tax?.enabled && (
              <div className="flex justify-between text-sm text-slate-500 font-medium">
                 <span>Tax ({settings.tax.rate}%)</span>
                 <span>{formatPrice(tax)}</span>
              </div>
           )}

           {/* Rounding Adjustment Display */}
           {roundingDifference !== 0 && (
              <div className="flex justify-between text-xs text-slate-400 italic">
                 <span>Rounding</span>
                 <span className={roundingDifference > 0 ? 'text-green-600' : 'text-red-500'}>
                    {roundingDifference > 0 ? '+' : ''}{formatPrice(roundingDifference)}
                 </span>
              </div>
           )}

           <div className="flex justify-between items-end pt-2 border-t border-slate-100">
              <span className="text-base font-bold text-slate-800">Total</span>
              <span className="text-4xl font-extrabold text-slate-900 tracking-tighter">{formatPrice(total)}</span>
           </div>
        </div>

        <div className="px-5">
           <button 
              onClick={onCheckout} 
              disabled={cart.length === 0}
              className="w-full py-4 bg-red-600 text-white rounded-2xl font-bold text-xl hover:bg-red-700 hover:shadow-lg transition-all flex items-center justify-center disabled:opacity-50 disabled:cursor-not-allowed active:scale-[0.98]"
           >
              <span>Charge {formatPrice(total)}</span>
              <ChevronRight className="w-5 h-5 ml-2 opacity-60" />
           </button>
        </div>
      </div>
    </div>
  );
};

import React from 'react';
import { Sale, SystemSettings } from '../../types';

interface PrintableReceiptProps {
  sale: Sale;
  settings?: SystemSettings;
  isReprint?: boolean;
}

export const PrintableReceipt: React.FC<PrintableReceiptProps> = ({ sale, settings, isReprint }) => {
  const receiptWidthClass = settings?.receiptPaperSize === '58mm' ? 'print-w-58mm' : settings?.receiptPaperSize === 'A4' ? 'print-w-A4' : 'print-w-80mm';

  const formatPrice = (amount: number) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: settings?.currencySymbol === '₭' ? 'LAK' : settings?.currencySymbol === '฿' ? 'THB' : 'USD',
      minimumFractionDigits: 0,
      maximumFractionDigits: 0,
    }).format(amount);
  };

  const showTax = settings?.tax?.displayOnReceipt !== false; // Default true if undefined
  // Check newly added setting, default to true if undefined for backward compatibility
  const showRounding = settings?.rounding?.displayOnReceipt !== false; 

  return (
    <div id="printable-receipt" className={`bg-white p-4 text-xs font-mono text-black mx-auto ${receiptWidthClass} print:shadow-none print:border-none`}>
      <div className="text-center mb-4">
        {settings?.receiptLogoUrl && (
           <img src={settings.receiptLogoUrl} alt="Logo" className="h-12 w-auto mx-auto mb-2 object-contain" />
        )}
        <h2 className="text-lg font-bold mb-1">{settings?.companyName || 'Store Name'}</h2>
        <p>{settings?.address}</p>
        <p>{settings?.phone}</p>
        {settings?.receiptShowTaxId && settings.taxId && <p>Tax ID: {settings.taxId}</p>}

        <div className="border-b border-dashed border-black my-2"></div>

        <div className="flex justify-between">
           <span>Inv: #{sale.id.slice(-6)}</span>
           <span>{new Date(sale.date).toLocaleDateString()}</span>
        </div>
        <div className="flex justify-between">
           <span>Time: {new Date(sale.date).toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}</span>
           {settings?.receiptShowCashier && <span>Staff: {sale.userName || 'Admin'}</span>}
        </div>
        {sale.customerName && <div className="text-left mt-1">Cust: {sale.customerName}</div>}
        {sale.status === 'voided' && <div className="font-bold text-center mt-1">[ VOIDED ]</div>}
      </div>

      <div className="border-b border-dashed border-black my-2"></div>

      <div className="space-y-1 mb-2">
        {sale.items.map((item, i) => (
          <div key={i} className="flex justify-between">
            <span className="truncate w-32">{item.name}</span>
            <span className="text-right">
              {item.quantity} x {formatPrice(item.sellPrice)}
            </span>
            <span className="font-bold text-right w-16">
              {formatPrice(item.quantity * item.sellPrice)}
            </span>
          </div>
        ))}
      </div>

      <div className="border-b border-dashed border-black my-2"></div>

      <div className="space-y-1">
        <div className="flex justify-between">
          <span>Subtotal</span>
          <span>{formatPrice(sale.subtotal || sale.total)}</span>
        </div>
        {sale.discountAmount ? (
          <div className="flex justify-between">
            <span>Discount</span>
            <span>-{formatPrice(sale.discountAmount)}</span>
          </div>
        ) : null}

        {sale.taxAmount && sale.taxAmount > 0 && showTax && (
           <div className="flex justify-between">
             <span>Tax</span>
             <span>{formatPrice(sale.taxAmount)}</span>
           </div>
        )}

        {/* Rounding Display - Controlled by Setting */}
        {sale.roundingDifference !== undefined && sale.roundingDifference !== 0 && showRounding && (
           <div className="flex justify-between italic text-[10px]">
             <span>Rounding</span>
             <span>
                {sale.roundingDifference > 0 ? '+' : ''}{formatPrice(sale.roundingDifference)}
             </span>
           </div>
        )}

        <div className="flex justify-between font-bold text-sm mt-1 pt-1 border-t border-black">
          <span>Total</span>
          <span>{formatPrice(sale.total)}</span>
        </div>
      </div>

      <div className="border-b border-dashed border-black my-3"></div>

      <div className="space-y-1">
        <div className="flex justify-between">
          <span className="capitalize">Paid via {sale.paymentMethod}</span>
          <span>{formatPrice(sale.amountReceived && sale.amountReceived > 0 ? sale.amountReceived : sale.total)}</span>
        </div>

        {(sale.paymentStatus === 'unpaid' || sale.paymentStatus === 'partial') && (
           <div className="flex justify-between font-bold">
              <span>Balance Due</span>
              <span>{formatPrice(sale.remainingAmount || 0)}</span>
           </div>
        )}

        {sale.change !== undefined && sale.change > 0 && (
          <div className="flex justify-between font-bold">
            <span>Change</span>
            <span>{formatPrice(sale.change)}</span>
          </div>
        )}
      </div>

      <div className="mt-6 text-center italic">
        <p className="mb-1">{settings?.receiptHeader}</p>
        <p>{settings?.receiptFooter}</p>
        {isReprint && <p className="text-[9px] mt-2 text-slate-500">*** REPRINT ***</p>}

        {/* QR Code at bottom if configured */}
        {settings?.receiptQrCodeUrl && (
          <div className="mt-3 flex flex-col items-center">
              <img src={settings.receiptQrCodeUrl} alt="QR" className="w-16 h-16 object-contain" />
              <span className="text-[9px] font-bold mt-1">Scan to Pay</span>
          </div>
        )}
      </div>
    </div>
  );
};

